// Database generato da Incantesimi.html. Mantiene id e ordine di spells-db.js, con testi e metadati in italiano.
window.DND_SPELLS_IT = [{"id":"abi-dalzim-s-horrid-wilting","name":"Abi-Dalzim's Horrid Wilting","name_it":"Orribile Avvizzimento di Abi-Dalzim","level":8,"level_it":"Livello 8","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (un pezzetto di spugna)","material":"un pezzetto di spugna","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Prosciughi l'umidità da ogni creatura in un cubo di 9 metri centrato su un punto a tua scelta entro gittata. Ogni creatura in quell'area deve effettuare un tiro salvezza su Costituzione. I costrutti e i non morti non sono interessati, mentre le piante e gli elementali dell'acqua effettuano questo tiro salvezza con svantaggio. Una creatura subisce 12d8 danni necrotici se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nLe piante non magiche nell'area che non sono creature, come alberi e arbusti, avvizziscono e muoiono all'istante.","language":"it","ui_language":"it"},{"id":"absorb-elements","name":"Absorb Elements","name_it":"Assorbire Elementi","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 reazione, che si esegue quando si subiscono danni da acido, freddo, fuoco, fulmine o tuono","range":"Personale","components":"S","material":"","duration":"1 round","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"L'incantesimo cattura parte dell'energia in arrivo, riducendone l'effetto su di te e immagazzinandola per il tuo prossimo attacco in mischia. Ottieni resistenza al tipo di danno che ha innescato l'incantesimo fino all'inizio del tuo prossimo turno. Inoltre, la prima volta che colpisci con un attacco in mischia nel tuo prossimo turno, il bersaglio subisce 1d6 danni aggiuntivi del tipo che ha innescato l'incantesimo, e l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aggiuntivi aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"acid-splash","name":"Acid Splash","name_it":"Spruzzo Acido","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scagli una bolla di acido. Scegli una creatura che puoi vedere entro gittata, oppure due creature che puoi vedere entro gittata e che si trovino entro 1,5 metri l'una dall'altra. Un bersaglio deve superare un tiro salvezza su Destrezza o subisce 1d6 danni da acido.\nI danni di questo incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"aganazzar-s-scorcher","name":"Aganazzar's Scorcher","name_it":"Vampa di Aganazzar","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una scaglia di drago rosso)","material":"una scaglia di drago rosso","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Una linea di fiamme ruggenti lunga 9 metri e larga 1,5 metri emana da te nella direzione che scegli. Ogni creatura nella linea deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 3d8 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"aid","name":"Aid","name_it":"Aiuto","level":2,"level_it":"Livello 2","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una piccola striscia di stoffa bianca)","material":"una piccola striscia di stoffa bianca","duration":"8 ore","classes":["Cleric","Paladin","Bard","Ranger"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Il tuo incantesimo rinvigorisce i tuoi alleati con tenacia e determinazione. Scegli fino a tre creature entro gittata. Il massimo dei punti ferita e i punti ferita attuali di ciascun bersaglio aumentano di 5 per la durata.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i punti ferita di un bersaglio aumentano di ulteriori 5 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"alarm","name":"Alarm","name_it":"Allarme","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":true,"casting_time":"1 minuto","range":"9 metri","components":"V, S, M (una piccola campana e un pezzo di filo d'argento sottile)","material":"una piccola campana e un pezzo di filo d'argento sottile","duration":"8 ore","classes":["Ranger","Wizard"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Predisponi un allarme contro le intrusioni indesiderate. Scegli una porta, una finestra o un'area entro gittata non più grande di un cubo di 6 metri. Fino al termine dell'incantesimo, un allarme ti avverte ogni volta che una creatura di taglia Minuscola o superiore tocca o entra nell'area protetta. Quando lanci l'incantesimo, puoi designare delle creature che non faranno scattare l'allarme. Scegli anche se l'allarme è mentale o udibile.\nUn allarme mentale ti avverte con un segnale nella tua mente se ti trovi entro 1,5 chilometri dall'area protetta. Questo segnale ti sveglia se stai dormendo. Un allarme udibile produce il suono di un campanello a mano per 10 secondi entro 18 metri.","language":"it","ui_language":"it"},{"id":"alter-self","name":"Alter Self","name_it":"Alterare se Stessi","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Assumi una forma diversa. Quando lanci l'incantesimo, scegli una delle seguenti opzioni, i cui effetti durano per la durata dell'incantesimo. Finché l'incantesimo persiste, puoi terminare un'opzione con un'azione per ottenere i benefici di un'altra.\nAdattamento Acquatico. Adatti il tuo corpo a un ambiente acquatico, facendo spuntare branchie e membrane tra le dita. Puoi respirare sott'acqua e ottieni una velocità di nuoto pari alla tua velocità sul terreno.\nCambiare Aspetto. Trasformi il tuo aspetto. Decidi che aspetto avere, inclusi altezza, peso, lineamenti del viso, suono della voce, lunghezza dei capelli, colorito ed eventuali caratteristiche distintive. Puoi far sì di apparire come un membro di un'altra razza, anche se nessuna delle tue statistiche cambia. Non puoi però apparire come una creatura di taglia diversa dalla tua, e la tua forma di base rimane invariata; se sei bipede, ad esempio, non puoi usare questo incantesimo per diventare quadrupede. In qualsiasi momento durante la durata dell'incantesimo, puoi usare la tua azione per cambiare di nuovo il tuo aspetto in questo modo.\nArmi Naturali. Ti crescono artigli, zanne, aculei, corna o un'altra arma naturale a tua scelta. I tuoi colpi senza armi infliggono 1d6 danni contundenti, perforanti o taglienti, a seconda dell'arma naturale che hai scelto, e sei competente nei tuoi colpi senza armi. Infine, l'arma naturale è magica e ottieni un bonus di +1 ai tiri per colpire e ai tiri per i danni che effettui con essa.","language":"it","ui_language":"it"},{"id":"animal-friendship","name":"Animal Friendship","name_it":"Amicizia con gli Animali","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un boccone di cibo)","material":"un boccone di cibo","duration":"24 ore","classes":["Bard","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo ti permette di convincere una bestia che non intendi farle del male. Scegli una bestia che puoi vedere entro gittata. Deve poterti vedere e sentire. Se l'Intelligenza della bestia è pari o superiore a 4, l'incantesimo fallisce. Altrimenti, la bestia deve superare un tiro salvezza su Saggezza o resta affascinata da te per la durata dell'incantesimo. Se tu o uno dei tuoi compagni ferite il bersaglio, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi interessare una bestia aggiuntiva per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"animal-messenger","name":"Animal Messenger","name_it":"Messaggero Animale","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":true,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un boccone di cibo)","material":"un boccone di cibo","duration":"24 ore","classes":["Bard","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per mezzo di questo incantesimo, utilizzi un animale per recapitare un messaggio. Scegli una bestia di taglia Minuscola che puoi vedere entro gittata, come uno scoiattolo, una ghiandaia o un pipistrello. Specifichi un luogo, che devi aver visitato, e un destinatario che corrisponda a una descrizione generica, come «un uomo o una donna con l'uniforme della guardia cittadina» oppure «un nano dai capelli rossi con un cappello a punta». Pronunci inoltre un messaggio di un massimo di venticinque parole. La bestia bersaglio viaggia per la durata dell'incantesimo verso il luogo specificato, coprendo circa 75 chilometri ogni 24 ore se è un messaggero volante, o 37,5 chilometri per gli altri animali.\nQuando il messaggero arriva, recapita il tuo messaggio alla creatura che hai descritto, riproducendo il suono della tua voce. Il messaggero parla solo a una creatura che corrisponda alla descrizione che hai fornito. Se il messaggero non raggiunge la sua destinazione prima che l'incantesimo termini, il messaggio va perduto e la bestia torna nel luogo in cui hai lanciato questo incantesimo.\nAi Livelli Superiori. Se lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, la durata dell'incantesimo aumenta di 48 ore per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"animal-shapes","name":"Animal Shapes","name_it":"Forme Animali","level":8,"level_it":"Livello 8","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 24 ore","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"La tua magia trasforma gli altri in bestie. Scegli un numero qualsiasi di creature consenzienti che puoi vedere entro gittata. Trasformi ciascun bersaglio nella forma di una bestia di taglia Grande o inferiore con un grado di sfida pari o inferiore a 4. Nei turni successivi, puoi usare la tua azione per trasformare le creature interessate in nuove forme.\nLa trasformazione dura per la durata dell'incantesimo per ciascun bersaglio, o finché il bersaglio non scende a 0 punti ferita o muore. Puoi scegliere una forma diversa per ciascun bersaglio. Le statistiche di gioco di un bersaglio sono sostituite da quelle della bestia scelta, anche se il bersaglio conserva il proprio allineamento e i propri punteggi di Intelligenza, Saggezza e Carisma. Il bersaglio assume i punti ferita della sua nuova forma e, quando torna alla sua forma normale, recupera il numero di punti ferita che aveva prima di trasformarsi. Se torna alla forma normale a causa della discesa a 0 punti ferita, gli eventuali danni in eccesso si ripercuotono sulla sua forma normale. Finché i danni in eccesso non riducono la forma normale della creatura a 0 punti ferita, essa non viene resa priva di sensi. La creatura è limitata nelle azioni che può compiere dalla natura della sua nuova forma, e non può parlare né lanciare incantesimi.\nL'equipaggiamento del bersaglio si fonde nella nuova forma. Il bersaglio non può attivare, impugnare o altrimenti beneficiare del proprio equipaggiamento.","language":"it","ui_language":"it"},{"id":"animate-dead","name":"Animate Dead","name_it":"Animare Morti","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 minuto","range":"3 metri","components":"V, S, M (una goccia di sangue, un pezzo di carne e un pizzico di polvere d'ossa)","material":"una goccia di sangue, un pezzo di carne e un pizzico di polvere d'ossa","duration":"Istantanea","classes":["Cleric","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo crea un servitore non morto. Scegli un mucchio di ossa o il cadavere di un umanoide di taglia Media o Piccola entro gittata. Il tuo incantesimo infonde nel bersaglio un'oscena imitazione della vita, rianimandolo come creatura non morta. Il bersaglio diventa uno scheletro se hai scelto le ossa o uno zombie se hai scelto un cadavere.\nA ogni tuo turno, puoi usare un'azione bonus per comandare mentalmente qualsiasi creatura che hai creato con questo incantesimo se la creatura si trova entro 18 metri da te (se controlli più creature, puoi comandarle tutte o in parte contemporaneamente, impartendo lo stesso comando a ciascuna). Decidi quale azione compirà la creatura e dove si muoverà durante il suo prossimo turno, oppure puoi impartire un comando generico, come sorvegliare una determinata stanza o corridoio. Se non impartisci comandi, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo finché il suo compito non è completato.\nLa creatura è sotto il tuo controllo per 24 ore, dopodiché smette di obbedire a qualsiasi comando tu le abbia impartito. Per mantenere il controllo della creatura per altre 24 ore, devi lanciare nuovamente questo incantesimo sulla creatura prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo riafferma il tuo controllo su un massimo di quattro creature che hai animato con questo incantesimo, invece di animarne una nuova.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, animi o riaffermi il controllo su due creature non morte aggiuntive per ogni livello dello slot superiore al 3°. Ciascuna delle creature deve provenire da un diverso cadavere o mucchio di ossa.","language":"it","ui_language":"it"},{"id":"animate-objects","name":"Animate Objects","name_it":"Animare Oggetti","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Gli oggetti prendono vita al tuo comando. Scegli fino a dieci oggetti non magici entro gittata che non siano indossati né trasportati. I bersagli di taglia Media contano come due oggetti, quelli di taglia Grande come quattro oggetti, quelli di taglia Enorme come otto oggetti. Non puoi animare alcun oggetto più grande di taglia Enorme. Ciascun bersaglio si anima e diventa una creatura sotto il tuo controllo fino al termine dell'incantesimo o finché non viene ridotto a 0 punti ferita.\nCome azione bonus, puoi comandare mentalmente qualsiasi creatura che hai creato con questo incantesimo se la creatura si trova entro 150 metri da te (se controlli più creature, puoi comandarle tutte o in parte contemporaneamente, impartendo lo stesso comando a ciascuna). Decidi quale azione compirà la creatura e dove si muoverà durante il suo prossimo turno, oppure puoi impartire un comando generico, come sorvegliare una determinata stanza o corridoio. Se non impartisci comandi, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo finché il suo compito non è completato.\nTaglia | PF | CA | Attacco | For | Des | Minuscola | 20 | 18 | +8 per colpire, 1d4 + 4 danni | 4 | 18 | Piccola | 25 | 16 | +6 per colpire, 1d8 + 2 danni | 6 | 14 | Media | 40 | 13 | +5 per colpire, 2d6 + 1 danni | 10 | 12 | Grande | 50 | 10 | +6 per colpire, 2d10 + 2 danni | 14 | 10 | Enorme | 80 | 10 | +8 per colpire, 2d12 + 4 danni | 18 | 6\nUn oggetto animato è un costrutto con CA, punti ferita, attacchi, Forza e Destrezza determinati dalla sua taglia. La sua Costituzione è 10, la sua Intelligenza e la sua Saggezza sono 3 e il suo Carisma è 1. La sua velocità è di 9 metri; se l'oggetto è privo di gambe o di altre appendici utilizzabili per spostarsi, ha invece una velocità di volo di 9 metri e può fluttuare. Se l'oggetto è saldamente fissato a una superficie o a un oggetto più grande, come una catena imbullonata a una parete, la sua velocità è 0. Ha vista cieca con un raggio di 9 metri ed è cieco oltre tale distanza. Quando l'oggetto animato scende a 0 punti ferita, torna alla sua forma di oggetto originale, e gli eventuali danni rimanenti si ripercuotono su tale forma originale.\nSe comandi a un oggetto di attaccare, esso può effettuare un singolo attacco in mischia contro una creatura entro 1,5 metri da esso. Effettua un attacco di percossa con un bonus di attacco e danni contundenti determinati dalla sua taglia. Il DM potrebbe stabilire che un oggetto specifico infligga danni taglienti o perforanti in base alla sua forma.\nAi Livelli Superiori. Se lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, puoi animare due oggetti aggiuntivi per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"antilife-shell","name":"Antilife Shell","name_it":"Guscio Antivita","level":5,"level_it":"Livello 5","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 3 metri)","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una barriera scintillante si estende da te per un raggio di 3 metri e si muove con te, rimanendo centrata su di te e tenendo a distanza le creature diverse dai non morti e dai costrutti. La barriera dura per la durata dell'incantesimo.\nLa barriera impedisce a una creatura interessata di attraversarla o di passarvi attraverso con gli arti. Una creatura interessata può lanciare incantesimi o effettuare attacchi con armi a distanza o con portata attraverso la barriera.\nSe ti muovi in modo tale che una creatura interessata sia costretta ad attraversare la barriera, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"antimagic-field","name":"Antimagic Field","name_it":"Campo Antimagia","level":8,"level_it":"Livello 8","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale (sfera con raggio di 3 metri)","components":"V, S, M (un pizzico di ferro in polvere o limatura di ferro)","material":"un pizzico di ferro in polvere o limatura di ferro","duration":"Concentrazione, fino a 1 ora","classes":["Cleric","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una sfera invisibile di antimagia con raggio di 3 metri ti circonda. Quest'area è separata dall'energia magica che permea il multiverso. All'interno della sfera, gli incantesimi non possono essere lanciati, le creature evocate scompaiono e perfino gli oggetti magici diventano comuni. Fino al termine dell'incantesimo, la sfera si muove con te, rimanendo centrata su di te.\nGli incantesimi e gli altri effetti magici, eccetto quelli creati da un artefatto o da una divinità, sono soppressi nella sfera e non possono protendersi al suo interno. Uno slot speso per lanciare un incantesimo soppresso viene comunque consumato. Mentre un effetto è soppresso, non funziona, ma il tempo che trascorre soppresso viene conteggiato ai fini della sua durata.\nEffetti Mirati. Gli incantesimi e gli altri effetti magici, come dardo incantato e ammaliare persone, che hanno come bersaglio una creatura o un oggetto nella sfera non hanno alcun effetto su tale bersaglio.\nAree di Magia. L'area di un altro incantesimo o effetto magico, come palla di fuoco, non può estendersi nella sfera. Se la sfera si sovrappone a un'area di magia, la parte dell'area coperta dalla sfera viene soppressa. Per esempio, le fiamme create da un muro di fuoco vengono soppresse all'interno della sfera, creando un varco nel muro se la sovrapposizione è abbastanza ampia.\nIncantesimi. Qualsiasi incantesimo o altro effetto magico attivo su una creatura o un oggetto nella sfera viene soppresso finché la creatura o l'oggetto si trova al suo interno.\nOggetti Magici. Le proprietà e i poteri degli oggetti magici sono soppressi nella sfera. Per esempio, una spada lunga +1 nella sfera funziona come una spada lunga non magica.\nLe proprietà e i poteri di un'arma magica sono soppressi se essa viene usata contro un bersaglio nella sfera o impugnata da un attaccante nella sfera. Se un'arma magica o un munizionamento magico esce completamente dalla sfera (per esempio, se scocchi una freccia magica o lanci una lancia magica contro un bersaglio fuori dalla sfera), la magia dell'oggetto cessa di essere soppressa non appena esce.\nViaggio Magico. Il teletrasporto e il viaggio planare non funzionano nella sfera, sia che la sfera sia la destinazione sia che sia il punto di partenza di tale viaggio magico. Un portale verso un altro luogo, mondo o piano di esistenza, così come un'apertura verso uno spazio extradimensionale come quello creato dall'incantesimo trucco della corda, si chiude temporaneamente mentre si trova nella sfera.\nCreature e Oggetti. Una creatura o un oggetto evocato o creato dalla magia svanisce temporaneamente dall'esistenza nella sfera. Tale creatura riappare immediatamente non appena lo spazio che occupava non è più all'interno della sfera.\nDissolvi Magie. Incantesimi ed effetti magici come dissolvi magie non hanno alcun effetto sulla sfera. Allo stesso modo, le sfere create da diversi incantesimi campo antimagia non si annullano a vicenda.","language":"it","ui_language":"it"},{"id":"antipathy-sympathy","name":"Antipathy/Sympathy","name_it":"Antipatia/Simpatia","level":8,"level_it":"Livello 8","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 ora","range":"18 metri","components":"V, S, M (un grumo di allume imbevuto di aceto per l'effetto antipatia oppure una goccia di miele per l'effetto simpatia)","material":"un grumo di allume imbevuto di aceto per l'effetto antipatia oppure una goccia di miele per l'effetto simpatia","duration":"10 giorni","classes":["Druid","Wizard","Bard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo attrae o respinge le creature a tua scelta. Prendi di mira qualcosa entro gittata: un oggetto o una creatura di taglia Enorme o inferiore, oppure un'area non più grande di un cubo di 60 metri. Specifichi poi un tipo di creatura intelligente, come draghi rossi, goblin o vampiri. Investi il bersaglio di un'aura che attrae o respinge le creature specificate per la durata dell'incantesimo. Scegli antipatia o simpatia come effetto dell'aura.\nAntipatia. L'ammaliamento fa sì che le creature del tipo che hai designato provino l'intenso impulso di abbandonare l'area e di evitare il bersaglio. Quando una tale creatura può vedere il bersaglio o giunge entro 18 metri da esso, deve superare un tiro salvezza su Saggezza o diventa spaventata. La creatura rimane spaventata finché può vedere il bersaglio o si trova entro 18 metri da esso. Mentre è spaventata dal bersaglio, la creatura deve usare il proprio movimento per spostarsi nel punto sicuro più vicino da cui non possa vedere il bersaglio. Se la creatura si allontana di più di 18 metri dal bersaglio e non riesce a vederlo, non è più spaventata, ma torna a esserlo se riacquista la vista del bersaglio o si sposta entro 18 metri da esso.\nSimpatia. L'ammaliamento fa sì che le creature specificate provino l'intenso impulso di avvicinarsi al bersaglio mentre si trovano entro 18 metri da esso o riescono a vederlo. Quando una tale creatura può vedere il bersaglio o giunge entro 18 metri da esso, deve superare un tiro salvezza su Saggezza o usare il proprio movimento a ogni turno per entrare nell'area o portarsi a portata del bersaglio. Una volta fatto ciò, non può allontanarsi volontariamente dal bersaglio.\nSe il bersaglio danneggia o altrimenti nuoce a una creatura interessata, quest'ultima può effettuare un tiro salvezza su Saggezza per terminare l'effetto, come descritto di seguito.\nTerminare l'Effetto. Se una creatura interessata termina il proprio turno mentre non si trova entro 18 metri dal bersaglio né riesce a vederlo, effettua un tiro salvezza su Saggezza. Con un tiro riuscito, la creatura non è più interessata dal bersaglio e riconosce la sensazione di repulsione o attrazione come magica. Inoltre, una creatura interessata dall'incantesimo può effettuare un nuovo tiro salvezza su Saggezza ogni 24 ore finché l'incantesimo persiste.\nUna creatura che supera con successo il tiro salvezza contro questo effetto ne è immune per 1 minuto, dopodiché può esserne nuovamente interessata.","language":"it","ui_language":"it"},{"id":"arcane-eye","name":"Arcane Eye","name_it":"Occhio Arcano","level":4,"level_it":"Livello 4","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un po' di pelo di pipistrello)","material":"un po' di pelo di pipistrello","duration":"Concentrazione, fino a 1 ora","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un occhio magico invisibile entro gittata che fluttua nell'aria per la durata dell'incantesimo.\nRicevi mentalmente le informazioni visive dall'occhio, che ha vista normale e scurovisione fino a 9 metri. L'occhio può guardare in ogni direzione.\nCon un'azione, puoi muovere l'occhio fino a 9 metri in qualsiasi direzione. Non c'è limite alla distanza a cui l'occhio può allontanarsi da te, ma non può entrare in un altro piano di esistenza. Una barriera solida blocca il movimento dell'occhio, ma l'occhio può passare attraverso un'apertura piccola fino a 2,5 cm di diametro.","language":"it","ui_language":"it"},{"id":"arcane-gate","name":"Arcane Gate","name_it":"Cancello Arcano","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"150 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Crei dei portali di teletrasporto collegati che rimangono aperti per la durata dell'incantesimo. Scegli due punti sul terreno che puoi vedere, un punto entro 3 metri da te e un punto entro 150 metri da te. Su ciascun punto si apre un portale circolare del diametro di 3 metri. Se il portale dovesse aprirsi nello spazio occupato da una creatura, l'incantesimo fallisce e il lancio va perduto.\nI portali sono anelli luminosi bidimensionali pieni di nebbia, che fluttuano a pochi centimetri dal terreno e perpendicolari a esso nei punti che scegli. Un anello è visibile solo da un lato (a tua scelta), che è il lato che funziona da portale.\nQualsiasi creatura o oggetto che entra in un portale esce dall'altro portale come se i due fossero adiacenti; attraversare un portale dal lato che non funge da portale non ha alcun effetto. La nebbia che riempie ciascun portale è opaca e impedisce la visuale attraverso di esso. Nel tuo turno, puoi ruotare gli anelli con un'azione bonus in modo che il lato attivo sia rivolto in una direzione diversa.","language":"it","ui_language":"it"},{"id":"arcane-lock","name":"Arcane Lock","name_it":"Serratura Arcana","level":2,"level_it":"Livello 2","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (polvere d'oro del valore di almeno 25 mo, che l'incantesimo consuma)","material":"polvere d'oro del valore di almeno 25 mo, che l'incantesimo consuma","duration":"Finché non viene dissolto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una porta, una finestra, un cancello, un baule o un altro varco chiuso, ed esso viene serrato per la durata dell'incantesimo. Tu e le creature che designi quando lanci questo incantesimo potete aprire l'oggetto normalmente. Puoi anche stabilire una parola d'ordine che, se pronunciata entro 1,5 metri dall'oggetto, sopprime questo incantesimo per 1 minuto. Altrimenti, l'oggetto è invalicabile finché non viene rotto o l'incantesimo non viene dissolto o soppresso. Lanciare bussare sull'oggetto sopprime serratura arcana per 10 minuti.\nMentre è interessato da questo incantesimo, l'oggetto è più difficile da rompere o forzare; la CD per romperlo o per scassinare le serrature su di esso aumenta di 10.","language":"it","ui_language":"it"},{"id":"armor-of-agathys","name":"Armor of Agathys","name_it":"Armatura di Agathys","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (una tazza d'acqua)","material":"una tazza d'acqua","duration":"1 ora","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Una forza magica protettiva ti circonda, manifestandosi come una brina spettrale che ricopre te e il tuo equipaggiamento. Ottieni 5 punti ferita temporanei per la durata. Se una creatura ti colpisce con un attacco in mischia mentre possiedi questi punti ferita, la creatura subisce 5 danni da freddo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, sia i punti ferita temporanei sia i danni da freddo aumentano di 5 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"arms-of-hadar","name":"Arms of Hadar","name_it":"Braccia di Hadar","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 3 metri)","components":"V, S","material":"","duration":"Istantanea","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Invochi il potere di Hadar, la Fame Oscura.\nTentacoli di energia oscura erompono da te e flagellano tutte le creature entro 3 metri da te. Ogni creatura in quell'area deve effettuare un tiro salvezza su Forza. Con un tiro fallito, il bersaglio subisce 2d6 danni necrotici e non può effettuare reazioni fino al suo prossimo turno. Con un tiro riuscito, la creatura subisce metà dei danni, ma non subisce altri effetti.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"ashardalon-s-stride","name":"Ashardalon's Stride","name_it":"Falcata di Ashardalon","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"Il lanciatore ottiene una velocità esplosiva di +6 metri e infligge 1d6 danni da fuoco entro 1,5 metri durante il suo movimento (velocità e danni in base al livello).","language":"it","ui_language":"it"},{"id":"astral-projection","name":"Astral Projection","name_it":"Proiezione Astrale","level":9,"level_it":"Livello 9","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 ora","range":"3 metri","components":"V, S, M (per ogni creatura interessata da questo incantesimo, devi fornire un giacinto del valore di almeno 1.000 mo e una barra d'argento finemente intagliata del valore di almeno 100 mo, che l'incantesimo consuma per intero)","material":"per ogni creatura interessata da questo incantesimo, devi fornire un giacinto del valore di almeno 1.000 mo e una barra d'argento finemente intagliata del valore di almeno 100 mo, che l'incantesimo consuma per intero","duration":"Speciale","classes":["Cleric","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tu e un massimo di otto creature consenzienti entro gittata proiettate i vostri corpi astrali nel Piano Astrale (l'incantesimo fallisce e il lancio è sprecato se ti trovi già su quel piano). Il corpo materiale che lasci alle spalle è privo di sensi e in uno stato di animazione sospesa; non ha bisogno di cibo o aria e non invecchia.\nIl tuo corpo astrale somiglia in quasi tutto alla tua forma mortale, riproducendo le tue statistiche di gioco e i tuoi averi. La differenza principale è l'aggiunta di un cordone argenteo che si estende da fra le tue scapole e ti segue, svanendo fino all'invisibilità dopo circa 30 centimetri. Questo cordone è il tuo legame con il tuo corpo materiale. Finché il legame rimane intatto, puoi ritrovare la via di casa. Se il cordone viene reciso — cosa che può accadere solo quando un effetto lo afferma espressamente — la tua anima e il tuo corpo si separano, uccidendoti all'istante.\nLa tua forma astrale può viaggiare liberamente attraverso il Piano Astrale e può attraversare i portali presenti che conducono a qualsiasi altro piano. Se entri in un nuovo piano o torni al piano in cui ti trovavi quando hai lanciato questo incantesimo, il tuo corpo e i tuoi averi vengono trasportati lungo il cordone argenteo, permettendoti di rientrare nel tuo corpo quando entri nel nuovo piano. La tua forma astrale è un'incarnazione separata. Qualsiasi danno o altro effetto che la riguarda non ha alcun effetto sul tuo corpo fisico, né persiste quando vi fai ritorno.\nL'incantesimo termina per te e per i tuoi compagni quando usi la tua azione per congedarlo. Quando l'incantesimo termina, la creatura interessata torna al proprio corpo fisico e si risveglia.\nL'incantesimo potrebbe anche terminare in anticipo per te o per uno dei tuoi compagni. Un incantesimo dissolvi magie riuscito, usato contro un corpo astrale o fisico, termina l'incantesimo per quella creatura. Se il corpo originale di una creatura o la sua forma astrale scendono a 0 punti ferita, l'incantesimo termina per quella creatura. Se l'incantesimo termina e il cordone argenteo è intatto, il cordone richiama la forma astrale della creatura al suo corpo, ponendo fine al suo stato di animazione sospesa.\nSe vieni riportato al tuo corpo prematuramente, i tuoi compagni rimangono nelle loro forme astrali e devono trovare da soli la via per tornare ai loro corpi, di solito scendendo a 0 punti ferita.","language":"it","ui_language":"it"},{"id":"augury","name":"Augury","name_it":"Presagio","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 minuto","range":"Personale","components":"V, S, M (bastoncini, ossa o gettoni simili appositamente contrassegnati, del valore di almeno 25 mo)","material":"bastoncini, ossa o gettoni simili appositamente contrassegnati, del valore di almeno 25 mo","duration":"Istantanea","classes":["Cleric","Druid","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"},{"name":"Wizard","name_it":"Mago","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Lanciando bastoncini intarsiati di gemme, gettando ossa di drago, disponendo carte ornate o impiegando qualche altro strumento divinatorio, ricevi un presagio da un'entità ultraterrena riguardo ai risultati di una specifica linea d'azione che intendi intraprendere entro i prossimi 30 minuti. Il DM sceglie tra i seguenti presagi possibili:\n• Fausto, per risultati positivi\n• Infausto, per risultati negativi\n• Fausto e infausto, per risultati sia positivi sia negativi\n• Nulla, per risultati né particolarmente positivi né negativi\nL'incantesimo non tiene conto di eventuali circostanze che potrebbero modificare l'esito, come il lancio di altri incantesimi o la perdita o l'aggiunta di un compagno.\nSe lanci l'incantesimo due o più volte prima di completare il tuo prossimo riposo lungo, c'è una probabilità cumulativa del 25 per cento per ogni lancio dopo il primo che tu ottenga una lettura casuale. Il DM effettua questo tiro in segreto.","language":"it","ui_language":"it"},{"id":"aura-of-life","name":"Aura of Life","name_it":"Aura di Vita","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 9 metri)","components":"V","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Paladin","Cleric"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore","description":"Un'energia che preserva la vita si irradia da te in un'aura con un raggio di 9 metri. Fino al termine dell'incantesimo, l'aura si muove con te, rimanendo centrata su di te. Ogni creatura non ostile nell'aura (incluso te) ha resistenza ai danni necrotici, e il suo massimo dei punti ferita non può essere ridotto. Inoltre, una creatura vivente non ostile recupera 1 punto ferita quando inizia il proprio turno nell'aura con 0 punti ferita.","language":"it","ui_language":"it"},{"id":"aura-of-purity","name":"Aura of Purity","name_it":"Aura di Purezza","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 9 metri)","components":"V","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Paladin","Cleric"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore","description":"Un'energia purificatrice si irradia da te in un'aura con un raggio di 9 metri. Fino al termine dell'incantesimo, l'aura si muove con te, rimanendo centrata su di te. Ogni creatura non ostile nell'aura (incluso te) non può ammalarsi, ha resistenza ai danni da veleno e ha vantaggio ai tiri salvezza contro gli effetti che causano una qualsiasi delle seguenti condizioni: accecato, affascinato, assordato, spaventato, paralizzato, avvelenato e stordito.","language":"it","ui_language":"it"},{"id":"aura-of-vitality","name":"Aura of Vitality","name_it":"Aura di Vitalità","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 9 metri)","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin","Cleric","Druid"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":true,"source":"TCoE"},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore","description":"Un'energia curativa si irradia da te in un'aura con un raggio di 9 metri. Fino al termine dell'incantesimo, l'aura si muove con te, rimanendo centrata su di te. Puoi usare un'azione bonus per far recuperare 2d6 punti ferita a una creatura nell'aura (incluso te).","language":"it","ui_language":"it"},{"id":"awaken","name":"Awaken","name_it":"Risvegliare","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"8 ore","range":"Contatto","components":"V, S, M (un'agata del valore di almeno 1.000 mo, che l'incantesimo consuma)","material":"un'agata del valore di almeno 1.000 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Bard","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Dopo aver trascorso il tempo di lancio a tracciare percorsi magici all'interno di una gemma preziosa, tocchi una bestia o una pianta di taglia Enorme o inferiore. Il bersaglio deve avere un punteggio di Intelligenza pari a 3 o inferiore, oppure non avere alcun punteggio di Intelligenza. Il bersaglio ottiene un'Intelligenza di 10. Il bersaglio ottiene anche la capacità di parlare una lingua che conosci. Se il bersaglio è una pianta, ottiene la capacità di muovere arti, radici, viticci, rampicanti e simili, e ottiene sensi analoghi a quelli di un essere umano. Il tuo DM sceglie statistiche appropriate per la pianta risvegliata, come quelle dell'arbusto risvegliato o dell'albero risvegliato.\nLa bestia o la pianta risvegliata è affascinata da te per 30 giorni o finché tu o i tuoi compagni non le fate qualcosa di dannoso. Quando la condizione di affascinato termina, la creatura risvegliata sceglie se rimanere amichevole nei tuoi confronti, in base a come l'hai trattata mentre era affascinata.","language":"it","ui_language":"it"},{"id":"bane","name":"Bane","name_it":"Rovina","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una goccia di sangue)","material":"una goccia di sangue","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Cleric"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fino a tre creature a tua scelta che puoi vedere entro gittata devono effettuare tiri salvezza su Carisma. Ogni volta che un bersaglio che ha fallito questo tiro salvezza effettua un tiro per colpire o un tiro salvezza prima che l'incantesimo termini, il bersaglio deve tirare un d4 e sottrarre il numero ottenuto dal tiro per colpire o dal tiro salvezza.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"banishing-smite","name":"Banishing Smite","name_it":"Colpo Bandente","level":5,"level_it":"Livello 5","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci una creatura con un attacco con un'arma prima che questo incantesimo termini, la tua arma crepita di forza e l'attacco infligge 5d10 danni da forza aggiuntivi al bersaglio. Inoltre, se questo attacco riduce il bersaglio a 50 punti ferita o meno, lo bandisci. Se il bersaglio è originario di un piano di esistenza diverso da quello in cui ti trovi, il bersaglio scompare, facendo ritorno al suo piano natale. Se il bersaglio è originario del piano in cui ti trovi, la creatura svanisce in un semipiano innocuo. Mentre si trova lì, il bersaglio è incapacitato. Vi rimane finché l'incantesimo non termina, momento in cui il bersaglio riappare nello spazio che aveva lasciato o nello spazio libero più vicino se quello spazio è occupato.","language":"it","ui_language":"it"},{"id":"banishment","name":"Banishment","name_it":"Bando","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un oggetto sgradito al bersaglio)","material":"un oggetto sgradito al bersaglio","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Paladin","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di inviare una creatura che puoi vedere entro gittata in un altro piano di esistenza. Il bersaglio deve superare un tiro salvezza su Carisma o viene bandito.\nSe il bersaglio è originario del piano di esistenza in cui ti trovi, bandisci il bersaglio in un semipiano innocuo. Mentre si trova lì, il bersaglio è incapacitato. Il bersaglio vi rimane finché l'incantesimo non termina, momento in cui riappare nello spazio che aveva lasciato o nello spazio libero più vicino se quello spazio è occupato.\nSe il bersaglio è originario di un piano di esistenza diverso da quello in cui ti trovi, il bersaglio viene bandito con un debole schiocco, facendo ritorno al suo piano natale. Se l'incantesimo termina prima che sia trascorso 1 minuto, il bersaglio riappare nello spazio che aveva lasciato o nello spazio libero più vicino se quello spazio è occupato. Altrimenti, il bersaglio non ritorna.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"barkskin","name":"Barkskin","name_it":"Pelle Cortecciosa","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (una manciata di corteccia di quercia)","material":"una manciata di corteccia di quercia","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente. Fino al termine dell'incantesimo, la pelle del bersaglio assume un aspetto ruvido e simile alla corteccia, e la CA del bersaglio non può essere inferiore a 16, indipendentemente dal tipo di armatura che indossa.","language":"it","ui_language":"it"},{"id":"beacon-of-hope","name":"Beacon of Hope","name_it":"Faro di Speranza","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo conferisce speranza e vitalità. Scegli un numero qualsiasi di creature entro gittata. Per la durata, ogni bersaglio ha vantaggio ai tiri salvezza su Saggezza e ai tiri salvezza contro morte, e recupera il numero massimo possibile di punti ferita da qualsiasi guarigione.","language":"it","ui_language":"it"},{"id":"beast-bond","name":"Beast Bond","name_it":"Legame Bestiale","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un po' di pelo avvolto in un panno)","material":"un po' di pelo avvolto in un panno","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Stabilisci un legame telepatico con una bestia che tocchi e che ti sia amichevole o sia affascinata da te. L'incantesimo fallisce se l'Intelligenza della bestia è pari o superiore a 4. Fino al termine dell'incantesimo, il legame è attivo mentre tu e la bestia siete nella reciproca linea di vista. Attraverso il legame, la bestia può comprendere i tuoi messaggi telepatici e può comunicarti telepaticamente in risposta emozioni e concetti semplici. Mentre il legame è attivo, la bestia ottiene vantaggio ai tiri per colpire contro qualsiasi creatura entro 1,5 metri da te che tu possa vedere.","language":"it","ui_language":"it"},{"id":"beast-sense","name":"Beast Sense","name_it":"Senso Bestiale","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Contatto","components":"S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Tocchi una bestia consenziente. Per la durata dell'incantesimo, puoi usare la tua azione per vedere attraverso gli occhi della bestia e udire ciò che essa ode, e continuare a farlo finché non usi la tua azione per tornare ai tuoi sensi normali. Mentre percepisci attraverso i sensi della bestia, ottieni i benefici di qualsiasi senso speciale posseduto da quella creatura, anche se sei accecato e assordato rispetto a ciò che ti circonda.","language":"it","ui_language":"it"},{"id":"bestow-curse","name":"Bestow Curse","name_it":"Infliggere Maledizione","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Cleric","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura, e quella creatura deve superare un tiro salvezza su Saggezza o viene maledetta per la durata dell'incantesimo. Quando lanci questo incantesimo, scegli la natura della maledizione tra le seguenti opzioni:\n• Scegli un punteggio di caratteristica. Mentre è maledetto, il bersaglio ha svantaggio alle prove di caratteristica e ai tiri salvezza effettuati con quel punteggio di caratteristica.\n• Mentre è maledetto, il bersaglio ha svantaggio ai tiri per colpire contro di te.\n• Mentre è maledetto, il bersaglio deve effettuare un tiro salvezza su Saggezza all'inizio di ogni suo turno. Se fallisce, spreca la propria azione di quel turno senza fare nulla.\n• Mentre il bersaglio è maledetto, i tuoi attacchi e i tuoi incantesimi infliggono 1d8 danni necrotici aggiuntivi al bersaglio.\nUn incantesimo rimuovere maledizione pone fine a questo effetto. A discrezione del DM, puoi scegliere un effetto di maledizione alternativo, che però non dovrebbe essere più potente di quelli descritti sopra. Il DM ha l'ultima parola sull'effetto di una tale maledizione.\nAi Livelli Superiori. Se lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, la durata diventa concentrazione, fino a 10 minuti. Se usi uno slot incantesimo di 5° livello o superiore, la durata diventa 8 ore. Se usi uno slot incantesimo di 7° livello o superiore, la durata diventa 24 ore. Se usi uno slot incantesimo di 9° livello, l'incantesimo dura finché non viene dissolto. Usare uno slot incantesimo di 5° livello o superiore conferisce una durata che non richiede concentrazione.","language":"it","ui_language":"it"},{"id":"bigby-s-hand","name":"Bigby's Hand","name_it":"Mano di Bigby","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un guscio d'uovo e un guanto di pelle di serpente)","material":"un guscio d'uovo e un guanto di pelle di serpente","duration":"Concentrazione, fino a 1 minuto","classes":["Wizard","Sorcerer"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Crei una grande mano di forza scintillante e traslucida in uno spazio libero che puoi vedere entro gittata. La mano dura per la durata dell'incantesimo e si muove al tuo comando, imitando i movimenti della tua stessa mano.\nLa mano è un oggetto che ha CA 20 e punti ferita pari al tuo massimo dei punti ferita. Se scende a 0 punti ferita, l'incantesimo termina. Ha una Forza di 26 (+8) e una Destrezza di 10 (+0). La mano non riempie il proprio spazio.\nQuando lanci l'incantesimo e come azione bonus nei tuoi turni successivi, puoi muovere la mano fino a 18 metri e poi produrre con essa uno dei seguenti effetti.\nPugno Serrato. La mano colpisce una creatura o un oggetto entro 1,5 metri da essa. Effettua un attacco con incantesimo in mischia per la mano usando le tue statistiche di gioco. Se colpisce, il bersaglio subisce 4d8 danni da forza.\nMano Vigorosa. La mano tenta di spingere una creatura entro 1,5 metri da essa in una direzione a tua scelta. Effettua una prova con la Forza della mano contrapposta alla prova di Forza (Atletica) del bersaglio. Se il bersaglio è di taglia Media o inferiore, hai vantaggio alla prova. Se hai successo, la mano spinge il bersaglio fino a 1,5 metri più un numero di metri pari a una volta e mezza il tuo modificatore di caratteristica da incantatore. La mano si muove insieme al bersaglio per rimanere entro 1,5 metri da esso.\nMano Afferrante. La mano tenta di afferrare una creatura di taglia Enorme o inferiore entro 1,5 metri da essa. Usi il punteggio di Forza della mano per risolvere la lotta. Se il bersaglio è di taglia Media o inferiore, hai vantaggio alla prova. Mentre la mano sta tenendo in lotta il bersaglio, puoi usare un'azione bonus per far sì che la mano lo stritoli. Quando lo fai, il bersaglio subisce danni contundenti pari a 2d6 + il tuo modificatore di caratteristica da incantatore.\nMano Frapponente. La mano si frappone tra te e una creatura a tua scelta finché non impartisci alla mano un comando diverso. La mano si muove per restare tra te e il bersaglio, fornendoti metà copertura contro il bersaglio. Il bersaglio non può muoversi attraverso lo spazio della mano se il suo punteggio di Forza è pari o inferiore a quello della mano. Se il suo punteggio di Forza è superiore a quello della mano, il bersaglio può muoversi verso di te attraverso lo spazio della mano, ma quello spazio è terreno difficile per il bersaglio.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, i danni dell'opzione pugno serrato aumentano di 2d8 e i danni della mano afferrante aumentano di 2d6 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"blade-barrier","name":"Blade Barrier","name_it":"Barriera di Lame","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un muro verticale di lame vorticanti e affilate come rasoi, fatte di energia magica. Il muro appare entro gittata e dura per la durata dell'incantesimo. Puoi creare un muro dritto lungo fino a 30 metri, alto 6 metri e spesso 1,5 metri, oppure un muro ad anello con un diametro massimo di 18 metri, alto 6 metri e spesso 1,5 metri. Il muro fornisce tre quarti di copertura alle creature dietro di esso, e il suo spazio è terreno difficile.\nQuando una creatura entra per la prima volta nell'area del muro in un turno o vi inizia il proprio turno, deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, la creatura subisce 6d10 danni taglienti. Con un tiro riuscito, la creatura subisce metà dei danni.","language":"it","ui_language":"it"},{"id":"blade-of-disaster","name":"Blade of Disaster","name_it":"Lama del Disastro","level":9,"level_it":"Livello 9","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Crei una fenditura planare a forma di lama lunga circa 90 centimetri in uno spazio libero che puoi vedere entro gittata. La lama dura per la durata dell'incantesimo. Quando lanci questo incantesimo, puoi effettuare fino a due attacchi con incantesimo in mischia con la lama, ciascuno contro una creatura, un oggetto sciolto o una struttura entro 1,5 metri dalla lama. Se colpisce, il bersaglio subisce 4d12 danni da forza. Questo attacco mette a segno un colpo critico se il numero ottenuto sul d20 è 18 o superiore. Con un colpo critico, la lama infligge 8d12 danni da forza aggiuntivi (per un totale di 12d12 danni da forza).\nCome azione bonus nel tuo turno, puoi muovere la lama fino a 9 metri verso uno spazio libero che puoi vedere e poi effettuare di nuovo con essa fino a due attacchi con incantesimo in mischia.\nLa lama può attraversare innocuamente qualsiasi barriera, incluso un muro di forza.","language":"it","ui_language":"it"},{"id":"blade-ward","name":"Blade Ward","name_it":"Difesa dalle Lame","level":0,"level_it":"Trucchetto","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"1 round","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Tendi la mano e tracci nell'aria un sigillo di protezione. Fino al termine del tuo prossimo turno, hai resistenza ai danni contundenti, perforanti e taglienti inflitti dagli attacchi con armi.","language":"it","ui_language":"it"},{"id":"bless","name":"Bless","name_it":"Benedizione","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (uno spruzzo di acqua santa)","material":"uno spruzzo di acqua santa","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Benedici fino a tre creature a tua scelta entro gittata. Ogni volta che un bersaglio effettua un tiro per colpire o un tiro salvezza prima che l'incantesimo termini, il bersaglio può tirare un d4 e aggiungere il numero ottenuto al tiro per colpire o al tiro salvezza.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"blight","name":"Blight","name_it":"Cancrena","level":4,"level_it":"Livello 4","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un'energia necromantica investe una creatura a tua scelta che puoi vedere entro gittata, prosciugandone l'umidità e la vitalità. Il bersaglio deve effettuare un tiro salvezza su Costituzione. Il bersaglio subisce 8d8 danni necrotici se fallisce il tiro salvezza, o la metà dei danni se lo supera. Questo incantesimo non ha effetto sui non morti o sui costrutti. Se prendi di mira una creatura vegetale o una pianta magica, essa effettua il tiro salvezza con svantaggio e l'incantesimo le infligge danni massimi.\nSe prendi di mira una pianta non magica che non sia una creatura, come un albero o un arbusto, essa non effettua alcun tiro salvezza; semplicemente avvizzisce e muore.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"blinding-smite","name":"Blinding Smite","name_it":"Colpo Accecante","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci una creatura con un attacco con un'arma da mischia durante la durata di questo incantesimo, la tua arma divampa di luce intensa e l'attacco infligge 3d8 danni radiosi aggiuntivi al bersaglio. Inoltre, il bersaglio deve superare un tiro salvezza su Costituzione o resta accecato fino al termine dell'incantesimo.\nUna creatura accecata da questo incantesimo effettua un altro tiro salvezza su Costituzione al termine di ogni suo turno. Con un tiro riuscito, non è più accecata.","language":"it","ui_language":"it"},{"id":"blindness-deafness","name":"Blindness/Deafness","name_it":"Cecità/Sordità","level":2,"level_it":"Livello 2","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V","material":"","duration":"1 minuto","classes":["Bard","Cleric","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Puoi accecare o assordare un nemico. Scegli una creatura che puoi vedere entro gittata: essa deve effettuare un tiro salvezza su Costituzione. Se fallisce, il bersaglio viene accecato o assordato (a tua scelta) per la durata. Al termine di ogni suo turno, il bersaglio può effettuare un tiro salvezza su Costituzione. Con un successo, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"blink","name":"Blink","name_it":"Lampeggiare","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tira un d20 al termine di ogni tuo turno per la durata dell'incantesimo. Con un risultato di 11 o superiore, svanisci dal tuo attuale piano di esistenza e compari nel Piano Etereo (l'incantesimo fallisce e il lancio è sprecato se ti trovavi già su quel piano). All'inizio del tuo prossimo turno, e quando l'incantesimo termina se ti trovi nel Piano Etereo, ritorni in uno spazio libero a tua scelta che puoi vedere entro 3 metri dallo spazio da cui eri svanito. Se non è disponibile alcuno spazio libero entro tale distanza, compari nello spazio libero più vicino (scelto a caso se più spazi sono ugualmente vicini). Puoi congedare questo incantesimo con un'azione.\nMentre ti trovi nel Piano Etereo, puoi vedere e udire il piano da cui provieni, che appare in tonalità di grigio, e non puoi vedere nulla che si trovi a più di 18 metri di distanza. Puoi influenzare ed essere influenzato solo da altre creature nel Piano Etereo. Le creature che non si trovano lì non possono percepirti né interagire con te, a meno che non ne abbiano la capacità.","language":"it","ui_language":"it"},{"id":"blur","name":"Blur","name_it":"Sfocatura","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Il tuo corpo diventa sfocato, mutando e ondeggiando agli occhi di chiunque possa vederti. Per la durata, qualsiasi creatura ha svantaggio ai tiri per colpire contro di te. Un attaccante è immune a questo effetto se non si affida alla vista, come con la vista cieca, o se può vedere attraverso le illusioni, come con la vista pura.","language":"it","ui_language":"it"},{"id":"bones-of-the-earth","name":"Bones of the Earth","name_it":"Ossa della Terra","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fai erompere fino a sei pilastri di pietra da punti del terreno che puoi vedere entro gittata. Ogni pilastro è un cilindro con un diametro di 1,5 metri e un'altezza massima di 9 metri. Il terreno in cui appare un pilastro deve essere abbastanza ampio da contenerne il diametro, e puoi prendere di mira il terreno sotto una creatura se quella creatura è di taglia Media o inferiore. Ogni pilastro ha CA 5 e 30 punti ferita. Quando viene ridotto a 0 punti ferita, un pilastro si sgretola in macerie, creando un'area di terreno difficile con un raggio di 3 metri che dura finché le macerie non vengono rimosse. Ogni porzione dell'area di 1,5 metri di diametro richiede almeno 1 minuto per essere sgombrata a mano.\nSe un pilastro viene creato sotto una creatura, quella creatura deve superare un tiro salvezza su Destrezza o viene sollevata dal pilastro. Una creatura può scegliere di fallire il tiro salvezza.\nSe a un pilastro viene impedito di raggiungere la propria altezza massima a causa di un soffitto o di un altro ostacolo, una creatura sul pilastro subisce 6d6 danni contundenti ed è trattenuta, schiacciata tra il pilastro e l'ostacolo. La creatura trattenuta può usare un'azione per effettuare una prova di Forza o di Destrezza (a scelta della creatura) contro la CD del tiro salvezza dell'incantesimo. Con un successo, la creatura non è più trattenuta e deve scendere dal pilastro o caderne.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, puoi creare due pilastri aggiuntivi per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"booming-blade","name":"Booming Blade","name_it":"Lama Rimbombante","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 1,5 metri)","components":"V, M (un'arma da mischia del valore di almeno 1 ma)","material":"un'arma da mischia del valore di almeno 1 ma","duration":"1 round","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Brandisci l'arma usata nel lancio dell'incantesimo ed effettui con essa un attacco in mischia contro una creatura entro 1,5 metri da te. Se colpisci, il bersaglio subisce i normali effetti dell'attacco con l'arma e poi viene avvolto da un'energia rimbombante fino all'inizio del tuo prossimo turno. Se il bersaglio si sposta volontariamente di 1,5 metri o più prima di allora, subisce 1d8 danni da tuono e l'incantesimo termina.\nI danni di questo incantesimo aumentano quando raggiungi determinati livelli. Al 5° livello, l'attacco in mischia infligge 1d8 danni da tuono aggiuntivi al bersaglio se colpisce, e i danni che il bersaglio subisce per essersi spostato aumentano a 2d8. Entrambi i tiri per i danni aumentano di 1d8 all'11° livello (2d8 e 3d8) e di nuovo al 17° livello (3d8 e 4d8).","language":"it","ui_language":"it"},{"id":"branding-smite","name":"Branding Smite","name_it":"Colpo Marchiante","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"La prossima volta che colpisci una creatura con un attacco con un'arma prima che questo incantesimo termini, l'arma riluce di radiosità astrale mentre colpisci. L'attacco infligge 2d6 danni radiosi aggiuntivi al bersaglio, che diventa visibile se è invisibile, e il bersaglio emana luce fioca in un raggio di 1,5 metri e non può diventare invisibile fino al termine dell'incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aggiuntivi aumentano di 1d6 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"burning-hands","name":"Burning Hands","name_it":"Mani Brucianti","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 4,5 metri)","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Mentre tieni le mani con i pollici a contatto e le dita aperte, un sottile lenzuolo di fiamme si proietta dalla punta delle tue dita protese. Ogni creatura in un cono di 4,5 metri deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 3d6 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nIl fuoco incendia qualsiasi oggetto infiammabile nell'area che non sia indossato né trasportato.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"call-lightning","name":"Call Lightning","name_it":"Chiamare il Fulmine","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una nube temporalesca appare a forma di cilindro alto 3 metri con un raggio di 18 metri, centrata su un punto che puoi vedere entro gittata direttamente sopra di te. L'incantesimo fallisce se non riesci a vedere un punto nell'aria in cui la nube temporalesca potrebbe apparire (per esempio, se ti trovi in una stanza che non può contenere la nube).\nQuando lanci l'incantesimo, scegli un punto che puoi vedere sotto la nube. Un fulmine guizza dalla nube verso quel punto. Ogni creatura entro 1,5 metri da quel punto deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 3d10 danni da fulmine se fallisce il tiro salvezza, o la metà dei danni se lo supera. A ogni tuo turno, fino al termine dell'incantesimo, puoi usare la tua azione per richiamare un fulmine in questo modo, prendendo di mira lo stesso punto o uno diverso.\nSe ti trovi all'aperto in condizioni di tempesta quando lanci questo incantesimo, l'incantesimo ti dà il controllo sulla tempesta esistente invece di crearne una nuova. In tali condizioni, i danni dell'incantesimo aumentano di 1d10.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d10 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"calm-emotions","name":"Calm Emotions","name_it":"Calmare le Emozioni","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Cleric"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di sopprimere le emozioni forti in un gruppo di persone. Ogni umanoide in una sfera con raggio di 6 metri centrata su un punto a tua scelta entro gittata deve effettuare un tiro salvezza su Carisma; una creatura può scegliere di fallire questo tiro salvezza se lo desidera. Se una creatura fallisce il tiro salvezza, scegli uno dei due seguenti effetti.\nPuoi sopprimere qualsiasi effetto che renda un bersaglio affascinato o spaventato. Quando questo incantesimo termina, ogni effetto soppresso riprende, a patto che nel frattempo la sua durata non sia scaduta.\nIn alternativa, puoi rendere un bersaglio indifferente nei confronti di creature a tua scelta verso cui è ostile. Questa indifferenza termina se il bersaglio viene attaccato o danneggiato da un incantesimo, o se assiste al ferimento di uno dei suoi amici. Quando l'incantesimo termina, la creatura torna a essere ostile, a meno che il DM non stabilisca altrimenti.","language":"it","ui_language":"it"},{"id":"catapult","name":"Catapult","name_it":"Catapulta","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un oggetto del peso compreso tra 0,5 e 2,5 chilogrammi entro gittata che non sia indossato né trasportato. L'oggetto vola in linea retta fino a 27 metri nella direzione che scegli prima di cadere a terra, fermandosi prima se impatta contro una superficie solida. Se l'oggetto dovesse colpire una creatura, quella creatura deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, l'oggetto colpisce il bersaglio e smette di muoversi. Quando l'oggetto colpisce qualcosa, l'oggetto e ciò che colpisce subiscono ciascuno 3d8 danni contundenti.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, il peso massimo degli oggetti che puoi prendere di mira con questo incantesimo aumenta di 2,5 chilogrammi e i danni aumentano di 1d8 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"catnap","name":"Catnap","name_it":"Pisolino","level":3,"level_it":"Livello 3","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"S, M (un pizzico di sabbia)","material":"un pizzico di sabbia","duration":"10 minuti","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Compi un gesto rilassante e fino a tre creature consenzienti a tua scelta che puoi vedere entro gittata cadono prive di sensi per la durata dell'incantesimo. L'incantesimo termina in anticipo su un bersaglio se questo subisce danni o se qualcuno usa un'azione per scuoterlo o schiaffeggiarlo per svegliarlo. Se un bersaglio rimane privo di sensi per l'intera durata, ottiene il beneficio di un riposo breve e non può essere nuovamente interessato da questo incantesimo finché non completa un riposo lungo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, puoi prendere di mira una creatura consenziente aggiuntiva per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"cause-fear","name":"Cause Fear","name_it":"Provocare Paura","level":1,"level_it":"Livello 1","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Risvegli il senso della mortalità in una creatura che puoi vedere entro gittata. Un costrutto o un non morto è immune a questo effetto. Il bersaglio deve superare un tiro salvezza su Saggezza o diventa spaventato da te fino al termine dell'incantesimo. Il bersaglio spaventato può ripetere il tiro salvezza al termine di ogni suo turno, ponendo fine all'effetto su di sé con un successo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 1°.\nLe creature devono trovarsi entro 9 metri l'una dall'altra quando le prendi di mira.","language":"it","ui_language":"it"},{"id":"ceremony","name":"Ceremony","name_it":"Cerimonia","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":true,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (argento in polvere del valore di 25 mo, che l'incantesimo consuma)","material":"argento in polvere del valore di 25 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Esegui una di diverse cerimonie religiose. Quando lanci l'incantesimo, scegli una delle seguenti cerimonie, il cui bersaglio deve trovarsi entro 3 metri da te per tutta la durata del lancio.\nEspiazione. Tocchi una creatura consenziente il cui allineamento è cambiato ed effettui una prova di Saggezza (Intuizione) con CD 20. Con una prova riuscita, riporti il bersaglio al suo allineamento originale.\nBenedire l'Acqua. Tocchi una fiala d'acqua e fai sì che diventi acqua santa.\nEtà Adulta. Tocchi un umanoide che è un giovane adulto. Per le 24 ore successive, ogni volta che il bersaglio effettua una prova di caratteristica, può tirare un d4 e aggiungere il numero ottenuto alla prova di caratteristica. Una creatura può beneficiare di questo rito una sola volta.\nConsacrazione. Tocchi un umanoide che desidera consacrarsi al servizio del tuo dio. Per le 24 ore successive, ogni volta che il bersaglio effettua un tiro salvezza, può tirare un d4 e aggiungere il numero ottenuto al tiro salvezza. Una creatura può beneficiare di questo rito una sola volta.\nRito Funebre. Tocchi un cadavere e, per i 7 giorni successivi, il bersaglio non può diventare un non morto con alcun mezzo che non sia un incantesimo desiderio.\nMatrimonio. Tocchi umanoidi adulti che desiderano essere uniti in matrimonio. Per i 7 giorni successivi, ogni bersaglio ottiene un bonus di +2 alla CA mentre si trovano entro 9 metri l'uno dall'altro. Una creatura può beneficiare nuovamente di questo rito solo se rimasta vedova.","language":"it","ui_language":"it"},{"id":"chain-lightning","name":"Chain Lightning","name_it":"Fulmine a Catena","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (un po' di pelo; un pezzo d'ambra, di vetro o una bacchetta di cristallo; e tre spilli d'argento)","material":"un po' di pelo; un pezzo d'ambra, di vetro o una bacchetta di cristallo; e tre spilli d'argento","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un fulmine che si propaga ad arco verso un bersaglio a tua scelta che puoi vedere entro gittata. Tre fulmini balzano poi da quel bersaglio verso un massimo di tre altri bersagli, ciascuno dei quali deve trovarsi entro 9 metri dal primo bersaglio. Un bersaglio può essere una creatura o un oggetto e può essere preso di mira da uno solo dei fulmini.\nUn bersaglio deve effettuare un tiro salvezza su Destrezza. Il bersaglio subisce 10d8 danni da fulmine se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, un fulmine aggiuntivo balza dal primo bersaglio verso un altro bersaglio per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"chaos-bolt","name":"Chaos Bolt","name_it":"Dardo del Caos","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scagli una massa ondeggiante e gorgheggiante di energia caotica contro una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, il bersaglio subisce 2d8 + 1d6 danni. Scegli uno dei d8. Il numero ottenuto su quel dado determina il tipo di danno dell'attacco, come indicato di seguito.\nd8 | Tipo di Danno | 1 | Acido | 2 | Freddo | 3 | Fuoco | 4 | Forza | 5 | Fulmine | 6 | Veleno | 7 | Psichico | 8 | Tuono\nSe ottieni lo stesso numero su entrambi i d8, l'energia caotica balza dal bersaglio verso una creatura diversa a tua scelta entro 9 metri da esso. Effettua un nuovo tiro per colpire contro il nuovo bersaglio ed effettua un nuovo tiro per i danni, il che potrebbe far balzare di nuovo l'energia caotica.\nUna creatura può essere presa di mira solo una volta da ciascun lancio di questo incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, ogni bersaglio subisce 1d6 danni aggiuntivi del tipo ottenuto per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"charm-monster","name":"Charm Monster","name_it":"Ammaliare Mostri","level":4,"level_it":"Livello 4","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"1 ora","classes":["Bard","Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Tenti di ammaliare una creatura che puoi vedere entro gittata. Essa deve effettuare un tiro salvezza su Saggezza, e lo fa con vantaggio se tu o i tuoi compagni la state combattendo. Se fallisce il tiro salvezza, resta affascinata da te fino al termine dell'incantesimo o finché tu o i tuoi compagni non le fate qualcosa di dannoso. La creatura affascinata ti è amichevole. Quando l'incantesimo termina, la creatura sa di essere stata affascinata da te.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 4°.\nLe creature devono trovarsi entro 9 metri l'una dall'altra quando le prendi di mira.","language":"it","ui_language":"it"},{"id":"charm-person","name":"Charm Person","name_it":"Ammaliare Persone","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"1 ora","classes":["Bard","Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di ammaliare un umanoide che puoi vedere entro gittata. Esso deve effettuare un tiro salvezza su Saggezza, e lo fa con vantaggio se tu o i tuoi compagni lo state combattendo. Se fallisce il tiro salvezza, resta affascinato da te fino al termine dell'incantesimo o finché tu o i tuoi compagni non gli fate qualcosa di dannoso. La creatura affascinata ti considera un conoscente amichevole. Quando l'incantesimo termina, la creatura sa di essere stata affascinata da te.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 1°.\nLe creature devono trovarsi entro 9 metri l'una dall'altra quando le prendi di mira.","language":"it","ui_language":"it"},{"id":"chill-touch","name":"Chill Touch","name_it":"Tocco Gelido","level":0,"level_it":"Trucchetto","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"1 round","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una mano scheletrica e spettrale nello spazio di una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro la creatura per assalirla con il gelo della tomba. Se colpisci, il bersaglio subisce 1d8 danni necrotici e non può recuperare punti ferita fino all'inizio del tuo prossimo turno. Fino ad allora, la mano si aggrappa al bersaglio. Se colpisci un bersaglio non morto, esso ha anche svantaggio ai tiri per colpire contro di te fino al termine del tuo prossimo turno.\nI danni di questo incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"chromatic-orb","name":"Chromatic Orb","name_it":"Sfera Cromatica","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un diamante del valore di almeno 50 mo)","material":"un diamante del valore di almeno 50 mo","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Scagli una sfera di energia del diametro di 10 centimetri contro una creatura che puoi vedere entro gittata. Scegli acido, freddo, fuoco, fulmine, veleno o tuono come tipo di sfera che crei, poi effettua un attacco con incantesimo a distanza contro il bersaglio. Se l'attacco colpisce, la creatura subisce 3d8 danni del tipo che hai scelto.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"circle-of-death","name":"Circle of Death","name_it":"Cerchio di Morte","level":6,"level_it":"Livello 6","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (la polvere di una perla nera frantumata del valore di almeno 500 mo)","material":"la polvere di una perla nera frantumata del valore di almeno 500 mo","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una sfera di energia negativa si propaga in una sfera con raggio di 18 metri da un punto entro gittata. Ogni creatura in quell'area deve effettuare un tiro salvezza su Costituzione. Un bersaglio subisce 8d6 danni necrotici se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, i danni aumentano di 2d6 per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"circle-of-power","name":"Circle of Power","name_it":"Cerchio di Potere","level":5,"level_it":"Livello 5","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 9 metri)","components":"V","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Un'energia divina si irradia da te, distorcendo e diffondendo l'energia magica entro 9 metri da te. Fino al termine dell'incantesimo, la sfera si muove con te, rimanendo centrata su di te. Per la durata, ogni creatura amichevole nell'area (incluso te) ha vantaggio ai tiri salvezza contro gli incantesimi e gli altri effetti magici.\nInoltre, quando una creatura interessata supera un tiro salvezza effettuato contro un incantesimo o un effetto magico che le consente di effettuare un tiro salvezza per subire solo metà dei danni, essa non subisce invece alcun danno se supera il tiro salvezza.","language":"it","ui_language":"it"},{"id":"clairvoyance","name":"Clairvoyance","name_it":"Chiaroveggenza","level":3,"level_it":"Livello 3","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"10 minuti","range":"1,5 chilometri","components":"V, S, M (un focalizzatore del valore di almeno 100 mo, ossia un corno ingioiellato per l'udito o un occhio di vetro per la vista)","material":"un focalizzatore del valore di almeno 100 mo, ossia un corno ingioiellato per l'udito o un occhio di vetro per la vista","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Cleric","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un sensore invisibile entro gittata in un luogo a te familiare (un luogo che hai già visitato o visto) o in un luogo evidente che ti è sconosciuto (come dietro una porta, dietro un angolo o in un boschetto). Il sensore rimane sul posto per la durata, e non può essere attaccato né si può interagire con esso in altro modo.\nQuando lanci l'incantesimo, scegli la vista o l'udito. Puoi usare il senso scelto attraverso il sensore come se ti trovassi nel suo spazio. Con la tua azione, puoi alternare la vista e l'udito.\nUna creatura che può vedere il sensore (come una creatura che beneficia di vedere invisibilità o di vista pura) vede un orbe luminoso e intangibile delle dimensioni circa di un pugno.","language":"it","ui_language":"it"},{"id":"clone","name":"Clone","name_it":"Clone","level":8,"level_it":"Livello 8","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (un diamante del valore di almeno 1.000 mo e almeno 16 centimetri cubi di carne della creatura da clonare, che l'incantesimo consuma, e un recipiente del valore di almeno 2.000 mo dotato di coperchio sigillabile e abbastanza grande da contenere la creatura da clonare, come un'enorme urna, una bara, una sacca piena di fango nel terreno o un contenitore di cristallo riempito di acqua salata)","material":"un diamante del valore di almeno 1.000 mo e almeno 16 centimetri cubi di carne della creatura da clonare, che l'incantesimo consuma, e un recipiente del valore di almeno 2.000 mo dotato di coperchio sigillabile e abbastanza grande da contenere la creatura da clonare, come un'enorme urna, una bara, una sacca piena di fango nel terreno o un contenitore di cristallo riempito di acqua salata","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo fa crescere un duplicato inerte di una creatura vivente come salvaguardia contro la morte. Questo clone si forma all'interno del recipiente usato nel lancio dell'incantesimo e raggiunge dimensioni e maturità complete dopo 120 giorni; puoi anche scegliere di rendere il clone una versione più giovane della stessa creatura. Rimane inerte e perdura indefinitamente, finché il suo recipiente rimane indisturbato.\nIn qualsiasi momento dopo che il clone è maturato, se la creatura originale muore, la sua anima si trasferisce nel clone, a patto che l'anima sia libera e disposta a tornare.\nIl clone è fisicamente identico all'originale e ha la stessa personalità, gli stessi ricordi e le stesse capacità, ma nessun equipaggiamento dell'originale. I resti fisici della creatura originale, se ancora esistono, diventano inerti e non possono più essere riportati in vita, poiché l'anima della creatura si trova altrove.","language":"it","ui_language":"it"},{"id":"cloud-of-daggers","name":"Cloud of Daggers","name_it":"Nube di Pugnali","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una scheggia di vetro)","material":"una scheggia di vetro","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Riempi l'aria di pugnali roteanti in un cubo di 1,5 metri per lato, centrato su un punto a tua scelta entro gittata. Una creatura subisce 4d4 danni taglienti quando entra per la prima volta nell'area dell'incantesimo in un turno o vi inizia il proprio turno.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 2d4 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"cloudkill","name":"Cloudkill","name_it":"Nube Mortale","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una sfera con raggio di 6 metri di nebbia velenosa di colore giallo-verde, centrata su un punto a tua scelta entro gittata. La nebbia si diffonde dietro gli angoli. Dura per la durata o finché un vento forte non la disperde, ponendo fine all'incantesimo. La sua area è fortemente oscurata.\nQuando una creatura entra per la prima volta nell'area dell'incantesimo in un turno o vi inizia il proprio turno, deve effettuare un tiro salvezza su Costituzione. La creatura subisce 5d8 danni da veleno se fallisce il tiro salvezza, o la metà dei danni se lo supera. Le creature sono interessate anche se trattengono il respiro o non hanno bisogno di respirare.\nLa nebbia si allontana di 3 metri da te all'inizio di ogni tuo turno, scorrendo lungo la superficie del terreno. I vapori, essendo più pesanti dell'aria, sprofondano al livello più basso del terreno, riversandosi perfino nelle aperture.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"color-spray","name":"Color Spray","name_it":"Spruzzo Colorato","level":1,"level_it":"Livello 1","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 4,5 metri)","components":"V, S, M (un pizzico di polvere o sabbia colorata di rosso, giallo e blu)","material":"un pizzico di polvere o sabbia colorata di rosso, giallo e blu","duration":"1 round","classes":["Sorcerer","Wizard","Bard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Una sfolgorante serie di luci colorate e lampeggianti scaturisce dalla tua mano. Tira 6d10; il totale rappresenta quanti punti ferita di creature questo incantesimo può interessare. Le creature in un cono di 4,5 metri che ha origine da te sono interessate in ordine crescente dei loro punti ferita attuali (ignorando le creature prive di sensi e quelle che non possono vedere).\nA partire dalla creatura con il minor numero di punti ferita attuali, ogni creatura interessata da questo incantesimo è accecata fino al termine del tuo prossimo turno. Sottrai i punti ferita di ciascuna creatura dal totale prima di passare alla creatura con il successivo minor numero di punti ferita. I punti ferita di una creatura devono essere pari o inferiori al totale rimanente affinché quella creatura sia interessata.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, tira altri 2d10 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"command","name":"Command","name_it":"Comando","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"1 round","classes":["Cleric","Paladin","Bard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Pronunci un comando di una sola parola a una creatura che puoi vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Saggezza o esegue il comando nel suo prossimo turno. L'incantesimo non ha effetto se il bersaglio è un non morto, se non comprende la tua lingua o se il tuo comando è direttamente dannoso per esso.\nDi seguito sono riportati alcuni comandi tipici e i loro effetti. Potresti impartire un comando diverso da quelli descritti qui. In tal caso, il DM determina come si comporta il bersaglio. Se al bersaglio viene impedito di eseguire il tuo comando, l'incantesimo termina.\nAvvicinarsi. Il bersaglio si muove verso di te per il percorso più breve e diretto, terminando il proprio turno se si porta entro 1,5 metri da te.\nLasciare. Il bersaglio lascia cadere ciò che sta tenendo e poi termina il proprio turno.\nFuggire. Il bersaglio passa il proprio turno ad allontanarsi da te con il mezzo più rapido disponibile.\nProstrarsi. Il bersaglio cade prono e poi termina il proprio turno.\nFermarsi. Il bersaglio rimane dove si trova e non compie alcuna azione.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi interessare una creatura aggiuntiva per ogni livello dello slot superiore al 1°.\nLe creature devono trovarsi entro 9 metri l'una dall'altra quando le prendi di mira.","language":"it","ui_language":"it"},{"id":"commune","name":"Commune","name_it":"Comunione","level":5,"level_it":"Livello 5","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 minuto","range":"Personale","components":"V, S, M (incenso e una fiala di acqua santa o acqua profana)","material":"incenso e una fiala di acqua santa o acqua profana","duration":"1 minuto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Contatti la tua divinità o un suo delegato divino e poni fino a tre domande a cui si possa rispondere con un sì o un no. Devi porre le tue domande prima che l'incantesimo termini. Ricevi una risposta corretta per ogni domanda.\nGli esseri divini non sono necessariamente onniscienti, quindi potresti ricevere «non chiaro» come risposta se una domanda riguarda informazioni che esulano dalla conoscenza della divinità. In un caso in cui una risposta di una sola parola potrebbe essere fuorviante o contraria agli interessi della divinità, il DM potrebbe offrire invece una breve frase come risposta.\nSe lanci l'incantesimo due o più volte prima di completare il tuo prossimo riposo lungo, c'è una probabilità cumulativa del 25 per cento per ogni lancio dopo il primo che tu non ottenga alcuna risposta. Il DM effettua questo tiro in segreto.","language":"it","ui_language":"it"},{"id":"commune-with-nature","name":"Commune with Nature","name_it":"Comunione con la Natura","level":5,"level_it":"Livello 5","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 minuto","range":"Personale","components":"V, S","material":"","duration":"Istantanea","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Diventi brevemente tutt'uno con la natura e acquisisci conoscenza del territorio circostante. All'aperto, l'incantesimo ti dà conoscenza del territorio entro 4,5 chilometri da te. Nelle caverne e in altri ambienti sotterranei naturali, il raggio è limitato a 90 metri. L'incantesimo non funziona dove la natura è stata sostituita da costruzioni, come nei sotterranei e nelle città.\nAcquisisci istantaneamente conoscenza di un massimo di tre informazioni a tua scelta riguardo a uno qualsiasi dei seguenti argomenti, per come si riferiscono all'area:\n• conformazione del terreno e bacini d'acqua\n• piante, minerali, animali o popoli predominanti\n• potenti celestiali, fatati, immondi, elementali o non morti\n• influenze da altri piani di esistenza\n• edifici\nPer esempio, potresti determinare la posizione di potenti non morti nell'area, la posizione delle principali fonti di acqua potabile sicura e la posizione di eventuali città vicine.","language":"it","ui_language":"it"},{"id":"compelled-duel","name":"Compelled Duel","name_it":"Duello Forzato","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione bonus","range":"9 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Tenti di costringere una creatura a un duello. Una creatura che puoi vedere entro gittata deve effettuare un tiro salvezza su Saggezza. Con un tiro fallito, la creatura è attratta verso di te, costretta dalla tua imposizione divina. Per la durata, ha svantaggio ai tiri per colpire contro creature diverse da te, e deve effettuare un tiro salvezza su Saggezza ogni volta che tenta di spostarsi in uno spazio che si trova a più di 9 metri da te; se supera questo tiro salvezza, questo incantesimo non limita il movimento del bersaglio per quel turno.\nL'incantesimo termina se attacchi qualsiasi altra creatura, se lanci un incantesimo che prende di mira una creatura ostile diversa dal bersaglio, se una creatura a te amichevole danneggia il bersaglio o gli lancia contro un incantesimo dannoso, o se termini il tuo turno a più di 9 metri dal bersaglio.","language":"it","ui_language":"it"},{"id":"comprehend-languages","name":"Comprehend Languages","name_it":"Comprendere i Linguaggi","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un pizzico di fuliggine e sale)","material":"un pizzico di fuliggine e sale","duration":"1 ora","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, comprendi il significato letterale di qualsiasi linguaggio parlato che odi. Comprendi anche qualsiasi linguaggio scritto che vedi, ma devi toccare la superficie su cui sono scritte le parole. Occorre circa 1 minuto per leggere una pagina di testo.\nQuesto incantesimo non decifra messaggi segreti in un testo o in un glifo, come un sigillo arcano, che non faccia parte di un linguaggio scritto.","language":"it","ui_language":"it"},{"id":"compulsion","name":"Compulsion","name_it":"Coercizione","level":4,"level_it":"Livello 4","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Le creature a tua scelta che puoi vedere entro gittata e che possono sentirti devono effettuare un tiro salvezza su Saggezza. Un bersaglio supera automaticamente questo tiro salvezza se non può essere affascinato. Con un tiro fallito, il bersaglio è interessato da questo incantesimo. Fino al termine dell'incantesimo, puoi usare un'azione bonus a ogni tuo turno per designare una direzione orizzontale rispetto a te. Ogni bersaglio interessato deve usare quanto più possibile del proprio movimento per muoversi in quella direzione nel suo prossimo turno. Può compiere la propria azione prima di muoversi. Dopo essersi mosso in questo modo, può effettuare un altro tiro salvezza su Saggezza per tentare di porre fine all'effetto.\nUn bersaglio non è costretto a muoversi verso un pericolo palesemente letale, come un fuoco o una fossa, ma provocherà attacchi di opportunità pur di muoversi nella direzione designata.","language":"it","ui_language":"it"},{"id":"cone-of-cold","name":"Cone of Cold","name_it":"Cono di Freddo","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 18 metri)","components":"V, S, M (un piccolo cono di cristallo o di vetro)","material":"un piccolo cono di cristallo o di vetro","duration":"Istantanea","classes":["Sorcerer","Wizard","Druid"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Un'esplosione di aria gelida erompe dalle tue mani. Ogni creatura in un cono di 18 metri deve effettuare un tiro salvezza su Costituzione. Una creatura subisce 8d8 danni da freddo se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nUna creatura uccisa da questo incantesimo diventa una statua congelata finché non si scongela.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"confusion","name":"Confusion","name_it":"Confusione","level":4,"level_it":"Livello 4","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (tre gusci di noce)","material":"tre gusci di noce","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Druid","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo assale e contorce la mente delle creature, generando deliri e provocando azioni incontrollate. Ogni creatura in una sfera con raggio di 3 metri centrata su un punto a tua scelta entro gittata deve superare un tiro salvezza su Saggezza quando lanci questo incantesimo o ne è interessata.\nUn bersaglio interessato non può effettuare reazioni e deve tirare un d10 all'inizio di ogni suo turno per determinare il proprio comportamento per quel turno.\nd10 | Comportamento | 1 | La creatura usa tutto il proprio movimento per spostarsi in una direzione casuale. Per determinare la direzione, tira un d8 e assegna una direzione a ciascuna faccia del dado. La creatura non compie alcuna azione in questo turno. | 2-6 | La creatura non si muove né compie azioni in questo turno. | 7-8 | La creatura usa la propria azione per effettuare un attacco in mischia contro una creatura determinata casualmente entro la sua portata. Se non c'è alcuna creatura entro la sua portata, la creatura non fa nulla in questo turno. | 9-10 | La creatura può agire e muoversi normalmente.\nAl termine di ogni suo turno, un bersaglio interessato può effettuare un tiro salvezza su Saggezza. Se lo supera, questo effetto termina per quel bersaglio.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, il raggio della sfera aumenta di 1,5 metri per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"conjure-animals","name":"Conjure Animals","name_it":"Evocare Animali","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi spiriti fatati che assumono la forma di bestie e compaiono in spazi liberi che puoi vedere entro gittata. Scegli una delle seguenti opzioni per ciò che appare:\n• Una bestia di grado di sfida 2 o inferiore\n• Due bestie di grado di sfida 1 o inferiore\n• Quattro bestie di grado di sfida 1/2 o inferiore\n• Otto bestie di grado di sfida 1/4 o inferiore\nOgni bestia è considerata anche fatata, e scompare quando scende a 0 punti ferita o quando l'incantesimo termina. Le creature evocate sono amichevoli verso di te e i tuoi compagni. Tira l'iniziativa per le creature evocate come gruppo, che ha i propri turni. Esse obbediscono a qualsiasi comando verbale che impartisci loro (senza che ti sia richiesta alcuna azione). Se non impartisci loro alcun comando, si difendono dalle creature ostili, ma per il resto non compiono alcuna azione. Il DM possiede le statistiche delle creature.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando determinati slot incantesimo di livello superiore, scegli una delle opzioni di evocazione sopra indicate e compaiono più creature: il doppio con uno slot di 5° livello, il triplo con uno slot di 7° livello e il quadruplo con uno slot di 9° livello.","language":"it","ui_language":"it"},{"id":"conjure-barrage","name":"Conjure Barrage","name_it":"Evocare Sbarramento","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 18 metri)","components":"V, S, M (un munizionamento o un'arma da lancio)","material":"un munizionamento o un'arma da lancio","duration":"Istantanea","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Lanci in aria un'arma non magica o scocchi un munizionamento non magico per creare un cono di armi identiche che si proiettano in avanti per poi scomparire. Ogni creatura in un cono di 18 metri deve superare un tiro salvezza su Destrezza. Una creatura subisce 3d8 danni se fallisce il tiro salvezza, o la metà dei danni se lo supera. Il tipo di danno è lo stesso dell'arma o del munizionamento usato come componente.","language":"it","ui_language":"it"},{"id":"conjure-celestial","name":"Conjure Celestial","name_it":"Evocare Celestiale","level":7,"level_it":"Livello 7","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"27 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi un celestiale di grado di sfida 4 o inferiore, che compare in uno spazio libero che puoi vedere entro gittata. Il celestiale scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\nIl celestiale è amichevole verso di te e i tuoi compagni per la durata. Tira l'iniziativa per il celestiale, che ha i propri turni. Esso obbedisce a qualsiasi comando verbale che gli impartisci (senza che ti sia richiesta alcuna azione), purché non violi il suo allineamento. Se non impartisci alcun comando al celestiale, esso si difende dalle creature ostili ma per il resto non compie alcuna azione. Il DM possiede le statistiche del celestiale.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 9° livello, evochi un celestiale di grado di sfida 5 o inferiore.","language":"it","ui_language":"it"},{"id":"conjure-elemental","name":"Conjure Elemental","name_it":"Evocare Elementale","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"27 metri","components":"V, S, M (incenso acceso per l'aria, argilla morbida per la terra, zolfo e fosforo per il fuoco, o acqua e sabbia per l'acqua)","material":"incenso acceso per l'aria, argilla morbida per la terra, zolfo e fosforo per il fuoco, o acqua e sabbia per l'acqua","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Convochi un servitore elementale. Scegli un'area di aria, terra, fuoco o acqua che riempia un cubo di 3 metri entro gittata. Un elementale di grado di sfida 5 o inferiore appropriato all'area che hai scelto compare in uno spazio libero entro 3 metri da essa. Per esempio, un elementale del fuoco emerge da un falò e un elementale della terra si solleva dal suolo. L'elementale scompare quando scende a 0 punti ferita o quando l'incantesimo termina. L'elementale è amichevole verso di te e i tuoi compagni per la durata. Tira l'iniziativa per l'elementale, che ha i propri turni. Esso obbedisce a qualsiasi comando verbale che gli impartisci (senza che ti sia richiesta alcuna azione). Se non impartisci alcun comando all'elementale, esso si difende dalle creature ostili ma per il resto non compie alcuna azione.\nSe la tua concentrazione viene interrotta, l'elementale non scompare. Invece, perdi il controllo dell'elementale, esso diventa ostile verso di te e i tuoi compagni e potrebbe attaccare. Un elementale fuori controllo non può essere congedato da te, e scompare 1 ora dopo che l'hai evocato. Il DM possiede le statistiche dell'elementale.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, il grado di sfida aumenta di 1 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"conjure-fey","name":"Conjure Fey","name_it":"Evocare Fatato","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"27 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Warlock"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi una creatura fatata di grado di sfida 6 o inferiore, oppure uno spirito fatato che assume la forma di una bestia di grado di sfida 6 o inferiore. Essa compare in uno spazio libero che puoi vedere entro gittata. La creatura fatata scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\nLa creatura fatata è amichevole verso di te e i tuoi compagni per la durata. Tira l'iniziativa per la creatura, che ha i propri turni. Essa obbedisce a qualsiasi comando verbale che le impartisci (senza che ti sia richiesta alcuna azione), purché non violi il suo allineamento. Se non impartisci alcun comando alla creatura fatata, essa si difende dalle creature ostili ma per il resto non compie alcuna azione.\nSe la tua concentrazione viene interrotta, la creatura fatata non scompare. Invece, perdi il controllo della creatura fatata, essa diventa ostile verso di te e i tuoi compagni e potrebbe attaccare. Una creatura fatata fuori controllo non può essere congedata da te, e scompare 1 ora dopo che l'hai evocata. Il DM possiede le statistiche della creatura fatata.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, il grado di sfida aumenta di 1 per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"conjure-minor-elementals","name":"Conjure Minor Elementals","name_it":"Evocare Elementali Minori","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"27 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi elementali che compaiono in spazi liberi che puoi vedere entro gittata. Scegli una delle seguenti opzioni per ciò che appare:\n• Un elementale di grado di sfida 2 o inferiore\n• Due elementali di grado di sfida 1 o inferiore\n• Quattro elementali di grado di sfida 1/2 o inferiore\n• Otto elementali di grado di sfida 1/4 o inferiore\nUn elementale evocato da questo incantesimo scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\nLe creature evocate sono amichevoli verso di te e i tuoi compagni. Tira l'iniziativa per le creature evocate come gruppo, che ha i propri turni. Esse obbediscono a qualsiasi comando verbale che impartisci loro (senza che ti sia richiesta alcuna azione). Se non impartisci loro alcun comando, si difendono dalle creature ostili, ma per il resto non compiono alcuna azione. Il DM possiede le statistiche delle creature.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando determinati slot incantesimo di livello superiore, scegli una delle opzioni di evocazione sopra indicate e compaiono più creature: il doppio con uno slot di 6° livello e il triplo con uno slot di 8° livello.","language":"it","ui_language":"it"},{"id":"conjure-volley","name":"Conjure Volley","name_it":"Evocare Scarica","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (un munizionamento o un'arma da lancio)","material":"un munizionamento o un'arma da lancio","duration":"Istantanea","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Scocchi un munizionamento non magico da un'arma a distanza o lanci in aria un'arma non magica e scegli un punto entro gittata. Centinaia di duplicati del munizionamento o dell'arma cadono in una scarica dall'alto per poi scomparire. Ogni creatura in un cilindro con raggio di 12 metri e alto 6 metri centrato su quel punto deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 8d8 danni se fallisce il tiro salvezza, o la metà dei danni se lo supera. Il tipo di danno è lo stesso del munizionamento o dell'arma.","language":"it","ui_language":"it"},{"id":"conjure-woodland-beings","name":"Conjure Woodland Beings","name_it":"Evocare Esseri Silvani","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una bacca di agrifoglio per ogni creatura evocata)","material":"una bacca di agrifoglio per ogni creatura evocata","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi creature fatate che compaiono in spazi liberi che puoi vedere entro gittata. Scegli una delle seguenti opzioni per ciò che appare:\n• Una creatura fatata di grado di sfida 2 o inferiore\n• Due creature fatate di grado di sfida 1 o inferiore\n• Quattro creature fatate di grado di sfida 1/2 o inferiore\n• Otto creature fatate di grado di sfida 1/4 o inferiore\nUna creatura evocata scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\nLe creature evocate sono amichevoli verso di te e i tuoi compagni. Tira l'iniziativa per le creature evocate come gruppo, che ha i propri turni. Esse obbediscono a qualsiasi comando verbale che impartisci loro (senza che ti sia richiesta alcuna azione). Se non impartisci loro alcun comando, si difendono dalle creature ostili, ma per il resto non compiono alcuna azione. Il DM possiede le statistiche delle creature.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando determinati slot incantesimo di livello superiore, scegli una delle opzioni di evocazione sopra indicate e compaiono più creature: il doppio con uno slot di 6° livello e il triplo con uno slot di 8° livello.","language":"it","ui_language":"it"},{"id":"contact-other-plane","name":"Contact Other Plane","name_it":"Contattare Altro Piano","level":5,"level_it":"Livello 5","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 minuto","range":"Personale","components":"V","material":"","duration":"1 minuto","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Contatti mentalmente un semidio, lo spirito di un saggio morto da tempo o qualche altra misteriosa entità di un altro piano. Contattare questa intelligenza extraplanare può mettere a dura prova o perfino spezzare la tua mente. Quando lanci questo incantesimo, effettua un tiro salvezza su Intelligenza con CD 15. Con un fallimento, subisci 6d6 danni psichici e sei folle finché non completi un riposo lungo. Mentre sei folle, non puoi compiere azioni, non puoi comprendere ciò che dicono le altre creature, non puoi leggere e parli solo in modo incomprensibile. Un incantesimo ripristino superiore lanciato su di te pone fine a questo effetto.\nCon un tiro salvezza riuscito, puoi porre all'entità fino a cinque domande. Devi porre le tue domande prima che l'incantesimo termini. Il DM risponde a ogni domanda con una sola parola, come «sì», «no», «forse», «mai», «irrilevante» o «non chiaro» (se l'entità non conosce la risposta alla domanda). Se una risposta di una sola parola fosse fuorviante, il DM potrebbe invece offrire una breve frase come risposta.","language":"it","ui_language":"it"},{"id":"contagion","name":"Contagion","name_it":"Contagio","level":5,"level_it":"Livello 5","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"7 giorni","classes":["Cleric","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Il tuo tocco infligge una malattia. Effettua un attacco con incantesimo in mischia contro una creatura entro la tua portata. Se colpisci, il bersaglio è avvelenato.\nAl termine di ogni turno del bersaglio avvelenato, esso deve effettuare un tiro salvezza su Costituzione. Se il bersaglio supera tre di questi tiri salvezza, non è più avvelenato e l'incantesimo termina. Se il bersaglio fallisce tre di questi tiri salvezza, non è più avvelenato, ma scegli una delle malattie seguenti. Il bersaglio è soggetto alla malattia scelta per la durata dell'incantesimo.\nPoiché questo incantesimo induce nel bersaglio una malattia naturale, qualsiasi effetto che rimuova una malattia o ne attenui gli effetti si applica a essa.\nMorbo Accecante. Il dolore attanaglia la mente della creatura e i suoi occhi diventano di un bianco latteo. La creatura ha svantaggio alle prove di Saggezza e ai tiri salvezza su Saggezza ed è accecata.\nFebbre Putrida. Una febbre furiosa pervade il corpo della creatura. La creatura ha svantaggio alle prove di Forza, ai tiri salvezza su Forza e ai tiri per colpire che usano la Forza.\nMarciume della Carne. La carne della creatura si decompone. La creatura ha svantaggio alle prove di Carisma e vulnerabilità a tutti i danni.\nFebbre Mentale. La mente della creatura diventa febbrile. La creatura ha svantaggio alle prove di Intelligenza e ai tiri salvezza su Intelligenza, e si comporta come se fosse sotto gli effetti dell'incantesimo confusione durante il combattimento.\nConvulsioni. La creatura è sopraffatta dai tremori. La creatura ha svantaggio alle prove di Destrezza, ai tiri salvezza su Destrezza e ai tiri per colpire che usano la Destrezza.\nRovina Viscida. La creatura inizia a sanguinare in modo incontrollabile. La creatura ha svantaggio alle prove di Costituzione e ai tiri salvezza su Costituzione. Inoltre, ogni volta che la creatura subisce danni, è stordita fino al termine del suo prossimo turno.","language":"it","ui_language":"it"},{"id":"contingency","name":"Contingency","name_it":"Eventualità","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"10 minuti","range":"Personale","components":"V, S, M (una statuetta di te stesso intagliata nell'avorio e decorata con gemme del valore di almeno 1.500 mo)","material":"una statuetta di te stesso intagliata nell'avorio e decorata con gemme del valore di almeno 1.500 mo","duration":"10 giorni","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli un incantesimo di 5° livello o inferiore che puoi lanciare, che abbia un tempo di lancio di 1 azione e che possa avere te come bersaglio. Lanci quell'incantesimo — chiamato incantesimo eventuale — come parte del lancio di eventualità, spendendo slot incantesimo per entrambi, ma l'incantesimo eventuale non entra in effetto. Invece, ha effetto quando si verifica una determinata circostanza. Descrivi quella circostanza quando lanci i due incantesimi. Per esempio, un'eventualità lanciata con respirare sott'acqua potrebbe stabilire che respirare sott'acqua entri in effetto quando vieni sommerso dall'acqua o da un liquido simile.\nL'incantesimo eventuale ha effetto immediatamente dopo che la circostanza si verifica per la prima volta, che tu lo voglia o no, e poi eventualità termina.\nL'incantesimo eventuale ha effetto solo su di te, anche se normalmente può avere altri come bersaglio. Puoi usare un solo incantesimo eventualità alla volta. Se lanci di nuovo questo incantesimo, l'effetto di un altro incantesimo eventualità su di te termina. Inoltre, eventualità termina su di te se la sua componente materiale non è più sulla tua persona.","language":"it","ui_language":"it"},{"id":"continual-flame","name":"Continual Flame","name_it":"Fiamma Perenne","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (polvere di rubino del valore di 50 mo, che l'incantesimo consuma)","material":"polvere di rubino del valore di 50 mo, che l'incantesimo consuma","duration":"Finché non viene dissolto","classes":["Cleric","Wizard","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Una fiamma, di luminosità equivalente a quella di una torcia, scaturisce da un oggetto che tocchi. L'effetto sembra una fiamma normale, ma non produce calore e non consuma ossigeno. Una fiamma perenne può essere coperta o nascosta, ma non soffocata né spenta.","language":"it","ui_language":"it"},{"id":"control-flames","name":"Control Flames","name_it":"Controllare le Fiamme","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S","material":"","duration":"Istantanea o 1 ora (vedi sotto)","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli una fiamma non magica che puoi vedere entro gittata e che rientri in un cubo di 1,5 metri. La influenzi in uno dei seguenti modi:\n• Espandi istantaneamente la fiamma di 1,5 metri in una direzione, a patto che nella nuova posizione siano presenti legna o altro combustibile.\n• Estingui istantaneamente le fiamme all'interno del cubo.\n• Raddoppi o dimezzi l'area di luce intensa e luce fioca proiettata dalla fiamma, ne cambi il colore, o entrambe le cose. Il cambiamento dura 1 ora.\n• Fai apparire all'interno delle fiamme forme semplici — come la vaga sagoma di una creatura, un oggetto inanimato o un luogo — e le animi a tuo piacimento. Le forme durano 1 ora.\nSe lanci questo incantesimo più volte, puoi avere attivi contemporaneamente fino a tre effetti non istantanei da esso creati, e puoi congedare un tale effetto con un'azione.","language":"it","ui_language":"it"},{"id":"control-water","name":"Control Water","name_it":"Controllare l'Acqua","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V, S, M (una goccia d'acqua e un pizzico di polvere)","material":"una goccia d'acqua e un pizzico di polvere","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric","Druid","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fino al termine dell'incantesimo, controlli qualsiasi acqua libera all'interno di un'area che scegli, ossia un cubo di un massimo di 30 metri per lato. Puoi scegliere uno qualsiasi dei seguenti effetti quando lanci questo incantesimo. Come azione nel tuo turno, puoi ripetere lo stesso effetto o sceglierne uno diverso.\nInondazione. Fai salire il livello di tutta l'acqua ferma nell'area fino a 6 metri. Se l'area include una riva, l'acqua dell'inondazione si riversa sulla terraferma. Se scegli un'area in un grande bacino d'acqua, crei invece un'onda alta 6 metri che attraversa l'area da un lato all'altro per poi infrangersi. Qualsiasi veicolo di taglia Enorme o inferiore sul percorso dell'onda viene trasportato con essa dall'altra parte. Qualsiasi veicolo di taglia Enorme o inferiore colpito dall'onda ha il 25 per cento di probabilità di capovolgersi. Il livello dell'acqua rimane elevato finché l'incantesimo non termina o non scegli un effetto diverso. Se questo effetto ha prodotto un'onda, l'onda si ripete all'inizio del tuo prossimo turno finché dura l'effetto di inondazione.\nSeparare le Acque. Fai allontanare l'acqua nell'area, creando una trincea. La trincea attraversa l'area dell'incantesimo e l'acqua separata forma una parete su ciascun lato. La trincea rimane finché l'incantesimo non termina o non scegli un effetto diverso. L'acqua riempie poi lentamente la trincea nel corso del round successivo, finché il normale livello dell'acqua non viene ripristinato.\nDeviare il Flusso. Fai muovere l'acqua corrente nell'area in una direzione che scegli, anche se l'acqua deve scorrere sopra ostacoli, su per le pareti o in altre direzioni improbabili. L'acqua nell'area si muove come la dirigi tu, ma una volta uscita dall'area dell'incantesimo riprende a scorrere in base alle condizioni del terreno. L'acqua continua a muoversi nella direzione che hai scelto finché l'incantesimo non termina o non scegli un effetto diverso.\nVortice. Questo effetto richiede un bacino d'acqua di almeno 15 metri di lato e profondo 7,5 metri. Fai formare un vortice al centro dell'area. Il vortice forma una spirale larga 1,5 metri alla base, larga fino a 15 metri in cima e alta 7,5 metri. Qualsiasi creatura o oggetto nell'acqua ed entro 7,5 metri dal vortice viene trascinato di 3 metri verso di esso. Una creatura può nuotare via dal vortice effettuando una prova di Forza (Atletica) contro la CD del tiro salvezza del tuo incantesimo.\nQuando una creatura entra nel vortice per la prima volta in un turno o vi inizia il proprio turno, deve effettuare un tiro salvezza su Forza. Con un tiro fallito, la creatura subisce 2d8 danni contundenti ed è intrappolata nel vortice fino al termine dell'incantesimo. Con un tiro riuscito, la creatura subisce metà dei danni e non è intrappolata nel vortice. Una creatura intrappolata nel vortice può usare la propria azione per tentare di nuotare via dal vortice come descritto sopra, ma ha svantaggio alla prova di Forza (Atletica) per farlo.\nLa prima volta che ogni turno un oggetto entra nel vortice, l'oggetto subisce 2d8 danni contundenti; questi danni si verificano a ogni round in cui rimane nel vortice.","language":"it","ui_language":"it"},{"id":"control-weather","name":"Control Weather","name_it":"Controllare il Clima","level":8,"level_it":"Livello 8","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"10 minuti","range":"Personale (raggio di 7,5 chilometri)","components":"V, S, M (incenso acceso e pezzetti di terra e legno mescolati nell'acqua)","material":"incenso acceso e pezzetti di terra e legno mescolati nell'acqua","duration":"Concentrazione, fino a 8 ore","classes":["Cleric","Druid","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Prendi il controllo del tempo atmosferico entro 7,5 chilometri da te per la durata. Devi trovarti all'aperto per lanciare questo incantesimo. Spostarsi in un luogo dove non hai una via libera verso il cielo termina l'incantesimo in anticipo.\nQuando lanci l'incantesimo, modifichi le condizioni atmosferiche attuali, che sono determinate dal DM in base al clima e alla stagione. Puoi modificare precipitazioni, temperatura e vento. Occorrono 1d4 × 10 minuti perché le nuove condizioni abbiano effetto. Una volta che ciò avviene, puoi modificare di nuovo le condizioni. Quando l'incantesimo termina, il tempo atmosferico torna gradualmente alla normalità. Quando modifichi le condizioni atmosferiche, trova una condizione attuale nelle tabelle seguenti e cambiane lo stadio di uno, in su o in giù. Quando modifichi il vento, puoi cambiarne la direzione.\nPrecipitazioni\nStadio | Condizione | 1 | Sereno | 2 | Nuvolosità leggera | 3 | Coperto o nebbia al suolo | 4 | Pioggia, grandine o neve | 5 | Pioggia torrenziale, grandinata violenta o bufera di neve\nTemperatura\nStadio | Condizione | 1 | Caldo insopportabile | 2 | Caldo | 3 | Tiepido | 4 | Fresco | 5 | Freddo | 6 | Freddo artico\nVento\nStadio | Condizione | 1 | Calmo | 2 | Vento moderato | 3 | Vento forte | 4 | Burrasca | 5 | Tempesta","language":"it","ui_language":"it"},{"id":"control-winds","name":"Control Winds","name_it":"Controllare i Venti","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Prendi il controllo dell'aria in un cubo di 30 metri che puoi vedere entro gittata. Scegli uno dei seguenti effetti quando lanci l'incantesimo. L'effetto dura per la durata dell'incantesimo, a meno che tu non usi la tua azione in un turno successivo per passare a un effetto diverso. Puoi anche usare la tua azione per arrestare temporaneamente l'effetto o per riavviarne uno che hai arrestato.\nRaffiche. Un vento si leva all'interno del cubo, soffiando continuamente in una direzione orizzontale che designi. Scegli l'intensità del vento: calmo, moderato o forte. Se il vento è moderato o forte, gli attacchi con armi a distanza che entrano nel cubo, ne escono o lo attraversano hanno svantaggio ai loro tiri per colpire. Se il vento è forte, qualsiasi creatura che si muove controvento deve spendere 0,3 metri di movimento extra per ogni metro percorso.\nCorrente Discendente. Fai soffiare una raffica sostenuta di vento forte verso il basso dalla sommità del cubo. Gli attacchi con armi a distanza che attraversano il cubo o che sono effettuati contro bersagli al suo interno hanno svantaggio ai loro tiri per colpire. Una creatura deve effettuare un tiro salvezza su Forza se vola nel cubo per la prima volta in un turno o vi inizia il proprio turno volando. Con un tiro fallito, la creatura viene buttata a terra prona.\nCorrente Ascendente. Crei una corrente ascendente sostenuta all'interno del cubo, che sale verso l'alto dal bordo inferiore del cubo. Le creature che terminano una caduta all'interno del cubo subiscono solo metà dei danni da caduta. Quando una creatura nel cubo effettua un salto verticale, può saltare fino a 3 metri più in alto del normale.","language":"it","ui_language":"it"},{"id":"cordon-of-arrows","name":"Cordon of Arrows","name_it":"Cordone di Frecce","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"1,5 metri","components":"V, S, M (quattro o più frecce o quadrelli)","material":"quattro o più frecce o quadrelli","duration":"8 ore","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Pianti nel terreno quattro munizionamenti non magici — frecce o quadrelli di balestra — entro gittata e poni su di essi una magia per proteggere un'area. Fino al termine dell'incantesimo, ogni volta che una creatura diversa da te giunge entro 9 metri dai munizionamenti per la prima volta in un turno o vi termina il proprio turno, un munizionamento si leva in volo per colpirla. La creatura deve superare un tiro salvezza su Destrezza o subisce 1d6 danni perforanti. Il munizionamento viene poi distrutto. L'incantesimo termina quando non rimane più alcun munizionamento.\nQuando lanci questo incantesimo, puoi designare le creature che desideri, e l'incantesimo le ignora.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, la quantità di munizionamento che può essere interessata aumenta di due per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"counterspell","name":"Counterspell","name_it":"Controincantesimo","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 reazione, che si esegue quando si vede una creatura entro 18 metri lanciare un incantesimo","range":"18 metri","components":"S","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di interrompere una creatura nell'atto di lanciare un incantesimo. Se la creatura sta lanciando un incantesimo di 3° livello o inferiore, il suo incantesimo fallisce e non ha effetto. Se sta lanciando un incantesimo di 4° livello o superiore, effettua una prova di caratteristica usando la tua caratteristica da incantatore. La CD è pari a 10 + il livello dell'incantesimo. Con un successo, l'incantesimo della creatura fallisce e non ha effetto.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, l'incantesimo interrotto non ha effetto se il suo livello è pari o inferiore al livello dello slot incantesimo che hai usato.","language":"it","ui_language":"it"},{"id":"create-bonfire","name":"Create Bonfire","name_it":"Creare Falò","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Crei un falò sul terreno che puoi vedere entro gittata. Fino al termine dell'incantesimo, il falò magico riempie un cubo di 1,5 metri. Qualsiasi creatura nello spazio del falò quando lanci l'incantesimo deve superare un tiro salvezza su Destrezza o subisce 1d8 danni da fuoco. Una creatura deve effettuare il tiro salvezza anche quando entra nello spazio del falò per la prima volta in un turno o vi termina il proprio turno.\nIl falò incendia gli oggetti infiammabili nella sua area che non siano indossati né trasportati.\nI danni dell'incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"create-food-and-water","name":"Create Food and Water","name_it":"Creare Cibo e Acqua","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei circa 22 chilogrammi di cibo e circa 110 litri d'acqua sul terreno o in contenitori entro gittata, a sufficienza per sostenere fino a quindici umanoidi o cinque cavalcature per 24 ore. Il cibo è insapore ma nutriente, e si guasta se non viene consumato entro 24 ore. L'acqua è pulita e non va a male.","language":"it","ui_language":"it"},{"id":"create-homunculus","name":"Create Homunculus","name_it":"Creare Homunculus","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (argilla, cenere e radice di mandragora, che l'incantesimo consuma, e un pugnale tempestato di gemme del valore di almeno 1.000 mo)","material":"argilla, cenere e radice di mandragora, che l'incantesimo consuma, e un pugnale tempestato di gemme del valore di almeno 1.000 mo","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Mentre pronunci un'intricata incantazione, ti ferisci con un pugnale tempestato di gemme, subendo 2d4 danni perforanti che non possono essere ridotti in alcun modo. Poi fai gocciolare il tuo sangue sulle altre componenti dell'incantesimo e le tocchi, trasformandole in uno speciale costrutto chiamato homunculus. È il tuo fedele compagno e muore se tu muori. Ogni volta che completi un riposo lungo, puoi spendere fino a metà dei tuoi Dadi Vita se l'homunculus si trova sul tuo stesso piano di esistenza. Quando lo fai, tira ogni dado e aggiungi il tuo modificatore di Costituzione. Il tuo massimo dei punti ferita è ridotto del totale, e sia il massimo dei punti ferita sia i punti ferita attuali dell'homunculus aumentano di pari quantità. Questo processo non può ridurti al di sotto di 1 punto ferita, e la modifica ai tuoi punti ferita e a quelli dell'homunculus termina quando completi il tuo prossimo riposo lungo. La riduzione al tuo massimo dei punti ferita non può essere rimossa con alcun mezzo prima di allora, tranne che con la morte dell'homunculus. Puoi avere un solo homunculus alla volta. Se lanci questo incantesimo mentre il tuo homunculus è in vita, l'incantesimo fallisce.","language":"it","ui_language":"it"},{"id":"create-or-destroy-water","name":"Create or Destroy Water","name_it":"Creare o Distruggere Acqua","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una goccia d'acqua per creare acqua o alcuni granelli di sabbia per distruggerla)","material":"una goccia d'acqua per creare acqua o alcuni granelli di sabbia per distruggerla","duration":"Istantanea","classes":["Cleric","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei o distruggi acqua.\nCreare Acqua. Crei fino a circa 38 litri di acqua pulita entro gittata in un contenitore aperto. In alternativa, l'acqua cade come pioggia in un cubo di 9 metri entro gittata, estinguendo le fiamme esposte nell'area.\nDistruggere Acqua. Distruggi fino a circa 38 litri di acqua in un contenitore aperto entro gittata. In alternativa, distruggi la nebbia in un cubo di 9 metri entro gittata.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, crei o distruggi altri 38 litri d'acqua circa, oppure la dimensione del cubo aumenta di 1,5 metri, per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"create-undead","name":"Create Undead","name_it":"Creare Non Morti","level":6,"level_it":"Livello 6","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 minuto","range":"3 metri","components":"V, S, M (un vaso di argilla pieno di terra di cimitero, un vaso di argilla pieno di acqua salmastra e una pietra di onice nero da 150 mo per ogni cadavere)","material":"un vaso di argilla pieno di terra di cimitero, un vaso di argilla pieno di acqua salmastra e una pietra di onice nero da 150 mo per ogni cadavere","duration":"Istantanea","classes":["Cleric","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Puoi lanciare questo incantesimo solo di notte. Scegli fino a tre cadaveri di umanoidi di taglia Media o Piccola entro gittata. Ogni cadavere diventa un ghoul sotto il tuo controllo.\nCome azione bonus a ogni tuo turno, puoi comandare mentalmente qualsiasi creatura che hai animato con questo incantesimo se la creatura si trova entro 36 metri da te (se controlli più creature, puoi comandarle tutte o in parte contemporaneamente, impartendo lo stesso comando a ciascuna). Decidi quale azione compirà la creatura e dove si muoverà durante il suo prossimo turno, oppure puoi impartire un comando generico, come sorvegliare una determinata stanza o corridoio. Se non impartisci comandi, la creatura si limita a difendersi dalle creature ostili. Una volta ricevuto un ordine, la creatura continua a seguirlo finché il suo compito non è completato.\nLa creatura è sotto il tuo controllo per 24 ore, dopodiché smette di obbedire a qualsiasi comando tu le abbia impartito. Per mantenere il controllo della creatura per altre 24 ore, devi lanciare questo incantesimo sulla creatura prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo riafferma il tuo controllo su un massimo di tre creature che hai animato con questo incantesimo, invece di animarne di nuove.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello, puoi animare o riaffermare il controllo su quattro ghoul. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 8° livello, puoi animare o riaffermare il controllo su cinque ghoul, oppure due ghast o wight. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 9° livello, puoi animare o riaffermare il controllo su sei ghoul, tre ghast o wight, oppure due mummie.","language":"it","ui_language":"it"},{"id":"creation","name":"Creation","name_it":"Creazione","level":5,"level_it":"Livello 5","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 minuto","range":"9 metri","components":"V, S, M (un minuscolo frammento di materia dello stesso tipo dell'oggetto che intendi creare)","material":"un minuscolo frammento di materia dello stesso tipo dell'oggetto che intendi creare","duration":"Speciale","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Estrai filamenti di materia d'ombra dallo Shadowfell per creare un oggetto non vivente di materia vegetale entro gittata: stoffe, corda, legno o qualcosa di simile. Puoi anche usare questo incantesimo per creare oggetti minerali come pietra, cristallo o metallo. L'oggetto creato non deve essere più grande di un cubo di 1,5 metri, e deve essere di una forma e di un materiale che hai già visto.\nLa durata dipende dal materiale dell'oggetto. Se l'oggetto è composto da più materiali, usa la durata più breve.\nMateriale | Durata | Materia vegetale | 1 giorno | Pietra o cristallo | 12 ore | Metalli preziosi | 1 ora | Gemme | 10 minuti | Adamantio o mithral | 1 minuto\nUsare qualsiasi materiale creato da questo incantesimo come componente materiale di un altro incantesimo fa fallire quest'ultimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, il cubo aumenta di 1,5 metri per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"crown-of-madness","name":"Crown of Madness","name_it":"Corona di Follia","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Un umanoide a tua scelta che puoi vedere entro gittata deve superare un tiro salvezza su Saggezza o resta affascinato da te per la durata. Mentre il bersaglio è affascinato in questo modo, una corona contorta di ferro frastagliato appare sul suo capo e una follia gli arde negli occhi.\nIl bersaglio affascinato deve usare la propria azione, prima di muoversi a ogni suo turno, per effettuare un attacco in mischia contro una creatura diversa da sé che tu scegli mentalmente. Il bersaglio può agire normalmente nel suo turno se non scegli alcuna creatura o se nessuna si trova entro la sua portata.\nNei tuoi turni successivi, devi usare la tua azione per mantenere il controllo sul bersaglio, altrimenti l'incantesimo termina. Inoltre, il bersaglio può effettuare un tiro salvezza su Saggezza al termine di ogni suo turno. Con un successo, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"crown-of-stars","name":"Crown of Stars","name_it":"Corona di Stelle","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"1 ora","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Sette granelli di luce simili a stelle appaiono e orbitano attorno alla tua testa fino al termine dell'incantesimo. Puoi usare un'azione bonus per scagliare uno dei granelli verso una creatura o un oggetto entro 36 metri da te. Quando lo fai, effettua un attacco con incantesimo a distanza. Se colpisci, il bersaglio subisce 4d12 danni radiosi. Che tu colpisca o manchi, il granello viene consumato. L'incantesimo termina in anticipo se consumi l'ultimo granello. Se ti rimangono quattro o più granelli, essi emanano luce intensa in un raggio di 9 metri e luce fioca per altri 9 metri. Se ti rimangono da uno a tre granelli, essi emanano luce fioca in un raggio di 9 metri.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 8° livello o superiore, il numero di granelli creati aumenta di due per ogni livello dello slot superiore al 7°.","language":"it","ui_language":"it"},{"id":"crusader-s-mantle","name":"Crusader's Mantle","name_it":"Manto del Crociato","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Un potere sacro si irradia da te in un'aura con un raggio di 9 metri, risvegliando l'ardimento nelle creature amichevoli. Fino al termine dell'incantesimo, l'aura si muove con te, rimanendo centrata su di te. Mentre si trova nell'aura, ogni creatura non ostile (incluso te) infligge 1d4 danni radiosi aggiuntivi quando colpisce con un attacco con un'arma.","language":"it","ui_language":"it"},{"id":"cure-wounds","name":"Cure Wounds","name_it":"Curare Ferite","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Cleric","Druid","Paladin","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura che tocchi recupera un numero di punti ferita pari a 1d8 + il tuo modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui non morti o sui costrutti.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, la guarigione aumenta di 1d8 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"dancing-lights","name":"Dancing Lights","name_it":"Luci Danzanti","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un po' di fosforo o di legno stregato, oppure una lucciola)","material":"un po' di fosforo o di legno stregato, oppure una lucciola","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei fino a quattro luci delle dimensioni di una torcia entro gittata, facendole apparire come torce, lanterne o orbi luminosi che fluttuano nell'aria per la durata. Puoi anche combinare le quattro luci in un'unica forma luminosa vagamente umanoide di taglia Media. Qualunque forma tu scelga, ogni luce emana luce fioca in un raggio di 3 metri.\nCome azione bonus nel tuo turno, puoi muovere le luci fino a 18 metri verso un nuovo punto entro gittata. Una luce deve trovarsi entro 6 metri da un'altra luce creata da questo incantesimo, e una luce si spegne se supera la gittata dell'incantesimo.","language":"it","ui_language":"it"},{"id":"danse-macabre","name":"Danse Macabre","name_it":"Danza Macabra","level":5,"level_it":"Livello 5","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fili di potere oscuro guizzano dalle tue dita per trafiggere fino a cinque cadaveri di taglia Piccola o Media che puoi vedere entro gittata. Ogni cadavere si rialza immediatamente e diventa non morto. Decidi se sia uno zombie o uno scheletro, e ottiene un bonus ai propri tiri per colpire e tiri per i danni pari al tuo modificatore di caratteristica da incantatore. Puoi usare un'azione bonus per comandare mentalmente le creature che crei con questo incantesimo, impartendo lo stesso comando a tutte. Per ricevere il comando, una creatura deve trovarsi entro 18 metri da te. Decidi quale azione compiranno le creature e dove si muoveranno durante il loro prossimo turno, oppure puoi impartire un comando generico, come sorvegliare una stanza o un passaggio contro i tuoi nemici. Se non impartisci comandi, le creature non fanno nulla tranne difendersi dalle creature ostili. Una volta ricevuto un ordine, le creature continuano a seguirlo finché il loro compito non è completato.\nLe creature sono sotto il tuo controllo fino al termine dell'incantesimo, dopodiché tornano a essere inanimate.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, animi fino a due cadaveri aggiuntivi per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"darkness","name":"Darkness","name_it":"Oscurità","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, M (pelo di pipistrello e una goccia di pece o un pezzo di carbone)","material":"pelo di pipistrello e una goccia di pece o un pezzo di carbone","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un'oscurità magica si diffonde da un punto a tua scelta entro gittata fino a riempire una sfera con raggio di 4,5 metri per la durata. L'oscurità si diffonde dietro gli angoli. Una creatura con scurovisione non può vedere attraverso questa oscurità, e la luce non magica non può illuminarla.\nSe il punto che scegli si trova su un oggetto che tieni in mano o su uno che non sia indossato né trasportato, l'oscurità emana dall'oggetto e si muove con esso. Coprire completamente la fonte dell'oscurità con un oggetto opaco, come una ciotola o un elmo, blocca l'oscurità.\nSe una qualsiasi parte dell'area di questo incantesimo si sovrappone a un'area di luce creata da un incantesimo di 2° livello o inferiore, l'incantesimo che ha creato la luce viene dissolto.","language":"it","ui_language":"it"},{"id":"darkvision","name":"Darkvision","name_it":"Scurovisione","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pizzico di carota essiccata oppure un'agata)","material":"un pizzico di carota essiccata oppure un'agata","duration":"8 ore","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente per conferirle la capacità di vedere nell'oscurità. Per la durata, quella creatura ha scurovisione fino a una distanza di 18 metri.","language":"it","ui_language":"it"},{"id":"dawn","name":"Dawn","name_it":"Alba","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un ciondolo a raggi di sole del valore di almeno 100 mo)","material":"un ciondolo a raggi di sole del valore di almeno 100 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"La luce dell'alba splende su un luogo che specifichi entro gittata. Fino al termine dell'incantesimo, vi brilla un cilindro di luce intensa con raggio di 9 metri e alto 12 metri. Questa luce è luce solare. Quando il cilindro appare, ogni creatura al suo interno deve effettuare un tiro salvezza su Costituzione, subendo 4d10 danni radiosi se fallisce il tiro salvezza, o la metà dei danni se lo supera. Una creatura deve effettuare questo tiro salvezza anche ogni volta che termina il proprio turno nel cilindro. Se ti trovi entro 18 metri dal cilindro, puoi spostarlo fino a 18 metri come azione bonus nel tuo turno.","language":"it","ui_language":"it"},{"id":"daylight","name":"Daylight","name_it":"Luce del Giorno","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"1 ora","classes":["Cleric","Druid","Paladin","Ranger","Sorcerer"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una sfera di luce con raggio di 18 metri si propaga da un punto a tua scelta entro gittata. La sfera è luce intensa ed emana luce fioca per altri 18 metri.\nSe hai scelto un punto su un oggetto che tieni in mano o su uno che non sia indossato né trasportato, la luce splende dall'oggetto e si muove con esso. Coprire completamente l'oggetto interessato con un oggetto opaco, come una ciotola o un elmo, blocca la luce.\nSe una qualsiasi parte dell'area di questo incantesimo si sovrappone a un'area di oscurità creata da un incantesimo di 3° livello o inferiore, l'incantesimo che ha creato l'oscurità viene dissolto.","language":"it","ui_language":"it"},{"id":"death-ward","name":"Death Ward","name_it":"Difesa dalla Morte","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"8 ore","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura e le conferisci una certa protezione dalla morte.\nLa prima volta che il bersaglio scenderebbe a 0 punti ferita a causa dei danni subiti, scende invece a 1 punto ferita, e l'incantesimo termina.\nSe l'incantesimo è ancora attivo quando il bersaglio è soggetto a un effetto che lo ucciderebbe all'istante senza infliggere danni, quell'effetto viene invece annullato nei confronti del bersaglio, e l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"delayed-blast-fireball","name":"Delayed Blast Fireball","name_it":"Palla di Fuoco a Scoppio Ritardato","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (una pallina di guano di pipistrello e zolfo)","material":"una pallina di guano di pipistrello e zolfo","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un raggio di luce gialla guizza dal tuo dito puntato, poi si condensa indugiando su un punto scelto entro gittata come una sfera incandescente per la durata. Quando l'incantesimo termina, perché la tua concentrazione viene interrotta o perché decidi di porvi fine, la sfera sboccia con un sordo boato in un'esplosione di fiamme che si diffonde dietro gli angoli. Ogni creatura in una sfera con raggio di 6 metri centrata su quel punto deve effettuare un tiro salvezza su Destrezza. Una creatura subisce danni da fuoco pari al totale dei danni accumulati se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nI danni base dell'incantesimo sono 12d6. Se al termine del tuo turno la sfera non è ancora detonata, i danni aumentano di 1d6.\nSe la sfera incandescente viene toccata prima che l'intervallo sia scaduto, la creatura che la tocca deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, l'incantesimo termina immediatamente, facendo erompere la sfera in fiamme. Con un tiro riuscito, la creatura può lanciare la sfera fino a 12 metri. Quando colpisce una creatura o un oggetto solido, l'incantesimo termina e la sfera esplode.\nIl fuoco danneggia gli oggetti nell'area e incendia quelli infiammabili che non siano indossati né trasportati.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 8° livello o superiore, i danni base aumentano di 1d6 per ogni livello dello slot superiore al 7°.","language":"it","ui_language":"it"},{"id":"demiplane","name":"Demiplane","name_it":"Semipiano","level":8,"level_it":"Livello 8","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S","material":"","duration":"1 ora","classes":["Warlock","Wizard","Sorcerer"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Crei una porta d'ombra su una superficie solida e piatta che puoi vedere entro gittata. La porta è abbastanza grande da consentire alle creature di taglia Media di passare senza impedimenti. Quando viene aperta, la porta conduce a un semipiano che appare come una stanza vuota di 9 metri per lato, fatta di legno o di pietra. Quando l'incantesimo termina, la porta scompare, e qualsiasi creatura o oggetto all'interno del semipiano vi rimane intrappolato, poiché la porta scompare anche dall'altro lato.\nOgni volta che lanci questo incantesimo, puoi creare un nuovo semipiano, oppure far sì che la porta d'ombra si colleghi a un semipiano che hai creato con un lancio precedente di questo incantesimo. Inoltre, se conosci la natura e il contenuto di un semipiano creato con un lancio di questo incantesimo da parte di un'altra creatura, puoi far sì che la porta d'ombra si colleghi al suo semipiano.","language":"it","ui_language":"it"},{"id":"destructive-wave","name":"Destructive Wave","name_it":"Onda Distruttiva","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 9 metri)","components":"V","material":"","duration":"Istantanea","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Colpisci il terreno, creando un'esplosione di energia divina che si propaga verso l'esterno da te. Ogni creatura a tua scelta entro 9 metri da te deve superare un tiro salvezza su Costituzione o subisce 5d6 danni da tuono, oltre a 5d6 danni radiosi o necrotici (a tua scelta), e viene buttata a terra prona. Una creatura che supera il proprio tiro salvezza subisce metà dei danni e non viene buttata a terra prona.","language":"it","ui_language":"it"},{"id":"detect-evil-and-good","name":"Detect Evil and Good","name_it":"Individuare il Bene e il Male","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, sai se c'è un'aberrazione, un celestiale, un elementale, un fatato, un immondo o un non morto entro 9 metri da te, così come la posizione in cui si trova la creatura. Allo stesso modo, sai se c'è un luogo o un oggetto entro 9 metri da te che è stato magicamente consacrato o profanato.\nL'incantesimo può penetrare la maggior parte delle barriere, ma viene bloccato da 30 centimetri di pietra, 2,5 centimetri di metallo comune, una sottile lamina di piombo o 90 centimetri di legno o terra.","language":"it","ui_language":"it"},{"id":"detect-magic","name":"Detect Magic","name_it":"Individuare il Magico","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Cleric","Druid","Paladin","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, percepisci la presenza di magia entro 9 metri da te. Se percepisci magia in questo modo, puoi usare la tua azione per vedere una debole aura attorno a qualsiasi creatura o oggetto visibile nell'area che rechi magia, e ne apprendi la scuola di magia, se ve n'è una.\nL'incantesimo può penetrare la maggior parte delle barriere, ma viene bloccato da 30 centimetri di pietra, 2,5 centimetri di metallo comune, una sottile lamina di piombo o 90 centimetri di legno o terra.","language":"it","ui_language":"it"},{"id":"detect-poison-and-disease","name":"Detect Poison and Disease","name_it":"Individuare Veleni e Malattie","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Personale","components":"V, S, M (una foglia di tasso)","material":"una foglia di tasso","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric","Druid","Paladin","Ranger"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, puoi percepire la presenza e la posizione di veleni, creature velenose e malattie entro 9 metri da te. In ogni caso, identifichi anche il tipo di veleno, creatura velenosa o malattia.\nL'incantesimo può penetrare la maggior parte delle barriere, ma viene bloccato da 30 centimetri di pietra, 2,5 centimetri di metallo comune, una sottile lamina di piombo o 90 centimetri di legno o terra.","language":"it","ui_language":"it"},{"id":"detect-thoughts","name":"Detect Thoughts","name_it":"Individuare Pensieri","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (una moneta di rame)","material":"una moneta di rame","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, puoi leggere i pensieri di determinate creature. Quando lanci l'incantesimo e come tua azione a ogni turno fino al termine dell'incantesimo, puoi concentrare la tua mente su una qualsiasi creatura che puoi vedere entro 9 metri da te. Se la creatura che scegli ha un'Intelligenza pari o inferiore a 3 o non parla alcuna lingua, la creatura non è interessata.\nInizialmente apprendi i pensieri superficiali della creatura, ossia ciò che ha più in mente in quel momento. Con un'azione, puoi spostare la tua attenzione sui pensieri di un'altra creatura o tentare di sondare più a fondo la mente della stessa creatura. Se sondi più a fondo, il bersaglio deve effettuare un tiro salvezza su Saggezza. Se fallisce, ottieni informazioni sul suo ragionamento (se ve n'è uno), sul suo stato emotivo e su qualcosa che occupa un posto rilevante nella sua mente (come qualcosa di cui si preoccupa, che ama o che odia). Se ha successo, l'incantesimo termina. In ogni caso, il bersaglio sa che stai sondando la sua mente e, a meno che tu non sposti la tua attenzione sui pensieri di un'altra creatura, la creatura può usare la propria azione nel suo turno per effettuare una prova di Intelligenza contrapposta alla tua prova di Intelligenza; se ha successo, l'incantesimo termina.\nLe domande rivolte verbalmente alla creatura bersaglio ne plasmano naturalmente il corso dei pensieri, quindi questo incantesimo è particolarmente efficace come parte di un interrogatorio.\nPuoi anche usare questo incantesimo per individuare la presenza di creature pensanti che non puoi vedere. Quando lanci l'incantesimo o come tua azione durante la durata, puoi cercare pensieri entro 9 metri da te. L'incantesimo può penetrare le barriere, ma 60 centimetri di roccia, 5 centimetri di qualsiasi metallo diverso dal piombo o una sottile lamina di piombo ti bloccano. Non puoi individuare una creatura con un'Intelligenza pari o inferiore a 3 o una che non parla alcuna lingua.\nUna volta individuata la presenza di una creatura in questo modo, puoi leggerne i pensieri per il resto della durata come descritto sopra, anche se non puoi vederla, ma essa deve comunque trovarsi entro gittata.","language":"it","ui_language":"it"},{"id":"dimension-door","name":"Dimension Door","name_it":"Porta Dimensionale","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"150 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Ti teletrasporti dalla tua posizione attuale a qualsiasi altro punto entro gittata. Arrivi esattamente nel punto desiderato. Può essere un luogo che puoi vedere, uno che puoi visualizzare o uno che puoi descrivere indicando distanza e direzione, come «60 metri dritto verso il basso» oppure «verso l'alto a nord-ovest con un angolo di 45 gradi, 90 metri».\nPuoi portare con te degli oggetti a patto che il loro peso non superi ciò che puoi trasportare. Puoi anche portare con te una creatura consenziente di taglia pari o inferiore alla tua che trasporti un equipaggiamento fino alla sua capacità di carico. La creatura deve trovarsi entro 1,5 metri da te quando lanci questo incantesimo.\nSe dovessi arrivare in un luogo già occupato da un oggetto o da una creatura, tu e qualsiasi creatura che viaggia con te subite ciascuno 4d6 danni da forza, e l'incantesimo non riesce a teletrasportarti.","language":"it","ui_language":"it"},{"id":"disguise-self","name":"Disguise Self","name_it":"Camuffare se Stessi","level":1,"level_it":"Livello 1","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"1 ora","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fai apparire diverso te stesso — inclusi vestiti, armatura, armi e altri averi sulla tua persona — fino al termine dell'incantesimo o finché non usi la tua azione per congedarlo. Puoi sembrare 30 centimetri più basso o più alto e puoi apparire magro, grasso o nella media. Non puoi cambiare il tuo tipo di corporatura, quindi devi adottare una forma che abbia la stessa disposizione di base degli arti. Per il resto, l'entità dell'illusione dipende da te.\nI cambiamenti operati da questo incantesimo non reggono a un'ispezione fisica. Per esempio, se usi questo incantesimo per aggiungere un cappello al tuo abbigliamento, gli oggetti passano attraverso il cappello, e chiunque lo tocchi non sentirebbe nulla o sentirebbe la tua testa e i tuoi capelli. Se usi questo incantesimo per apparire più magro di quanto sei, la mano di qualcuno che si protende per toccarti urterebbe contro di te mentre apparentemente si trova ancora a mezz'aria.\nPer accorgersi che sei camuffato, una creatura può usare la propria azione per ispezionare il tuo aspetto e deve superare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza del tuo incantesimo.","language":"it","ui_language":"it"},{"id":"disintegrate","name":"Disintegrate","name_it":"Disintegrazione","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una magnetite e un pizzico di polvere)","material":"una magnetite e un pizzico di polvere","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un sottile raggio verde scaturisce dal tuo dito puntato verso un bersaglio che puoi vedere entro gittata. Il bersaglio può essere una creatura, un oggetto o una creazione di forza magica, come la parete creata da muro di forza.\nUna creatura presa di mira da questo incantesimo deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, il bersaglio subisce 10d6 + 40 danni da forza. Il bersaglio viene disintegrato se questi danni lo lasciano con 0 punti ferita.\nUna creatura disintegrata e tutto ciò che indossa e trasporta, eccetto gli oggetti magici, sono ridotti a un mucchio di polvere grigia e fine. La creatura può essere riportata in vita solo per mezzo di un incantesimo vera resurrezione o desiderio.\nQuesto incantesimo disintegra automaticamente un oggetto non magico o una creazione di forza magica di taglia Grande o inferiore. Se il bersaglio è un oggetto o una creazione di forza di taglia Enorme o superiore, questo incantesimo ne disintegra una porzione pari a un cubo di 3 metri. Un oggetto magico non è interessato da questo incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, i danni aumentano di 3d6 per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"dispel-evil-and-good","name":"Dispel Evil and Good","name_it":"Dissolvere il Bene e il Male","level":5,"level_it":"Livello 5","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (acqua santa o argento e ferro in polvere)","material":"acqua santa o argento e ferro in polvere","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un'energia scintillante ti circonda e ti protegge dai fatati, dai non morti e dalle creature originarie di oltre il Piano Materiale. Per la durata, i celestiali, gli elementali, i fatati, gli immondi e i non morti hanno svantaggio ai tiri per colpire contro di te.\nPuoi terminare l'incantesimo in anticipo usando una delle seguenti funzioni speciali.\nSpezzare l'Incantamento. Con la tua azione, tocchi una creatura che puoi raggiungere e che è affascinata, spaventata o posseduta da un celestiale, un elementale, un fatato, un immondo o un non morto. La creatura che tocchi non è più affascinata, spaventata o posseduta da tali creature.\nCongedo. Con la tua azione, effettua un attacco con incantesimo in mischia contro un celestiale, un elementale, un fatato, un immondo o un non morto che puoi raggiungere. Se colpisci, tenti di respingere la creatura al suo piano natale. La creatura deve superare un tiro salvezza su Carisma o viene rispedita al suo piano natale (se non vi si trova già). Se non si trovano sul loro piano natale, i non morti vengono inviati allo Shadowfell e i fatati vengono inviati al Reame Fatato.","language":"it","ui_language":"it"},{"id":"dispel-magic","name":"Dispel Magic","name_it":"Dissolvi Magie","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Cleric","Druid","Paladin","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura, un oggetto o un effetto magico entro gittata. Qualsiasi incantesimo di 3° livello o inferiore sul bersaglio termina. Per ogni incantesimo di 4° livello o superiore sul bersaglio, effettua una prova di caratteristica usando la tua caratteristica da incantatore. La CD è pari a 10 + il livello dell'incantesimo. Con una prova riuscita, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, termini automaticamente gli effetti di un incantesimo sul bersaglio se il livello di quell'incantesimo è pari o inferiore al livello dello slot incantesimo che hai usato.","language":"it","ui_language":"it"},{"id":"dissonant-whispers","name":"Dissonant Whispers","name_it":"Sussurri Dissonanti","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Sussurri una melodia discordante che solo una creatura a tua scelta entro gittata può udire, straziandola con un dolore terribile. Il bersaglio deve effettuare un tiro salvezza su Saggezza. Con un tiro fallito, subisce 3d6 danni psichici e deve usare immediatamente la propria reazione, se disponibile, per allontanarsi da te per quanto glielo consente la sua velocità. La creatura non si dirige verso un terreno palesemente pericoloso, come un fuoco o una fossa. Con un tiro riuscito, il bersaglio subisce metà dei danni e non è costretto ad allontanarsi. Una creatura assordata supera automaticamente il tiro salvezza.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"divination","name":"Divination","name_it":"Divinazione","level":4,"level_it":"Livello 4","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Personale","components":"V, S, M (incenso e un'offerta sacrificale appropriata alla tua religione, del valore complessivo di almeno 25 mo, che l'incantesimo consuma)","material":"incenso e un'offerta sacrificale appropriata alla tua religione, del valore complessivo di almeno 25 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Cleric","Druid","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"},{"name":"Wizard","name_it":"Mago","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"La tua magia e un'offerta ti mettono in contatto con un dio o con i servitori di un dio. Poni un'unica domanda riguardante un obiettivo, un evento o un'attività specifici che si verificheranno entro 7 giorni. Il DM offre una risposta veritiera. La risposta potrebbe essere una breve frase, una rima criptica o un presagio.\nL'incantesimo non tiene conto di eventuali circostanze che potrebbero modificare l'esito, come il lancio di altri incantesimi o la perdita o l'aggiunta di un compagno.\nSe lanci l'incantesimo due o più volte prima di completare il tuo prossimo riposo lungo, c'è una probabilità cumulativa del 25 per cento per ogni lancio dopo il primo che tu ottenga una lettura casuale. Il DM effettua questo tiro in segreto.","language":"it","ui_language":"it"},{"id":"divine-favor","name":"Divine Favor","name_it":"Favore Divino","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"La tua preghiera ti potenzia con una radiosità divina. Fino al termine dell'incantesimo, i tuoi attacchi con armi infliggono 1d4 danni radiosi aggiuntivi se colpiscono.","language":"it","ui_language":"it"},{"id":"divine-word","name":"Divine Word","name_it":"Parola Divina","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"9 metri","components":"V","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Pronunci una parola divina, intrisa del potere che plasmò il mondo all'alba della creazione. Scegli un numero qualsiasi di creature che puoi vedere entro gittata. Ogni creatura che può sentirti deve effettuare un tiro salvezza su Carisma. Con un tiro fallito, una creatura subisce un effetto in base ai suoi punti ferita attuali:\n• 50 punti ferita o meno: assordata per 1 minuto\n• 40 punti ferita o meno: assordata e accecata per 10 minuti\n• 30 punti ferita o meno: accecata, assordata e stordita per 1 ora\n• 20 punti ferita o meno: uccisa all'istante\nIndipendentemente dai suoi punti ferita attuali, un celestiale, un elementale, un fatato o un immondo che fallisce il tiro salvezza viene respinto al suo piano di origine (se non vi si trova già) e non può tornare al tuo piano attuale per 24 ore con alcun mezzo che non sia un incantesimo desiderio.","language":"it","ui_language":"it"},{"id":"dominate-beast","name":"Dominate Beast","name_it":"Dominare Bestie","level":4,"level_it":"Livello 4","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di soggiogare una bestia che puoi vedere entro gittata. Essa deve superare un tiro salvezza su Saggezza o resta affascinata da te per la durata. Se tu o creature a te amichevoli la state combattendo, ha vantaggio al tiro salvezza.\nMentre la creatura è affascinata, hai un legame telepatico con essa finché vi trovate entrambi sullo stesso piano di esistenza. Puoi usare questo legame telepatico per impartire comandi alla creatura mentre sei cosciente (senza che ti sia richiesta alcuna azione), che essa fa del suo meglio per obbedire. Puoi specificare una linea d'azione semplice e generica, come «Attacca quella creatura», «Corri laggiù» o «Recupera quell'oggetto». Se la creatura completa l'ordine e non riceve ulteriori indicazioni da te, si difende e si preserva al meglio delle proprie capacità.\nPuoi usare la tua azione per assumere il controllo totale e preciso del bersaglio. Fino al termine del tuo prossimo turno, la creatura compie solo le azioni che scegli tu e non fa nulla che tu non le permetta di fare. Durante questo periodo, puoi anche far sì che la creatura usi una reazione, ma ciò richiede che usi anche la tua reazione. Ogni volta che il bersaglio subisce danni, effettua un nuovo tiro salvezza su Saggezza contro l'incantesimo. Se il tiro salvezza ha successo, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo con uno slot incantesimo di 5° livello, la durata diventa concentrazione, fino a 10 minuti. Quando usi uno slot incantesimo di 6° livello, la durata diventa concentrazione, fino a 1 ora. Quando usi uno slot incantesimo di 7° livello o superiore, la durata diventa concentrazione, fino a 8 ore.","language":"it","ui_language":"it"},{"id":"dominate-monster","name":"Dominate Monster","name_it":"Dominare Mostri","level":8,"level_it":"Livello 8","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di soggiogare una creatura che puoi vedere entro gittata. Essa deve superare un tiro salvezza su Saggezza o resta affascinata da te per la durata. Se tu o creature a te amichevoli la state combattendo, ha vantaggio al tiro salvezza.\nMentre la creatura è affascinata, hai un legame telepatico con essa finché vi trovate entrambi sullo stesso piano di esistenza. Puoi usare questo legame telepatico per impartire comandi alla creatura mentre sei cosciente (senza che ti sia richiesta alcuna azione), che essa fa del suo meglio per obbedire. Puoi specificare una linea d'azione semplice e generica, come «Attacca quella creatura», «Corri laggiù» o «Recupera quell'oggetto». Se la creatura completa l'ordine e non riceve ulteriori indicazioni da te, si difende e si preserva al meglio delle proprie capacità.\nPuoi usare la tua azione per assumere il controllo totale e preciso del bersaglio. Fino al termine del tuo prossimo turno, la creatura compie solo le azioni che scegli tu e non fa nulla che tu non le permetta di fare. Durante questo periodo, puoi anche far sì che la creatura usi una reazione, ma ciò richiede che usi anche la tua reazione. Ogni volta che il bersaglio subisce danni, effettua un nuovo tiro salvezza su Saggezza contro l'incantesimo. Se il tiro salvezza ha successo, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo con uno slot incantesimo di 9° livello, la durata diventa concentrazione, fino a 8 ore.","language":"it","ui_language":"it"},{"id":"dominate-person","name":"Dominate Person","name_it":"Dominare Persone","level":5,"level_it":"Livello 5","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di soggiogare un umanoide che puoi vedere entro gittata. Esso deve superare un tiro salvezza su Saggezza o resta affascinato da te per la durata. Se tu o creature a te amichevoli lo state combattendo, ha vantaggio al tiro salvezza.\nMentre la creatura è affascinata, hai un legame telepatico con essa finché vi trovate entrambi sullo stesso piano di esistenza. Puoi usare questo legame telepatico per impartire comandi alla creatura mentre sei cosciente (senza che ti sia richiesta alcuna azione), che essa fa del suo meglio per obbedire. Puoi specificare una linea d'azione semplice e generica, come «Attacca quella creatura», «Corri laggiù» o «Recupera quell'oggetto». Se la creatura completa l'ordine e non riceve ulteriori indicazioni da te, si difende e si preserva al meglio delle proprie capacità.\nPuoi usare la tua azione per assumere il controllo totale e preciso del bersaglio. Fino al termine del tuo prossimo turno, la creatura compie solo le azioni che scegli tu e non fa nulla che tu non le permetta di fare. Durante questo periodo, puoi anche far sì che la creatura usi una reazione, ma ciò richiede che usi anche la tua reazione. Ogni volta che il bersaglio subisce danni, effettua un nuovo tiro salvezza su Saggezza contro l'incantesimo. Se il tiro salvezza ha successo, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello, la durata diventa concentrazione, fino a 10 minuti. Quando usi uno slot incantesimo di 7° livello, la durata diventa concentrazione, fino a 1 ora. Quando usi uno slot incantesimo di 8° livello o superiore, la durata diventa concentrazione, fino a 8 ore.","language":"it","ui_language":"it"},{"id":"draconic-transformation","name":"Draconic Transformation","name_it":"Trasformazione Draconica","level":7,"level_it":"Livello 7","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale (cono di 18 metri)","components":"V, S, M (una statuetta di drago, del valore di almeno 500 mo)","material":"una statuetta di drago, del valore di almeno 500 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"Il lanciatore ottiene vista cieca (9 metri), un'arma a soffio (6d8 danni da forza in un cono di 18 metri) e ali (velocità di volo di 18 metri).","language":"it","ui_language":"it"},{"id":"dragon-s-breath","name":"Dragon's Breath","name_it":"Soffio del Drago","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Contatto","components":"V, S, M (un peperoncino piccante)","material":"un peperoncino piccante","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Tocchi una creatura consenziente e la imbevi del potere di sputare energia magica dalla bocca, a patto che ne abbia una. Scegli acido, freddo, fuoco, fulmine o veleno. Fino al termine dell'incantesimo, la creatura può usare un'azione per esalare energia del tipo scelto in un cono di 4,5 metri. Ogni creatura in quell'area deve effettuare un tiro salvezza su Destrezza, subendo 3d6 danni del tipo scelto se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"drawmij-s-instant-summons","name":"Drawmij's Instant Summons","name_it":"Evocazione Istantanea di Drawmij","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":true,"casting_time":"1 minuto","range":"Contatto","components":"V, S, M (uno zaffiro del valore di 1.000 mo)","material":"uno zaffiro del valore di 1.000 mo","duration":"Finché non viene dissolto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un oggetto del peso di 5 chilogrammi o meno la cui dimensione più lunga sia di 1,8 metri o meno. L'incantesimo lascia un marchio invisibile sulla sua superficie e iscrive invisibilmente il nome dell'oggetto sullo zaffiro che usi come componente materiale. Ogni volta che lanci questo incantesimo, devi usare uno zaffiro diverso.\nIn qualsiasi momento successivo, puoi usare la tua azione per pronunciare il nome dell'oggetto e frantumare lo zaffiro. L'oggetto appare istantaneamente nella tua mano indipendentemente dalle distanze fisiche o planari, e l'incantesimo termina.\nSe un'altra creatura tiene o trasporta l'oggetto, frantumare lo zaffiro non trasporta l'oggetto da te, ma scopri invece chi è la creatura che possiede l'oggetto e approssimativamente dove si trova quella creatura in quel momento.\nDissolvi magie o un effetto simile applicato con successo allo zaffiro pone fine all'effetto di questo incantesimo.","language":"it","ui_language":"it"},{"id":"dream","name":"Dream","name_it":"Sogno","level":5,"level_it":"Livello 5","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 minuto","range":"Speciale","components":"V, S, M (una manciata di sabbia, un po' d'inchiostro e una penna d'oca strappata a un uccello addormentato)","material":"una manciata di sabbia, un po' d'inchiostro e una penna d'oca strappata a un uccello addormentato","duration":"8 ore","classes":["Bard","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo plasma i sogni di una creatura. Scegli una creatura a te nota come bersaglio di questo incantesimo. Il bersaglio deve trovarsi sul tuo stesso piano di esistenza. Le creature che non dormono, come gli elfi, non possono essere contattate da questo incantesimo. Tu, o una creatura consenziente che tocchi, entri in uno stato di trance, agendo da messaggero. Mentre è in trance, il messaggero è consapevole di ciò che lo circonda, ma non può compiere azioni né muoversi.\nSe il bersaglio sta dormendo, il messaggero appare nei sogni del bersaglio e può conversare con lui finché rimane addormentato, per tutta la durata dell'incantesimo. Il messaggero può anche plasmare l'ambiente del sogno, creando paesaggi, oggetti e altre immagini. Il messaggero può emergere dalla trance in qualsiasi momento, ponendo fine in anticipo all'effetto dell'incantesimo. Il bersaglio ricorda perfettamente il sogno al risveglio. Se il bersaglio è sveglio quando lanci l'incantesimo, il messaggero lo sa e può porre fine alla trance (e all'incantesimo) o attendere che il bersaglio si addormenti, momento in cui il messaggero appare nei sogni del bersaglio.\nPuoi far apparire il messaggero mostruoso e terrificante agli occhi del bersaglio. In tal caso, il messaggero può recapitare un messaggio di non più di dieci parole, dopodiché il bersaglio deve effettuare un tiro salvezza su Saggezza. Con un tiro fallito, gli echi della mostruosità fantasmatica generano un incubo che dura per tutta la durata del sonno del bersaglio e gli impedisce di trarre qualsiasi beneficio da quel riposo. Inoltre, al risveglio, il bersaglio subisce 3d6 danni psichici.\nSe possiedi una parte del corpo, una ciocca di capelli, un ritaglio di unghia o una porzione simile del corpo del bersaglio, il bersaglio effettua il tiro salvezza con svantaggio.","language":"it","ui_language":"it"},{"id":"dream-of-the-blue-veil","name":"Dream of the Blue Veil","name_it":"Sogno del Velo Azzurro","level":7,"level_it":"Livello 7","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"10 minuti","range":"6 metri","components":"V, S, M (un oggetto magico o una creatura consenziente proveniente dal mondo di destinazione)","material":"un oggetto magico o una creatura consenziente proveniente dal mondo di destinazione","duration":"6 ore","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Tu e un massimo di otto creature consenzienti entro gittata cadete privi di sensi per la durata dell'incantesimo e fate esperienza di visioni di un altro mondo del Piano Materiale, come Oerth, Toril, Krynn o Eberron. Se l'incantesimo raggiunge la sua durata completa, le visioni si concludono con ciascuno di voi che incontra e scosta un misterioso sipario azzurro. L'incantesimo termina poi con il tuo trasporto mentale e fisico nel mondo che era nelle visioni.\nPer lanciare questo incantesimo, devi avere un oggetto magico originario del mondo che desideri raggiungere, e devi essere consapevole dell'esistenza di quel mondo, anche se non ne conosci il nome. La tua destinazione nell'altro mondo è un luogo sicuro entro 1,5 chilometri da dove l'oggetto magico è stato creato. In alternativa, puoi lanciare l'incantesimo se una delle creature interessate è nata nell'altro mondo, il che fa sì che la tua destinazione sia un luogo sicuro entro 1,5 chilometri da dove quella creatura è nata.\nL'incantesimo termina in anticipo su una creatura se quella creatura subisce danni, e la creatura non viene trasportata. Se tu subisci danni, l'incantesimo termina per te e per tutte le altre creature, e nessuno di voi viene trasportato.","language":"it","ui_language":"it"},{"id":"druid-grove","name":"Druid Grove","name_it":"Boschetto del Druido","level":6,"level_it":"Livello 6","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"10 minuti","range":"Contatto","components":"V, S, M (vischio, che l'incantesimo consuma, raccolto con un falcetto d'oro alla luce della luna piena)","material":"vischio, che l'incantesimo consuma, raccolto con un falcetto d'oro alla luce della luna piena","duration":"24 ore","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Invochi gli spiriti della natura per proteggere un'area all'aperto o sottoterra. L'area può essere piccola come un cubo di 9 metri o grande come un cubo di 27 metri. Gli edifici e le altre strutture sono esclusi dall'area interessata. Se lanci questo incantesimo nella stessa area ogni giorno per un anno, l'incantesimo dura finché non viene dissolto. L'incantesimo crea i seguenti effetti all'interno dell'area. Quando lanci questo incantesimo, puoi indicare delle creature come amiche, che sono immuni agli effetti. Puoi anche specificare una parola d'ordine che, se pronunciata ad alta voce, rende chi la pronuncia immune a questi effetti. L'intera area protetta irradia magia. Un dissolvi magie lanciato sull'area, se ha successo, rimuove solo uno dei seguenti effetti, non l'intera area. Il lanciatore di quell'incantesimo sceglie quale effetto terminare. Solo quando tutti i suoi effetti sono scomparsi questo incantesimo è dissolto.\nNebbia Solida. Puoi riempire un numero qualsiasi di quadrati di 1,5 metri sul terreno con una fitta nebbia, rendendoli fortemente oscurati. La nebbia raggiunge un'altezza di 3 metri. Inoltre, ogni metro di movimento attraverso la nebbia costa 2 metri supplementari. Per una creatura immune a questo effetto, la nebbia non oscura nulla e appare come una soffice foschia, con granelli di luce verde fluttuanti nell'aria.\nSottobosco Afferrante. Puoi riempire un numero qualsiasi di quadrati di 1,5 metri sul terreno non occupati dalla nebbia con erbacce e rampicanti afferranti, come se fossero interessati da un incantesimo intralciare. Per una creatura immune a questo effetto, le erbacce e i rampicanti risultano morbidi e si rimodellano per fungere da sedute o giacigli temporanei.\nGuardiani del Boschetto. Puoi animare fino a quattro alberi nell'area, facendoli sradicare dal terreno. Questi alberi hanno le stesse statistiche di un albero risvegliato, tranne che non possono parlare, e la loro corteccia è ricoperta di simboli druidici. Se una creatura non immune a questo effetto entra nell'area protetta, i guardiani del boschetto combattono finché non hanno scacciato o ucciso gli intrusi. I guardiani del boschetto obbediscono anche ai comandi che pronunci (senza che ti sia richiesta alcuna azione) mentre ti trovi nell'area. Se non impartisci loro comandi e non sono presenti intrusi, i guardiani del boschetto non fanno nulla. I guardiani del boschetto non possono lasciare l'area protetta. Quando l'incantesimo termina, la magia che li anima scompare e gli alberi tornano a radicarsi se possibile.\nEffetto Magico Aggiuntivo. Puoi collocare a tua scelta uno dei seguenti effetti magici all'interno dell'area protetta:\n• Una costante raffica di vento in due punti a tua scelta\n• Crescita spinata in un punto a tua scelta\n• Muro di vento in due punti a tua scelta\nPer una creatura immune a questo effetto, i venti sono una brezza delicata e profumata, e l'area di crescita spinata è innocua.","language":"it","ui_language":"it"},{"id":"druidcraft","name":"Druidcraft","name_it":"Artificio Druidico","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Sussurrando agli spiriti della natura, crei uno dei seguenti effetti entro gittata:\n• Crei un minuscolo e innocuo effetto sensoriale che predice quale sarà il tempo atmosferico nella tua posizione per le prossime 24 ore. L'effetto potrebbe manifestarsi come un orbe dorato per cielo sereno, una nuvola per pioggia, fiocchi di neve che cadono per neve e così via. Questo effetto persiste per 1 round.\n• Fai sbocciare istantaneamente un fiore, aprire un baccello o schiudere una gemma fogliare.\n• Crei un effetto sensoriale istantaneo e innocuo, come foglie che cadono, un soffio di vento, il verso di un piccolo animale o il debole odore di una puzzola. L'effetto deve rientrare in un cubo di 1,5 metri.\n• Accendi o spegni istantaneamente una candela, una torcia o un piccolo fuoco da campo.","language":"it","ui_language":"it"},{"id":"dust-devil","name":"Dust Devil","name_it":"Diavolo di Polvere","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pizzico di polvere)","material":"un pizzico di polvere","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un cubo d'aria libero di 1,5 metri che puoi vedere entro gittata. Una forza elementale che somiglia a un turbine di polvere appare nel cubo e dura per la durata dell'incantesimo.\nQualsiasi creatura che termina il proprio turno entro 1,5 metri dal diavolo di polvere deve effettuare un tiro salvezza su Forza. Con un tiro fallito, la creatura subisce 1d8 danni contundenti ed è spinta di 3 metri lontano dal diavolo di polvere. Con un tiro riuscito, la creatura subisce metà dei danni e non è spinta.\nCome azione bonus, puoi muovere il diavolo di polvere fino a 9 metri in qualsiasi direzione. Se il diavolo di polvere si muove sopra sabbia, polvere, terra smossa o ghiaia leggera, ne aspira il materiale e forma attorno a sé una nube di detriti con raggio di 3 metri che dura fino all'inizio del tuo prossimo turno. La nube oscura fortemente la propria area.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"earth-tremor","name":"Earth Tremor","name_it":"Tremore Tellurico","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"3 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Druid","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Provochi un tremore nel terreno entro gittata. Ogni creatura diversa da te in quell'area deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, una creatura subisce 1d6 danni contundenti ed è buttata a terra prona. Se il terreno in quell'area è terra smossa o pietra, diventa terreno difficile finché non viene sgombrato, con ogni porzione di 1,5 metri di diametro che richiede almeno 1 minuto per essere sgombrata a mano.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"earthbind","name":"Earthbind","name_it":"Vincolo Terrestre","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli una creatura che puoi vedere entro gittata. Strisce gialle di energia magica si avvolgono attorno alla creatura. Il bersaglio deve superare un tiro salvezza su Forza, oppure la sua velocità di volo (se ne ha una) è ridotta a 0 metri per la durata dell'incantesimo. Una creatura in volo interessata da questo incantesimo scende di 18 metri per round finché non raggiunge il suolo o finché l'incantesimo non termina.","language":"it","ui_language":"it"},{"id":"earthquake","name":"Earthquake","name_it":"Terremoto","level":8,"level_it":"Livello 8","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"150 metri","components":"V, S, M (un pizzico di terra, un pezzo di roccia e un grumo di argilla)","material":"un pizzico di terra, un pezzo di roccia e un grumo di argilla","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Druid","Sorcerer"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un disturbo sismico in un punto sul terreno che puoi vedere entro gittata. Per la durata, un tremore intenso percorre il terreno in un cerchio con raggio di 30 metri centrato su quel punto e scuote le creature e le strutture a contatto con il terreno in quell'area.\nIl terreno nell'area diventa terreno difficile. Ogni creatura sul terreno che si sta concentrando deve effettuare un tiro salvezza su Costituzione. Con un tiro fallito, la concentrazione della creatura viene interrotta.\nQuando lanci questo incantesimo e al termine di ogni turno in cui ti concentri su di esso, ogni creatura sul terreno nell'area deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, la creatura è buttata a terra prona.\nQuesto incantesimo può avere effetti aggiuntivi a seconda del terreno nell'area, come determinato dal DM.\nCrepacci. All'inizio del tuo prossimo turno dopo aver lanciato l'incantesimo, si aprono crepacci in tutta l'area dell'incantesimo. Si aprono in totale 1d6 di tali crepacci in punti scelti dal DM. Ciascuno è profondo 1d10 × 3 metri, largo 3 metri e si estende da un bordo dell'area dell'incantesimo al lato opposto. Una creatura che si trova in un punto in cui si apre un crepaccio deve superare un tiro salvezza su Destrezza o vi cade dentro. Una creatura che supera il tiro salvezza si sposta con il bordo del crepaccio mentre si apre.\nUn crepaccio che si apre sotto una struttura ne provoca il crollo automatico (vedi sotto).\nStrutture. Il tremore infligge 50 danni contundenti a qualsiasi struttura a contatto con il terreno nell'area quando lanci l'incantesimo e all'inizio di ogni tuo turno fino al termine dell'incantesimo. Se una struttura scende a 0 punti ferita, crolla e potenzialmente danneggia le creature vicine. Una creatura entro metà della distanza pari all'altezza di una struttura deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, la creatura subisce 5d6 danni contundenti, è buttata a terra prona ed è sepolta dalle macerie, richiedendo una prova di Forza (Atletica) con CD 20 come azione per liberarsi. Il DM può aumentare o diminuire la CD, a seconda della natura delle macerie. Con un tiro riuscito, la creatura subisce metà dei danni e non è buttata a terra prona né sepolta.","language":"it","ui_language":"it"},{"id":"eldritch-blast","name":"Eldritch Blast","name_it":"Raggio Occulto","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un raggio di energia crepitante sfreccia verso una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, il bersaglio subisce 1d10 danni da forza.\nL'incantesimo crea più di un raggio quando raggiungi i livelli superiori: due raggi al 5° livello, tre raggi all'11° livello e quattro raggi al 17° livello. Puoi dirigere i raggi sullo stesso bersaglio o su bersagli diversi. Effettua un tiro per colpire separato per ciascun raggio.","language":"it","ui_language":"it"},{"id":"elemental-bane","name":"Elemental Bane","name_it":"Rovina Elementale","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli una creatura che puoi vedere entro gittata e scegli uno dei seguenti tipi di danno: acido, freddo, fuoco, fulmine o tuono. Il bersaglio deve superare un tiro salvezza su Costituzione o è interessato dall'incantesimo per la durata. La prima volta che a ogni turno il bersaglio interessato subisce danni del tipo scelto, subisce 2d6 danni aggiuntivi di quel tipo. Inoltre, il bersaglio perde qualsiasi resistenza a quel tipo di danno fino al termine dell'incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 4°.\nLe creature devono trovarsi entro 9 metri l'una dall'altra quando le prendi di mira.","language":"it","ui_language":"it"},{"id":"elemental-weapon","name":"Elemental Weapon","name_it":"Arma Elementale","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Paladin","Druid","Ranger"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore","description":"Un'arma non magica che tocchi diventa un'arma magica. Scegli uno dei seguenti tipi di danno: acido, freddo, fuoco, fulmine o tuono. Per la durata, l'arma ha un bonus di +1 ai tiri per colpire e infligge 1d4 danni aggiuntivi del tipo scelto quando colpisce.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° o 6° livello, il bonus ai tiri per colpire aumenta a +2 e i danni aggiuntivi aumentano a 2d4. Quando usi uno slot incantesimo di 7° livello o superiore, il bonus aumenta a +3 e i danni aggiuntivi aumentano a 3d4.","language":"it","ui_language":"it"},{"id":"enemies-abound","name":"Enemies Abound","name_it":"Nemici Ovunque","level":3,"level_it":"Livello 3","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Penetri nella mente di una creatura che puoi vedere e la costringi a effettuare un tiro salvezza su Intelligenza. Una creatura supera automaticamente il tiro se è immune all'essere spaventata. Con un tiro fallito, il bersaglio perde la capacità di distinguere gli amici dai nemici, considerando come nemiche tutte le creature che può vedere fino al termine dell'incantesimo. Ogni volta che il bersaglio subisce danni, può ripetere il tiro salvezza, ponendo fine all'effetto su di sé con un successo.\nOgni volta che la creatura interessata sceglie un'altra creatura come bersaglio, deve sceglierlo a caso tra le creature che può vedere entro la gittata dell'attacco, dell'incantesimo o dell'altra capacità che sta usando. Se un nemico provoca un attacco di opportunità dalla creatura interessata, la creatura deve effettuare quell'attacco se ne è in grado.","language":"it","ui_language":"it"},{"id":"enervation","name":"Enervation","name_it":"Snervamento","level":5,"level_it":"Livello 5","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Un tentacolo di tenebra come inchiostro si protende da te, toccando una creatura che puoi vedere entro gittata per prosciugarne la vita. Il bersaglio deve effettuare un tiro salvezza su Destrezza. Con un tiro riuscito, il bersaglio subisce 2d8 danni necrotici e l'incantesimo termina. Con un tiro fallito, il bersaglio subisce 4d8 danni necrotici e, fino al termine dell'incantesimo, puoi usare la tua azione a ogni tuo turno per infliggere automaticamente 4d8 danni necrotici al bersaglio. L'incantesimo termina se usi la tua azione per fare qualcos'altro, se il bersaglio si trova in qualsiasi momento fuori dalla gittata dell'incantesimo o se il bersaglio ha copertura totale rispetto a te. Ogni volta che l'incantesimo infligge danni a un bersaglio, recuperi punti ferita pari alla metà dei danni necrotici subiti dal bersaglio.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"enhance-ability","name":"Enhance Ability","name_it":"Potenziare Caratteristica","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (pelo o una piuma di una bestia)","material":"pelo o una piuma di una bestia","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Cleric","Druid","Sorcerer","Ranger","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"},{"name":"Wizard","name_it":"Mago","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura e le conferisci un potenziamento magico. Scegli uno dei seguenti effetti; il bersaglio ottiene quell'effetto fino al termine dell'incantesimo.\nTempra dell'Orso. Il bersaglio ha vantaggio alle prove di Costituzione. Ottiene inoltre 2d6 punti ferita temporanei, che vengono persi quando l'incantesimo termina.\nForza del Toro. Il bersaglio ha vantaggio alle prove di Forza e la sua capacità di carico raddoppia.\nGrazia del Gatto. Il bersaglio ha vantaggio alle prove di Destrezza. Inoltre non subisce danni da cadute di 6 metri o meno se non è incapacitato.\nSplendore dell'Aquila. Il bersaglio ha vantaggio alle prove di Carisma.\nAstuzia della Volpe. Il bersaglio ha vantaggio alle prove di Intelligenza.\nSaggezza del Gufo. Il bersaglio ha vantaggio alle prove di Saggezza.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"enlarge-reduce","name":"Enlarge/Reduce","name_it":"Ingrandire/Ridurre","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un pizzico di ferro in polvere)","material":"un pizzico di ferro in polvere","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard","Bard","Druid"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Fai sì che una creatura o un oggetto che puoi vedere entro gittata diventi più grande o più piccolo per la durata. Scegli una creatura oppure un oggetto che non sia indossato né trasportato. Se il bersaglio è riluttante, può effettuare un tiro salvezza su Costituzione. Con un successo, l'incantesimo non ha effetto.\nSe il bersaglio è una creatura, tutto ciò che indossa e trasporta cambia dimensione con lei. Qualsiasi oggetto lasciato cadere da una creatura interessata torna immediatamente alle dimensioni normali.\nIngrandire. Le dimensioni del bersaglio raddoppiano in tutte le direzioni e il suo peso è moltiplicato per otto. Questa crescita aumenta la sua taglia di una categoria, ad esempio da Media a Grande. Se non c'è abbastanza spazio perché il bersaglio raddoppi le proprie dimensioni, la creatura o l'oggetto raggiunge la massima dimensione possibile nello spazio disponibile. Fino al termine dell'incantesimo, il bersaglio ha inoltre vantaggio alle prove di Forza e ai tiri salvezza su Forza. Anche le armi del bersaglio crescono per adeguarsi alle sue nuove dimensioni. Mentre queste armi sono ingrandite, gli attacchi del bersaglio con esse infliggono 1d4 danni aggiuntivi.\nRidurre. Le dimensioni del bersaglio si dimezzano in tutte le direzioni e il suo peso è ridotto a un ottavo del normale. Questa riduzione diminuisce la sua taglia di una categoria, ad esempio da Media a Piccola. Fino al termine dell'incantesimo, il bersaglio ha inoltre svantaggio alle prove di Forza e ai tiri salvezza su Forza. Anche le armi del bersaglio si rimpiccioliscono per adeguarsi alle sue nuove dimensioni. Mentre queste armi sono ridotte, gli attacchi del bersaglio con esse infliggono 1d4 danni in meno (ciò non può ridurre i danni al di sotto di 1).","language":"it","ui_language":"it"},{"id":"ensnaring-strike","name":"Ensnaring Strike","name_it":"Colpo Intrappolante","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci una creatura con un attacco con un'arma prima che questo incantesimo termini, una massa contorta di rampicanti spinosi appare nel punto d'impatto, e il bersaglio deve superare un tiro salvezza su Forza o resta trattenuto dai rampicanti magici fino al termine dell'incantesimo. Una creatura di taglia Grande o superiore ha vantaggio a questo tiro salvezza. Se il bersaglio supera il tiro salvezza, i rampicanti avvizziscono. Mentre è trattenuto da questo incantesimo, il bersaglio subisce 1d6 danni perforanti all'inizio di ogni suo turno. Una creatura trattenuta dai rampicanti, o una che può toccarla, può usare la propria azione per effettuare una prova di Forza contro la CD del tiro salvezza del tuo incantesimo. Con un successo, il bersaglio è liberato.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"entangle","name":"Entangle","name_it":"Intralciare","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Erbacce e rampicanti afferranti spuntano dal terreno in un quadrato di 6 metri a partire da un punto entro gittata. Per la durata, queste piante trasformano il terreno nell'area in terreno difficile.\nUna creatura nell'area quando lanci l'incantesimo deve superare un tiro salvezza su Forza o resta trattenuta dalle piante intralcianti fino al termine dell'incantesimo. Una creatura trattenuta dalle piante può usare la propria azione per effettuare una prova di Forza contro la CD del tiro salvezza del tuo incantesimo. Con un successo, si libera.\nQuando l'incantesimo termina, le piante evocate avvizziscono.","language":"it","ui_language":"it"},{"id":"enthrall","name":"Enthrall","name_it":"Avvincere","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"1 minuto","classes":["Bard","Warlock"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Intrecci una sequenza di parole che distrae, facendo sì che le creature a tua scelta che puoi vedere entro gittata e che possono sentirti effettuino un tiro salvezza su Saggezza. Qualsiasi creatura che non può essere affascinata supera automaticamente questo tiro salvezza e, se tu o i tuoi compagni state combattendo una creatura, essa ha vantaggio al tiro salvezza. Con un tiro fallito, il bersaglio ha svantaggio alle prove di Saggezza (Percezione) effettuate per percepire qualsiasi creatura diversa da te fino al termine dell'incantesimo o finché il bersaglio non riesce più a sentirti. L'incantesimo termina se sei incapacitato o non riesci più a parlare.","language":"it","ui_language":"it"},{"id":"erupting-earth","name":"Erupting Earth","name_it":"Terra Eruttante","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un pezzo di ossidiana)","material":"un pezzo di ossidiana","duration":"Istantanea","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un punto che puoi vedere sul terreno entro gittata. Una fontana di terra e pietra rivoltate erompe in un cubo di 6 metri centrato su quel punto. Ogni creatura in quell'area deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 3d12 danni contundenti se fallisce il tiro salvezza, o la metà dei danni se lo supera. Inoltre, il terreno in quell'area diventa terreno difficile finché non viene sgombrato. Ogni porzione quadrata di 1,5 metri dell'area richiede almeno 1 minuto per essere sgombrata a mano.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d12 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"etherealness","name":"Etherealness","name_it":"Etereità","level":7,"level_it":"Livello 7","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Fino a 8 ore","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Entri nelle regioni di confine del Piano Etereo, nell'area in cui esso si sovrappone al tuo piano attuale. Rimani nell'Etereo di Confine per la durata o finché non usi la tua azione per congedare l'incantesimo. Durante questo periodo, puoi muoverti in qualsiasi direzione. Se ti muovi verso l'alto o verso il basso, ogni metro di movimento costa un metro extra. Puoi vedere e udire il piano da cui provieni, ma tutto ciò che vi si trova appare grigio, e non puoi vedere nulla che sia a più di 18 metri di distanza.\nMentre ti trovi nel Piano Etereo, puoi influenzare ed essere influenzato solo da altre creature presenti su quel piano. Le creature che non si trovano nel Piano Etereo non possono percepirti né interagire con te, a meno che una capacità speciale o una magia non abbia conferito loro la capacità di farlo.\nIgnori tutti gli oggetti e gli effetti che non si trovano nel Piano Etereo, il che ti permette di muoverti attraverso gli oggetti che percepisci sul piano da cui provieni.\nQuando l'incantesimo termina, torni immediatamente al piano da cui provieni, nel punto che occupi in quel momento. Se occupi lo stesso punto di un oggetto solido o di una creatura quando ciò avviene, vieni immediatamente spostato nello spazio libero più vicino che puoi occupare e subisci danni da forza pari al doppio del numero di metri di cui vieni spostato.\nQuesto incantesimo non ha effetto se lo lanci mentre ti trovi nel Piano Etereo o in un piano che non confina con esso, come uno dei Piani Esterni.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 8° livello o superiore, puoi prendere di mira fino a tre creature consenzienti (incluso te) per ogni livello dello slot superiore al 7°. Le creature devono trovarsi entro 3 metri da te quando lanci l'incantesimo.","language":"it","ui_language":"it"},{"id":"evard-s-black-tentacles","name":"Evard's Black Tentacles","name_it":"Tentacoli Neri di Evard","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un pezzo di tentacolo di polpo gigante o di calamaro gigante)","material":"un pezzo di tentacolo di polpo gigante o di calamaro gigante","duration":"Concentrazione, fino a 1 minuto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tentacoli neri e contorti riempiono un quadrato di 6 metri sul terreno che puoi vedere entro gittata. Per la durata, questi tentacoli trasformano il terreno nell'area in terreno difficile.\nQuando una creatura entra nell'area interessata per la prima volta in un turno o vi inizia il proprio turno, deve superare un tiro salvezza su Destrezza o subisce 3d6 danni contundenti ed è trattenuta dai tentacoli fino al termine dell'incantesimo. Una creatura che inizia il proprio turno nell'area ed è già trattenuta dai tentacoli subisce 3d6 danni contundenti.\nUna creatura trattenuta dai tentacoli può usare la propria azione per effettuare una prova di Forza o di Destrezza (a sua scelta) contro la CD del tiro salvezza del tuo incantesimo. Con un successo, si libera.","language":"it","ui_language":"it"},{"id":"expeditious-retreat","name":"Expeditious Retreat","name_it":"Ritirata Veloce","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo ti permette di muoverti a un ritmo incredibile. Quando lanci questo incantesimo, e poi come azione bonus a ogni tuo turno fino al termine dell'incantesimo, puoi compiere l'azione di Scatto.","language":"it","ui_language":"it"},{"id":"eyebite","name":"Eyebite","name_it":"Malocchio","level":6,"level_it":"Livello 6","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata dell'incantesimo, i tuoi occhi diventano un vuoto come inchiostro intriso di un potere terrificante. Una creatura a tua scelta entro 18 metri da te che puoi vedere deve superare un tiro salvezza su Saggezza o è interessata da uno dei seguenti effetti a tua scelta per la durata. A ogni tuo turno fino al termine dell'incantesimo, puoi usare la tua azione per prendere di mira un'altra creatura, ma non puoi prendere di mira di nuovo una creatura se ha superato un tiro salvezza contro questo lancio di malocchio.\nAddormentato. Il bersaglio cade privo di sensi. Si sveglia se subisce danni o se un'altra creatura usa la propria azione per scuotere il dormiente e svegliarlo.\nPanico. Il bersaglio è spaventato da te. A ogni suo turno, la creatura spaventata deve compiere l'azione di Scatto e allontanarsi da te per il percorso più sicuro e breve disponibile, a meno che non ci sia alcun luogo in cui spostarsi. Se il bersaglio si sposta in un luogo ad almeno 18 metri da te dove non riesce più a vederti, questo effetto termina.\nNauseato. Il bersaglio ha svantaggio ai tiri per colpire e alle prove di caratteristica. Al termine di ogni suo turno, può effettuare un altro tiro salvezza su Saggezza. Se lo supera, l'effetto termina.","language":"it","ui_language":"it"},{"id":"fabricate","name":"Fabricate","name_it":"Fabbricare","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"10 minuti","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Converti materie prime in prodotti dello stesso materiale. Per esempio, puoi fabbricare un ponte di legno da un gruppo di alberi, una corda da un mucchio di canapa e dei vestiti dal lino o dalla lana.\nScegli le materie prime che puoi vedere entro gittata. Puoi fabbricare un oggetto di taglia Grande o inferiore (contenuto in un cubo di 3 metri, o in otto cubi di 1,5 metri collegati), data una quantità sufficiente di materia prima. Se però stai lavorando con metallo, pietra o un'altra sostanza minerale, l'oggetto fabbricato non può essere più grande di taglia Media (contenuto in un singolo cubo di 1,5 metri). La qualità degli oggetti creati dall'incantesimo è commisurata alla qualità delle materie prime.\nLe creature o gli oggetti magici non possono essere creati o trasmutati da questo incantesimo. Non puoi nemmeno usarlo per creare oggetti che normalmente richiedono un elevato grado di maestria artigianale, come gioielli, armi, vetro o armature, a meno che tu non sia competente nel tipo di strumenti da artigiano usati per fabbricare tali oggetti.","language":"it","ui_language":"it"},{"id":"faerie-fire","name":"Faerie Fire","name_it":"Fuoco Fatato","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Ogni oggetto in un cubo di 6 metri entro gittata è contornato da luce blu, verde o viola (a tua scelta). Qualsiasi creatura nell'area quando l'incantesimo viene lanciato è anch'essa contornata di luce se fallisce un tiro salvezza su Destrezza. Per la durata, gli oggetti e le creature interessate emanano luce fioca in un raggio di 3 metri.\nQualsiasi tiro per colpire contro una creatura o un oggetto interessato ha vantaggio se l'attaccante può vederlo, e la creatura o l'oggetto interessato non può beneficiare dell'essere invisibile.","language":"it","ui_language":"it"},{"id":"false-life","name":"False Life","name_it":"Vita Fittizia","level":1,"level_it":"Livello 1","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (una piccola quantità di alcol o di distillato)","material":"una piccola quantità di alcol o di distillato","duration":"1 ora","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Rinvigorendoti con una riproduzione necromantica della vita, ottieni 1d4 + 4 punti ferita temporanei per la durata.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, ottieni 5 punti ferita temporanei aggiuntivi per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"far-step","name":"Far Step","name_it":"Passo Lontano","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Ti teletrasporti fino a 18 metri verso uno spazio libero che puoi vedere. A ogni tuo turno prima che l'incantesimo termini, puoi usare un'azione bonus per teletrasportarti di nuovo in questo modo.","language":"it","ui_language":"it"},{"id":"fear","name":"Fear","name_it":"Paura","level":3,"level_it":"Livello 3","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 9 metri)","components":"V, S, M (una piuma bianca o il cuore di una gallina)","material":"una piuma bianca o il cuore di una gallina","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Proietti un'immagine fantasmatica delle peggiori paure di una creatura. Ogni creatura in un cono di 9 metri deve superare un tiro salvezza su Saggezza o lascia cadere ciò che sta tenendo e diventa spaventata per la durata. Mentre è spaventata da questo incantesimo, una creatura deve compiere l'azione di Scatto e allontanarsi da te per il percorso più sicuro disponibile a ogni suo turno, a meno che non ci sia alcun luogo in cui spostarsi. Se la creatura termina il proprio turno in un luogo da cui non ha linea di vista verso di te, può effettuare un tiro salvezza su Saggezza. Con un tiro riuscito, l'incantesimo termina per quella creatura.","language":"it","ui_language":"it"},{"id":"feather-fall","name":"Feather Fall","name_it":"Caduta Morbida","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 reazione, che si esegue quando il lanciatore o una creatura entro 18 metri da lui cade","range":"18 metri","components":"V, M (una piccola piuma o un po' di piumino)","material":"una piccola piuma o un po' di piumino","duration":"1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli fino a cinque creature in caduta entro gittata. La velocità di discesa di una creatura in caduta rallenta a 18 metri per round fino al termine dell'incantesimo. Se la creatura atterra prima che l'incantesimo termini, non subisce alcun danno da caduta e può atterrare in piedi, e l'incantesimo termina per quella creatura.","language":"it","ui_language":"it"},{"id":"feeblemind","name":"Feeblemind","name_it":"Mente Indebolita","level":8,"level_it":"Livello 8","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (una manciata di sfere di argilla, cristallo, vetro o minerale)","material":"una manciata di sfere di argilla, cristallo, vetro o minerale","duration":"Istantanea","classes":["Bard","Druid","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Colpisci la mente di una creatura che puoi vedere entro gittata, tentando di frantumarne l'intelletto e la personalità. Il bersaglio subisce 4d6 danni psichici e deve effettuare un tiro salvezza su Intelligenza.\nCon un tiro fallito, i punteggi di Intelligenza e Carisma della creatura diventano 1. La creatura non può lanciare incantesimi, attivare oggetti magici, comprendere il linguaggio o comunicare in alcun modo intelligibile. La creatura può tuttavia identificare i propri amici, seguirli e persino proteggerli.\nAl termine di ogni 30 giorni, la creatura può ripetere il proprio tiro salvezza contro questo incantesimo. Se supera il tiro salvezza, l'incantesimo termina.\nL'incantesimo può essere terminato anche da ripristino superiore, guarigione o desiderio.","language":"it","ui_language":"it"},{"id":"feign-death","name":"Feign Death","name_it":"Simulare la Morte","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":true,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pizzico di terra di cimitero)","material":"un pizzico di terra di cimitero","duration":"1 ora","classes":["Bard","Cleric","Druid","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Tocchi una creatura consenziente e la poni in uno stato catalettico indistinguibile dalla morte.\nPer la durata dell'incantesimo, o finché non usi un'azione per toccare il bersaglio e congedare l'incantesimo, il bersaglio appare morto a qualsiasi ispezione esteriore e agli incantesimi usati per determinarne lo stato. Il bersaglio è accecato e incapacitato, e la sua velocità scende a 0. Il bersaglio ha resistenza a tutti i danni eccetto i danni psichici. Se il bersaglio è malato o avvelenato quando lanci l'incantesimo, o si ammala o viene avvelenato mentre è sotto l'effetto dell'incantesimo, la malattia e il veleno non hanno effetto fino al termine dell'incantesimo.","language":"it","ui_language":"it"},{"id":"find-familiar","name":"Find Familiar","name_it":"Trovare Famiglio","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":true,"casting_time":"1 ora","range":"3 metri","components":"V, S, M (carbone, incenso ed erbe del valore di 10 mo, che devono essere consumati dal fuoco in un braciere d'ottone)","material":"carbone, incenso ed erbe del valore di 10 mo, che devono essere consumati dal fuoco in un braciere d'ottone","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Ottieni i servigi di un famiglio, uno spirito che assume una forma animale a tua scelta: pipistrello, gatto, granchio, rana (rospo), falco, lucertola, polpo, gufo, serpente velenoso, pesce (quipper), ratto, corvo, cavalluccio marino, ragno o donnola. Apparendo in uno spazio libero entro gittata, il famiglio ha le statistiche della forma scelta, anche se è un celestiale, un fatato o un immondo (a tua scelta) invece di una bestia.\nIl tuo famiglio agisce in modo indipendente da te, ma obbedisce sempre ai tuoi comandi. In combattimento, tira la propria iniziativa e agisce nel proprio turno. Un famiglio non può attaccare, ma può compiere normalmente altre azioni.\nQuando il famiglio scende a 0 punti ferita, scompare senza lasciare alcuna forma fisica. Riappare dopo che lanci nuovamente questo incantesimo. Con un'azione, puoi congedare temporaneamente il famiglio in una dimensione tascabile. In alternativa, puoi congedarlo per sempre. Con un'azione mentre è temporaneamente congedato, puoi farlo riapparire in qualsiasi spazio libero entro 9 metri da te. Ogni volta che il famiglio scende a 0 punti ferita o scompare nella dimensione tascabile, lascia nel proprio spazio tutto ciò che indossava o trasportava.\nMentre il tuo famiglio si trova entro 30 metri da te, puoi comunicare con esso telepaticamente. Inoltre, con un'azione, puoi vedere attraverso gli occhi del famiglio e udire ciò che esso ode fino all'inizio del tuo prossimo turno, ottenendo i benefici di qualsiasi senso speciale che il famiglio possiede. Durante questo periodo, sei sordo e cieco rispetto ai tuoi sensi.\nNon puoi avere più di un famiglio alla volta. Se lanci questo incantesimo mentre hai già un famiglio, fai invece sì che esso adotti una nuova forma. Scegli una delle forme dall'elenco sopra. Il tuo famiglio si trasforma nella creatura scelta.\nInfine, quando lanci un incantesimo con gittata di contatto, il tuo famiglio può recapitare l'incantesimo come se lo avesse lanciato lui. Il tuo famiglio deve trovarsi entro 30 metri da te e deve usare la propria reazione per recapitare l'incantesimo quando lo lanci. Se l'incantesimo richiede un tiro per colpire, usi il tuo modificatore di attacco per il tiro.","language":"it","ui_language":"it"},{"id":"find-greater-steed","name":"Find Greater Steed","name_it":"Trovare Cavalcatura Superiore","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"10 minuti","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Evochi uno spirito che assume la forma di una cavalcatura leale e maestosa. Apparendo in uno spazio libero entro gittata, lo spirito assume una forma a tua scelta: un grifone, un pegaso, un peritone, un lupo crudele, un rinoceronte o una tigre dai denti a sciabola. La creatura ha le statistiche fornite nel Manuale dei Mostri per la forma scelta, anche se è un celestiale, un fatato o un immondo (a tua scelta) invece del suo normale tipo di creatura. Inoltre, se ha un punteggio di Intelligenza pari o inferiore a 5, la sua Intelligenza diventa 6 e ottiene la capacità di comprendere una lingua a tua scelta che tu parli. Controlli la cavalcatura in combattimento. Mentre la cavalcatura si trova entro 1,5 chilometri da te, puoi comunicare con essa telepaticamente. Mentre la cavalchi, puoi far sì che qualsiasi incantesimo che lanci e che ha come unico bersaglio te stesso prenda di mira anche la cavalcatura. La cavalcatura scompare temporaneamente quando scende a 0 punti ferita o quando la congedi con un'azione. Lanciare di nuovo questo incantesimo rievoca la cavalcatura legata, con tutti i suoi punti ferita ripristinati e qualsiasi condizione rimossa. Non puoi avere più di una cavalcatura legata da questo incantesimo o da trovare cavalcatura alla volta. Con un'azione, puoi liberare una cavalcatura dal suo legame, facendola scomparire permanentemente. Ogni volta che la cavalcatura scompare, lascia dietro di sé qualsiasi oggetto indossava o trasportava.","language":"it","ui_language":"it"},{"id":"find-steed","name":"Find Steed","name_it":"Trovare Cavalcatura","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"10 minuti","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi uno spirito che assume la forma di una cavalcatura insolitamente intelligente, forte e leale, creando con essa un legame duraturo. Apparendo in uno spazio libero entro gittata, la cavalcatura assume una forma a tua scelta: un cavallo da guerra, un pony, un cammello, un alce o un mastino. (Il tuo DM potrebbe permettere di evocare altri animali come cavalcature.) La cavalcatura ha le statistiche della forma scelta, anche se è un celestiale, un fatato o un immondo (a tua scelta) invece del suo normale tipo. Inoltre, se la tua cavalcatura ha un'Intelligenza pari o inferiore a 5, la sua Intelligenza diventa 6 e ottiene la capacità di comprendere una lingua a tua scelta che tu parli.\nLa tua cavalcatura ti serve come destriero, sia in combattimento sia fuori, e hai con essa un legame istintivo che ti permette di combattere come un'unità perfetta. Mentre la cavalchi, puoi far sì che qualsiasi incantesimo che lanci e che ha come unico bersaglio te stesso prenda di mira anche la cavalcatura.\nQuando la cavalcatura scende a 0 punti ferita, scompare senza lasciare alcuna forma fisica. Puoi anche congedare la cavalcatura in qualsiasi momento con un'azione, facendola scomparire. In entrambi i casi, lanciare di nuovo questo incantesimo evoca la stessa cavalcatura, ripristinata al suo massimo dei punti ferita.\nMentre la tua cavalcatura si trova entro 1,5 chilometri da te, potete comunicare telepaticamente l'uno con l'altra.\nNon puoi avere più di una cavalcatura legata da questo incantesimo alla volta. Con un'azione, puoi liberare la cavalcatura dal suo legame in qualsiasi momento, facendola scomparire.","language":"it","ui_language":"it"},{"id":"find-the-path","name":"Find the Path","name_it":"Trovare il Sentiero","level":6,"level_it":"Livello 6","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 minuto","range":"Personale","components":"V, S, M (un set di strumenti divinatori — come ossa, bastoncini d'avorio, carte, denti o rune intagliate — del valore di 100 mo e un oggetto proveniente dal luogo che desideri trovare)","material":"un set di strumenti divinatori — come ossa, bastoncini d'avorio, carte, denti o rune intagliate — del valore di 100 mo e un oggetto proveniente dal luogo che desideri trovare","duration":"Concentrazione, fino a 1 giorno","classes":["Bard","Cleric","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo ti permette di trovare il percorso fisico più breve e diretto verso un luogo specifico, fisso e a te familiare, sullo stesso piano di esistenza. Se nomini una destinazione su un altro piano di esistenza, una destinazione che si sposta (come una fortezza mobile) o una destinazione non specifica (come «la tana di un drago verde»), l'incantesimo fallisce.\nPer la durata, finché ti trovi sullo stesso piano di esistenza della destinazione, sai quanto è distante e in quale direzione si trova. Mentre vi sei diretto, ogni volta che ti si presenta una scelta di percorsi lungo il cammino, determini automaticamente quale percorso è il più breve e diretto (ma non necessariamente il più sicuro) verso la destinazione.","language":"it","ui_language":"it"},{"id":"find-traps","name":"Find Traps","name_it":"Individuazione di Trappole","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Druid","Ranger"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Percepisci la presenza di qualsiasi trappola entro gittata che si trovi in linea di vista. Ai fini di questo incantesimo, una trappola include qualunque cosa infligga un effetto improvviso o inaspettato che tu consideri dannoso o indesiderabile, appositamente concepito come tale dal suo creatore. Pertanto, l'incantesimo percepirebbe un'area interessata dall'incantesimo allarme, un sigillo runico d'avvertimento, o una trappola meccanica a fossa, ma non rivelerebbe un punto debole naturale nel pavimento, un soffitto instabile o una voragine nascosta.\nQuesto incantesimo si limita a rivelare che è presente una trappola. Non apprendi la posizione di ciascuna trappola, ma apprendi la natura generale del pericolo rappresentato da una trappola che percepisci.","language":"it","ui_language":"it"},{"id":"finger-of-death","name":"Finger of Death","name_it":"Dito della Morte","level":7,"level_it":"Livello 7","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fai scorrere energia negativa attraverso una creatura che riesci a vedere entro gittata, causandole un dolore lancinante. Il bersaglio deve effettuare un tiro salvezza su Costituzione. Subisce 7d8 + 30 danni necrotici se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nUn umanoide ucciso da questo incantesimo si rialza all'inizio del tuo turno successivo come uno zombie permanentemente sotto il tuo comando, che segue i tuoi ordini verbali al meglio delle sue capacità.","language":"it","ui_language":"it"},{"id":"fire-bolt","name":"Fire Bolt","name_it":"Dardo di Fuoco","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scagli una manciata di fuoco contro una creatura o un oggetto entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, il bersaglio subisce 1d10 danni da fuoco. Un oggetto infiammabile colpito da questo incantesimo prende fuoco se non viene indossato o trasportato.\nI danni di questo incantesimo aumentano di 1d10 quando raggiungi il 5° livello (2d10), l'11° livello (3d10) e il 17° livello (4d10).","language":"it","ui_language":"it"},{"id":"fire-shield","name":"Fire Shield","name_it":"Scudo di Fuoco","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un pizzico di fosforo o una lucciola)","material":"un pizzico di fosforo o una lucciola","duration":"10 minuti","classes":["Wizard","Druid","Sorcerer"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Fiamme sottili e vaporose avvolgono il tuo corpo per la durata, emanando luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri. Puoi terminare l'incantesimo anticipatamente usando un'azione per dissolverlo.\nLe fiamme ti forniscono uno scudo caldo o uno scudo freddo, a tua scelta. Lo scudo caldo ti garantisce resistenza ai danni da freddo, e lo scudo freddo ti garantisce resistenza ai danni da fuoco.\nInoltre, ogni volta che una creatura entro 1,5 metri da te ti colpisce con un attacco in mischia, lo scudo erompe in fiamme. L'attaccante subisce 2d8 danni da fuoco da uno scudo caldo, o 2d8 danni da freddo da uno scudo freddo.","language":"it","ui_language":"it"},{"id":"fire-storm","name":"Fire Storm","name_it":"Tempesta di Fuoco","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Druid","Sorcerer"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una tempesta composta da lenzuola di fiamme ruggenti appare in un punto a tua scelta entro gittata. L'area della tempesta consiste in un massimo di dieci cubi di 3 metri di lato, che puoi disporre come preferisci. Ogni cubo deve avere almeno una faccia adiacente alla faccia di un altro cubo. Ogni creatura nell'area deve effettuare un tiro salvezza su Destrezza. Subisce 7d10 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nIl fuoco danneggia gli oggetti nell'area e incendia gli oggetti infiammabili che non vengono indossati o trasportati. Se scegli così, la vegetazione nell'area non è interessata da questo incantesimo.","language":"it","ui_language":"it"},{"id":"fireball","name":"Fireball","name_it":"Palla di Fuoco","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (una piccola sfera di guano di pipistrello e zolfo)","material":"una piccola sfera di guano di pipistrello e zolfo","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una striscia luminosa parte dal tuo dito puntato verso un punto a tua scelta entro gittata, per poi sbocciare con un cupo boato in un'esplosione di fiamme. Ogni creatura in una sfera con raggio di 6 metri centrata su quel punto deve effettuare un tiro salvezza su Destrezza. Un bersaglio subisce 8d6 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nIl fuoco si propaga attorno agli angoli. Incendia gli oggetti infiammabili nell'area che non vengono indossati o trasportati.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"fizban-s-platinum-shield","name":"Fizban's Platinum Shield","name_it":"Scudo di Platino di Fizban","level":6,"level_it":"Livello 6","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V, S, M (una scaglia di drago placcata in platino, del valore di almeno 500 mo)","material":"una scaglia di drago placcata in platino, del valore di almeno 500 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"L'incantatore ottiene mezza copertura, resistenza ai danni da acido, freddo, fuoco, fulmine e veleno, ed Evasione.","language":"it","ui_language":"it"},{"id":"flame-arrows","name":"Flame Arrows","name_it":"Frecce Fiammeggianti","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Tocchi una faretra contenente frecce o quadrelli. Quando un bersaglio viene colpito da un attacco con arma a distanza che utilizza un pezzo di munizione estratto dalla faretra, il bersaglio subisce 1d6 danni da fuoco aggiuntivi. La magia dell'incantesimo termina sul pezzo di munizione quando colpisce o manca il bersaglio, e l'incantesimo termina quando dodici pezzi di munizione sono stati estratti dalla faretra.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, il numero di pezzi di munizione che puoi interessare con questo incantesimo aumenta di due per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"flame-blade","name":"Flame Blade","name_it":"Lama di Fuoco","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S, M (una foglia di sommacco)","material":"una foglia di sommacco","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Evochi una lama fiammeggiante nella tua mano libera. La lama è simile per dimensioni e forma a una scimitarra, e dura per la durata dell'incantesimo. Se lasci andare la lama, questa scompare, ma puoi evocarla di nuovo come azione bonus.\nPuoi usare la tua azione per effettuare un attacco con incantesimo in mischia con la lama fiammeggiante. Se colpisci, il bersaglio subisce 3d6 danni da fuoco.\nLa lama fiammeggiante emana luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 ogni due livelli dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"flame-strike","name":"Flame Strike","name_it":"Colonna di Fuoco","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pizzico di zolfo)","material":"un pizzico di zolfo","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una colonna verticale di fuoco divino piomba giù dai cieli in un punto che tu specifichi. Ogni creatura in un cilindro con raggio di 3 metri e alto 12 metri centrato su un punto a tua scelta entro gittata deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 4d6 danni da fuoco e 4d6 danni radiosi se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, i danni da fuoco o i danni radiosi (a tua scelta) aumentano di 1d6 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"flaming-sphere","name":"Flaming Sphere","name_it":"Sfera Fiammeggiante","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un po' di sego, un pizzico di zolfo e una spolverata di ferro in polvere)","material":"un po' di sego, un pizzico di zolfo e una spolverata di ferro in polvere","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Wizard","Sorcerer"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Una sfera di fuoco con un diametro di 1,5 metri appare in uno spazio libero a tua scelta entro gittata e dura per la durata dell'incantesimo. Qualsiasi creatura che termina il proprio turno entro 1,5 metri dalla sfera deve effettuare un tiro salvezza su Destrezza. La creatura subisce 2d6 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nCome azione bonus, puoi spostare la sfera fino a 9 metri. Se sbatti la sfera contro una creatura, quella creatura deve effettuare il tiro salvezza contro i danni della sfera, e la sfera smette di muoversi in quel turno.\nQuando sposti la sfera, puoi dirigerla oltre barriere alte fino a 1,5 metri e farla saltare attraverso fosse larghe fino a 3 metri. La sfera incendia gli oggetti infiammabili non indossati né trasportati, ed emana luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"flesh-to-stone","name":"Flesh to Stone","name_it":"Pietrificazione","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pizzico di calce, acqua e terra)","material":"un pizzico di calce, acqua e terra","duration":"Concentrazione, fino a 1 minuto","classes":["Warlock","Wizard","Druid","Sorcerer"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di trasformare in pietra una creatura che riesci a vedere entro gittata. Se il corpo del bersaglio è fatto di carne, la creatura deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, viene immobilizzata mentre la sua carne inizia a indurirsi. Se supera il tiro salvezza, la creatura non è interessata.\nUna creatura immobilizzata da questo incantesimo deve effettuare un altro tiro salvezza su Costituzione alla fine di ciascuno dei propri turni. Se supera con successo questo tiro salvezza per tre volte, l'incantesimo termina. Se fallisce i tiri salvezza per tre volte, viene trasformata in pietra e soggetta alla condizione pietrificato per la durata dell'incantesimo. I successi e i fallimenti non devono essere consecutivi; tieni traccia di entrambi finché il bersaglio non ne colleziona tre dello stesso tipo.\nSe la creatura viene fisicamente spezzata mentre è pietrificata, subisce deformità simili se ritorna al proprio stato originale.\nSe mantieni la concentrazione su questo incantesimo per l'intera durata possibile, la creatura viene trasformata in pietra finché l'effetto non viene rimosso.","language":"it","ui_language":"it"},{"id":"fly","name":"Fly","name_it":"Volare","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (una piuma alare di un qualsiasi uccello)","material":"una piuma alare di un qualsiasi uccello","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente. Il bersaglio ottiene una velocità di volo di 18 metri per la durata dell'incantesimo. Quando l'incantesimo termina, il bersaglio cade se si trova ancora in volo, a meno che non possa fermare la caduta.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, puoi prendere di mira una creatura aggiuntiva per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"fog-cloud","name":"Fog Cloud","name_it":"Nube di Nebbia","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una sfera con raggio di 6 metri di nebbia centrata su un punto a tua scelta entro gittata. La sfera si propaga attorno agli angoli, e la sua area è pesantemente offuscata. Dura per la durata dell'incantesimo o finché un vento di velocità moderata o superiore (almeno 16 chilometri orari) non la disperde.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, il raggio della nebbia aumenta di 6 metri per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"forbiddance","name":"Forbiddance","name_it":"Interdizione","level":6,"level_it":"Livello 6","school":"abjuration","school_it":"Abiurazione","ritual":true,"casting_time":"10 minuti","range":"Contatto","components":"V, S, M (dell'acqua santa, incenso raro e rubino in polvere del valore di almeno 1.000 mo)","material":"dell'acqua santa, incenso raro e rubino in polvere del valore di almeno 1.000 mo","duration":"1 giorno","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una protezione contro i viaggi magici che protegge fino a 3.700 metri quadrati di superficie del pavimento fino a un'altezza di 9 metri sopra il pavimento stesso. Per la durata dell'incantesimo, le creature non possono teletrasportarsi nell'area né utilizzare portali, come quelli creati dall'incantesimo portale, per entrarvi. L'incantesimo protegge l'area anche dai viaggi planari, e pertanto impedisce alle creature di accedervi tramite il Piano Astrale, il Piano Etereo, il Feywild, lo Shadowfell o l'incantesimo cambio di piano.\nInoltre, l'incantesimo danneggia i tipi di creature che scegli quando lo lanci. Scegli uno o più dei seguenti: celestiali, elementali, fatati, immondi e non morti. Quando una creatura scelta entra nell'area dell'incantesimo per la prima volta in un turno o inizia lì il proprio turno, subisce 5d10 danni radiosi o necrotici (a tua scelta quando lanci questo incantesimo).\nQuando lanci questo incantesimo, puoi designare una parola d'ordine. Una creatura che pronuncia la parola d'ordine mentre entra nell'area non subisce danni dall'incantesimo.\nL'area dell'incantesimo non può sovrapporsi all'area di un altro incantesimo interdizione. Se lanci interdizione ogni giorno per 30 giorni nello stesso luogo, l'incantesimo dura finché non viene dissolto, e le componenti materiali vengono consumate all'ultimo lancio.","language":"it","ui_language":"it"},{"id":"forcecage","name":"Forcecage","name_it":"Gabbia di Forza","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"30 metri","components":"V, S, M (polvere di rubino del valore di 1.500 mo)","material":"polvere di rubino del valore di 1.500 mo","duration":"1 ora","classes":["Bard","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una prigione immobile, invisibile, a forma di cubo, composta di forza magica, scaturisce all'esistenza attorno a un'area a tua scelta entro gittata. La prigione può essere una gabbia o una scatola solida, a tua scelta.\nUna prigione a forma di gabbia può misurare fino a 6 metri di lato ed è fatta di sbarre con un diametro di 1,25 centimetri distanziate di 1,25 centimetri l'una dall'altra.\nUna prigione a forma di scatola può misurare fino a 3 metri di lato, creando una barriera solida che impedisce a qualsiasi materia di attraversarla e blocca qualsiasi incantesimo lanciato al suo interno o dal suo interno verso l'esterno.\nQuando lanci l'incantesimo, qualsiasi creatura che si trova completamente all'interno dell'area della gabbia rimane intrappolata. Le creature solo parzialmente all'interno dell'area, o quelle troppo grandi per entrarvi, vengono spinte via dal centro dell'area finché non si trovano completamente all'esterno di essa.\nUna creatura all'interno della gabbia non può uscirne con mezzi non magici. Se la creatura tenta di usare il teletrasporto o il viaggio interplanare per lasciare la gabbia, deve prima effettuare un tiro salvezza su Carisma. In caso di successo, la creatura può usare quella magia per uscire dalla gabbia. In caso di fallimento, la creatura non può uscire dalla gabbia e spreca l'uso dell'incantesimo o dell'effetto. La gabbia si estende anche nel Piano Etereo, bloccando i viaggi eterei.\nQuesto incantesimo non può essere dissolto da dissolvi magie.","language":"it","ui_language":"it"},{"id":"foresight","name":"Foresight","name_it":"Preveggenza","level":9,"level_it":"Livello 9","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 minuto","range":"Contatto","components":"V, S, M (una piuma di colibrì)","material":"una piuma di colibrì","duration":"8 ore","classes":["Bard","Druid","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente e le conferisci una limitata capacità di vedere nel futuro immediato. Per la durata dell'incantesimo, il bersaglio non può essere colto di sorpresa e ha vantaggio ai tiri per colpire, alle prove di caratteristica e ai tiri salvezza. Inoltre, le altre creature hanno svantaggio ai tiri per colpire contro il bersaglio per la durata dell'incantesimo.\nQuesto incantesimo termina immediatamente se lo lanci di nuovo prima che la sua durata sia terminata.","language":"it","ui_language":"it"},{"id":"freedom-of-movement","name":"Freedom of Movement","name_it":"Libertà di Movimento","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (una cinghia di cuoio, legata attorno al braccio o a un'appendice simile)","material":"una cinghia di cuoio, legata attorno al braccio o a un'appendice simile","duration":"1 ora","classes":["Bard","Cleric","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente. Per la durata dell'incantesimo, il movimento del bersaglio non è influenzato dal terreno difficile, e gli incantesimi e altri effetti magici non possono né ridurre la velocità del bersaglio né fare in modo che venga paralizzato o immobilizzato.\nIl bersaglio può inoltre spendere 1,5 metri di movimento per liberarsi automaticamente da restrizioni non magiche, come manette o una creatura che lo ha afferrato. Infine, trovarsi sott'acqua non impone alcuna penalità al movimento o agli attacchi del bersaglio.","language":"it","ui_language":"it"},{"id":"friends","name":"Friends","name_it":"Amicizia","level":0,"level_it":"Trucchetto","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"Personale","components":"S, M (una piccola quantità di trucco applicata sul viso mentre viene lanciato questo incantesimo)","material":"una piccola quantità di trucco applicata sul viso mentre viene lanciato questo incantesimo","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Per la durata dell'incantesimo, hai vantaggio a tutte le prove di Carisma dirette a una creatura a tua scelta che non sia ostile nei tuoi confronti. Quando l'incantesimo termina, la creatura si rende conto che hai usato la magia per influenzare il suo umore e diventa ostile nei tuoi confronti. Una creatura incline alla violenza potrebbe attaccarti. Un'altra creatura potrebbe cercare vendetta in altri modi (a discrezione del DM), a seconda della natura della tua interazione con essa.","language":"it","ui_language":"it"},{"id":"frostbite","name":"Frostbite","name_it":"Morso del Gelo","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fai formare un gelo intorpidente su una creatura che riesci a vedere entro gittata. Il bersaglio deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, il bersaglio subisce 1d6 danni da freddo e ha svantaggio al prossimo tiro per colpire con un'arma che effettua prima della fine del suo prossimo turno.\nI danni di questo incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"gaseous-form","name":"Gaseous Form","name_it":"Forma Gassosa","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pezzo di garza e un filo di fumo)","material":"un pezzo di garza e un filo di fumo","duration":"Concentrazione, fino a 1 ora","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Trasformi una creatura consenziente che tocchi, insieme a tutto ciò che indossa e porta con sé, in una nube di nebbia per la durata dell'incantesimo. L'incantesimo termina se la creatura scende a 0 punti ferita. Una creatura incorporea non viene influenzata.\nMentre si trova in questa forma, l'unico metodo di movimento del bersaglio è una velocità di volo di 3 metri. Il bersaglio può entrare e occupare lo spazio di un'altra creatura. Il bersaglio ha resistenza ai danni non magici e ha vantaggio ai tiri salvezza su Forza, Destrezza e Costituzione. Il bersaglio può passare attraverso piccoli fori, aperture strette e persino semplici fessure, sebbene tratti i liquidi come se fossero superfici solide. Il bersaglio non può cadere e rimane sospeso in aria anche quando è stordito o altrimenti incapacitato.\nMentre si trova sotto forma di nube di nebbia, il bersaglio non può parlare né manipolare oggetti, e qualsiasi oggetto che stesse portando o tenendo non può essere lasciato cadere, usato o altrimenti manipolato. Il bersaglio non può attaccare né lanciare incantesimi.","language":"it","ui_language":"it"},{"id":"gate","name":"Gate","name_it":"Portale","level":9,"level_it":"Livello 9","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un diamante del valore di almeno 5.000 mo)","material":"un diamante del valore di almeno 5.000 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Sorcerer","Wizard","Warlock"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Evochi un portale che collega uno spazio libero che puoi vedere entro gittata a una posizione precisa su un piano di esistenza diverso. Il portale è un'apertura circolare, che puoi rendere di diametro compreso tra 1,5 e 6 metri. Puoi orientare il portale nella direzione che preferisci. Il portale dura per la durata dell'incantesimo.\nIl portale ha un fronte e un retro su ciascun piano in cui appare. Attraversarlo è possibile solo passando dal suo fronte. Chiunque lo faccia viene istantaneamente trasportato sull'altro piano, comparendo nello spazio libero più vicino al portale.\nLe divinità e gli altri sovrani planari possono impedire che i portali creati da questo incantesimo si aprano in loro presenza o in qualsiasi punto all'interno dei loro domini.\nQuando lanci questo incantesimo, puoi pronunciare il nome di una creatura specifica (uno pseudonimo, un titolo o un soprannome non funzionano). Se quella creatura si trova su un piano diverso da quello in cui ti trovi, il portale si apre nelle immediate vicinanze della creatura nominata e la attira attraverso di sé fino allo spazio libero più vicino dal tuo lato del portale. Non ottieni alcun potere speciale sulla creatura, che è libera di agire come il DM ritiene opportuno. Potrebbe andarsene, attaccarti o aiutarti.","language":"it","ui_language":"it"},{"id":"geas","name":"Geas","name_it":"Geas","level":5,"level_it":"Livello 5","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 minuto","range":"18 metri","components":"V","material":"","duration":"30 giorni","classes":["Bard","Cleric","Druid","Paladin","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Imponi un comando magico su una creatura che riesci a vedere entro gittata, costringendola a svolgere un servizio o ad astenersi da una determinata azione o linea di condotta, a tua scelta. Se la creatura riesce a comprenderti, deve effettuare un tiro salvezza su Saggezza o essere ammaliata da te per la durata dell'incantesimo. Mentre è ammaliata da te, subisce 5d10 danni psichici ogni volta che agisce in un modo direttamente contrario alle tue istruzioni, ma non più di una volta al giorno. Una creatura che non riesce a comprenderti non è influenzata dall'incantesimo.\nPuoi impartire qualsiasi comando tu scelga, purché non si tratti di un'attività che comporterebbe una morte certa. Se impartisci un comando suicida, l'incantesimo termina.\nPuoi porre fine all'incantesimo in anticipo usando un'azione per dissolverlo. Anche un incantesimo rimuovere maledizione, ripristino superiore o desiderio pone fine all'incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° o 8° livello, la durata è di 1 anno. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 9° livello, l'incantesimo dura finché non viene terminato da uno degli incantesimi sopra menzionati.","language":"it","ui_language":"it"},{"id":"gentle-repose","name":"Gentle Repose","name_it":"Quiete Perpetua","level":2,"level_it":"Livello 2","school":"necromancy","school_it":"Necromanzia","ritual":true,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pizzico di sale e un pezzo di rame posto su ciascun occhio del cadavere, che devono rimanere lì per la durata dell'incantesimo)","material":"un pizzico di sale e un pezzo di rame posto su ciascun occhio del cadavere, che devono rimanere lì per la durata dell'incantesimo","duration":"10 giorni","classes":["Cleric","Wizard","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un cadavere o altri resti. Per la durata dell'incantesimo, il bersaglio è protetto dalla decomposizione e non può diventare non morto.\nL'incantesimo estende inoltre di fatto il limite di tempo per far resuscitare il bersaglio dalla morte, poiché i giorni trascorsi sotto l'influenza di questo incantesimo non vengono conteggiati ai fini del limite di tempo di incantesimi come resurrezione.","language":"it","ui_language":"it"},{"id":"giant-insect","name":"Giant Insect","name_it":"Insetto Gigante","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Trasformi fino a dieci centopiedi, tre ragni, cinque vespe o uno scorpione entro gittata in versioni giganti delle loro forme naturali per la durata dell'incantesimo. Un centopiede diventa un centopiedi gigante, un ragno diventa un ragno gigante, una vespa diventa una vespa gigante e uno scorpione diventa uno scorpione gigante.\nOgni creatura obbedisce ai tuoi comandi verbali e, in combattimento, agisce nel tuo turno a ogni round. Il DM possiede le statistiche di queste creature e ne gestisce le azioni e il movimento.\nUna creatura rimane nella sua taglia gigante per la durata dell'incantesimo, finché non scende a 0 punti ferita o finché non usi un'azione per dissolvere l'effetto su di essa.\nIl DM potrebbe permetterti di scegliere bersagli diversi. Ad esempio, se trasformi un'ape, la sua versione gigante potrebbe avere le stesse statistiche di una vespa gigante.","language":"it","ui_language":"it"},{"id":"glibness","name":"Glibness","name_it":"Loquacità","level":8,"level_it":"Livello 8","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V","material":"","duration":"1 ora","classes":["Bard","Warlock"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Finché l'incantesimo non termina, quando effettui una prova di Carisma, puoi sostituire il numero ottenuto con un 15. Inoltre, indipendentemente da ciò che dici, qualsiasi magia che dovrebbe determinare se stai dicendo la verità indica che sei sincero.","language":"it","ui_language":"it"},{"id":"globe-of-invulnerability","name":"Globe of Invulnerability","name_it":"Sfera di Invulnerabilità","level":6,"level_it":"Livello 6","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 3 metri)","components":"V, S, M (una perlina di vetro o cristallo che si frantuma quando l'incantesimo termina)","material":"una perlina di vetro o cristallo che si frantuma quando l'incantesimo termina","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una barriera immobile e debolmente scintillante prende vita in un raggio di 3 metri intorno a te e rimane per la durata dell'incantesimo.\nQualsiasi incantesimo di 5° livello o inferiore lanciato dall'esterno della barriera non può influenzare le creature o gli oggetti al suo interno, anche se l'incantesimo viene lanciato utilizzando uno slot incantesimo di livello superiore. Un incantesimo di questo tipo può avere come bersaglio creature e oggetti all'interno della barriera, ma non ha alcun effetto su di essi. Allo stesso modo, l'area all'interno della barriera è esclusa dalle aree interessate da tali incantesimi.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, la barriera blocca incantesimi di un livello superiore per ogni livello dello slot al di sopra del 6°.","language":"it","ui_language":"it"},{"id":"glyph-of-warding","name":"Glyph of Warding","name_it":"Runa di Protezione","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (incenso e diamante in polvere del valore di almeno 200 mo, che l'incantesimo consuma)","material":"incenso e diamante in polvere del valore di almeno 200 mo, che l'incantesimo consuma","duration":"Finché non viene dissolto o innescato","classes":["Bard","Cleric","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Quando lanci questo incantesimo, incidi una runa che danneggia le altre creature, su una superficie (come un tavolo o una sezione di pavimento o muro) oppure all'interno di un oggetto che può essere chiuso (come un libro, una pergamena o un forziere) per nasconderla. La runa può coprire un'area di diametro non superiore a 3 metri. Se la superficie o l'oggetto vengono spostati per più di 3 metri dal punto in cui hai lanciato l'incantesimo, la runa si spezza e l'incantesimo termina senza essere innescato.\nLa runa è quasi invisibile e richiede una prova di Intelligenza (Investigare) riuscita, contro la CD di salvezza del tuo incantesimo, per essere individuata.\nDecidi tu cosa innesca la runa quando lanci l'incantesimo. Per le rune incise su una superficie, gli inneschi più comuni includono toccare o stare in piedi sulla runa, rimuovere un altro oggetto che la copre, avvicinarsi entro una certa distanza dalla runa, o manipolare l'oggetto su cui è incisa. Per le rune incise all'interno di un oggetto, gli inneschi più comuni includono aprire quell'oggetto, avvicinarsi entro una certa distanza dall'oggetto, oppure vedere o leggere la runa. Una volta che una runa viene innescata, questo incantesimo termina.\nPuoi inoltre perfezionare l'innesco in modo che l'incantesimo si attivi solo in determinate circostanze o in base a caratteristiche fisiche (come altezza o peso), tipo di creatura (ad esempio, la protezione potrebbe essere impostata per colpire solo aberrazioni o drow) o allineamento. Puoi anche stabilire delle condizioni per le creature che non fanno scattare la runa, come coloro che pronunciano una determinata parola d'ordine.\nQuando incidi la runa, scegli tra rune esplosive o runa d'incantesimo.\nRune Esplosive. Quando viene innescata, la runa erutta energia magica in una sfera dal raggio di 6 metri centrata sulla runa. La sfera si espande oltre gli angoli. Ogni creatura nell'area deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 5d8 danni da acido, freddo, fuoco, fulmine o tuono in caso di fallimento del tiro salvezza (a tua scelta quando crei la runa), o la metà dei danni in caso di successo.\nRuna d'Incantesimo. Puoi memorizzare un incantesimo preparato di 3° livello o inferiore nella runa, lanciandolo come parte della sua creazione. L'incantesimo deve avere come bersaglio una singola creatura o un'area. L'incantesimo memorizzato non ha alcun effetto immediato quando viene lanciato in questo modo. Quando la runa viene innescata, l'incantesimo memorizzato viene lanciato. Se l'incantesimo ha un bersaglio, ha come bersaglio la creatura che ha innescato la runa. Se l'incantesimo interessa un'area, l'area è centrata su quella creatura. Se l'incantesimo evoca creature ostili o crea oggetti o trappole dannosi, questi compaiono il più vicino possibile all'intruso e lo attaccano. Se l'incantesimo richiede concentrazione, dura fino alla fine della sua intera durata.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni di una runa esplosiva aumentano di 1d8 per ogni livello dello slot superiore al 3°. Se crei una runa d'incantesimo, puoi memorizzare qualsiasi incantesimo fino allo stesso livello dello slot che utilizzi per la runa di protezione.","language":"it","ui_language":"it"},{"id":"goodberry","name":"Goodberry","name_it":"Bacca Nutriente","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un rametto di vischio)","material":"un rametto di vischio","duration":"Istantanea","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fino a dieci bacche appaiono nella tua mano e vengono infuse di magia per la durata dell'incantesimo. Una creatura può usare la sua azione per mangiare una bacca. Mangiare una bacca ripristina 1 punto ferita, e la bacca fornisce nutrimento sufficiente a sostentare una creatura per un giorno.\nLe bacche perdono la loro potenza se non vengono consumate entro 24 ore dal lancio dell'incantesimo.","language":"it","ui_language":"it"},{"id":"grasping-vine","name":"Grasping Vine","name_it":"Vite Afferrante","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"9 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Evochi una vite che spunta dal terreno in uno spazio libero a tua scelta che puoi vedere entro gittata. Quando lanci questo incantesimo, puoi indirizzare la vite affinché colpisca una creatura entro 9 metri da essa che riesci a vedere. Quella creatura deve effettuare un tiro salvezza su Destrezza o essere trascinata per 6 metri direttamente verso la vite.\nFinché l'incantesimo non termina, puoi indirizzare la vite affinché colpisca la stessa creatura o un'altra come azione bonus a ogni tuo turno.","language":"it","ui_language":"it"},{"id":"grease","name":"Grease","name_it":"Untume","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pezzo di cotenna di maiale o burro)","material":"un pezzo di cotenna di maiale o burro","duration":"1 minuto","classes":["Wizard","Sorcerer"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Un untume scivoloso copre il terreno in un quadrato di 3 metri di lato centrato su un punto entro gittata e lo trasforma in terreno difficile per la durata dell'incantesimo.\nQuando l'untume appare, ogni creatura che si trova nella sua area deve effettuare un tiro salvezza su Destrezza o cadere prona. Una creatura che entra nell'area o termina il suo turno lì deve anch'essa effettuare un tiro salvezza su Destrezza o cadere prona.","language":"it","ui_language":"it"},{"id":"greater-invisibility","name":"Greater Invisibility","name_it":"Invisibilità Superiore","level":4,"level_it":"Livello 4","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tu o una creatura che tocchi diventate invisibili finché l'incantesimo non termina. Qualsiasi cosa il bersaglio indossi o porti con sé è invisibile finché rimane sulla persona del bersaglio.","language":"it","ui_language":"it"},{"id":"greater-restoration","name":"Greater Restoration","name_it":"Ripristino Superiore","level":5,"level_it":"Livello 5","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (polvere di diamante del valore di almeno 100 mo, che l'incantesimo consuma)","material":"polvere di diamante del valore di almeno 100 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Bard","Cleric","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Infondi in una creatura che tocchi energia positiva per annullare un effetto debilitante. Puoi ridurre di uno il livello di sfinimento del bersaglio, oppure porre fine a uno dei seguenti effetti sul bersaglio:\n• Un effetto che ha ammaliato o pietrificato il bersaglio\n• Una maledizione, incluso il sintonizzarsi del bersaglio con un oggetto magico maledetto\n• Qualsiasi riduzione a uno dei punteggi di caratteristica del bersaglio\n• Un effetto che riduce i punti ferita massimi del bersaglio","language":"it","ui_language":"it"},{"id":"green-flame-blade","name":"Green-Flame Blade","name_it":"Lama di Fiamma Verde","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 1,5 metri)","components":"S, M (un'arma da mischia del valore di almeno 1 ma)","material":"un'arma da mischia del valore di almeno 1 ma","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Brandisci l'arma usata per lanciare l'incantesimo ed effettui con essa un attacco in mischia contro una creatura entro 1,5 metri da te. Se colpisci, il bersaglio subisce gli effetti normali dell'attacco con l'arma, e puoi far balzare fuoco verde dal bersaglio verso un'altra creatura a tua scelta che riesci a vedere entro 1,5 metri da esso. La seconda creatura subisce danni da fuoco pari al tuo modificatore di caratteristica da incantatore.\nI danni di questo incantesimo aumentano quando raggiungi determinati livelli. Al 5° livello, l'attacco in mischia infligge 1d8 danni da fuoco aggiuntivi al bersaglio se colpisce, e i danni da fuoco alla seconda creatura aumentano a 1d8 + il tuo modificatore di caratteristica da incantatore. Entrambi i tiri per i danni aumentano di 1d8 all'11° livello (2d8 e 2d8) e al 17° livello (3d8 e 3d8).","language":"it","ui_language":"it"},{"id":"guardian-of-faith","name":"Guardian of Faith","name_it":"Guardiano della Fede","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V","material":"","duration":"8 ore","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un guardiano spettrale di taglia Grande appare e aleggia per la durata dell'incantesimo in uno spazio libero a tua scelta che puoi vedere entro gittata. Il guardiano occupa quello spazio ed è indistinto, a eccezione di una spada e uno scudo scintillanti, raffiguranti il simbolo della tua divinità.\nQualsiasi creatura ostile a te che si sposta in uno spazio entro 3 metri dal guardiano per la prima volta in un turno deve effettuare un tiro salvezza su Destrezza. La creatura subisce 20 danni radianti se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Il guardiano svanisce dopo aver inflitto un totale di 60 danni.","language":"it","ui_language":"it"},{"id":"guardian-of-nature","name":"Guardian of Nature","name_it":"Guardiano della Natura","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Uno spirito della natura risponde alla tua chiamata e ti trasforma in un potente guardiano. La trasformazione dura finché l'incantesimo non termina. Scegli una delle seguenti forme da assumere: Bestia Primordiale o Grande Albero.\nBestia Primordiale. Una pelliccia ferina copre il tuo corpo, i tuoi tratti del viso diventano bestiali, e ottieni i seguenti benefici:\n• La tua velocità di movimento aumenta di 3 metri.\n• Ottieni scurovisione con un raggio di 36 metri.\n• Effettui le prove di attacco basate sulla Forza con vantaggio.\n• I tuoi attacchi in mischia con armi infliggono 1d6 danni da forza aggiuntivi se colpisci.\nGrande Albero. La tua pelle appare simile a corteccia, dai tuoi capelli spuntano foglie, e ottieni i seguenti benefici:\n• Ottieni 10 punti ferita temporanei.\n• Effettui i tiri salvezza su Costituzione con vantaggio.\n• Effettui le prove di attacco basate su Destrezza e Saggezza con vantaggio.\n• Mentre ti trovi a terra, il terreno entro 4,5 metri da te è terreno difficile per i tuoi nemici.","language":"it","ui_language":"it"},{"id":"guards-and-wards","name":"Guards and Wards","name_it":"Guardie e Vedette","level":6,"level_it":"Livello 6","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"10 minuti","range":"Contatto","components":"V, S, M (incenso in combustione, una piccola quantità di zolfo e olio, una cordicella annodata, una piccola quantità di sangue di umber hulk e una piccola verga d'argento del valore di almeno 10 mo)","material":"incenso in combustione, una piccola quantità di zolfo e olio, una cordicella annodata, una piccola quantità di sangue di umber hulk e una piccola verga d'argento del valore di almeno 10 mo","duration":"24 ore","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una protezione che copre fino a 230 metri quadrati di superficie del pavimento (un'area di 15 metri per lato, ovvero cento caselle da 1,5 metri o venticinque caselle da 3 metri). L'area protetta può essere alta fino a 6 metri e avere la forma che desideri. Puoi proteggere più piani di una fortezza suddividendo l'area tra di essi, purché tu possa camminare in ciascuna area contigua mentre lanci l'incantesimo.\nQuando lanci questo incantesimo, puoi specificare individui che non sono influenzati da alcuno o tutti gli effetti che scegli. Puoi anche specificare una parola d'ordine che, se pronunciata ad alta voce, rende chi la dice immune a questi effetti.\nGuardie e vedette crea i seguenti effetti all'interno dell'area protetta.\nCorridoi. Una nebbia riempie tutti i corridoi protetti, rendendoli fortemente offuscati. Inoltre, a ogni incrocio o passaggio con diramazioni che offre una scelta di direzione, c'è una probabilità del 50% che una creatura diversa da te creda di andare nella direzione opposta a quella che sceglie.\nPorte. Tutte le porte nell'area protetta sono magicamente chiuse a chiave, come se fossero sigillate da un incantesimo serratura arcana. Inoltre, puoi coprire fino a dieci porte con un'illusione (equivalente alla funzione di oggetto illusorio dell'incantesimo illusione minore) per farle apparire come semplici sezioni di muro.\nScale. Ragnatele riempiono tutte le scale nell'area protetta dall'alto verso il basso, come l'incantesimo ragnatela. Questi fili ricrescono in 10 minuti se vengono bruciati o strappati mentre guardie e vedette dura.\nAltro Effetto Incantesimo. Puoi collocare, a tua scelta, uno dei seguenti effetti magici all'interno dell'area protetta della fortezza.\n• Colloca luci danzanti in quattro corridoi. Puoi designare un semplice schema che le luci ripetono finché dura guardie e vedette.\n• Colloca bocca magica in due punti.\n• Colloca nube nauseante in due punti. I vapori compaiono nei luoghi che designi; ritornano entro 10 minuti se dispersi dal vento mentre guardie e vedette dura.\n• Colloca una costante raffica di vento in un corridoio o in una stanza.\n• Colloca un suggerimento in un punto. Selezioni un'area fino a 1,5 metri di lato, e qualsiasi creatura che entra o passa attraverso l'area riceve il suggerimento mentalmente.\nL'intera area protetta emana magia. Un dissolvi magie lanciato su un effetto specifico, se ha successo, rimuove solo quell'effetto.\nPuoi creare una struttura permanentemente sorvegliata e protetta lanciando questo incantesimo lì ogni giorno per un anno.","language":"it","ui_language":"it"},{"id":"guidance","name":"Guidance","name_it":"Guida","level":0,"level_it":"Trucchetto","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente. Una volta prima che l'incantesimo termini, il bersaglio può tirare un d4 e aggiungere il numero ottenuto a una prova di caratteristica a sua scelta. Può tirare il dado prima o dopo aver effettuato la prova di caratteristica. L'incantesimo termina quindi.","language":"it","ui_language":"it"},{"id":"guiding-bolt","name":"Guiding Bolt","name_it":"Dardo Guida","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"1 round","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un lampo di luce sfreccia verso una creatura a tua scelta entro gittata. Effettui un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, il bersaglio subisce 4d6 danni radianti, e il prossimo tiro per colpire effettuato contro questo bersaglio prima della fine del tuo prossimo turno ha vantaggio, grazie alla mistica luce fioca che scintilla sul bersaglio fino ad allora.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"gust","name":"Gust","name_it":"Folata","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Afferri l'aria e la costringi a creare uno dei seguenti effetti in un punto che riesci a vedere entro gittata:\n• Una creatura di taglia Media o inferiore a tua scelta deve effettuare un tiro salvezza su Forza o essere spinta fino a 1,5 metri lontano da te.\n• Crei una piccola raffica d'aria capace di muovere un oggetto che non è tenuto né trasportato e che pesa non più di 2,5 chilogrammi. L'oggetto viene spinto fino a 3 metri lontano da te. Non viene spinto con forza sufficiente a causare danni.\n• Crei un innocuo effetto sensoriale utilizzando l'aria, come far frusciare le foglie, far sbattere le imposte al vento, o far ondeggiare i tuoi vestiti in una brezza.","language":"it","ui_language":"it"},{"id":"gust-of-wind","name":"Gust of Wind","name_it":"Raffica di Vento","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (linea di 18 metri)","components":"V, S, M (un seme di legume)","material":"un seme di legume","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Una linea di vento potente lunga 18 metri e larga 3 metri erompe da te in una direzione a tua scelta per la durata dell'incantesimo. Ogni creatura che inizia il proprio turno nella linea deve superare un tiro salvezza su Forza o essere spinta fino a 4,5 metri lontano da te in una direzione che segue la linea.\nOgni creatura nella linea deve spendere 60 centimetri di movimento per ogni 30 centimetri percorsi quando si muove verso di te.\nLa raffica disperde gas o vapori ed estingue candele, torce e fiamme simili non protette nell'area. Fa danzare selvaggiamente le fiamme protette, come quelle delle lanterne, e ha una probabilità del 50% di spegnerle.\nCome azione bonus in ognuno dei tuoi turni prima che l'incantesimo termini, puoi cambiare la direzione in cui la linea erompe da te.","language":"it","ui_language":"it"},{"id":"hail-of-thorns","name":"Hail of Thorns","name_it":"Pioggia di Spine","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci una creatura con un attacco con arma a distanza prima che l'incantesimo termini, questo incantesimo crea una pioggia di spine che germoglia dalla tua arma a distanza o dalle tue munizioni. Oltre al normale effetto dell'attacco, il bersaglio dell'attacco e ogni creatura entro 1,5 metri da esso devono effettuare un tiro salvezza su Destrezza. Una creatura subisce 1d10 danni perforanti se fallisce il tiro salvezza, o la metà dei danni se ha successo.\nAi Livelli Superiori. Se lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d10 per ogni livello dello slot superiore al 1° (fino a un massimo di 6d10).","language":"it","ui_language":"it"},{"id":"hallow","name":"Hallow","name_it":"Consacrazione","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"24 ore","range":"Contatto","components":"V, S, M (erbe, oli e incenso del valore di almeno 1.000 mo, che l'incantesimo consuma)","material":"erbe, oli e incenso del valore di almeno 1.000 mo, che l'incantesimo consuma","duration":"Finché non viene dissolto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un punto e infondi un'area circostante con potere sacro (o profano). L'area può avere un raggio fino a 18 metri, e l'incantesimo fallisce se il raggio include un'area già sotto l'effetto di un incantesimo di consacrazione. L'area interessata è soggetta ai seguenti effetti.\nPrimo, celestiali, elementali, fatati, immondi e non morti non possono entrare nell'area, né tali creature possono ammaliare, spaventare o possedere le creature al suo interno. Ogni creatura ammaliata, spaventata o posseduta da una tale creatura non è più ammaliata, spaventata o posseduta non appena entra nell'area. Puoi escludere una o più di quelle tipologie di creature da questo effetto.\nSecondo, puoi legare un effetto aggiuntivo all'area. Scegli l'effetto dalla lista seguente, oppure scegli un effetto offerto dal DM. Alcuni di questi effetti si applicano alle creature nell'area; puoi stabilire se l'effetto si applica a tutte le creature, alle creature che seguono una specifica divinità o un leader, oppure a creature di un tipo specifico, come orchi o troll. Quando una creatura che verrebbe interessata entra nell'area dell'incantesimo per la prima volta in un turno o inizia il proprio turno lì, può effettuare un tiro salvezza su Carisma. Se ha successo, la creatura ignora l'effetto aggiuntivo finché non lascia l'area.\nCoraggio. Le creature interessate non possono essere spaventate mentre si trovano nell'area.\nOscurità. L'oscurità riempie l'area. La luce normale, così come la luce magica creata da incantesimi di livello inferiore allo slot che hai usato per lanciare questo incantesimo, non può illuminare l'area.\nLuce del Giorno. La luce intensa riempie l'area. L'oscurità magica creata da incantesimi di livello inferiore allo slot che hai usato per lanciare questo incantesimo non può estinguere la luce.\nProtezione dall'Energia. Le creature interessate nell'area hanno resistenza a un tipo di danno a tua scelta, eccetto contundente, perforante o tagliente.\nVulnerabilità all'Energia. Le creature interessate nell'area hanno vulnerabilità a un tipo di danno a tua scelta, eccetto contundente, perforante o tagliente.\nRiposo Eterno. I corpi sepolti nell'area non possono essere trasformati in non morti.\nInterferenza Extradimensionale. Le creature interessate non possono muoversi o viaggiare tramite teletrasporto o mezzi extradimensionali o interplanari.\nPaura. Le creature interessate sono spaventate mentre si trovano nell'area.\nSilenzio. Nessun suono può emanare dall'interno dell'area, e nessun suono può raggiungerla dall'esterno.\nLinguaggi. Le creature interessate possono comunicare con qualsiasi altra creatura nell'area, anche se non condividono una lingua comune.","language":"it","ui_language":"it"},{"id":"hallucinatory-terrain","name":"Hallucinatory Terrain","name_it":"Terreno Illusorio","level":4,"level_it":"Livello 4","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"10 minuti","range":"90 metri","components":"V, S, M (una pietra, un ramoscello e un pezzo di pianta verde)","material":"una pietra, un ramoscello e un pezzo di pianta verde","duration":"24 ore","classes":["Bard","Druid","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fai in modo che un terreno naturale in un cubo di 45 metri di lato entro gittata assomigli, suoni e odori come un altro tipo di terreno naturale. Così, campi aperti o una strada possono essere fatti assomigliare a una palude, una collina, un crepaccio o un altro terreno difficile o impraticabile. Uno stagno può sembrare un prato erboso, un precipizio un pendio dolce, oppure un burrone pieno di rocce una strada larga e liscia. Strutture costruite, equipaggiamento e creature all'interno dell'area non cambiano aspetto.\nLe caratteristiche tattili del terreno restano invariate, quindi le creature che entrano nell'area sono in grado di vedere attraverso l'illusione. Se la differenza non è evidente al tatto, una creatura che esamina attentamente l'illusione può tentare una prova di Intelligenza (Indagare) contro la CD di salvezza del tuo incantesimo per non crederci. Una creatura che percepisce l'illusione per quello che è, la vede come una vaga immagine sovrapposta al terreno.","language":"it","ui_language":"it"},{"id":"harm","name":"Harm","name_it":"Nuocere","level":6,"level_it":"Livello 6","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scateni una malattia virulenta su una creatura che riesci a vedere entro gittata. Il bersaglio deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, subisce 14d6 danni necrotici, oppure la metà dei danni se ha successo. Il danno non può ridurre i punti ferita del bersaglio sotto 1. Se il bersaglio fallisce il tiro salvezza, il suo massimo dei punti ferita viene ridotto per 1 ora di una quantità pari ai danni necrotici subiti. Qualsiasi effetto che rimuove una malattia permette al massimo dei punti ferita di una creatura di tornare alla normalità prima che quel tempo trascorra.","language":"it","ui_language":"it"},{"id":"haste","name":"Haste","name_it":"Velocità","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una scaglia di radice di liquirizia)","material":"una scaglia di radice di liquirizia","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura consenziente che riesci a vedere entro gittata. Finché l'incantesimo non termina, la velocità del bersaglio raddoppia, ottiene un bonus di +2 alla CA, ha vantaggio ai tiri salvezza su Destrezza e ottiene un'azione aggiuntiva in ognuno dei suoi turni. Quell'azione può essere utilizzata solo per compiere l'azione Attaccare (un solo attacco con arma), Scattare, Disimpegnarsi, Nascondersi o Usare un Oggetto.\nQuando l'incantesimo termina, il bersaglio non può muoversi né compiere azioni fino al termine del suo turno successivo, mentre un'ondata di letargia lo pervade.","language":"it","ui_language":"it"},{"id":"heal","name":"Heal","name_it":"Curare","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura che riesci a vedere entro gittata. Un'ondata di energia positiva attraversa la creatura, facendole recuperare 70 punti ferita. Questo incantesimo pone fine anche a cecità, sordità e a qualsiasi malattia che colpisce il bersaglio. Questo incantesimo non ha effetto su costrutti o non morti.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, la quantità di cura aumenta di 10 per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"healing-spirit","name":"Healing Spirit","name_it":"Spirito Curativo","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Evochi uno spirito della natura per lenire i feriti. Lo spirito intangibile appare in uno spazio che è un cubo di 1,5 metri di lato che riesci a vedere entro gittata. Lo spirito assomiglia a una bestia o a un fatato trasparente (a tua scelta).\nFinché l'incantesimo non termina, ogni volta che tu o una creatura che riesci a vedere si muove nello spazio dello spirito per la prima volta in un turno o inizia lì il proprio turno, puoi far sì che lo spirito ripristini 1d6 punti ferita a quella creatura (non è richiesta alcuna azione). Lo spirito non può curare costrutti o non morti.\nCome azione bonus nel tuo turno, puoi spostare lo Spirito fino a 9 metri in uno spazio che riesci a vedere. Lo spirito può curare un numero di volte pari a 1 + il tuo modificatore della caratteristica da incantatore (minimo due volte). Dopo aver curato per quel numero di volte, lo spirito scompare.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, la cura aumenta di 1d6 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"healing-word","name":"Healing Word","name_it":"Parola Curativa","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Cleric","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura a tua scelta che riesci a vedere entro gittata recupera punti ferita pari a 1d4 + il tuo modificatore della caratteristica da incantatore. Questo incantesimo non ha effetto su non morti o costrutti.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, la cura aumenta di 1d4 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"heat-metal","name":"Heat Metal","name_it":"Arroventare Metallo","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pezzo di ferro e una fiamma)","material":"un pezzo di ferro e una fiamma","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli un oggetto metallico costruito, come un'arma di metallo o un'armatura pesante o media di metallo, che riesci a vedere entro gittata. Fai in modo che l'oggetto diventi incandescente. Ogni creatura in contatto fisico con l'oggetto subisce 2d8 danni da fuoco quando lanci l'incantesimo. Finché l'incantesimo non termina, puoi usare un'azione bonus in ognuno dei tuoi turni successivi per infliggere nuovamente questo danno.\nSe una creatura sta tenendo o indossando l'oggetto e subisce il danno da esso, la creatura deve superare un tiro salvezza su Costituzione o lasciar cadere l'oggetto, se può. Se non lascia cadere l'oggetto, ha svantaggio ai tiri per colpire e alle prove di caratteristica fino all'inizio del tuo turno successivo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"hellish-rebuke","name":"Hellish Rebuke","name_it":"Rimprovero Infernale","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 reazione, che si esegue in risposta al subire danni da una creatura visibile entro 18 metri","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Punti il dito, e la creatura che ti ha danneggiato viene momentaneamente circondata da fiamme infernali. La creatura deve effettuare un tiro salvezza su Destrezza. Subisce 2d10 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni se ha successo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d10 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"heroes-feast","name":"Heroes' Feast","name_it":"Banchetto degli Eroi","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"10 minuti","range":"9 metri","components":"V, S, M (una ciotola incrostata di gemme del valore di almeno 1.000 mo, che l'incantesimo consuma)","material":"una ciotola incrostata di gemme del valore di almeno 1.000 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Cleric","Druid","Bard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Fai apparire un grande banchetto, comprendente cibo e bevande magnifici. Il banchetto richiede 1 ora per essere consumato e scompare al termine di quel tempo, e gli effetti benefici non si manifestano finché quest'ora non è trascorsa. Fino a dodici creature possono partecipare al banchetto.\nUna creatura che partecipa al banchetto ottiene diversi benefici. La creatura viene curata da tutte le malattie e i veleni, diventa immune al veleno e all'essere spaventata, ed effettua tutti i tiri salvezza su Saggezza con vantaggio. Il suo massimo dei punti ferita aumenta inoltre di 2d10, e ottiene lo stesso numero di punti ferita. Questi benefici durano 24 ore.","language":"it","ui_language":"it"},{"id":"heroism","name":"Heroism","name_it":"Eroismo","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Paladin"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura consenziente che tocchi viene infusa di coraggio. Finché l'incantesimo non termina, la creatura è immune all'essere spaventata e ottiene punti ferita temporanei pari al tuo modificatore della caratteristica da incantatore all'inizio di ognuno dei suoi turni. Quando l'incantesimo termina, il bersaglio perde ogni punto ferita temporaneo rimanente ottenuto da questo incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"hex","name":"Hex","name_it":"Stregare","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione bonus","range":"27 metri","components":"V, S, M (l'occhio pietrificato di un tritone)","material":"l'occhio pietrificato di un tritone","duration":"Concentrazione, fino a 1 ora","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Poni una maledizione su una creatura che riesci a vedere entro gittata. Finché l'incantesimo non termina, infliggi 1d6 danni necrotici aggiuntivi al bersaglio ogni volta che lo colpisci con un attacco. Inoltre, scegli una caratteristica quando lanci l'incantesimo. Il bersaglio ha svantaggio alle prove effettuate con la caratteristica scelta.\nSe il bersaglio scende a 0 punti ferita prima che questo incantesimo termini, puoi usare un'azione bonus in un turno successivo per maledire una nuova creatura.\nUn incantesimo rimuovere maledizione lanciato sul bersaglio termina anticipatamente questo incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° o 4° livello, puoi mantenere la concentrazione sull'incantesimo fino a 8 ore. Quando utilizzi uno slot incantesimo di 5° livello o superiore, puoi mantenere la concentrazione sull'incantesimo fino a 24 ore.","language":"it","ui_language":"it"},{"id":"hold-monster","name":"Hold Monster","name_it":"Paralizzare Mostri","level":5,"level_it":"Livello 5","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un piccolo pezzo di ferro dritto)","material":"un piccolo pezzo di ferro dritto","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura che riesci a vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Saggezza o essere paralizzato per la durata. Questo incantesimo non ha effetto sui non morti. Alla fine di ognuno dei suoi turni, il bersaglio può effettuare un altro tiro salvezza su Saggezza. Se ha successo, l'incantesimo termina sul bersaglio.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, puoi scegliere come bersaglio una creatura aggiuntiva per ogni livello dello slot superiore al 5°. Le creature devono trovarsi entro 9 metri l'una dall'altra quando le scegli come bersaglio.","language":"it","ui_language":"it"},{"id":"hold-person","name":"Hold Person","name_it":"Paralizzare Persone","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un piccolo pezzo di ferro dritto)","material":"un piccolo pezzo di ferro dritto","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli un umanoide che riesci a vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Saggezza o essere paralizzato per la durata. Alla fine di ognuno dei suoi turni, il bersaglio può effettuare un altro tiro salvezza su Saggezza. Se ha successo, l'incantesimo termina sul bersaglio.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, puoi scegliere come bersaglio un umanoide aggiuntivo per ogni livello dello slot superiore al 2°. Gli umanoidi devono trovarsi entro 9 metri l'uno dall'altro quando li scegli come bersaglio.","language":"it","ui_language":"it"},{"id":"holy-aura","name":"Holy Aura","name_it":"Aura Sacra","level":8,"level_it":"Livello 8","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un piccolo reliquiario del valore di almeno 1.000 mo contenente una reliquia sacra, come un frammento di stoffa della veste di un santo o un pezzo di pergamena di un testo religioso)","material":"un piccolo reliquiario del valore di almeno 1.000 mo contenente una reliquia sacra, come un frammento di stoffa della veste di un santo o un pezzo di pergamena di un testo religioso","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una luce divina si irradia da te e si condensa in un tenue bagliore in un raggio di 9 metri intorno a te. Le creature a tua scelta in quel raggio quando lanci questo incantesimo emanano luce fioca in un raggio di 1,5 metri e hanno vantaggio a tutti i tiri salvezza, e le altre creature hanno svantaggio ai tiri per colpire contro di esse finché l'incantesimo non termina. Inoltre, quando un immondo o un non morto colpisce una creatura interessata con un attacco in mischia, l'aura lampeggia con luce brillante. L'attaccante deve superare un tiro salvezza su Costituzione o essere accecato finché l'incantesimo non termina.","language":"it","ui_language":"it"},{"id":"holy-weapon","name":"Holy Weapon","name_it":"Arma Sacra","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Infondi un'arma che tocchi con potere sacro. Finché l'incantesimo non termina, l'arma emette luce intensa in un raggio di 9 metri e luce fioca per ulteriori 9 metri. Inoltre, gli attacchi con l'arma infliggono 2d8 danni radianti aggiuntivi quando colpiscono. Se l'arma non è già un'arma magica, lo diventa per la durata. Come azione bonus nel tuo turno, puoi dissolvere questo incantesimo e far emettere all'arma un'esplosione di radiosità. Ogni creatura a tua scelta che riesci a vedere entro 9 metri dall'arma deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, una creatura subisce 4d8 danni radianti, ed è accecata per 1 minuto. Se ha successo, una creatura subisce la metà dei danni e non viene accecata. Alla fine di ognuno dei suoi turni, una creatura accecata può effettuare un tiro salvezza su Costituzione, ponendo fine all'effetto su di sé in caso di successo.","language":"it","ui_language":"it"},{"id":"hunger-of-hadar","name":"Hunger of Hadar","name_it":"Fame di Hadar","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (un tentacolo di polpo sott'aceto)","material":"un tentacolo di polpo sott'aceto","duration":"Concentrazione, fino a 1 minuto","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Apri un varco verso il buio tra le stelle, una regione infestata da orrori sconosciuti. Una sfera di oscurità e freddo pungente con un raggio di 6 metri appare, centrata su un punto entro gittata e dura per l'intera durata. Questo vuoto è pieno di una cacofonia di sussurri sommessi e rumori di risucchio udibili fino a 9 metri di distanza. Nessuna luce, magica o meno, può illuminare l'area, e le creature interamente all'interno dell'area sono accecate.\nIl vuoto crea una distorsione nel tessuto dello spazio, e l'area è terreno difficile. Ogni creatura che inizia il proprio turno nell'area subisce 2d6 danni da freddo. Ogni creatura che termina il proprio turno nell'area deve superare un tiro salvezza su Destrezza o subire 2d6 danni da acido mentre tentacoli lattiginosi e ultraterreni la sfiorano.","language":"it","ui_language":"it"},{"id":"hunter-s-mark","name":"Hunter's Mark","name_it":"Marchio del Cacciatore","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione bonus","range":"27 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura che riesci a vedere entro gittata e la marchi misticamente come tua preda. Finché l'incantesimo non termina, infliggi 1d6 danni aggiuntivi al bersaglio ogni volta che lo colpisci con un attacco con arma, e hai vantaggio a qualsiasi prova di Saggezza (Percezione) o Saggezza (Sopravvivenza) che effettui per trovarlo. Se il bersaglio scende a 0 punti ferita prima che questo incantesimo termini, puoi usare un'azione bonus in un turno successivo per marchiare una nuova creatura.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° o 4° livello, puoi mantenere la concentrazione sull'incantesimo fino a 8 ore. Quando utilizzi uno slot incantesimo di 5° livello o superiore, puoi mantenere la concentrazione sull'incantesimo fino a 24 ore.","language":"it","ui_language":"it"},{"id":"hypnotic-pattern","name":"Hypnotic Pattern","name_it":"Motivo Ipnotico","level":3,"level_it":"Livello 3","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"S, M (un bastoncino di incenso luminoso o una fiala di cristallo piena di materiale fosforescente)","material":"un bastoncino di incenso luminoso o una fiala di cristallo piena di materiale fosforescente","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un motivo intrecciato di colori che si dipana nell'aria all'interno di un cubo di 9 metri di lato entro gittata. Il motivo appare per un istante e poi svanisce. Ogni creatura nell'area che vede il motivo deve effettuare un tiro salvezza su Saggezza. Se il tiro salvezza fallisce, la creatura viene affascinata per la durata dell'incantesimo. Mentre è affascinata da questo incantesimo, la creatura è incapacitata e ha velocità 0. L'incantesimo termina per una creatura interessata se subisce danni o se qualcun altro usa un'azione per scuoterla e farla uscire dal torpore.","language":"it","ui_language":"it"},{"id":"ice-knife","name":"Ice Knife","name_it":"Coltello di Ghiaccio","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S, M (una goccia d'acqua o un pezzo di ghiaccio)","material":"una goccia d'acqua o un pezzo di ghiaccio","duration":"Istantanea","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Crei un frammento di ghiaccio e lo scagli contro una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. In caso di successo, il bersaglio subisce 1d10 danni perforanti. Che l'attacco vada a segno o meno, il frammento poi esplode. Il bersaglio e ogni creatura entro 1,5 metri da esso devono superare un tiro salvezza su Destrezza o subire 2d6 danni da freddo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni da freddo aumentano di 1d6 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"ice-storm","name":"Ice Storm","name_it":"Tempesta di Ghiaccio","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V, S, M (un pizzico di polvere e qualche goccia d'acqua)","material":"un pizzico di polvere e qualche goccia d'acqua","duration":"Istantanea","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una grandinata di ghiaccio duro come roccia si abbatte al suolo in un cilindro con un raggio di 6 metri e un'altezza di 12 metri, centrato su un punto entro gittata. Ogni creatura nel cilindro deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 2d8 danni contundenti e 4d6 danni da freddo se il tiro fallisce, o la metà dei danni se ha successo.\nI chicchi di grandine trasformano l'area d'effetto della tempesta in terreno difficile fino alla fine del tuo prossimo turno.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, i danni contundenti aumentano di 1d8 per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"identify","name":"Identify","name_it":"Identificare","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 minuto","range":"Contatto","components":"V, S, M (una perla dal valore di almeno 100 mo e una piuma di gufo)","material":"una perla dal valore di almeno 100 mo e una piuma di gufo","duration":"Istantanea","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli un oggetto che devi toccare per l'intera durata del lancio dell'incantesimo. Se è un oggetto magico o comunque impregnato di magia, apprendi le sue proprietà e come usarle, se richiede sintonia per essere usato, e quante cariche possiede, se ne ha. Apprendi se qualche incantesimo lo sta influenzando e quale. Se l'oggetto è stato creato da un incantesimo, apprendi quale incantesimo lo ha creato.\nSe invece tocchi una creatura per l'intera durata del lancio, apprendi quali incantesimi, se presenti, la stanno attualmente influenzando.","language":"it","ui_language":"it"},{"id":"illusory-dragon","name":"Illusory Dragon","name_it":"Drago Illusorio","level":8,"level_it":"Livello 8","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Raccogliendo filamenti di materia ombrosa dal Piano Ombra, crei un drago ombroso di taglia Enorme in uno spazio libero che riesci a vedere entro gittata. L'illusione dura per la durata dell'incantesimo e occupa il suo spazio, come se fosse una creatura.\nQuando l'illusione appare, ogni tuo nemico che riesce a vederla deve superare un tiro salvezza su Saggezza o essere spaventato da essa per 1 minuto. Se una creatura spaventata termina il proprio turno in un luogo da cui non ha linea di vista sull'illusione, può ripetere il tiro salvezza, ponendo fine all'effetto su di sé in caso di successo.\nCome azione bonus nel tuo turno, puoi muovere l'illusione fino a 18 metri. In qualsiasi momento durante il suo movimento, puoi farle esalare un'ondata di energia in un cono di 18 metri che ha origine dal suo spazio.\nQuando crei il drago, scegli un tipo di danno: acido, freddo, fuoco, fulmine, necrotico o veleno. Ogni creatura nel cono deve effettuare un tiro salvezza su Intelligenza, subendo 7d6 danni del tipo scelto se il tiro fallisce, o la metà dei danni se ha successo.\nL'illusione è tangibile a causa della materia ombrosa usata per crearla, ma gli attacchi la mancano automaticamente. Ha successo automatico in tutti i tiri salvezza, ed è immune a tutti i danni e le condizioni. Una creatura che usa un'azione per esaminare il drago può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD di salvezza del tuo incantesimo. Se una creatura scopre la vera natura dell'illusione, può vederci attraverso e ha vantaggio ai tiri salvezza contro il suo soffio.","language":"it","ui_language":"it"},{"id":"illusory-script","name":"Illusory Script","name_it":"Scrittura Illusoria","level":1,"level_it":"Livello 1","school":"illusion","school_it":"Illusione","ritual":true,"casting_time":"1 minuto","range":"Contatto","components":"S, M (un inchiostro a base di piombo dal valore di almeno 10 mo, che l'incantesimo consuma)","material":"un inchiostro a base di piombo dal valore di almeno 10 mo, che l'incantesimo consuma","duration":"10 giorni","classes":["Bard","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scrivi su pergamena, carta o un altro materiale adatto alla scrittura e lo impregni con una potente illusione che dura per la durata dell'incantesimo.\nPer te e per qualsiasi creatura tu designi al momento del lancio, la scrittura appare normale, scritta di tuo pugno, e trasmette qualsiasi significato tu intendessi quando hai scritto il testo. Per tutti gli altri, la scrittura appare come se fosse scritta in una lingua sconosciuta o magica e risulta incomprensibile. In alternativa, puoi far apparire la scrittura come un messaggio completamente diverso, scritto con una mano e in una lingua diverse, purché la lingua sia una che conosci.\nSe l'incantesimo viene dissolto, sia la scrittura originale che l'illusione scompaiono.\nUna creatura con vista pura può leggere il messaggio nascosto.","language":"it","ui_language":"it"},{"id":"immolation","name":"Immolation","name_it":"Immolazione","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Le fiamme avvolgono una creatura che riesci a vedere entro gittata. Il bersaglio deve effettuare un tiro salvezza su Destrezza. Subisce 8d6 danni da fuoco se il tiro fallisce, o la metà dei danni se ha successo. Se il tiro salvezza fallisce, il bersaglio prende inoltre fuoco per la durata dell'incantesimo. Il bersaglio in fiamme emana luce brillante in un raggio di 9 metri e luce fioca per ulteriori 9 metri. Alla fine di ognuno dei suoi turni, il bersaglio ripete il tiro salvezza. Subisce 4d6 danni da fuoco se il tiro fallisce, e l'incantesimo termina se ha successo. Queste fiamme magiche non possono essere estinte con mezzi non magici.\nSe i danni di questo incantesimo uccidono un bersaglio, il bersaglio viene ridotto in cenere.","language":"it","ui_language":"it"},{"id":"imprisonment","name":"Imprisonment","name_it":"Imprigionamento","level":9,"level_it":"Livello 9","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 minuto","range":"9 metri","components":"V, S, M (una raffigurazione su velluto o una statuetta intagliata a somiglianza del bersaglio, e una componente speciale che varia a seconda della versione dell'incantesimo che scegli, dal valore di almeno 500 mo per Dado Vita del bersaglio)","material":"una raffigurazione su velluto o una statuetta intagliata a somiglianza del bersaglio, e una componente speciale che varia a seconda della versione dell'incantesimo che scegli, dal valore di almeno 500 mo per Dado Vita del bersaglio","duration":"Finché non viene dissolto","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una restrizione magica per trattenere una creatura che riesci a vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Saggezza o essere vincolato dall'incantesimo; se ha successo, diventa immune a questo incantesimo se lo lanci di nuovo su di esso. Mentre è interessata da questo incantesimo, la creatura non ha bisogno di respirare, mangiare o bere, e non invecchia. Gli incantesimi di divinazione non possono localizzarla né percepirla.\nQuando lanci l'incantesimo, scegli una delle seguenti forme di imprigionamento.\nSepoltura. Il bersaglio viene sepolto in profondità sotto la terra in una sfera di forza magica appena abbastanza grande da contenerlo. Nulla può attraversare la sfera, né alcuna creatura può teletrasportarsi o usare il viaggio planare per entrarvi o uscirne.\nLa componente speciale per questa versione dell'incantesimo è una piccola sfera di mithral.\nIncatenamento. Pesanti catene, saldamente ancorate al terreno, tengono il bersaglio fermo. Il bersaglio è immobilizzato finché l'incantesimo non termina, e non può muoversi né essere spostato con alcun mezzo fino ad allora.\nLa componente speciale per questa versione dell'incantesimo è una fine catena di metallo prezioso.\nPrigione Recintata. L'incantesimo trasporta il bersaglio in un minuscolo semipiano protetto contro il teletrasporto e il viaggio planare. Il semipiano può essere un labirinto, una gabbia, una torre, o qualsiasi struttura o area confinata simile di tua scelta.\nLa componente speciale per questa versione dell'incantesimo è una rappresentazione in miniatura della prigione fatta di giada.\nContenimento Minimo. Il bersaglio si rimpicciolisce fino a un'altezza di 2,5 centimetri e viene imprigionato dentro una gemma o un oggetto simile. La luce può attraversare la gemma normalmente (permettendo al bersaglio di vedere fuori e alle altre creature di vedere dentro), ma nient'altro può attraversarla, nemmeno tramite teletrasporto o viaggio planare. La gemma non può essere tagliata o rotta finché l'incantesimo rimane in effetto.\nLa componente speciale per questa versione dell'incantesimo è una grande gemma trasparente, come un corindone, un diamante o un rubino.\nSopore. Il bersaglio si addormenta e non può essere svegliato.\nLa componente speciale per questa versione dell'incantesimo consiste in rare erbe soporifere.\nPorre Fine all'Incantesimo. Durante il lancio dell'incantesimo, in qualsiasi sua versione, puoi specificare una condizione che farà terminare l'incantesimo e libererà il bersaglio. La condizione può essere specifica o elaborata quanto vuoi, ma il DM deve concordare che la condizione sia ragionevole e abbia una probabilità di verificarsi. Le condizioni possono basarsi sul nome, l'identità o la divinità di una creatura, ma per il resto devono basarsi su azioni o qualità osservabili e non su elementi intangibili come livello, classe o punti ferita.\nUn incantesimo di dissolvi magie può porre fine all'incantesimo solo se viene lanciato come incantesimo di 9° livello, avendo come bersaglio la prigione o la componente speciale usata per crearla.\nPuoi usare una particolare componente speciale per creare una sola prigione alla volta. Se lanci di nuovo l'incantesimo usando la stessa componente, il bersaglio del primo lancio viene immediatamente liberato dal suo vincolo.","language":"it","ui_language":"it"},{"id":"incendiary-cloud","name":"Incendiary Cloud","name_it":"Nube Incendiaria","level":8,"level_it":"Livello 8","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard","Druid"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Una nube vorticosa di fumo attraversata da braci incandescenti appare in una sfera con un raggio di 6 metri centrata su un punto entro gittata.\nLa nube si diffonde intorno agli angoli ed è fortemente oscurata. Dura per l'intera durata o finché un vento di velocità moderata o superiore (almeno 16 chilometri orari) non la disperde. Quando la nube appare, ogni creatura al suo interno deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 10d8 danni da fuoco se il tiro fallisce, o la metà dei danni se ha successo. Una creatura deve effettuare questo tiro salvezza anche quando entra per la prima volta nell'area dell'incantesimo durante un turno o termina il proprio turno lì.\nLa nube si muove di 3 metri direttamente lontano da te in una direzione che scegli all'inizio di ognuno dei tuoi turni.","language":"it","ui_language":"it"},{"id":"infernal-calling","name":"Infernal Calling","name_it":"Chiamata Infernale","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"27 metri","components":"V, S, M (un rubino dal valore di almeno 999 mo)","material":"un rubino dal valore di almeno 999 mo","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Pronunciando un'oscura incantazione, evochi un diavolo dai Nove Inferi. Scegli il tipo di diavolo, che deve avere grado di sfida 6 o inferiore, come un diavolo spinato o un diavolo barbuto. Il diavolo appare in uno spazio libero che riesci a vedere entro gittata. Il diavolo scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\nIl diavolo è ostile verso di te e i tuoi compagni. Tira l'iniziativa per il diavolo, che ha i propri turni. È sotto il controllo del DM e agisce secondo la sua natura in ognuno dei suoi turni, il che potrebbe portarlo ad attaccarti se pensa di poter prevalere, o a tentare di indurti a compiere un'azione malvagia in cambio di un servizio limitato. Il DM possiede le statistiche della creatura.\nIn ognuno dei tuoi turni, puoi provare a impartire un comando verbale al diavolo (non richiede alcuna azione da parte tua). Obbedisce al comando se il probabile esito è in accordo con i suoi desideri, specialmente se il risultato ti avvicinerebbe al male. Altrimenti, devi effettuare una prova di Carisma (Inganno, Intimidire o Persuasione) contrastata dalla sua prova di Saggezza (Intuizione). Effettui la prova con vantaggio se pronunci il vero nome del diavolo. Se la tua prova fallisce, il diavolo diventa immune ai tuoi comandi verbali per la durata dell'incantesimo, anche se può comunque eseguire i tuoi comandi se lo desidera. Se la tua prova ha successo, il diavolo esegue il tuo comando — come \"attacca i miei nemici\", \"esplora la stanza qui davanti\" o \"porta questo messaggio alla regina\" — finché non completa l'attività, momento in cui torna da te per riferire di averlo fatto.\nSe la tua concentrazione termina prima che l'incantesimo raggiunga la sua piena durata, il diavolo non scompare se è diventato immune ai tuoi comandi verbali. Invece, agisce come meglio crede per 3d6 minuti, e poi scompare.\nSe possiedi il talismano di un diavolo particolare, puoi evocare quel diavolo se ha il grado di sfida appropriato più 1, e obbedisce a tutti i tuoi comandi, senza che siano richieste prove di Carisma.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, il grado di sfida aumenta di 1 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"infestation","name":"Infestation","name_it":"Infestazione","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una pulce viva)","material":"una pulce viva","duration":"Istantanea","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fai apparire momentaneamente una nube di acari, pulci e altri parassiti su una creatura che riesci a vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Costituzione, oppure subisce 1d6 danni da veleno e si muove di 1,5 metri in una direzione casuale se può muoversi e ha una velocità di almeno 1,5 metri. Tira un d4 per la direzione: 1, nord; 2, sud; 3, est; o 4, ovest. Questo movimento non provoca attacchi di opportunità, e se la direzione ottenuta è bloccata, il bersaglio non si muove.\nI danni dell'incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"inflict-wounds","name":"Inflict Wounds","name_it":"Infliggere Ferite","level":1,"level_it":"Livello 1","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Effettua un attacco con incantesimo in mischia contro una creatura che riesci a raggiungere. In caso di successo, il bersaglio subisce 3d10 danni necrotici.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d10 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"insect-plague","name":"Insect Plague","name_it":"Piaga d'Insetti","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V, S, M (qualche granello di zucchero, alcuni chicchi di grano e un'untuosa macchia di grasso)","material":"qualche granello di zucchero, alcuni chicchi di grano e un'untuosa macchia di grasso","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric","Druid","Sorcerer"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Uno sciame di locuste ronzanti e pungenti riempie una sfera con un raggio di 6 metri centrata su un punto che scegli entro gittata. La sfera si diffonde intorno agli angoli. La sfera rimane per l'intera durata, e la sua area è leggermente oscurata. L'area della sfera è terreno difficile.\nQuando l'area appare, ogni creatura al suo interno deve effettuare un tiro salvezza su Costituzione. Una creatura subisce 4d10 danni perforanti se il tiro fallisce, o la metà dei danni se ha successo. Una creatura deve effettuare questo tiro salvezza anche quando entra per la prima volta nell'area dell'incantesimo durante un turno o termina il proprio turno lì.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d10 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"intellect-fortress","name":"Intellect Fortress","name_it":"Fortezza dell'Intelletto","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Per l'intera durata, tu o una creatura consenziente che riesci a vedere entro gittata ottiene resistenza ai danni psichici, oltre a vantaggio ai tiri salvezza su Intelligenza, Saggezza e Carisma.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, puoi bersagliare una creatura aggiuntiva per ogni livello dello slot superiore al 3°. Le creature devono trovarsi entro 9 metri l'una dall'altra quando le bersagli.","language":"it","ui_language":"it"},{"id":"investiture-of-flame","name":"Investiture of Flame","name_it":"Investitura della Fiamma","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Le fiamme corrono lungo il tuo corpo, emanando luce brillante in un raggio di 9 metri e luce fioca per ulteriori 9 metri per l'intera durata dell'incantesimo. Le fiamme non ti danneggiano. Finché l'incantesimo non termina, ottieni i seguenti benefici:\n• Sei immune ai danni da fuoco e hai resistenza ai danni da freddo.\n• Ogni creatura che si muove entro 1,5 metri da te per la prima volta durante un turno o termina il proprio turno lì subisce 1d10 danni da fuoco.\n• Puoi usare la tua azione per creare una linea di fuoco lunga 4,5 metri e larga 1,5 metri che si estende da te in una direzione che scegli. Ogni creatura nella linea deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 4d8 danni da fuoco se il tiro fallisce, o la metà dei danni se ha successo.","language":"it","ui_language":"it"},{"id":"investiture-of-ice","name":"Investiture of Ice","name_it":"Investitura del Ghiaccio","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Finché l'incantesimo non termina, il ghiaccio ricopre il tuo corpo, e ottieni i seguenti benefici:\n• Sei immune ai danni da freddo e hai resistenza ai danni da fuoco.\n• Puoi muoverti attraverso il terreno difficile creato da ghiaccio o neve senza spendere movimento aggiuntivo.\n• Il terreno in un raggio di 3 metri intorno a te è ghiacciato ed è terreno difficile per le creature diverse da te. Il raggio si sposta con te.\n• Puoi usare la tua azione per creare un cono di vento gelido lungo 4,5 metri che si estende dalla tua mano tesa in una direzione che scegli. Ogni creatura nel cono deve effettuare un tiro salvezza su Costituzione. Una creatura subisce 4d6 danni da freddo se il tiro fallisce, o la metà dei danni se ha successo. Una creatura che fallisce il tiro salvezza contro questo effetto ha la propria velocità dimezzata fino all'inizio del tuo prossimo turno.","language":"it","ui_language":"it"},{"id":"investiture-of-stone","name":"Investiture of Stone","name_it":"Investitura della Pietra","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Finché l'incantesimo non termina, frammenti di roccia si diffondono sul tuo corpo, e ottieni i seguenti benefici:\n• Hai resistenza ai danni contundenti, perforanti e taglienti provenienti da attacchi non magici.\n• Puoi usare la tua azione per creare un piccolo terremoto sul terreno in un raggio di 4,5 metri centrato su di te. Le altre creature su quel terreno devono superare un tiro salvezza su Destrezza o essere atterrate.\n• Puoi muoverti attraverso il terreno difficile fatto di terra o pietra senza spendere movimento aggiuntivo. Puoi muoverti attraverso terra o pietra solida come se fosse aria e senza destabilizzarla, ma non puoi terminare il tuo movimento lì. Se lo fai, vieni espulso nello spazio libero più vicino, questo incantesimo termina, e resti stordito fino alla fine del tuo prossimo turno.","language":"it","ui_language":"it"},{"id":"investiture-of-wind","name":"Investiture of Wind","name_it":"Investitura del Vento","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Finché l'incantesimo non termina, il vento turbina intorno a te, e ottieni i seguenti benefici:\n• Gli attacchi con armi a distanza effettuati contro di te hanno svantaggio al tiro per colpire.\n• Ottieni una velocità di volo di 18 metri. Se stai ancora volando quando l'incantesimo termina, cadi, a meno che tu non riesca in qualche modo a evitarlo.\n• Puoi usare la tua azione per creare un cubo di 4,5 metri di lato di vento vorticoso centrato su un punto che riesci a vedere entro 18 metri da te. Ogni creatura in quell'area deve effettuare un tiro salvezza su Costituzione. Una creatura subisce 2d10 danni contundenti se il tiro fallisce, o la metà dei danni se ha successo. Se una creatura di taglia Grande o inferiore fallisce il tiro, quella creatura viene inoltre spinta fino a 3 metri lontano dal centro del cubo.","language":"it","ui_language":"it"},{"id":"invisibility","name":"Invisibility","name_it":"Invisibilità","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un ciglio racchiuso in gomma arabica)","material":"un ciglio racchiuso in gomma arabica","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura che tocchi diventa invisibile finché l'incantesimo non termina. Qualsiasi cosa il bersaglio indossi o porti con sé è invisibile finché rimane sulla persona del bersaglio. L'incantesimo termina per un bersaglio che attacca o lancia un incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, puoi bersagliare una creatura aggiuntiva per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"invulnerability","name":"Invulnerability","name_it":"Invulnerabilità","level":9,"level_it":"Livello 9","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un piccolo pezzo di adamantio dal valore di almeno 500 mo, che l'incantesimo consuma)","material":"un piccolo pezzo di adamantio dal valore di almeno 500 mo, che l'incantesimo consuma","duration":"Concentrazione, fino a 10 minuti","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Sei immune a tutti i danni finché l'incantesimo non termina.","language":"it","ui_language":"it"},{"id":"jump","name":"Jump","name_it":"Salto","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (la zampa posteriore di una cavalletta)","material":"la zampa posteriore di una cavalletta","duration":"1 minuto","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura. La distanza di salto della creatura triplica finché l'incantesimo non termina.","language":"it","ui_language":"it"},{"id":"knock","name":"Knock","name_it":"Bussare","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli un oggetto che riesci a vedere entro gittata. L'oggetto può essere una porta, una scatola, un baule, un paio di manette, un lucchetto o un altro oggetto che contiene un mezzo mondano o magico che ne impedisce l'accesso.\nUn bersaglio tenuto chiuso da una serratura comune, oppure incastrato o sbarrato, si sblocca, si libera dall'incastro o perde le sue sbarre. Se l'oggetto ha più serrature, solo una di esse viene sbloccata.\nSe scegli un bersaglio tenuto chiuso da serratura arcana, quell'incantesimo viene soppresso per 10 minuti, durante i quali il bersaglio può essere aperto e chiuso normalmente.\nQuando lanci l'incantesimo, un forte bussare, udibile fino a 90 metri di distanza, emana dall'oggetto bersaglio.","language":"it","ui_language":"it"},{"id":"legend-lore","name":"Legend Lore","name_it":"Sapienza Leggendaria","level":5,"level_it":"Livello 5","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"10 minuti","range":"Personale","components":"V, S, M (incenso del valore di almeno 250 mo, che l'incantesimo consuma, e quattro strisce d'avorio del valore di almeno 50 mo ciascuna)","material":"incenso del valore di almeno 250 mo, che l'incantesimo consuma, e quattro strisce d'avorio del valore di almeno 50 mo ciascuna","duration":"Istantanea","classes":["Bard","Cleric","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Nomina o descrivi una persona, un luogo o un oggetto. L'incantesimo ti porta alla mente un breve riassunto delle informazioni significative riguardanti la cosa che hai nominato. Le informazioni possono consistere in racconti attuali, storie dimenticate o persino sapienza segreta che non è mai stata ampiamente conosciuta. Se la cosa che hai nominato non ha importanza leggendaria, non ottieni alcuna informazione. Più informazioni possiedi già sulla cosa, più precise e dettagliate sono quelle che ricevi.\nLe informazioni che apprendi sono accurate, ma potrebbero essere espresse in un linguaggio figurato. Ad esempio, se hai a disposizione una misteriosa ascia magica, l'incantesimo potrebbe fornirti questa informazione: «Guai al malvagio la cui mano tocchi l'ascia, poiché persino il manico taglia la mano dei malvagi. Solo un vero Figlio della Pietra, amante e amato da Moradin, può risvegliare i veri poteri dell'ascia, e solo pronunciando la sacra parola Rudnogg».","language":"it","ui_language":"it"},{"id":"leomund-s-secret-chest","name":"Leomund's Secret Chest","name_it":"Baule Segreto di Leomund","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (uno scrigno squisito, 90 x 60 x 60 centimetri, costruito con materiali rari del valore di almeno 5.000 mo, e una replica in miniatura di taglia Minuscola realizzata con gli stessi materiali del valore di almeno 50 mo)","material":"uno scrigno squisito, 90 x 60 x 60 centimetri, costruito con materiali rari del valore di almeno 5.000 mo, e una replica in miniatura di taglia Minuscola realizzata con gli stessi materiali del valore di almeno 50 mo","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Nascondi uno scrigno, e tutto il suo contenuto, nel Piano Etereo. Devi toccare lo scrigno e la replica in miniatura che funge da componente materiale per l'incantesimo. Lo scrigno può contenere fino a 0,34 metri cubi di materiale non vivente (90 x 60 x 60 centimetri).\nFinché lo scrigno rimane nel Piano Etereo, puoi usare un'azione e toccare la replica per richiamare lo scrigno. Esso appare in uno spazio libero sul terreno entro 1,5 metri da te. Puoi rimandare lo scrigno nel Piano Etereo usando un'azione e toccando sia lo scrigno che la replica.\nDopo 60 giorni, c'è una probabilità cumulativa del 5 percento al giorno che l'effetto dell'incantesimo termini. Questo effetto termina se lanci di nuovo questo incantesimo, se la replica più piccola viene distrutta, oppure se scegli di terminare l'incantesimo come azione. Se l'incantesimo termina e lo scrigno più grande si trova nel Piano Etereo, esso viene perso irrimediabilmente.","language":"it","ui_language":"it"},{"id":"leomund-s-tiny-hut","name":"Leomund's Tiny Hut","name_it":"Piccola Capanna di Leomund","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":true,"casting_time":"1 minuto","range":"Personale (emisfero con raggio di 3 metri)","components":"V, S, M (una piccola perlina di cristallo)","material":"una piccola perlina di cristallo","duration":"8 ore","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una cupola di forza immobile con un raggio di 3 metri si materializza intorno e sopra di te e rimane stazionaria per la durata. L'incantesimo termina se lasci la sua area.\nNove creature di taglia Media o inferiore possono stare all'interno della cupola insieme a te. L'incantesimo fallisce se la sua area include una creatura più grande o più di nove creature. Le creature e gli oggetti all'interno della cupola quando lanci questo incantesimo possono muoversi liberamente attraverso di essa. Tutte le altre creature e oggetti non possono passarvi attraverso. Gli incantesimi e altri effetti magici non possono estendersi attraverso la cupola né essere lanciati attraverso di essa. L'atmosfera all'interno dello spazio è confortevole e asciutta, indipendentemente dal clima esterno.\nFinché l'incantesimo non termina, puoi comandare all'interno di diventare debolmente illuminato o buio. La cupola è opaca dall'esterno, del colore che scegli, ma è trasparente dall'interno.","language":"it","ui_language":"it"},{"id":"lesser-restoration","name":"Lesser Restoration","name_it":"Ripristino Inferiore","level":2,"level_it":"Livello 2","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Cleric","Druid","Paladin","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura e puoi porre fine a una malattia o a una condizione che la affligge. La condizione può essere accecato, assordato, paralizzato o avvelenato.","language":"it","ui_language":"it"},{"id":"levitate","name":"Levitate","name_it":"Levitazione","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un piccolo anello di cuoio oppure un pezzo di filo d'oro piegato a forma di coppa con un lungo stelo a un'estremità)","material":"un piccolo anello di cuoio oppure un pezzo di filo d'oro piegato a forma di coppa con un lungo stelo a un'estremità","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura o un oggetto libero a tua scelta che riesci a vedere entro gittata si solleva verticalmente, fino a 6 metri, e rimane sospeso lì per la durata. L'incantesimo può far levitare un bersaglio che pesa fino a 250 chilogrammi. Una creatura non consenziente che supera un tiro salvezza su Costituzione non viene interessata.\nIl bersaglio può muoversi solo spingendo o tirando contro un oggetto o una superficie fissa a portata (come un muro o un soffitto), il che gli permette di muoversi come se stesse arrampicandosi. Puoi cambiare l'altitudine del bersaglio fino a 6 metri in entrambe le direzioni durante il tuo turno. Se sei tu il bersaglio, puoi muoverti su o giù come parte del tuo movimento. Altrimenti, puoi usare la tua azione per muovere il bersaglio, che deve rimanere entro la gittata dell'incantesimo.\nQuando l'incantesimo termina, il bersaglio scende dolcemente fluttuando fino al suolo se è ancora in volo.","language":"it","ui_language":"it"},{"id":"life-transference","name":"Life Transference","name_it":"Trasferimento Vitale","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Sacrifichi parte della tua salute per curare le ferite di un'altra creatura. Subisci 4d8 danni necrotici, e una creatura a tua scelta che riesci a vedere entro gittata recupera un numero di punti ferita pari al doppio dei danni necrotici che subisci.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"light","name":"Light","name_it":"Luce","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, M (una lucciola o del muschio fosforescente)","material":"una lucciola o del muschio fosforescente","duration":"1 ora","classes":["Bard","Cleric","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un oggetto non più grande di 3 metri in nessuna dimensione. Finché l'incantesimo non termina, l'oggetto emana luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri. La luce può essere del colore che preferisci. Coprire completamente l'oggetto con qualcosa di opaco blocca la luce. L'incantesimo termina se lo lanci di nuovo o lo congedi come azione.\nSe prendi di mira un oggetto tenuto o indossato da una creatura ostile, quella creatura deve superare un tiro salvezza su Destrezza per evitare l'incantesimo.","language":"it","ui_language":"it"},{"id":"lightning-arrow","name":"Lightning Arrow","name_it":"Freccia Fulminante","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che effettui un attacco con arma a distanza durante la durata dell'incantesimo, le munizioni dell'arma, o l'arma stessa se è un'arma da lancio, si trasformano in un fulmine. Effettua il tiro per colpire normalmente. Il bersaglio subisce 4d8 danni da fulmine se colpito, o la metà dei danni se mancato, al posto dei normali danni dell'arma.\nChe tu colpisca o manchi, ogni creatura entro 3 metri dal bersaglio deve effettuare un tiro salvezza su Destrezza. Ciascuna di queste creature subisce 2d8 danni da fulmine se il tiro fallisce, o la metà dei danni se ha successo.\nIl pezzo di munizione o l'arma ritorna quindi alla sua forma normale.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni di entrambi gli effetti dell'incantesimo aumentano di 1d8 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"lightning-bolt","name":"Lightning Bolt","name_it":"Fulmine","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (linea di 30 metri)","components":"V, S, M (un pezzo di pelliccia e un'asta d'ambra, cristallo o vetro)","material":"un pezzo di pelliccia e un'asta d'ambra, cristallo o vetro","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un fulmine che forma una linea lunga 30 metri e larga 1,5 metri esplode da te nella direzione che scegli. Ogni creatura nella linea deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 8d6 danni da fulmine se il tiro fallisce, o la metà dei danni se ha successo.\nIl fulmine incendia gli oggetti infiammabili nell'area che non sono indossati né trasportati.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"lightning-lure","name":"Lightning Lure","name_it":"Richiamo Fulminante","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 4,5 metri)","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Crei una frusta di energia fulminante che colpisce una creatura a tua scelta che riesci a vedere entro 4,5 metri da te. Il bersaglio deve superare un tiro salvezza su Forza oppure viene trascinato fino a 3 metri in linea retta verso di te e subisce quindi 1d8 danni da fulmine se si trova entro 1,5 metri da te.\nI danni di questo incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"locate-animals-or-plants","name":"Locate Animals or Plants","name_it":"Localizzare Animali o Piante","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un po' di pelo di un segugio)","material":"un po' di pelo di un segugio","duration":"Istantanea","classes":["Bard","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Descrivi o nomina un tipo specifico di bestia o pianta. Concentrandoti sulla voce della natura che ti circonda, apprendi la direzione e la distanza della creatura o pianta più vicina di quel tipo entro 7,5 chilometri, se ve ne sono presenti.","language":"it","ui_language":"it"},{"id":"locate-creature","name":"Locate Creature","name_it":"Localizzare Creatura","level":4,"level_it":"Livello 4","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un po' di pelo di un segugio)","material":"un po' di pelo di un segugio","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Cleric","Druid","Paladin","Ranger","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Descrivi o nomina una creatura che ti è familiare. Percepisci la direzione verso la posizione della creatura, purché quella creatura si trovi entro 300 metri da te. Se la creatura si sta muovendo, conosci la direzione del suo movimento.\nL'incantesimo può localizzare una creatura specifica a te nota, oppure la creatura più vicina di un tipo specifico (come un umano o un unicorno), purché tu abbia visto da vicino -entro 9 metri- una creatura simile almeno una volta. Se la creatura che hai descritto o nominato si trova in una forma diversa, ad esempio sotto gli effetti di un incantesimo di metamorfosi, questo incantesimo non localizza la creatura.\nQuesto incantesimo non può localizzare una creatura se dell'acqua corrente larga almeno 3 metri blocca un percorso diretto tra te e la creatura.","language":"it","ui_language":"it"},{"id":"locate-object","name":"Locate Object","name_it":"Localizzare Oggetto","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un ramoscello biforcuto)","material":"un ramoscello biforcuto","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Cleric","Druid","Paladin","Ranger","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Descrivi o nomina un oggetto che ti è familiare. Percepisci la direzione verso la posizione dell'oggetto, purché quell'oggetto si trovi entro 300 metri da te. Se l'oggetto è in movimento, conosci la direzione del suo movimento.\nL'incantesimo può localizzare un oggetto specifico a te noto, purché tu lo abbia visto da vicino —entro 9 metri— almeno una volta. In alternativa, l'incantesimo può localizzare l'oggetto più vicino di un tipo particolare, come un certo tipo di indumento, gioiello, mobile, attrezzo o arma.\nQuesto incantesimo non può localizzare un oggetto se un qualsiasi spessore di piombo, anche un sottile foglio, blocca un percorso diretto tra te e l'oggetto.","language":"it","ui_language":"it"},{"id":"longstrider","name":"Longstrider","name_it":"Falcata","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pizzico di terra)","material":"un pizzico di terra","duration":"1 ora","classes":["Bard","Druid","Ranger","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura. La velocità del bersaglio aumenta di 3 metri finché l'incantesimo non termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, puoi bersagliare una creatura aggiuntiva per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"maddening-darkness","name":"Maddening Darkness","name_it":"Oscurità Enfollente","level":8,"level_it":"Livello 8","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, M (una goccia di pece mescolata con una goccia di mercurio)","material":"una goccia di pece mescolata con una goccia di mercurio","duration":"Concentrazione, fino a 10 minuti","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Un'oscurità magica si diffonde da un punto che scegli entro gittata per riempire una sfera con un raggio di 18 metri finché l'incantesimo non termina. L'oscurità si diffonde intorno agli angoli. Una creatura con scurovisione non può vedere attraverso questa oscurità. La luce non magica, così come la luce creata da incantesimi di 8° livello o inferiore, non può illuminare l'area. All'interno della sfera si possono udire urla, farfugliamenti e risate folli. Ogni volta che una creatura inizia il suo turno nella sfera, deve effettuare un tiro salvezza su Saggezza, subendo 8d8 danni psichici se il tiro fallisce, o la metà dei danni se ha successo.","language":"it","ui_language":"it"},{"id":"maelstrom","name":"Maelstrom","name_it":"Maelstrom","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (carta o una foglia a forma di imbuto)","material":"carta o una foglia a forma di imbuto","duration":"Concentrazione, fino a 1 minuto","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Una massa d'acqua profonda 1,5 metri appare e vortica in un raggio di 9 metri centrato su un punto che riesci a vedere entro gittata. Il punto deve trovarsi sul terreno o in uno specchio d'acqua. Finché l'incantesimo non termina, quell'area è terreno difficile, e qualsiasi creatura che inizia il suo turno lì deve superare un tiro salvezza su Forza o subire 6d6 danni contundenti ed essere trascinata per 3 metri verso il centro.","language":"it","ui_language":"it"},{"id":"mage-armor","name":"Mage Armor","name_it":"Armatura del Mago","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pezzo di cuoio conciato)","material":"un pezzo di cuoio conciato","duration":"8 ore","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente che non indossa armatura, e una forza magica protettiva la circonda finché l'incantesimo non termina. La CA base del bersaglio diventa 13 + il suo modificatore di Destrezza. L'incantesimo termina se il bersaglio indossa un'armatura o se lo congedi come azione.","language":"it","ui_language":"it"},{"id":"mage-hand","name":"Mage Hand","name_it":"Manomagica","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una mano spettrale e fluttuante appare in un punto che scegli entro gittata. La mano dura per la durata o finché non la congedi come azione. La mano svanisce se si trova mai a più di 9 metri da te o se lanci di nuovo questo incantesimo.\nPuoi usare la tua azione per controllare la mano. Puoi usare la mano per manipolare un oggetto, aprire una porta o un contenitore sbloccato, riporre o recuperare un oggetto da un contenitore aperto, oppure versare il contenuto di una fiala. Puoi spostare la mano fino a 9 metri ogni volta che la usi.\nLa mano non può attaccare, attivare oggetti magici o trasportare più di 5 chilogrammi.","language":"it","ui_language":"it"},{"id":"magic-circle","name":"Magic Circle","name_it":"Cerchio Magico","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 minuto","range":"3 metri","components":"V, S, M (acqua santa o polvere d'argento e ferro del valore di almeno 100 mo, che l'incantesimo consuma)","material":"acqua santa o polvere d'argento e ferro del valore di almeno 100 mo, che l'incantesimo consuma","duration":"1 ora","classes":["Cleric","Paladin","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un cilindro di energia magica con un raggio di 3 metri e un'altezza di 6 metri, centrato su un punto sul terreno che riesci a vedere entro gittata. Rune luminose appaiono ovunque il cilindro intersechi il pavimento o un'altra superficie.\nScegli uno o più dei seguenti tipi di creature: celestiali, elementali, fatati, immondi o non morti. Il cerchio influenza una creatura del tipo scelto nei seguenti modi:\n• La creatura non può entrare volontariamente nel cilindro con mezzi non magici. Se la creatura tenta di usare il teletrasporto o il viaggio interpianare per farlo, deve prima superare un tiro salvezza su Carisma.\n• La creatura ha svantaggio ai tiri per colpire contro bersagli all'interno del cilindro.\n• I bersagli all'interno del cilindro non possono essere ammaliati, spaventati o posseduti dalla creatura.\nQuando lanci questo incantesimo, puoi scegliere di far operare la sua magia in direzione inversa, impedendo a una creatura del tipo specificato di lasciare il cilindro e proteggendo i bersagli all'esterno di esso.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 4 o superiore, la durata aumenta di 1 ora per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"magic-jar","name":"Magic Jar","name_it":"Vaso Magico","level":6,"level_it":"Livello 6","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 minuto","range":"Personale","components":"V, S, M (una gemma, un cristallo, un reliquiario o un altro contenitore ornamentale del valore di almeno 500 mo)","material":"una gemma, un cristallo, un reliquiario o un altro contenitore ornamentale del valore di almeno 500 mo","duration":"Finché non viene dissolto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Il tuo corpo cade in uno stato catatonico mentre la tua anima lo abbandona ed entra nel contenitore che hai usato come componente materiale dell'incantesimo. Finché la tua anima abita il contenitore, sei consapevole di ciò che ti circonda come se ti trovassi nello spazio del contenitore. Non puoi muoverti né usare reazioni. L'unica azione che puoi compiere è proiettare la tua anima fino a 30 metri fuori dal contenitore, tornando nel tuo corpo vivente (ponendo così fine all'incantesimo) oppure tentando di possedere il corpo di un umanoide.\nPuoi tentare di possedere qualsiasi umanoide entro 30 metri da te che riesci a vedere (le creature protette da un incantesimo di protezione dal male e dal bene o cerchio magico non possono essere possedute). Il bersaglio deve effettuare un tiro salvezza su Carisma. In caso di fallimento, la tua anima si trasferisce nel corpo del bersaglio, e l'anima del bersaglio rimane intrappolata nel contenitore. In caso di successo, il bersaglio resiste ai tuoi tentativi di possessione, e non puoi tentare di possederlo di nuovo per 24 ore.\nUna volta che possiedi il corpo di una creatura, lo controlli. Le tue statistiche di gioco vengono sostituite da quelle della creatura, sebbene tu mantenga il tuo allineamento e i tuoi punteggi di Intelligenza, Saggezza e Carisma. Mantieni il beneficio delle tue caratteristiche di classe. Se il bersaglio possiede livelli di classe, non puoi usare nessuna delle sue caratteristiche di classe.\nNel frattempo, l'anima della creatura posseduta può percepire dal contenitore usando i propri sensi, ma non può muoversi né compiere azioni.\nMentre possiedi un corpo, puoi usare la tua azione per tornare dal corpo ospite al contenitore se questo si trova entro 30 metri da te, restituendo l'anima della creatura ospite al proprio corpo. Se il corpo ospite muore mentre ti trovi in esso, la creatura muore, e devi effettuare un tiro salvezza su Carisma contro la tua stessa CD di lancio incantesimi. In caso di successo, torni nel contenitore se questo si trova entro 30 metri da te. Altrimenti, muori.\nSe il contenitore viene distrutto o l'incantesimo termina, la tua anima ritorna immediatamente al tuo corpo. Se il tuo corpo si trova a più di 30 metri da te o se il tuo corpo è morto quando tenti di tornarvi, muori. Se l'anima di un'altra creatura si trova nel contenitore quando questo viene distrutto, l'anima della creatura torna al proprio corpo se questo è vivo ed entro 30 metri. Altrimenti, quella creatura muore.\nQuando l'incantesimo termina, il contenitore viene distrutto.","language":"it","ui_language":"it"},{"id":"magic-missile","name":"Magic Missile","name_it":"Missile Incantato","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei tre dardi luminosi di forza magica. Ogni dardo colpisce una creatura a tua scelta che riesci a vedere entro gittata. Un dardo infligge 1d4 + 1 danni da forza al proprio bersaglio. I dardi colpiscono tutti simultaneamente, e puoi indirizzarli per colpire una sola creatura o diverse.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 2 o superiore, l'incantesimo crea un dardo aggiuntivo per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"magic-mouth","name":"Magic Mouth","name_it":"Bocca Magica","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":true,"casting_time":"1 minuto","range":"9 metri","components":"V, S, M (un piccolo pezzo di favo e polvere di giada del valore di almeno 10 mo, che l'incantesimo consuma)","material":"un piccolo pezzo di favo e polvere di giada del valore di almeno 10 mo, che l'incantesimo consuma","duration":"Finché non viene dissolto","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Impianti un messaggio all'interno di un oggetto entro gittata, un messaggio che viene pronunciato quando si verifica una condizione scatenante. Scegli un oggetto che riesci a vedere e che non sia indossato o trasportato da un'altra creatura. Poi pronuncia il messaggio, che deve essere composto da 25 parole o meno, sebbene possa essere pronunciato nell'arco di 10 minuti. Infine, determina la circostanza che attiverà l'incantesimo facendogli pronunciare il tuo messaggio.\nQuando quella circostanza si verifica, una bocca magica appare sull'oggetto e recita il messaggio con la tua voce e allo stesso volume con cui l'hai pronunciato. Se l'oggetto che hai scelto ha una bocca o qualcosa che assomiglia a una bocca (per esempio, la bocca di una statua), la bocca magica appare lì, in modo che le parole sembrino provenire dalla bocca dell'oggetto. Quando lanci questo incantesimo, puoi far terminare l'incantesimo dopo che ha pronunciato il suo messaggio, oppure può rimanere e ripetere il messaggio ogni volta che si verifica la condizione scatenante.\nLa circostanza scatenante può essere generica o dettagliata quanto vuoi, purché sia basata su condizioni visive o uditive che si verificano entro 9 metri dall'oggetto. Per esempio, potresti istruire la bocca a parlare quando una creatura qualsiasi si muove entro 9 metri dall'oggetto oppure quando una campanella d'argento suona entro 9 metri da esso.","language":"it","ui_language":"it"},{"id":"magic-stone","name":"Magic Stone","name_it":"Pietra Magica","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Contatto","components":"V, S","material":"","duration":"1 minuto","classes":["Druid","Warlock"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Tocchi da uno a tre sassolini e li imbui di magia. Tu o qualcun altro potete effettuare un attacco con incantesimo a distanza con uno dei sassolini lanciandolo o scagliandolo con una fionda. Se lanciato, ha una gittata di 18 metri. Se qualcun altro attacca con il sassolino, quell'attaccante aggiunge il tuo modificatore di caratteristica da incantatore, non quello dell'attaccante, al tiro per colpire. In caso di colpo, il bersaglio subisce danni contundenti pari a 1d6 + il tuo modificatore di caratteristica da incantatore. Che l'attacco colpisca o fallisca, l'incantesimo termina sul sasso.\nSe lanci di nuovo questo incantesimo, l'incantesimo termina su qualsiasi sassolino ancora interessato dal tuo precedente lancio.","language":"it","ui_language":"it"},{"id":"magic-weapon","name":"Magic Weapon","name_it":"Arma Magica","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Paladin","Wizard","Ranger","Sorcerer"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un'arma non magica. Finché l'incantesimo non termina, quell'arma diventa un'arma magica con un bonus di +1 ai tiri per colpire e ai tiri per i danni.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 4 o superiore, il bonus aumenta a +2. Quando usi uno slot incantesimo di livello 6 o superiore, il bonus aumenta a +3.","language":"it","ui_language":"it"},{"id":"major-image","name":"Major Image","name_it":"Immagine Complessa","level":3,"level_it":"Livello 3","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un pezzetto di lana)","material":"un pezzetto di lana","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei l'immagine di un oggetto, una creatura o qualche altro fenomeno visibile non più grande di un cubo di 6 metri di lato. L'immagine appare in un punto che riesci a vedere entro gittata e dura per la durata. Sembra completamente reale, inclusi suoni, odori e temperatura appropriati alla cosa raffigurata. Non puoi creare calore o freddo sufficienti a causare danni, un suono abbastanza forte da infliggere danni da tuono o assordare una creatura, oppure un odore in grado di far star male una creatura (come il fetore di un troglodita).\nFinché ti trovi entro gittata dall'illusione, puoi usare la tua azione per far spostare l'immagine in qualsiasi altro punto entro gittata. Mentre l'immagine cambia posizione, puoi alterarne l'aspetto in modo che i suoi movimenti appaiano naturali per l'immagine. Per esempio, se crei l'immagine di una creatura e la sposti, puoi alterare l'immagine in modo che sembri camminare. Allo stesso modo, puoi far emettere all'illusione suoni diversi in momenti diversi, facendola persino intrattenere una conversazione, per esempio.\nL'interazione fisica con l'immagine rivela che si tratta di un'illusione, perché le cose possono attraversarla. Una creatura che usa la sua azione per esaminare l'immagine può determinare che si tratta di un'illusione con una prova di Intelligenza (Indagare) riuscita contro la CD di salvezza del tuo incantesimo. Se una creatura scopre l'illusione per quello che è, la creatura può vedere attraverso l'immagine, e le sue altre qualità sensoriali diventano deboli per la creatura.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 6 o superiore, l'incantesimo dura finché non viene dissolto, senza richiedere la tua concentrazione.","language":"it","ui_language":"it"},{"id":"mass-cure-wounds","name":"Mass Cure Wounds","name_it":"Cura Ferite di Massa","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Cleric","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un'ondata di energia curativa si propaga da un punto a tua scelta entro gittata. Scegli fino a sei creature in una sfera con un raggio di 9 metri centrata su quel punto. Ogni bersaglio recupera un numero di punti ferita pari a 3d8 + il tuo modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto su non morti o costrutti.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 6 o superiore, la guarigione aumenta di 1d8 per ogni livello dello slot superiore al 5°.","language":"it","ui_language":"it"},{"id":"mass-heal","name":"Mass Heal","name_it":"Guarigione di Massa","level":9,"level_it":"Livello 9","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un flusso di energia curativa scorre da te verso le creature ferite intorno a te. Ripristini fino a 700 punti ferita, suddivisi come preferisci tra un numero qualsiasi di creature che riesci a vedere entro gittata. Le creature guarite da questo incantesimo vengono anche curate da tutte le malattie e da qualsiasi effetto che le rende accecate o assordate. Questo incantesimo non ha effetto su non morti o costrutti.","language":"it","ui_language":"it"},{"id":"mass-healing-word","name":"Mass Healing Word","name_it":"Parola Curativa di Massa","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Cleric","Bard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Mentre pronunci parole di guarigione, fino a sei creature a tua scelta che riesci a vedere entro gittata recuperano un numero di punti ferita pari a 1d4 + il tuo modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto su non morti o costrutti.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 4 o superiore, la guarigione aumenta di 1d4 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"mass-polymorph","name":"Mass Polymorph","name_it":"Metamorfosi di Massa","level":9,"level_it":"Livello 9","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un bozzolo di bruco)","material":"un bozzolo di bruco","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Trasformi fino a dieci creature a tua scelta che riesci a vedere entro gittata. Un bersaglio non consenziente deve superare un tiro salvezza su Saggezza per resistere alla trasformazione. Un mutaforma non consenziente ha automaticamente successo al tiro salvezza.\nOgni bersaglio assume una forma bestiale a tua scelta, e puoi scegliere la stessa forma o forme diverse per ciascun bersaglio. La nuova forma può essere quella di qualsiasi bestia che tu abbia visto, il cui grado di sfida sia pari o inferiore a quello del bersaglio (o alla metà del livello del bersaglio, se questo non ha un grado di sfida). Le statistiche di gioco del bersaglio, inclusi i punteggi di caratteristica mentali, vengono sostituite da quelle della bestia scelta, ma il bersaglio mantiene i suoi punti ferita, l'allineamento e la personalità.\nOgni bersaglio ottiene un numero di punti ferita temporanei pari ai punti ferita della sua nuova forma. Questi punti ferita temporanei non possono essere sostituiti da punti ferita temporanei provenienti da un'altra fonte. Un bersaglio ritorna alla sua forma normale quando non ha più punti ferita temporanei o quando muore. Se l'incantesimo termina prima di allora, la creatura perde tutti i suoi punti ferita temporanei e ritorna alla sua forma normale.\nLa creatura è limitata nelle azioni che può compiere dalla natura della sua nuova forma. Non può parlare, lanciare incantesimi o fare qualsiasi altra cosa che richieda mani o parola. L'equipaggiamento del bersaglio si fonde con la nuova forma.\nIl bersaglio non può attivare, usare, brandire o altrimenti beneficiare di alcuno del suo equipaggiamento.","language":"it","ui_language":"it"},{"id":"mass-suggestion","name":"Mass Suggestion","name_it":"Suggestione di Massa","level":6,"level_it":"Livello 6","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, M (la lingua di un serpente e un pezzetto di favo oppure una goccia di olio dolce)","material":"la lingua di un serpente e un pezzetto di favo oppure una goccia di olio dolce","duration":"24 ore","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Suggerisci un corso d'azione (limitato a una o due frasi) e influenzi magicamente fino a dodici creature a tua scelta che riesci a vedere entro gittata e che possono sentirti e capirti. Le creature che non possono essere ammaliate sono immuni a questo effetto. Il suggerimento deve essere formulato in modo tale da far apparire ragionevole il corso d'azione. Chiedere alla creatura di pugnalarsi, gettarsi su una lancia, darsi fuoco o compiere qualche altro atto palesemente dannoso annulla automaticamente l'effetto dell'incantesimo.\nOgni bersaglio deve effettuare un tiro salvezza su Saggezza. In caso di fallimento, persegue il corso d'azione che hai descritto al meglio delle sue capacità. Il corso d'azione suggerito può continuare per l'intera durata. Se l'attività suggerita può essere completata in un tempo più breve, l'incantesimo termina quando il soggetto finisce ciò che gli è stato chiesto di fare.\nPuoi anche specificare condizioni che attiveranno un'attività speciale durante la durata. Per esempio, potresti suggerire che un gruppo di soldati dia tutto il proprio denaro al primo mendicante che incontra. Se la condizione non viene soddisfatta prima che l'incantesimo termini, l'attività non viene eseguita.\nSe tu o uno dei tuoi compagni infliggete danni a una creatura interessata da questo incantesimo, l'incantesimo termina per quella creatura.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 7° livello, la durata è di 10 giorni. Quando usi uno slot incantesimo di 8° livello, la durata è di 30 giorni. Quando usi uno slot incantesimo di 9° livello, la durata è di un anno e un giorno.","language":"it","ui_language":"it"},{"id":"maximilian-s-earthen-grasp","name":"Maximilian's Earthen Grasp","name_it":"Presa Terrosa di Maximilian","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una piccola mano scolpita nell'argilla)","material":"una piccola mano scolpita nell'argilla","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli uno spazio libero di 1,5 metri per lato sul terreno che riesci a vedere entro gittata. Una mano di taglia Media fatta di terra compattata si solleva lì e si protende verso una creatura che riesci a vedere entro 1,5 metri da essa. Il bersaglio deve effettuare un tiro salvezza su Forza. In caso di fallimento, il bersaglio subisce 2d6 danni contundenti ed è trattenuto per la durata dell'incantesimo.\nCome azione, puoi far sì che la mano schiacci il bersaglio trattenuto, che deve effettuare un tiro salvezza su Forza. Il bersaglio subisce 2d6 danni contundenti in caso di fallimento, o la metà dei danni in caso di successo.\nPer liberarsi, il bersaglio trattenuto può usare la sua azione per effettuare una prova di Forza contro la CD di salvezza del tuo incantesimo. In caso di successo, il bersaglio si libera e non è più trattenuto dalla mano.\nCome azione, puoi far sì che la mano si protenda verso una creatura diversa o si sposti in uno spazio libero diverso entro gittata. La mano rilascia un bersaglio trattenuto se fai una di queste due cose.","language":"it","ui_language":"it"},{"id":"maze","name":"Maze","name_it":"Labirinto","level":8,"level_it":"Livello 8","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Bandisci una creatura che riesci a vedere entro gittata in un demipiano labirintico. Il bersaglio vi rimane per la durata o finché non riesce a fuggire dal labirinto.\nIl bersaglio può usare la sua azione per tentare di fuggire. Quando lo fa, effettua una prova di Intelligenza con CD 20. Se ha successo, fugge e l'incantesimo termina (un minotauro o un demone goristro hanno automaticamente successo).\nQuando l'incantesimo termina, il bersaglio riappare nello spazio che ha lasciato o, se quello spazio è occupato, nello spazio libero più vicino.","language":"it","ui_language":"it"},{"id":"meld-into-stone","name":"Meld into Stone","name_it":"Fondersi con la Pietra","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":true,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"8 ore","classes":["Cleric","Druid","Ranger"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Ti fondi in un oggetto o superficie di pietra abbastanza grande da contenere completamente il tuo corpo, fondendo te stesso e tutto l'equipaggiamento che porti con la pietra per la durata. Usando il tuo movimento, entri nella pietra in un punto che puoi toccare. Nulla della tua presenza rimane visibile o altrimenti rilevabile con sensi non magici.\nMentre sei fuso con la pietra, non puoi vedere ciò che accade all'esterno, e qualsiasi prova di Saggezza (Percezione) che effettui per udire suoni all'esterno viene effettuata con svantaggio. Rimani consapevole del trascorrere del tempo e puoi lanciare incantesimi su te stesso mentre sei fuso nella pietra. Puoi usare il tuo movimento per uscire dalla pietra nel punto in cui sei entrato, il che pone fine all'incantesimo. Altrimenti non puoi muoverti.\nUn danno fisico minore alla pietra non ti danneggia, ma la sua distruzione parziale o un cambiamento nella sua forma (al punto da non entrarci più) ti espelle e ti infligge 6d6 danni contundenti. La distruzione completa della pietra (o la sua trasmutazione in una sostanza diversa) ti espelle e ti infligge 50 danni contundenti. Se espulso, cadi prono nello spazio libero più vicino a dove sei entrato per la prima volta.","language":"it","ui_language":"it"},{"id":"melf-s-acid-arrow","name":"Melf's Acid Arrow","name_it":"Freccia Acida di Melf","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (foglia di rabarbaro polverizzata e lo stomaco di una vipera)","material":"foglia di rabarbaro polverizzata e lo stomaco di una vipera","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una freccia verde scintillante sfreccia verso un bersaglio entro gittata ed esplode in uno spruzzo d'acido. Effettua un attacco con incantesimo a distanza contro il bersaglio. In caso di colpo, il bersaglio subisce immediatamente 4d4 danni da acido e altri 2d4 danni da acido alla fine del suo prossimo turno. In caso di fallimento, la freccia spruzza il bersaglio di acido infliggendo metà del danno iniziale e nessun danno alla fine del suo prossimo turno.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 3 o superiore, il danno (sia iniziale che successivo) aumenta di 1d4 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"melf-s-minute-meteors","name":"Melf's Minute Meteors","name_it":"Piccole Meteore di Melf","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (nitro, zolfo e catrame di pino modellati in una pallina)","material":"nitro, zolfo e catrame di pino modellati in una pallina","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Crei sei minuscole meteore nel tuo spazio. Fluttuano nell'aria e orbitano intorno a te per la durata dell'incantesimo. Quando lanci l'incantesimo—e come azione bonus in ciascuno dei tuoi turni successivi—puoi consumare una o due meteore, scagliandole verso un punto o più punti a tua scelta entro 36 metri da te. Una volta che una meteora raggiunge la sua destinazione o colpisce una superficie solida, la meteora esplode. Ogni creatura entro 1,5 metri dal punto in cui la meteora esplode deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 2d6 danni da fuoco in caso di fallimento, o la metà dei danni in caso di successo.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello 4 o superiore, il numero di meteore create aumenta di due per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"mending","name":"Mending","name_it":"Riparare","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 minuto","range":"Contatto","components":"V, S, M (due calamite)","material":"due calamite","duration":"Istantanea","classes":["Bard","Cleric","Druid","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo ripara una singola rottura o strappo in un oggetto che tocchi, come l'anello spezzato di una catena, le due metà di una chiave rotta, un mantello strappato o un otre che perde. Purché la rottura o lo strappo non sia più largo di 30 centimetri in nessuna dimensione, lo ripari, senza lasciare traccia del danno precedente. Questo incantesimo può riparare fisicamente un oggetto magico o un costrutto, ma l'incantesimo non può ripristinarne la magia.","language":"it","ui_language":"it"},{"id":"mental-prison","name":"Mental Prison","name_it":"Prigione Mentale","level":6,"level_it":"Livello 6","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Tenti di intrappolare una creatura all'interno di una cella illusoria che solo essa percepisce. Una creatura che riesci a vedere entro gittata deve effettuare un tiro salvezza su Intelligenza. Il bersaglio ha automaticamente successo se è immune all'essere ammaliato. In caso di successo, il bersaglio subisce 5d10 danni psichici, e l'incantesimo termina. In caso di fallimento, il bersaglio subisce 5d10 danni psichici, e fai apparire l'area immediatamente intorno allo spazio del bersaglio come pericolosa in qualche modo. Potresti far percepire al bersaglio di essere circondato da fuoco, rasoi fluttuanti o orribili fauci piene di denti gocciolanti. Qualunque forma assuma l'illusione, il bersaglio non può vedere né sentire nulla al di là di essa ed è trattenuto per la durata dell'incantesimo. Se il bersaglio viene spostato fuori dall'illusione, effettua un attacco in mischia attraverso di essa, o vi allunga una parte del proprio corpo, il bersaglio subisce 10d10 danni psichici, e l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"message","name":"Message","name_it":"Messaggio","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un corto pezzo di filo di rame)","material":"un corto pezzo di filo di rame","duration":"1 round","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Punti il dito verso una creatura entro gittata e sussurri un messaggio. Il bersaglio (e solo il bersaglio) sente il messaggio e può rispondere con un sussurro che solo tu riesci a sentire.\nPuoi lanciare questo incantesimo attraverso oggetti solidi se conosci bene il bersaglio e sai che si trova oltre la barriera. Silenzio magico, 30 centimetri di pietra, 2,5 centimetri di metallo comune, una sottile lamina di piombo, o 90 centimetri di legno bloccano l'incantesimo. L'incantesimo non deve seguire una linea retta e può viaggiare liberamente attorno agli angoli o attraverso aperture.","language":"it","ui_language":"it"},{"id":"meteor-swarm","name":"Meteor Swarm","name_it":"Pioggia di Meteore","level":9,"level_it":"Livello 9","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"1,5 chilometri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Sfere fiammeggianti di fuoco precipitano al suolo in quattro punti diversi che riesci a vedere entro gittata. Ogni creatura in una sfera con raggio di 12 metri centrata su ciascun punto che scegli deve effettuare un tiro salvezza su Destrezza. La sfera si propaga attorno agli angoli. Una creatura subisce 20d6 danni da fuoco e 20d6 danni contundenti in caso di fallimento, o metà del danno in caso di successo. Una creatura nell'area di più di un'esplosione di fuoco viene colpita una sola volta.\nL'incantesimo danneggia gli oggetti nell'area e incendia gli oggetti infiammabili che non vengono indossati o trasportati.","language":"it","ui_language":"it"},{"id":"mighty-fortress","name":"Mighty Fortress","name_it":"Fortezza Possente","level":8,"level_it":"Livello 8","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"1,5 chilometri","components":"V, S, M (un diamante del valore di almeno 500 mo, che l'incantesimo consuma)","material":"un diamante del valore di almeno 500 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Una fortezza di pietra erompe da un'area quadrata di terreno a tua scelta che riesci a vedere entro gittata. L'area è di 36 metri per lato e non deve contenere edifici o altre strutture. Tutte le creature presenti nell'area vengono sollevate senza subire danni mentre la fortezza si innalza.\nLa fortezza ha quattro torrette con basi quadrate, ciascuna di 6 metri per lato e alta 9 metri, con una torretta su ogni angolo. Le torrette sono collegate tra loro da mura di pietra lunghe 24 metri ciascuna, che creano un'area recintata. Ogni muro è spesso 30 centimetri ed è composto da pannelli larghi 3 metri e alti 6 metri. Ogni pannello è contiguo ad altri due pannelli, oppure a un pannello e a una torretta. Puoi posizionare fino a quattro porte di pietra nel muro esterno della fortezza.\nUn piccolo maniero si erge all'interno dell'area recintata. Il maniero ha una base quadrata di 15 metri per lato e ha tre piani con soffitti alti 3 metri. Ciascuno dei piani può essere suddiviso in tante stanze quante desideri, a patto che ogni stanza sia di almeno 1,5 metri per lato. I piani del maniero sono collegati da scale di pietra, le sue mura sono spesse 15 centimetri e le stanze interne possono avere porte di pietra o archi aperti a tua scelta. Il maniero è arredato e decorato come preferisci, e contiene cibo a sufficienza per servire un banchetto di nove portate a un massimo di 100 persone ogni giorno. Gli arredi, il cibo e gli altri oggetti creati da questo incantesimo si sgretolano in polvere se rimossi dalla fortezza.\nUno stuolo di cento servitori invisibili obbedisce a qualsiasi ordine impartito loro dalle creature che designi quando lanci l'incantesimo. Ogni servitore agisce come se fosse creato dall'incantesimo servitore invisibile.\nLe mura, le torrette e il maniero sono tutti fatti di pietra che può essere danneggiata. Ogni sezione di pietra di 3 metri per 3 metri ha CA 15 e 30 punti ferita per ogni 2,5 centimetri di spessore. È immune ai danni da veleno e psichici. Ridurre a 0 punti ferita una sezione di pietra la distrugge e potrebbe far vacillare e crollare le sezioni collegate, a discrezione del DM.\nDopo 7 giorni, o quando lanci di nuovo questo incantesimo altrove, la fortezza si sgretola senza causare danni e sprofonda di nuovo nel terreno, lasciando in sicurezza al suolo qualsiasi creatura che si trovasse al suo interno.\nLanciare questo incantesimo nello stesso punto una volta ogni 7 giorni per un anno rende la fortezza permanente.","language":"it","ui_language":"it"},{"id":"mind-blank","name":"Mind Blank","name_it":"Mente Vacua","level":8,"level_it":"Livello 8","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"24 ore","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fino al termine dell'incantesimo, una creatura consenziente che tocchi è immune ai danni psichici, a qualsiasi effetto che percepisca le sue emozioni o legga i suoi pensieri, agli incantesimi di divinazione e alla condizione ammaliato. L'incantesimo vanifica persino gli incantesimi desiderio e incantesimi o effetti di potere simile usati per influenzare la mente del bersaglio o per ottenere informazioni su di esso.","language":"it","ui_language":"it"},{"id":"mind-sliver","name":"Mind Sliver","name_it":"Scheggia Mentale","level":0,"level_it":"Trucchetto","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"1 round","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Scagli una scheggia disorientante di energia psichica nella mente di una creatura che riesci a vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Intelligenza, altrimenti subisce 1d6 danni psichici e sottrae 1d4 al prossimo tiro salvezza che effettua prima della fine del tuo turno successivo.\nIl danno di questo incantesimo aumenta di 1d6 quando raggiungi determinati livelli: 5° livello (2d6), 11° livello (3d6) e 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"mind-spike","name":"Mind Spike","name_it":"Picco Mentale","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Ti insinui nella mente di una creatura che riesci a vedere entro gittata. Il bersaglio deve effettuare un tiro salvezza su Saggezza, subendo 3d8 danni psichici in caso di fallimento, o metà del danno in caso di successo. In caso di fallimento, conosci sempre anche la posizione del bersaglio fino al termine dell'incantesimo, ma solo finché entrambi vi trovate sullo stesso piano di esistenza. Finché possiedi questa conoscenza, il bersaglio non può nascondersi da te e, se è invisibile, non ottiene alcun beneficio da tale condizione nei tuoi confronti.\nAi Livelli Superiori. Se lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d8 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"minor-illusion","name":"Minor Illusion","name_it":"Illusione Minore","level":0,"level_it":"Trucchetto","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"S, M (un pizzico di lana)","material":"un pizzico di lana","duration":"1 minuto","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un suono o l'immagine di un oggetto entro gittata, che perdura per la durata dell'incantesimo. L'illusione termina anche se la dissolvi con un'azione o se lanci di nuovo questo incantesimo.\nSe crei un suono, il suo volume può variare da un sussurro a un grido. Può essere la tua voce, la voce di qualcun altro, il ruggito di un leone, un rullo di tamburi o qualsiasi altro suono tu scelga. Il suono continua ininterrottamente per tutta la durata, oppure puoi produrre suoni distinti in momenti diversi prima che l'incantesimo termini.\nSe crei l'immagine di un oggetto – come una sedia, delle impronte fangose o un piccolo forziere – non deve essere più grande di un cubo di 1,5 metri di lato. L'immagine non può creare suoni, luce, odori o qualsiasi altro effetto sensoriale. L'interazione fisica con l'immagine rivela che si tratta di un'illusione, poiché gli oggetti possono attraversarla.\nSe una creatura utilizza la propria azione per esaminare il suono o l'immagine, può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD di salvezza del tuo incantesimo. Se una creatura scopre la vera natura dell'illusione, questa diventa sbiadita ai suoi occhi.","language":"it","ui_language":"it"},{"id":"mirage-arcane","name":"Mirage Arcane","name_it":"Miraggio Arcano","level":7,"level_it":"Livello 7","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"10 minuti","range":"Vista","components":"V, S","material":"","duration":"10 giorni","classes":["Bard","Druid","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fai in modo che il terreno in un'area quadrata con lato fino a 1,5 chilometri abbia l'aspetto, il suono, l'odore e persino la consistenza di un altro tipo di terreno. La forma generale del terreno, tuttavia, rimane la stessa. Campi aperti o una strada potrebbero essere fatti assomigliare a una palude, una collina, un crepaccio o un altro terreno difficile o impraticabile. Uno stagno può sembrare un prato erboso, un precipizio un pendio dolce, oppure un canalone cosparso di rocce una strada ampia e liscia.\nAllo stesso modo, puoi alterare l'aspetto delle strutture, o aggiungerle dove non ve ne sono. L'incantesimo non maschera, occulta o aggiunge creature.\nL'illusione include elementi uditivi, visivi, tattili e olfattivi, quindi può trasformare un terreno libero in terreno difficile (o viceversa) o altrimenti ostacolare il movimento attraverso l'area. Qualsiasi elemento del terreno illusorio (come una roccia o un ramoscello) che viene rimosso dall'area dell'incantesimo scompare immediatamente.\nLe creature con vista pura possono vedere attraverso l'illusione la vera forma del terreno; tuttavia, tutti gli altri elementi dell'illusione rimangono, quindi, sebbene la creatura sia consapevole della presenza dell'illusione, può comunque interagire fisicamente con essa.","language":"it","ui_language":"it"},{"id":"mirror-image","name":"Mirror Image","name_it":"Immagine Speculare","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"1 minuto","classes":["Sorcerer","Warlock","Wizard","Bard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tre duplicati illusori di te stesso appaiono nel tuo spazio. Finché l'incantesimo dura, i duplicati si muovono con te e imitano le tue azioni, spostandosi in modo da rendere impossibile capire quale immagine sia quella reale. Puoi usare la tua azione per dissolvere i duplicati illusori.\nOgni volta che una creatura ti bersaglia con un attacco durante la durata dell'incantesimo, tira 1d20 per determinare se l'attacco colpisce invece uno dei tuoi duplicati.\nSe hai tre duplicati, devi ottenere un 6 o più per spostare il bersaglio dell'attacco su un duplicato. Con due duplicati, devi ottenere un 8 o più. Con un duplicato, devi ottenere un 11 o più.\nLa CA di un duplicato è pari a 10 + il tuo modificatore di Destrezza. Se un attacco colpisce un duplicato, il duplicato viene distrutto. Un duplicato può essere distrutto solo da un attacco che lo colpisce. Ignora ogni altro danno ed effetto. L'incantesimo termina quando tutti e tre i duplicati sono stati distrutti.\nUna creatura non è influenzata da questo incantesimo se non può vedere, se fa affidamento su sensi diversi dalla vista, come la vista cieca, o se è in grado di percepire le illusioni come tali, come nel caso della vista pura.","language":"it","ui_language":"it"},{"id":"mislead","name":"Mislead","name_it":"Fuorviare","level":5,"level_it":"Livello 5","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Wizard","Warlock"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Diventi invisibile nello stesso momento in cui un doppio illusorio di te appare nel punto in cui ti trovavi. Il doppio dura per la durata dell'incantesimo, ma l'invisibilità termina se attacchi o lanci un incantesimo.\nPuoi usare la tua azione per muovere il tuo doppio illusorio fino al doppio della tua velocità e fargli gesticolare, parlare e comportarsi come preferisci.\nPuoi vedere attraverso i suoi occhi e sentire attraverso le sue orecchie come se ti trovassi dove si trova lui. A ogni tuo turno, come azione bonus, puoi passare dall'uso dei suoi sensi all'uso dei tuoi, o viceversa. Mentre usi i suoi sensi, sei accecato e assordato rispetto al tuo ambiente circostante.","language":"it","ui_language":"it"},{"id":"misty-step","name":"Misty Step","name_it":"Passo Nebbioso","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Avvolto brevemente da una nebbia argentea, ti teletrasporti fino a 9 metri in uno spazio libero che riesci a vedere.","language":"it","ui_language":"it"},{"id":"modify-memory","name":"Modify Memory","name_it":"Modificare la Memoria","level":5,"level_it":"Livello 5","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tenti di rimodellare i ricordi di un'altra creatura. Una creatura che riesci a vedere deve effettuare un tiro salvezza su Saggezza. Se stai combattendo la creatura, questa ha vantaggio al tiro salvezza. In caso di fallimento, il bersaglio viene ammaliato da te per la durata dell'incantesimo. Il bersaglio ammaliato è incapacitato e ignaro di ciò che lo circonda, sebbene possa ancora sentirti. Se subisce qualsiasi danno o viene bersagliato da un altro incantesimo, questo incantesimo termina e nessuno dei ricordi del bersaglio viene modificato.\nFinché dura questo ammaliamento, puoi influenzare il ricordo che il bersaglio ha di un evento vissuto nelle ultime 24 ore e durato non più di 10 minuti. Puoi eliminare permanentemente ogni ricordo dell'evento, permettere al bersaglio di ricordarlo con perfetta chiarezza e in ogni dettaglio, modificarne il ricordo dei particolari, oppure creare il ricordo di un evento diverso.\nDevi parlare al bersaglio per descrivere come i suoi ricordi vengono modificati, e il bersaglio deve essere in grado di comprendere la tua lingua affinché i ricordi modificati attecchiscano. La sua mente colma automaticamente eventuali lacune nei dettagli della tua descrizione. Se l'incantesimo termina prima che tu abbia finito di descrivere i ricordi modificati, il ricordo della creatura non viene alterato. Altrimenti, i ricordi modificati si consolidano quando l'incantesimo termina.\nUn ricordo modificato non influisce necessariamente sul comportamento di una creatura, in particolare se il ricordo contraddice le inclinazioni naturali, l'allineamento o le convinzioni della creatura. Un ricordo modificato illogico, come impiantare il ricordo di quanto la creatura si sia divertita a immergersi nell'acido, viene respinto, magari come un brutto sogno. Il DM potrebbe ritenere un ricordo modificato troppo insensato per influenzare in modo significativo una creatura.\nUn incantesimo di rimuovere maledizione o ripristino superiore lanciato sul bersaglio ripristina il vero ricordo della creatura.\nAi Livelli Superiori. Se lanci questo incantesimo usando uno slot incantesimo di 6° livello o superiore, puoi alterare i ricordi del bersaglio relativi a un evento avvenuto fino a 7 giorni fa (6° livello), 30 giorni fa (7° livello), 1 anno fa (8° livello), o in qualsiasi momento del passato della creatura (9° livello).","language":"it","ui_language":"it"},{"id":"mold-earth","name":"Mold Earth","name_it":"Modellare la Terra","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"S","material":"","duration":"Istantanea o 1 ora (vedi sotto)","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli una porzione di terra o pietra che riesci a vedere entro gittata e che rientra in un cubo di 1,5 metri di lato. La manipoli in uno dei seguenti modi:\n• Se prendi di mira un'area di terra smossa, puoi scavarla istantaneamente, spostarla lungo il terreno e depositarla fino a 1,5 metri di distanza. Questo movimento non ha abbastanza forza da causare danni.\n• Fai apparire forme, colori o entrambi sulla terra o sulla pietra, componendo parole, creando immagini o disegnando motivi. I cambiamenti durano 1 ora.\n• Se la terra o la pietra che prendi di mira si trova sul terreno, la trasformi in terreno difficile. In alternativa, puoi far tornare normale il terreno se è già terreno difficile. Questo cambiamento dura 1 ora.\nSe lanci questo incantesimo più volte, puoi avere al massimo due dei suoi effetti non istantanei attivi contemporaneamente, e puoi dissolvere uno di questi effetti con un'azione.","language":"it","ui_language":"it"},{"id":"moonbeam","name":"Moonbeam","name_it":"Raggio di Luna","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (alcuni semi di una qualsiasi pianta di semiluna e un pezzo di feldspato opalescente)","material":"alcuni semi di una qualsiasi pianta di semiluna e un pezzo di feldspato opalescente","duration":"Concentrazione, fino a 1 minuto","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un raggio argentato di luce pallida risplende in un cilindro con raggio di 1,5 metri e altezza di 12 metri, centrato su un punto entro gittata. Finché l'incantesimo dura, una luce fioca riempie il cilindro.\nQuando una creatura entra per la prima volta nell'area dell'incantesimo durante un turno, o inizia lì il proprio turno, viene avvolta da fiamme spettrali che causano un dolore lancinante, e deve effettuare un tiro salvezza su Costituzione. Subisce 2d10 danni radiosi in caso di fallimento, o metà del danno in caso di successo.\nUn mutaforma effettua il proprio tiro salvezza con svantaggio. Se fallisce, riprende anche istantaneamente la propria forma originale e non può assumerne un'altra finché non lascia la luce dell'incantesimo.\nA ogni tuo turno successivo al lancio di questo incantesimo, puoi usare un'azione per spostare il raggio fino a 18 metri in qualsiasi direzione.\nAi Livelli Superiori. Se lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d10 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"mordenkainen-s-faithful-hound","name":"Mordenkainen's Faithful Hound","name_it":"Fedele Segugio di Mordenkainen","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un piccolo fischietto d'argento, un pezzo d'osso e un filo)","material":"un piccolo fischietto d'argento, un pezzo d'osso e un filo","duration":"8 ore","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi un cane da guardia spettrale in uno spazio libero che riesci a vedere entro gittata, dove rimane per la durata dell'incantesimo, finché non lo dissolvi con un'azione o finché non ti allontani più di 30 metri da esso.\nIl segugio è invisibile a tutte le creature tranne te e non può essere danneggiato. Quando una creatura di taglia Piccola o superiore si avvicina entro 9 metri da esso senza prima pronunciare la parola d'ordine che specifichi quando lanci questo incantesimo, il segugio inizia ad abbaiare rumorosamente. Il segugio vede le creature invisibili e può vedere nel Piano Etereo. Ignora le illusioni.\nAll'inizio di ciascuno dei tuoi turni, il segugio tenta di mordere una creatura entro 1,5 metri da esso che sia ostile nei tuoi confronti. Il bonus di attacco del segugio è pari al tuo modificatore di caratteristica da incantatore + il tuo bonus di competenza. In caso di colpo, infligge 4d8 danni perforanti.","language":"it","ui_language":"it"},{"id":"mordenkainen-s-magnificent-mansion","name":"Mordenkainen's Magnificent Mansion","name_it":"Magnifica Magione di Mordenkainen","level":7,"level_it":"Livello 7","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"90 metri","components":"V, S, M (un portale in miniatura intagliato nell'avorio, un piccolo pezzo di marmo levigato e un piccolo cucchiaio d'argento, ciascun oggetto del valore di almeno 5 mo)","material":"un portale in miniatura intagliato nell'avorio, un piccolo pezzo di marmo levigato e un piccolo cucchiaio d'argento, ciascun oggetto del valore di almeno 5 mo","duration":"24 ore","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi un'abitazione extradimensionale entro gittata che dura per la durata dell'incantesimo. Scegli dove si trova il suo unico ingresso. L'ingresso luccica debolmente ed è largo 1,5 metri e alto 3 metri. Tu e qualsiasi creatura tu designi quando lanci l'incantesimo potete entrare nell'abitazione extradimensionale finché il portale rimane aperto. Puoi aprire o chiudere il portale se ti trovi entro 9 metri da esso. Quando è chiuso, il portale è invisibile.\nOltre il portale si trova un magnifico atrio con numerose camere oltre di esso. L'atmosfera è pulita, fresca e calda.\nPuoi creare qualsiasi pianta desideri, ma lo spazio non può superare 50 cubi, ciascuno di 3 metri per lato. Il luogo è arredato e decorato come preferisci. Contiene cibo a sufficienza per servire un banchetto di nove portate a un massimo di 100 persone. Uno stuolo di 100 servitori semitrasparenti assiste chiunque entri. Decidi l'aspetto visivo di questi servitori e il loro abbigliamento. Sono completamente obbedienti ai tuoi ordini. Ogni servitore può svolgere qualsiasi compito che un normale servitore umano potrebbe svolgere, ma non può attaccare né compiere alcuna azione che danneggerebbe direttamente un'altra creatura. I servitori possono quindi prendere oggetti, pulire, rammendare, piegare abiti, accendere fuochi, servire cibo, versare vino e così via. I servitori possono andare ovunque nella magione, ma non possono lasciarla. Gli arredi e gli altri oggetti creati da questo incantesimo si dissolvono in fumo se rimossi dalla magione. Quando l'incantesimo termina, tutte le creature o gli oggetti rimasti all'interno dello spazio extradimensionale vengono espulsi negli spazi liberi più vicini all'ingresso.","language":"it","ui_language":"it"},{"id":"mordenkainen-s-private-sanctum","name":"Mordenkainen's Private Sanctum","name_it":"Santuario Privato di Mordenkainen","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"10 minuti","range":"36 metri","components":"V, S, M (un sottile foglio di piombo, un pezzo di vetro opaco, un batuffolo di cotone o stoffa e crisolito in polvere)","material":"un sottile foglio di piombo, un pezzo di vetro opaco, un batuffolo di cotone o stoffa e crisolito in polvere","duration":"24 ore","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Rendi magicamente sicura un'area entro gittata. L'area è un cubo che può misurare da un minimo di 1,5 metri a un massimo di 30 metri per lato. L'incantesimo dura per la durata indicata o finché non usi un'azione per dissolverlo.\nQuando lanci l'incantesimo, decidi che tipo di sicurezza esso fornisce, scegliendo una o più delle seguenti proprietà:\n• Il suono non può attraversare la barriera ai margini dell'area protetta.\n• La barriera dell'area protetta appare scura e nebbiosa, impedendo la vista (inclusa la scurovisione) attraverso di essa.\n• I sensori creati dagli incantesimi di divinazione non possono apparire all'interno dell'area protetta né attraversare la barriera al suo perimetro.\n• Le creature nell'area non possono essere bersagliate da incantesimi di divinazione.\n• Nulla può teletrasportarsi dentro o fuori dall'area protetta.\n• I viaggi planari sono bloccati all'interno dell'area protetta.\nLanciare questo incantesimo nello stesso punto ogni giorno per un anno rende permanente questo effetto.\nAi Livelli Superiori. Se lanci questo incantesimo usando uno slot incantesimo di 5° livello o superiore, puoi aumentare le dimensioni del cubo di 30 metri per ogni livello dello slot oltre il 4°. Potresti quindi proteggere un cubo che può arrivare fino a 60 metri per lato usando uno slot incantesimo di 5° livello.","language":"it","ui_language":"it"},{"id":"mordenkainen-s-sword","name":"Mordenkainen's Sword","name_it":"Spada di Mordenkainen","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una spada di platino in miniatura con impugnatura e pomo di rame e zinco, del valore di 250 mo)","material":"una spada di platino in miniatura con impugnatura e pomo di rame e zinco, del valore di 250 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un piano di forza a forma di spada che fluttua entro gittata. Dura per la durata dell'incantesimo.\nQuando la spada appare, effettui un attacco da incantesimo in mischia contro un bersaglio a tua scelta entro 1,5 metri dalla spada. In caso di colpo, il bersaglio subisce 3d10 danni da forza. Finché l'incantesimo dura, puoi usare un'azione bonus a ogni tuo turno per muovere la spada fino a 6 metri verso un punto che riesci a vedere e ripetere questo attacco contro lo stesso bersaglio o uno diverso.","language":"it","ui_language":"it"},{"id":"move-earth","name":"Move Earth","name_it":"Muovere la Terra","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (una lama di ferro e un piccolo sacchetto contenente un miscuglio di terreni: argilla, terriccio e sabbia)","material":"una lama di ferro e un piccolo sacchetto contenente un miscuglio di terreni: argilla, terriccio e sabbia","duration":"Concentrazione, fino a 2 ore","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli un'area di terreno non più grande di 12 metri per lato entro gittata. Puoi rimodellare la terra, la sabbia o l'argilla nell'area come preferisci per la durata dell'incantesimo. Puoi innalzare o abbassare l'elevazione dell'area, creare o riempire una trincea, erigere o abbattere un muro, oppure formare un pilastro. L'entità di tali cambiamenti non può superare la metà della dimensione maggiore dell'area. Quindi, se influenzi un quadrato di 12 metri, puoi creare un pilastro alto fino a 6 metri, innalzare o abbassare l'elevazione del quadrato fino a 6 metri, scavare una trincea profonda fino a 6 metri, e così via. Il completamento di questi cambiamenti richiede 10 minuti.\nAlla fine di ogni periodo di 10 minuti che passi concentrandoti sull'incantesimo, puoi scegliere una nuova area di terreno da influenzare.\nPoiché la trasformazione del terreno avviene lentamente, le creature nell'area di solito non possono restare intrappolate né essere ferite dal movimento del suolo.\nQuesto incantesimo non può manipolare la pietra naturale o le costruzioni in pietra. Rocce e strutture si spostano per adattarsi al nuovo terreno. Se il modo in cui modelli il terreno renderebbe instabile una struttura, questa potrebbe crollare.\nAllo stesso modo, questo incantesimo non influisce direttamente sulla crescita delle piante. La terra spostata porta con sé qualsiasi pianta.","language":"it","ui_language":"it"},{"id":"nathair-s-mischief","name":"Nathair's Mischief","name_it":"Marachella di Nathair","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"S, M (un pezzo di crosta di una torta di mele)","material":"un pezzo di crosta di una torta di mele","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"Riempi un cubo di 6 metri di lato con un effetto magico. L'effetto casuale può essere ammaliato, accecato, incapacitato o terreno difficile.","language":"it","ui_language":"it"},{"id":"negative-energy-flood","name":"Negative Energy Flood","name_it":"Flusso di Energia Negativa","level":5,"level_it":"Livello 5","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, M (un osso rotto e un quadrato di seta nera)","material":"un osso rotto e un quadrato di seta nera","duration":"Istantanea","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scagli nastri di energia negativa contro una creatura che riesci a vedere entro gittata. A meno che il bersaglio non sia un non morto, deve effettuare un tiro salvezza su Costituzione, subendo 5d12 danni necrotici in caso di fallimento, o metà del danno in caso di successo. Un bersaglio ucciso da questo danno si rialza come uno zombie all'inizio del tuo turno successivo. Lo zombie insegue qualsiasi creatura più vicina che riesce a vedere. Se prendi di mira un non morto con questo incantesimo, il bersaglio non effettua un tiro salvezza. Tira invece 5d12. Il bersaglio guadagna la metà del totale come punti ferita temporanei.","language":"it","ui_language":"it"},{"id":"nondetection","name":"Nondetection","name_it":"Non Rilevabilità","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un pizzico di polvere di diamante del valore di 25 mo, cosparsa sul bersaglio, che l'incantesimo consuma)","material":"un pizzico di polvere di diamante del valore di 25 mo, cosparsa sul bersaglio, che l'incantesimo consuma","duration":"8 ore","classes":["Bard","Ranger","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, nascondi un bersaglio che tocchi dalla magia di divinazione. Il bersaglio può essere una creatura consenziente, un luogo o un oggetto non più grande di 3 metri in qualsiasi dimensione. Il bersaglio non può essere preso di mira da alcuna magia di divinazione né essere percepito attraverso sensori di divinazione magici.","language":"it","ui_language":"it"},{"id":"nystul-s-magic-aura","name":"Nystul's Magic Aura","name_it":"Aura Magica di Nystul","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un piccolo quadrato di seta)","material":"un piccolo quadrato di seta","duration":"24 ore","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Poni un'illusione su una creatura o un oggetto che tocchi, in modo che gli incantesimi di divinazione rivelino informazioni false su di esso. Il bersaglio può essere una creatura consenziente o un oggetto che non sia trasportato né indossato da un'altra creatura.\nQuando lanci l'incantesimo, scegli uno o entrambi i seguenti effetti. L'effetto dura per la durata dell'incantesimo. Se lanci questo incantesimo sulla stessa creatura o oggetto ogni giorno per 30 giorni, applicando lo stesso effetto ogni volta, l'illusione dura finché non viene dissolta.\nFalsa Aura. Cambi il modo in cui il bersaglio appare agli incantesimi e agli effetti magici, come individuare il magico, che rilevano le aure magiche. Puoi far apparire magico un oggetto non magico, far apparire non magico un oggetto magico, oppure cambiare l'aura magica dell'oggetto in modo che sembri appartenere a una specifica scuola di magia a tua scelta. Quando usi questo effetto su un oggetto, puoi rendere evidente la falsa magia a qualsiasi creatura che maneggi l'oggetto.\nMaschera. Cambi il modo in cui il bersaglio appare agli incantesimi e agli effetti magici che rilevano i tipi di creatura, come il Senso Divino di un paladino o l'innesco di un incantesimo simbolo. Scegli un tipo di creatura, e gli altri incantesimi ed effetti magici trattano il bersaglio come se fosse una creatura di quel tipo o di quell'allineamento.","language":"it","ui_language":"it"},{"id":"otiluke-s-freezing-sphere","name":"Otiluke's Freezing Sphere","name_it":"Sfera Congelante di Otiluke","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V, S, M (una piccola sfera di cristallo)","material":"una piccola sfera di cristallo","duration":"Istantanea","classes":["Wizard","Sorcerer"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Un gelido globo di energia fredda si proietta dalla punta delle tue dita verso un punto a tua scelta entro gittata, dove esplode in una sfera del raggio di 18 metri. Ogni creatura all'interno dell'area deve effettuare un tiro salvezza su Costituzione, subendo 10d6 danni da freddo in caso di fallimento, o metà del danno in caso di successo.\nSe il globo colpisce uno specchio d'acqua o un liquido composto principalmente da acqua (escluse le creature acquatiche), congela il liquido fino a una profondità di 15 centimetri su un'area di 9 metri per lato. Questo ghiaccio dura 1 minuto. Le creature che stavano nuotando sulla superficie dell'acqua ghiacciata restano intrappolate nel ghiaccio. Una creatura intrappolata può usare un'azione per effettuare una prova di Forza contro la CD di salvezza del tuo incantesimo per liberarsi.\nSe lo desideri, puoi astenerti dal lanciare il globo dopo aver completato l'incantesimo. Un piccolo globo, delle dimensioni di una pietra da fionda e freddo al tatto, appare nella tua mano. In qualsiasi momento, tu o una creatura a cui dai il globo potete lanciarlo (fino a una gittata di 12 metri) o scagliarlo con una fionda (fino alla gittata normale della fionda). Si frantuma all'impatto, con lo stesso effetto del lancio normale dell'incantesimo. Puoi anche posare il globo a terra senza frantumarlo. Dopo 1 minuto, se il globo non si è già frantumato, esplode.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, il danno aumenta di 1d6 per ogni livello dello slot superiore al 6°.","language":"it","ui_language":"it"},{"id":"otiluke-s-resilient-sphere","name":"Otiluke's Resilient Sphere","name_it":"Sfera Resiliente di Otiluke","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una porzione emisferica di cristallo trasparente e una corrispondente porzione emisferica di gomma arabica)","material":"una porzione emisferica di cristallo trasparente e una corrispondente porzione emisferica di gomma arabica","duration":"Concentrazione, fino a 1 minuto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una sfera di forza scintillante racchiude una creatura o un oggetto di taglia Grande o inferiore entro gittata. Una creatura non consenziente deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, la creatura resta racchiusa per la durata dell'incantesimo.\nNulla — né oggetti fisici, energia, né altri effetti di incantesimo — può attraversare la barriera, né in entrata né in uscita, sebbene una creatura all'interno della sfera possa respirare. La sfera è immune a ogni danno, e una creatura o un oggetto al suo interno non può essere danneggiato da attacchi o effetti provenienti dall'esterno, né una creatura all'interno della sfera può danneggiare qualcosa al di fuori di essa.\nLa sfera è priva di peso ed è appena abbastanza grande da contenere la creatura o l'oggetto al suo interno. Una creatura racchiusa può usare la propria azione per spingere contro le pareti della sfera e farla così rotolare fino alla metà della propria velocità. Allo stesso modo, il globo può essere sollevato e spostato da altre creature.\nUn incantesimo di disintegrazione lanciato sul globo lo distrugge senza danneggiare nulla al suo interno.","language":"it","ui_language":"it"},{"id":"otto-s-irresistible-dance","name":"Otto's Irresistible Dance","name_it":"Danza Irresistibile di Otto","level":6,"level_it":"Livello 6","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura che riesci a vedere entro gittata. Il bersaglio inizia a danzare comicamente sul posto: trascinando i piedi, battendoli a tempo e saltellando per la durata dell'incantesimo. Le creature che non possono essere ammaliate sono immuni a questo incantesimo.\nUna creatura che danza deve utilizzare tutto il proprio movimento per danzare senza lasciare il proprio spazio e ha svantaggio ai tiri salvezza su Destrezza e ai tiri per colpire. Finché il bersaglio è soggetto a questo incantesimo, le altre creature hanno vantaggio ai tiri per colpire contro di esso. Come azione, una creatura che danza effettua un tiro salvezza su Saggezza per riprendere il controllo di sé. In caso di successo, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"pass-without-trace","name":"Pass without Trace","name_it":"Passare Senza Lasciare Traccia","level":2,"level_it":"Livello 2","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (cenere di una foglia di vischio bruciata e un rametto di abete rosso)","material":"cenere di una foglia di vischio bruciata e un rametto di abete rosso","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un velo di ombre e silenzio si irradia da te, mascherando te e i tuoi compagni dal rilevamento. Per la durata, ogni creatura che scegli entro 9 metri da te (te compreso) ottiene un bonus di +10 alle prove di Destrezza (Furtività) e non può essere tracciata se non con mezzi magici. Una creatura che riceve questo bonus non lascia dietro di sé tracce o altri segni del proprio passaggio.","language":"it","ui_language":"it"},{"id":"passwall","name":"Passwall","name_it":"Passamuro","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un pizzico di semi di sesamo)","material":"un pizzico di semi di sesamo","duration":"1 ora","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un passaggio appare in un punto a tua scelta che riesci a vedere su una superficie di legno, intonaco o pietra (come una parete, un soffitto o un pavimento) entro gittata, e dura per la durata dell'incantesimo. Scegli le dimensioni dell'apertura: fino a 1,5 metri di larghezza, 2,4 metri di altezza e 6 metri di profondità. Il passaggio non causa alcuna instabilità nella struttura circostante.\nQuando l'apertura scompare, qualsiasi creatura o oggetto ancora presente nel passaggio creato dall'incantesimo viene espulso in sicurezza nello spazio libero più vicino alla superficie su cui hai lanciato l'incantesimo.","language":"it","ui_language":"it"},{"id":"phantasmal-force","name":"Phantasmal Force","name_it":"Forza Fantasmagorica","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un po' di lana)","material":"un po' di lana","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Crei un'illusione che si radica nella mente di una creatura che riesci a vedere entro gittata. Il bersaglio deve effettuare un tiro salvezza su Intelligenza. In caso di fallimento, crei un oggetto, una creatura o un altro fenomeno visibile fantasmagorico a tua scelta, non più grande di un cubo di 3 metri di lato, percepibile solo dal bersaglio per la durata dell'incantesimo. Questo incantesimo non ha alcun effetto su non morti o costrutti.\nIl fantasma include suoni, temperatura e altri stimoli, anch'essi percepibili solo dalla creatura.\nIl bersaglio può usare la propria azione per esaminare il fantasma con una prova di Intelligenza (Indagare) contro la CD di salvezza del tuo incantesimo. Se la prova ha successo, il bersaglio si rende conto che il fantasma è un'illusione, e l'incantesimo termina.\nFinché il bersaglio è soggetto all'incantesimo, tratta il fantasma come se fosse reale. Il bersaglio razionalizza qualsiasi esito illogico derivante dall'interazione con il fantasma. Per esempio, un bersaglio che tenta di attraversare a piedi un ponte fantasmagorico che scavalca un burrone cade non appena mette piede sul ponte. Se il bersaglio sopravvive alla caduta, continua comunque a credere che il ponte esista e trova qualche altra spiegazione per la propria caduta — è stato spinto, è scivolato, oppure una raffica di vento potrebbe averlo fatto cadere.\nUn bersaglio soggetto all'incantesimo è così convinto della realtà del fantasma da poter persino subire danni dall'illusione. Un fantasma creato per apparire come una creatura può attaccare il bersaglio. Allo stesso modo, un fantasma creato per apparire come fuoco, una pozza d'acido o lava può bruciare il bersaglio. Ogni round, nel tuo turno, il fantasma può infliggere 1d6 danni psichici al bersaglio se questo si trova nell'area del fantasma o entro 1,5 metri da esso, a patto che l'illusione rappresenti una creatura o un pericolo che potrebbe logicamente infliggere danno, ad esempio attaccando. Il bersaglio percepisce il danno come del tipo appropriato all'illusione.","language":"it","ui_language":"it"},{"id":"phantasmal-killer","name":"Phantasmal Killer","name_it":"Uccisore Fantasmagorico","level":4,"level_it":"Livello 4","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Wizard","Bard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Attingi agli incubi di una creatura che riesci a vedere entro gittata e crei una manifestazione illusoria delle sue paure più profonde, visibile solo a quella creatura. Il bersaglio deve effettuare un tiro salvezza su Saggezza. In caso di fallimento, il bersaglio diventa spaventato per la durata dell'incantesimo. Alla fine di ciascuno dei propri turni, prima che l'incantesimo termini, il bersaglio deve superare un tiro salvezza su Saggezza o subire 4d10 danni psichici. In caso di successo, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 5° livello o superiore, il danno aumenta di 1d10 per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"phantom-steed","name":"Phantom Steed","name_it":"Destriero Fantasma","level":3,"level_it":"Livello 3","school":"illusion","school_it":"Illusione","ritual":true,"casting_time":"1 minuto","range":"9 metri","components":"V, S","material":"","duration":"1 ora","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura quasi reale, dall'aspetto equino, di taglia Grande appare sul terreno in uno spazio libero a tua scelta entro gittata. Decidi tu l'aspetto della creatura, ma essa è equipaggiata con sella, morso e briglie. Qualsiasi equipaggiamento creato dall'incantesimo svanisce in uno sbuffo di fumo se viene portato a più di 3 metri dal destriero.\nPer la durata, tu o una creatura che scegli potete cavalcare il destriero. La creatura utilizza le statistiche di un cavallo da sella, tranne per il fatto che ha una velocità di 30 metri e può percorrere 15 chilometri in un'ora, oppure 19,5 chilometri a passo sostenuto. Quando l'incantesimo termina, il destriero svanisce gradualmente, concedendo al cavaliere 1 minuto per smontare. L'incantesimo termina se usi un'azione per dissolverlo o se il destriero subisce un qualsiasi danno.","language":"it","ui_language":"it"},{"id":"planar-ally","name":"Planar Ally","name_it":"Alleato Planare","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"10 minuti","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Supplichi un'entità ultraterrena per ottenere aiuto. L'essere deve esserti noto: una divinità, un primordiale, un principe demoniaco o un altro essere di potere cosmico. Quell'entità invia un celestiale, un elementale o un infernale a essa leale per aiutarti, facendo apparire la creatura in uno spazio libero entro gittata. Se conosci il nome specifico di una creatura, puoi pronunciare quel nome quando lanci questo incantesimo per richiedere quella creatura, anche se potresti comunque ottenerne una diversa (a scelta del DM).\nQuando la creatura appare, non è soggetta ad alcun obbligo di comportarsi in un modo particolare. Puoi chiedere alla creatura di svolgere un servizio in cambio di un pagamento, ma essa non è tenuta a farlo. Il compito richiesto può variare da semplice (portaci in volo oltre il burrone, o aiutaci a combattere una battaglia) a complesso (spia i nostri nemici, o proteggici durante la nostra incursione nel dungeon). Devi essere in grado di comunicare con la creatura per negoziare i suoi servigi.\nIl pagamento può assumere varie forme. Un celestiale potrebbe richiedere una cospicua donazione d'oro o di oggetti magici a un tempio alleato, mentre un infernale potrebbe pretendere un sacrificio vivente o un dono di tesori. Alcune creature potrebbero scambiare il proprio servizio con una missione da te intrapresa.\nCome regola generale, un compito misurabile in minuti richiede un pagamento del valore di 100 mo per minuto. Un compito misurabile in ore richiede 1.000 mo per ora. E un compito misurabile in giorni (fino a 10 giorni) richiede 10.000 mo per giorno. Il DM può adeguare questi pagamenti in base alle circostanze in cui lanci l'incantesimo. Se il compito è in linea con l'etica della creatura, il pagamento potrebbe essere dimezzato o persino rinunciato. I compiti non pericolosi richiedono in genere solo la metà del pagamento suggerito, mentre i compiti particolarmente rischiosi potrebbero richiedere un dono maggiore. Le creature raramente accettano compiti che sembrano suicidi.\nDopo che la creatura ha portato a termine il compito, o quando scade la durata concordata del servizio, la creatura ritorna al proprio piano d'origine dopo essersi presentata a te per riferire, se ciò è appropriato al compito e se possibile.\nSe non riesci a concordare un prezzo per il servizio della creatura, questa ritorna immediatamente al proprio piano d'origine.\nUna creatura arruolata per unirsi al tuo gruppo ne diventa un membro a tutti gli effetti, ricevendo una parte completa dei punti esperienza assegnati.","language":"it","ui_language":"it"},{"id":"planar-binding","name":"Planar Binding","name_it":"Vincolo Planare","level":5,"level_it":"Livello 5","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 ora","range":"18 metri","components":"V, S, M (una gemma del valore di almeno 1.000 mo, che l'incantesimo consuma)","material":"una gemma del valore di almeno 1.000 mo, che l'incantesimo consuma","duration":"24 ore","classes":["Bard","Cleric","Druid","Wizard","Warlock"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Con questo incantesimo, tenti di vincolare al tuo servizio un celestiale, un elementale, un fatato o un infernale. La creatura deve trovarsi entro gittata per l'intera durata del lancio dell'incantesimo. (Solitamente, la creatura viene prima evocata al centro di un cerchio magico invertito, per tenerla intrappolata mentre questo incantesimo viene lanciato.) Al termine del lancio, il bersaglio deve effettuare un tiro salvezza su Carisma. In caso di fallimento, viene vincolato al tuo servizio per la durata dell'incantesimo. Se la creatura era stata evocata o creata da un altro incantesimo, la durata di quell'incantesimo viene estesa per corrispondere alla durata di questo incantesimo.\nUna creatura vincolata deve seguire le tue istruzioni al meglio delle proprie capacità. Puoi ordinare alla creatura di accompagnarti in un'avventura, di sorvegliare un luogo o di recapitare un messaggio. La creatura obbedisce alla lettera delle tue istruzioni, ma se è ostile nei tuoi confronti, si sforza di stravolgere le tue parole per raggiungere i propri obiettivi. Se la creatura porta a termine completamente le tue istruzioni prima che l'incantesimo termini, viaggia fino a te per riferirtelo, se ti trovi sullo stesso piano d'esistenza. Se ti trovi su un piano d'esistenza diverso, ritorna nel luogo in cui l'hai vincolata e vi rimane finché l'incantesimo non termina.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di livello superiore, la durata aumenta a 10 giorni con uno slot di 6° livello, a 30 giorni con uno slot di 7° livello, a 180 giorni con uno slot di 8° livello, e a un anno e un giorno con uno slot incantesimo di 9° livello.","language":"it","ui_language":"it"},{"id":"plane-shift","name":"Plane Shift","name_it":"Spostamento Planare","level":7,"level_it":"Livello 7","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (una verga di metallo biforcuta del valore di almeno 250 mo, sintonizzata su un particolare piano d'esistenza)","material":"una verga di metallo biforcuta del valore di almeno 250 mo, sintonizzata su un particolare piano d'esistenza","duration":"Istantanea","classes":["Cleric","Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tu e fino a otto creature consenzienti che si uniscono per mano in cerchio venite trasportati su un piano d'esistenza diverso. Puoi specificare una destinazione in termini generali, come la Città di Ottone sul Piano Elementale del Fuoco o il palazzo di Dispater nel secondo livello dei Nove Inferi, e apparirai in prossimità di quella destinazione. Se stai cercando di raggiungere la Città di Ottone, per esempio, potresti arrivare nella sua Via dell'Acciaio, davanti al suo Cancello delle Ceneri, oppure osservando la città dall'altra parte del Mare di Fuoco, a discrezione del DM.\nIn alternativa, se conosci la sequenza di sigilli di un cerchio di teletrasporto su un altro piano d'esistenza, questo incantesimo può condurti a quel cerchio. Se il cerchio di teletrasporto è troppo piccolo per contenere tutte le creature che hai trasportato, esse appaiono negli spazi liberi più vicini accanto al cerchio.\nPuoi usare questo incantesimo per bandire una creatura non consenziente su un altro piano. Scegli una creatura entro la tua portata ed effettua un attacco con incantesimo in mischia contro di essa. Se colpisci, la creatura deve effettuare un tiro salvezza su Carisma. Se la creatura fallisce questo tiro salvezza, viene trasportata in un luogo casuale sul piano d'esistenza che specifichi. Una creatura trasportata in questo modo deve trovare da sola la via del ritorno al tuo piano d'esistenza attuale.","language":"it","ui_language":"it"},{"id":"plant-growth","name":"Plant Growth","name_it":"Crescita delle Piante","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione o 8 ore","range":"45 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo incanala vitalità nelle piante all'interno di un'area specifica. Ci sono due possibili usi per l'incantesimo, che concede benefici immediati oppure a lungo termine.\nSe lanci questo incantesimo impiegando 1 azione, scegli un punto entro gittata. Tutte le piante normali in un raggio di 30 metri centrato su quel punto diventano fitte e rigogliose. Una creatura che si muove attraverso l'area deve spendere 1,2 metri di movimento per ogni 30 centimetri percorsi.\nPuoi escludere una o più aree di qualsiasi dimensione all'interno dell'area dell'incantesimo dall'essere influenzate.\nSe lanci questo incantesimo nell'arco di 8 ore, arricchisci il terreno. Tutte le piante in un raggio di 0,75 chilometri centrato su un punto entro gittata diventano arricchite per 1 anno. Le piante producono il doppio della quantità normale di cibo quando vengono raccolte.","language":"it","ui_language":"it"},{"id":"poison-spray","name":"Poison Spray","name_it":"Spruzzo Velenoso","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"3 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Allunghi la mano verso una creatura che riesci a vedere entro gittata e proietti dal palmo uno sbuffo di gas nocivo. La creatura deve superare un tiro salvezza su Costituzione o subire 1d12 danni da veleno.\nIl danno di questo incantesimo aumenta di 1d12 quando raggiungi il 5° livello (2d12), l'11° livello (3d12) e il 17° livello (4d12).","language":"it","ui_language":"it"},{"id":"polymorph","name":"Polymorph","name_it":"Metamorfosi","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un bozzolo di bruco)","material":"un bozzolo di bruco","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Druid","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo trasforma una creatura che riesci a vedere entro gittata in una nuova forma. Una creatura non consenziente deve effettuare un tiro salvezza su Saggezza per evitare l'effetto. L'incantesimo non ha alcun effetto su un mutaforma o su una creatura con 0 punti ferita.\nLa trasformazione dura per la durata dell'incantesimo, oppure finché il bersaglio non scende a 0 punti ferita o muore. La nuova forma può essere qualsiasi bestia il cui grado di sfida sia pari o inferiore a quello del bersaglio (o al livello del bersaglio, se non possiede un grado di sfida). Le statistiche di gioco del bersaglio, inclusi i punteggi delle caratteristiche mentali, vengono sostituite dalle statistiche della bestia scelta. Il bersaglio conserva il proprio allineamento e la propria personalità.\nIl bersaglio assume i punti ferita della sua nuova forma. Quando torna alla sua forma normale, la creatura recupera il numero di punti ferita che aveva prima di trasformarsi. Se torna alla forma normale a causa della discesa a 0 punti ferita, gli eventuali danni in eccesso si ripercuotono sulla sua forma normale. Finché i danni in eccesso non riducono a 0 i punti ferita della forma normale della creatura, questa non viene resa priva di sensi.\nLa creatura è limitata nelle azioni che può compiere dalla natura della sua nuova forma, e non può parlare, lanciare incantesimi o compiere qualsiasi altra azione che richieda mani o parola.\nL'equipaggiamento del bersaglio si fonde nella nuova forma. La creatura non può attivare, usare, impugnare o altrimenti trarre beneficio da alcuno dei propri equipaggiamenti.","language":"it","ui_language":"it"},{"id":"power-word-heal","name":"Power Word Heal","name_it":"Parola del Potere: Guarigione","level":9,"level_it":"Livello 9","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Cleric"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore","description":"Un'ondata di energia curativa investe una creatura che tocchi. Il bersaglio recupera tutti i suoi punti ferita. Se la creatura è ammaliata, spaventata, paralizzata o stordita, la condizione termina. Se la creatura è prona, può usare la propria reazione per rialzarsi. Questo incantesimo non ha alcun effetto su non morti o costrutti.","language":"it","ui_language":"it"},{"id":"power-word-kill","name":"Power Word Kill","name_it":"Parola del Potere: Morte","level":9,"level_it":"Livello 9","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Pronunci una parola di potere in grado di costringere una creatura che riesci a vedere entro gittata a morire istantaneamente. Se la creatura che scegli ha 100 punti ferita o meno, muore. Altrimenti, l'incantesimo non ha alcun effetto.","language":"it","ui_language":"it"},{"id":"power-word-pain","name":"Power Word Pain","name_it":"Parola del Potere: Dolore","level":7,"level_it":"Livello 7","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Pronunci una parola di potere che scatena ondate di dolore intenso contro una creatura che riesci a vedere entro gittata. Se il bersaglio ha 100 punti ferita o meno, è soggetto a un dolore debilitante. Altrimenti, l'incantesimo non ha alcun effetto su di esso. Un bersaglio è inoltre non influenzato se è immune all'essere ammaliato.\nFinché il bersaglio è soggetto al dolore debilitante, qualsiasi velocità possieda non può superare 3 metri. Il bersaglio ha inoltre svantaggio ai tiri per colpire, alle prove di caratteristica e ai tiri salvezza, eccetto i tiri salvezza su Costituzione. Infine, se il bersaglio tenta di lanciare un incantesimo, deve prima superare un tiro salvezza su Costituzione, altrimenti il lancio fallisce e l'incantesimo viene sprecato.\nUn bersaglio che soffre questo dolore può effettuare un tiro salvezza su Costituzione al termine di ciascuno dei propri turni. In caso di successo, il dolore termina.","language":"it","ui_language":"it"},{"id":"power-word-stun","name":"Power Word Stun","name_it":"Parola del Potere: Stordimento","level":8,"level_it":"Livello 8","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Pronunci una parola di potere in grado di sopraffare la mente di una creatura che riesci a vedere entro gittata, lasciandola sbigottita. Se il bersaglio ha 150 punti ferita o meno, viene stordito. Altrimenti, l'incantesimo non ha alcun effetto.\nIl bersaglio stordito deve effettuare un tiro salvezza su Costituzione al termine di ciascuno dei propri turni. In caso di successo, questo effetto di stordimento termina.","language":"it","ui_language":"it"},{"id":"prayer-of-healing","name":"Prayer of Healing","name_it":"Preghiera di Guarigione","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"10 minuti","range":"9 metri","components":"V","material":"","duration":"Istantanea","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Fino a sei creature a tua scelta che riesci a vedere entro gittata recuperano ciascuna punti ferita pari a 2d8 + il tuo modificatore di caratteristica da incantatore. Questo incantesimo non ha alcun effetto su non morti o costrutti.\nAi Livelli Superiori. Se lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, la guarigione aumenta di 1d8 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"prestidigitation","name":"Prestidigitation","name_it":"Prestidigitazione","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"3 metri","components":"V, S","material":"","duration":"Fino a 1 ora","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo è un piccolo trucco magico che gli incantatori novizi usano per esercitarsi. Crei uno dei seguenti effetti magici entro gittata:\n• Crei un effetto sensoriale istantaneo e innocuo, come una pioggia di scintille, uno sbuffo di vento, deboli note musicali o uno strano odore.\n• Accendi o spegni istantaneamente una candela, una torcia o un piccolo falò.\n• Pulisci o sporchi istantaneamente un oggetto non più grande di un cubo di 30 centimetri di lato.\n• Raffreddi, riscaldi o insaporisci fino a un cubo di 30 centimetri di lato di materiale non vivente per 1 ora.\n• Fai apparire un colore, un piccolo segno o un simbolo su un oggetto o una superficie per 1 ora.\n• Crei un piccolo ninnolo non magico o un’immagine illusoria che può stare nel palmo della tua mano e che dura fino alla fine del tuo turno successivo.\nSe lanci questo incantesimo più volte, puoi avere attivi fino a tre dei suoi effetti non istantanei contemporaneamente, e puoi dissolvere uno di questi effetti come azione.","language":"it","ui_language":"it"},{"id":"primal-savagery","name":"Primal Savagery","name_it":"Ferocia Primordiale","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"S","material":"","duration":"Istantanea","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Incanali la magia primordiale per affilare i tuoi denti o le tue unghie, pronto a sferrare un attacco corrosivo. Effettua un attacco con incantesimo in mischia contro una creatura entro 1,5 metri da te. Se colpisci, il bersaglio subisce 1d10 danni da acido. Dopo aver effettuato l’attacco, i tuoi denti o le tue unghie tornano normali.\nI danni di questo incantesimo aumentano di 1d10 quando raggiungi il 5° livello (2d10), l’11° livello (3d10) e il 17° livello (4d10).","language":"it","ui_language":"it"},{"id":"primordial-ward","name":"Primordial Ward","name_it":"Guardia Primordiale","level":6,"level_it":"Livello 6","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Hai resistenza ai danni da acido, freddo, fuoco, fulmine e tuono per la durata dell’incantesimo.\nQuando subisci danni di uno di questi tipi, puoi usare la tua reazione per ottenere l’immunità a quel tipo di danno, inclusi i danni che hanno innescato la reazione. Se lo fai, le resistenze terminano e hai l’immunità fino al termine del tuo turno successivo, momento in cui l’incantesimo termina.","language":"it","ui_language":"it"},{"id":"prismatic-spray","name":"Prismatic Spray","name_it":"Spruzzo Prismatico","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 18 metri)","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard","Bard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Otto raggi di luce multicolore guizzano dalla tua mano. Ogni raggio ha un colore diverso e possiede un potere e uno scopo differenti. Ogni creatura in un cono di 18 metri deve effettuare un tiro salvezza su Destrezza. Per ogni bersaglio, tira un d8 per determinare quale raggio colorato lo colpisce.\n1. Rosso. Il bersaglio subisce 10d6 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni in caso di successo.\n2. Arancione. Il bersaglio subisce 10d6 danni da acido se fallisce il tiro salvezza, o la metà dei danni in caso di successo.\n3. Giallo. Il bersaglio subisce 10d6 danni da fulmine se fallisce il tiro salvezza, o la metà dei danni in caso di successo.\n4. Verde. Il bersaglio subisce 10d6 danni da veleno se fallisce il tiro salvezza, o la metà dei danni in caso di successo.\n5. Blu. Il bersaglio subisce 10d6 danni da freddo se fallisce il tiro salvezza, o la metà dei danni in caso di successo.\n6. Indaco. Se fallisce il tiro salvezza, il bersaglio è trattenuto. Deve quindi effettuare un tiro salvezza su Costituzione al termine di ciascuno dei propri turni. Se supera con successo il tiro salvezza per tre volte, l’incantesimo termina. Se fallisce il tiro salvezza per tre volte, si trasforma permanentemente in pietra ed è soggetto alla condizione pietrificato. I successi e i fallimenti non devono essere consecutivi; tieni traccia di entrambi finché il bersaglio non ne colleziona tre dello stesso tipo.\n7. Violetto. Se fallisce il tiro salvezza, il bersaglio è accecato. Deve quindi effettuare un tiro salvezza su Saggezza all’inizio del tuo turno successivo. Un tiro salvezza riuscito pone fine alla cecità. Se fallisce quel tiro salvezza, la creatura viene trasportata in un altro piano di esistenza a scelta del DM e non è più accecata. (Tipicamente, una creatura che si trova su un piano diverso dal proprio piano d’origine viene rimandata a casa, mentre le altre creature vengono di norma scaraventate nel Piano Astrale o nel Piano Etereo.)\n8. Speciale. Il bersaglio è colpito da due raggi. Tira di nuovo due volte, ritirando ogni 8 ottenuto.","language":"it","ui_language":"it"},{"id":"prismatic-wall","name":"Prismatic Wall","name_it":"Muro Prismatico","level":9,"level_it":"Livello 9","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"10 minuti","classes":["Wizard","Bard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Un piano di luce scintillante e multicolore forma un muro verticale opaco — lungo fino a 27 metri, alto 9 metri e spesso 2,5 centimetri — centrato su un punto che riesci a vedere entro gittata. In alternativa, puoi dare al muro la forma di una sfera con un diametro massimo di 9 metri, centrata su un punto a tua scelta entro gittata. Il muro rimane in posizione per la durata. Se posizioni il muro in modo che attraversi lo spazio occupato da una creatura, l’incantesimo fallisce e la tua azione e lo slot incantesimo vengono sprecati.\nIl muro emana luce intensa in un raggio di 30 metri e luce fioca per ulteriori 30 metri. Tu e le creature che designi nel momento in cui lanci l’incantesimo potete attraversarlo e rimanere nelle sue vicinanze senza subire danni. Se un’altra creatura in grado di vedere il muro si sposta entro 6 metri da esso o inizia lì il proprio turno, quella creatura deve superare un tiro salvezza su Costituzione o essere accecata per 1 minuto.\nIl muro è composto da sette strati, ciascuno di un colore diverso. Quando una creatura tenta di infilare la mano nel muro o di attraversarlo, lo fa uno strato alla volta, attraverso tutti gli strati del muro. Mentre attraversa o infila la mano in ciascuno strato, la creatura deve effettuare un tiro salvezza su Destrezza o essere soggetta agli effetti di quello strato, come descritto di seguito.\nIl muro può essere distrutto, anch’esso uno strato alla volta, in ordine dal rosso al violetto, tramite mezzi specifici per ciascuno strato. Una volta distrutto, uno strato rimane tale per la durata dell’incantesimo. Campo antimagia non ha alcun effetto sul muro e dissolvi magie può influenzare solo lo strato violetto.\n1. Rosso. La creatura subisce 10d6 danni da fuoco se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Finché questo strato è presente, gli attacchi a distanza non magici non possono attraversare il muro. Lo strato può essere distrutto infliggendogli almeno 25 danni da freddo.\n2. Arancione. La creatura subisce 10d6 danni da acido se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Finché questo strato è presente, gli attacchi a distanza magici non possono attraversare il muro. Lo strato viene distrutto da un forte vento.\n3. Giallo. La creatura subisce 10d6 danni da fulmine se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Questo strato può essere distrutto infliggendogli almeno 60 danni da forza.\n4. Verde. La creatura subisce 10d6 danni da veleno se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Un incantesimo passamuro, o un altro incantesimo di livello pari o superiore in grado di aprire un varco in una superficie solida, distrugge questo strato.\n5. Blu. La creatura subisce 10d6 danni da freddo se fallisce il tiro salvezza, o la metà dei danni in caso di successo. Questo strato può essere distrutto infliggendogli almeno 25 danni da fuoco.\n6. Indaco. Se fallisce il tiro salvezza, la creatura è trattenuta. Deve quindi effettuare un tiro salvezza su Costituzione al termine di ciascuno dei propri turni. Se supera con successo il tiro salvezza per tre volte, l’incantesimo termina. Se fallisce il tiro salvezza per tre volte, si trasforma permanentemente in pietra ed è soggetta alla condizione pietrificato. I successi e i fallimenti non devono essere consecutivi; tieni traccia di entrambi finché la creatura non ne colleziona tre dello stesso tipo.\nFinché questo strato è presente, non è possibile lanciare incantesimi attraverso il muro. Lo strato viene distrutto dalla luce intensa emanata da un incantesimo luce del giorno o da un incantesimo simile di livello pari o superiore.\n7. Violetto. Se fallisce il tiro salvezza, la creatura è accecata. Deve quindi effettuare un tiro salvezza su Saggezza all’inizio del tuo turno successivo. Un tiro salvezza riuscito pone fine alla cecità. Se fallisce quel tiro salvezza, la creatura viene trasportata in un altro piano a scelta del DM e non è più accecata. (Tipicamente, una creatura che si trova su un piano diverso dal proprio piano d’origine viene rimandata a casa, mentre le altre creature vengono di norma scaraventate nel Piano Astrale o nel Piano Etereo.) Questo strato viene distrutto da un incantesimo dissolvi magie o da un incantesimo simile di livello pari o superiore in grado di porre fine a incantesimi ed effetti magici.","language":"it","ui_language":"it"},{"id":"produce-flame","name":"Produce Flame","name_it":"Produrre Fiamma","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"10 minuti","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una fiamma tremolante appare nella tua mano. La fiamma vi rimane per la durata e non danneggia né te né il tuo equipaggiamento. La fiamma emana luce intensa in un raggio di 3 metri e luce fioca per ulteriori 3 metri. L’incantesimo termina se lo dissolvi con un’azione o se lo lanci di nuovo.\nPuoi anche attaccare con la fiamma, sebbene farlo termini l’incantesimo. Quando lanci questo incantesimo, o come azione in un turno successivo, puoi scagliare la fiamma contro una creatura entro 9 metri da te. Effettua un attacco con incantesimo a distanza. Se colpisci, il bersaglio subisce 1d8 danni da fuoco.\nI danni di questo incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l’11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"programmed-illusion","name":"Programmed Illusion","name_it":"Illusione Programmata","level":6,"level_it":"Livello 6","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un po’ di lana e polvere di giada del valore di almeno 25 mo)","material":"un po’ di lana e polvere di giada del valore di almeno 25 mo","duration":"Finché non viene dissolto","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei l’illusione di un oggetto, di una creatura o di qualche altro fenomeno visibile entro gittata, che si attiva quando si verifica una condizione specifica. Fino ad allora, l’illusione è impercettibile. Non deve essere più grande di un cubo di 9 metri, e decidi al momento del lancio dell’incantesimo come si comporta l’illusione e quali suoni produce. Questa rappresentazione programmata può durare fino a 5 minuti.\nQuando si verifica la condizione che hai specificato, l’illusione prende vita e si manifesta nel modo che hai descritto. Una volta terminata la rappresentazione, l’illusione scompare e rimane dormiente per 10 minuti. Trascorso questo tempo, l’illusione può essere attivata di nuovo.\nLa condizione scatenante può essere generica o dettagliata quanto desideri, purché si basi su condizioni visive o uditive che si verificano entro 9 metri dall’area. Per esempio, potresti creare un’illusione di te stesso che appare per mettere in guardia chiunque tenti di aprire una porta trappolata, oppure potresti impostare l’illusione affinché si attivi solo quando una creatura pronuncia la parola o la frase corretta.\nL’interazione fisica con l’immagine rivela che si tratta di un’illusione, perché le cose possono attraversarla. Una creatura che usa la sua azione per esaminare l’immagine può determinare che si tratta di un’illusione con una prova di Intelligenza (Indagare) riuscita contro la CD di salvezza del tuo incantesimo. Se una creatura scopre l’illusione per quello che è, la creatura può vedere attraverso l’immagine, e ogni suono che produce risulta ovattato per la creatura.","language":"it","ui_language":"it"},{"id":"project-image","name":"Project Image","name_it":"Proiettare Immagine","level":7,"level_it":"Livello 7","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"750 chilometri","components":"V, S, M (una piccola replica di te stesso realizzata con materiali del valore di almeno 5 mo)","material":"una piccola replica di te stesso realizzata con materiali del valore di almeno 5 mo","duration":"Concentrazione, fino a 1 giorno","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una copia illusoria di te stesso che dura per la durata dell’incantesimo. La copia può apparire in qualsiasi luogo entro gittata che tu abbia già visto in precedenza, indipendentemente dagli ostacoli frapposti. L’illusione ha il tuo aspetto e la tua voce, ma è intangibile. Se l’illusione subisce danni, scompare e l’incantesimo termina.\nPuoi usare la tua azione per muovere questa illusione fino al doppio della tua velocità, e farle gesticolare, parlare e comportarsi nel modo che scegli. Essa imita perfettamente le tue movenze.\nPuoi vedere attraverso i suoi occhi e sentire attraverso le sue orecchie come se ti trovassi dove si trova lei. A ogni tuo turno, come azione bonus, puoi passare dall’uso dei suoi sensi all’uso dei tuoi, o viceversa. Mentre usi i suoi sensi, sei accecato e assordato rispetto al tuo ambiente circostante.\nL’interazione fisica con l’immagine rivela che si tratta di un’illusione, perché le cose possono attraversarla. Una creatura che usa la sua azione per esaminare l’immagine può determinare che si tratta di un’illusione con una prova di Intelligenza (Indagare) riuscita contro la CD di salvezza del tuo incantesimo. Se una creatura scopre l’illusione per quello che è, la creatura può vedere attraverso l’immagine, e ogni suono che produce risulta ovattato per la creatura.","language":"it","ui_language":"it"},{"id":"protection-from-energy","name":"Protection from Energy","name_it":"Protezione dall’Energia","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Cleric","Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, la creatura consenziente che tocchi ha resistenza a un tipo di danno a tua scelta: acido, freddo, fuoco, fulmine o tuono.","language":"it","ui_language":"it"},{"id":"protection-from-evil-and-good","name":"Protection from Evil and Good","name_it":"Protezione dal Male e dal Bene","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (acqua santa o polvere d’argento e ferro, che l’incantesimo consuma)","material":"acqua santa o polvere d’argento e ferro, che l’incantesimo consuma","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric","Paladin","Warlock","Wizard","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Finché l’incantesimo non termina, una creatura consenziente che tocchi è protetta contro certi tipi di creature: aberrazioni, celestiali, elementali, fatati, immondi e non morti.\nLa protezione conferisce diversi benefici. Le creature di quei tipi hanno svantaggio ai tiri per colpire contro il bersaglio. Il bersaglio inoltre non può essere ammaliato, spaventato o posseduto da esse. Se il bersaglio è già ammaliato, spaventato o posseduto da una di queste creature, il bersaglio ha vantaggio a ogni nuovo tiro salvezza contro l’effetto pertinente.","language":"it","ui_language":"it"},{"id":"protection-from-poison","name":"Protection from Poison","name_it":"Protezione dal Veleno","level":2,"level_it":"Livello 2","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"1 ora","classes":["Cleric","Druid","Paladin","Ranger"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura. Se è avvelenata, neutralizzi il veleno. Se il bersaglio è affetto da più di un veleno, neutralizzi un veleno che sai essere presente, oppure ne neutralizzi uno a caso.\nPer la durata, il bersaglio ha vantaggio ai tiri salvezza contro l’essere avvelenato, e ha resistenza ai danni da veleno.","language":"it","ui_language":"it"},{"id":"psychic-scream","name":"Psychic Scream","name_it":"Urlo Psichico","level":9,"level_it":"Livello 9","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"S","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scateni il potere della tua mente per colpire l’intelletto di un massimo di dieci creature a tua scelta che riesci a vedere entro gittata. Le creature con un punteggio di Intelligenza pari o inferiore a 2 non sono interessate.\nOgni bersaglio deve effettuare un tiro salvezza su Intelligenza. Se fallisce il tiro salvezza, il bersaglio subisce 14d6 danni psichici ed è stordito. Se supera il tiro salvezza, il bersaglio subisce metà dei danni e non è stordito. Se un bersaglio viene ucciso da questo danno, la sua testa esplode, ammesso che ne abbia una.\nUn bersaglio stordito può effettuare un tiro salvezza su Intelligenza al termine di ciascuno dei propri turni. In caso di successo, questo effetto di stordimento termina.","language":"it","ui_language":"it"},{"id":"purify-food-and-drink","name":"Purify Food and Drink","name_it":"Purificare Cibo e Bevande","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":true,"casting_time":"1 azione","range":"3 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Druid","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tutto il cibo e le bevande non magici in una sfera con raggio di 1,5 metri centrata su un punto a tua scelta entro gittata vengono purificati e resi privi di veleno e malattie.","language":"it","ui_language":"it"},{"id":"pyrotechnics","name":"Pyrotechnics","name_it":"Pirotecnica","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un’area di fiamme non magiche che riesci a vedere e che rientra in un cubo di 1,5 metri entro gittata. Puoi estinguere il fuoco in quell’area, e così facendo crei fuochi d’artificio oppure fumo.\nFuochi d’artificio. Il bersaglio esplode con un’abbagliante esibizione di colori. Ogni creatura entro 3 metri dal bersaglio deve superare un tiro salvezza su Costituzione o essere accecata fino al termine del tuo turno successivo.\nFumo. Un denso fumo nero si diffonde dal bersaglio in un raggio di 6 metri, aggirando gli angoli. L’area del fumo è fortemente offuscata. Il fumo persiste per 1 minuto o finché un forte vento non lo disperde.","language":"it","ui_language":"it"},{"id":"raise-dead","name":"Raise Dead","name_it":"Resurrezione","level":5,"level_it":"Livello 5","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (un diamante del valore di almeno 500 mo, che l’incantesimo consuma)","material":"un diamante del valore di almeno 500 mo, che l’incantesimo consuma","duration":"Istantanea","classes":["Bard","Cleric","Paladin"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Riporti in vita una creatura morta che tocchi, a condizione che sia morta da non più di 10 giorni. Se l’anima della creatura è sia disposta sia libera di ricongiungersi al corpo, la creatura ritorna in vita con 1 punto ferita.\nQuesto incantesimo neutralizza inoltre eventuali veleni e cura le malattie non magiche che affliggevano la creatura al momento della morte. Questo incantesimo non rimuove, tuttavia, malattie magiche, maledizioni o effetti simili; se questi non vengono rimossi prima di lanciare l’incantesimo, hanno effetto quando la creatura ritorna in vita. L’incantesimo non può riportare in vita una creatura non morta.\nQuesto incantesimo richiude tutte le ferite mortali, ma non ripristina le parti del corpo mancanti. Se alla creatura mancano parti del corpo o organi essenziali per la sua sopravvivenza — come la testa, per esempio — l’incantesimo fallisce automaticamente.\nTornare dalla morte è una prova durissima. Il bersaglio subisce una penalità di -4 a tutti i tiri per colpire, ai tiri salvezza e alle prove di caratteristica. Ogni volta che il bersaglio completa un riposo lungo, la penalità si riduce di 1 finché non scompare.","language":"it","ui_language":"it"},{"id":"rary-s-telepathic-bond","name":"Rary's Telepathic Bond","name_it":"Legame Telepatico di Rary","level":5,"level_it":"Livello 5","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (frammenti di guscio d’uovo provenienti da due tipi di creature diverse)","material":"frammenti di guscio d’uovo provenienti da due tipi di creature diverse","duration":"1 ora","classes":["Wizard","Bard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Forgi un legame telepatico tra un massimo di otto creature consenzienti a tua scelta entro gittata, collegando psichicamente ciascuna creatura a tutte le altre per la durata. Le creature con un punteggio di Intelligenza pari o inferiore a 2 non sono interessate da questo incantesimo.\nFinché l’incantesimo non termina, i bersagli possono comunicare telepaticamente attraverso il legame, indipendentemente dal fatto che condividano una lingua comune. La comunicazione è possibile a qualsiasi distanza, sebbene non possa estendersi ad altri piani di esistenza.","language":"it","ui_language":"it"},{"id":"raulothim-s-psychic-lance","name":"Raulothim's Psychic Lance","name_it":"Lancia Psichica di Raulothim","level":4,"level_it":"Livello 4","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"Il bersaglio deve superare un tiro salvezza su Intelligenza o subisce 7d6 danni psichici ed è incapacitato (danno/livello).","language":"it","ui_language":"it"},{"id":"ray-of-enfeeblement","name":"Ray of Enfeeblement","name_it":"Raggio di Indebolimento","level":2,"level_it":"Livello 2","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un raggio nero di energia debilitante scaturisce dal tuo dito puntato verso una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, finché l’incantesimo non termina il bersaglio infligge solo metà dei danni con gli attacchi con armi che usano la Forza.\nAl termine di ciascuno dei propri turni, il bersaglio può effettuare un tiro salvezza su Costituzione contro l’incantesimo. In caso di successo, l’incantesimo termina.","language":"it","ui_language":"it"},{"id":"ray-of-frost","name":"Ray of Frost","name_it":"Raggio di Gelo","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un gelido raggio di luce bianco-azzurra sfreccia verso una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, subisce 1d8 danni da freddo e la sua velocità si riduce di 3 metri fino all’inizio del tuo turno successivo.\nI danni di questo incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l’11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"ray-of-sickness","name":"Ray of Sickness","name_it":"Raggio di Malattia","level":1,"level_it":"Livello 1","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Un raggio di energia verdastra e nauseante scaturisce verso una creatura entro gittata. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se colpisci, il bersaglio subisce 2d8 danni da veleno e deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, è anche avvelenato fino alla fine del tuo turno successivo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d8 per ogni livello di slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"regenerate","name":"Regenerate","name_it":"Rigenerazione","level":7,"level_it":"Livello 7","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 minuto","range":"Contatto","components":"V, S, M (una ruota di preghiera e acqua santa)","material":"una ruota di preghiera e acqua santa","duration":"1 ora","classes":["Bard","Cleric","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura e stimoli la sua naturale capacità di guarigione. Il bersaglio recupera 4d8 + 15 punti ferita. Per la durata dell’incantesimo, il bersaglio recupera 1 punto ferita all’inizio di ciascuno dei suoi turni (10 punti ferita ogni minuto).\nGli arti recisi del bersaglio (dita, gambe, code e simili), se presenti, vengono ripristinati dopo 2 minuti. Se possiedi la parte recisa e la tieni a contatto con il moncone, l’incantesimo fa istantaneamente riattaccare l’arto al moncone.","language":"it","ui_language":"it"},{"id":"reincarnate","name":"Reincarnate","name_it":"Reincarnare","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (rari oli e unguenti del valore di almeno 1.000 mo, che l’incantesimo consuma)","material":"rari oli e unguenti del valore di almeno 1.000 mo, che l’incantesimo consuma","duration":"Istantanea","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un umanoide morto o un pezzo di un umanoide morto. Purché la creatura sia morta da non più di 10 giorni, l’incantesimo forma per essa un nuovo corpo adulto e poi richiama l’anima affinché entri in quel corpo.\nSe l’anima del bersaglio non è libera o non è disposta a farlo, l’incantesimo fallisce.\nLa magia forgia un nuovo corpo che la creatura dovrà abitare, il che probabilmente ne cambia la razza. Il DM tira un d100 e consulta la tabella seguente per determinare quale forma assume la creatura quando torna in vita, oppure il DM sceglie una forma.\nd100 | Razza | 01-04 | Draconide | 05-13 | Nano delle Colline | 14-21 | Nano di Montagna | 22-25 | Elfo Scuro | 26-34 | Elfo Alto | 35-42 | Elfo dei Boschi | 43-46 | Gnomo Silvano | 47-52 | Gnomo delle Rocce | 53-56 | Mezzelfo | 57-60 | Mezzorco | 61-68 | Halfling Piedelesto | 69-76 | Halfling Tozzo | 77-96 | Umano | 97-00 | Tiefling\nLa creatura reincarnata ricorda la sua vita e le sue esperienze precedenti. Mantiene le capacità che aveva nella sua forma originale, tranne per il fatto che scambia la sua razza originale con quella nuova e modifica di conseguenza i propri tratti razziali.","language":"it","ui_language":"it"},{"id":"remove-curse","name":"Remove Curse","name_it":"Rimuovere Maledizione","level":3,"level_it":"Livello 3","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Paladin","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Al tuo tocco, tutte le maledizioni che affliggono una creatura o un oggetto terminano. Se l’oggetto è un oggetto magico maledetto, la sua maledizione rimane, ma l’incantesimo interrompe la sintonia del proprietario con l’oggetto, così che possa essere rimosso o scartato.","language":"it","ui_language":"it"},{"id":"resistance","name":"Resistance","name_it":"Resistenza","level":0,"level_it":"Trucchetto","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un mantello in miniatura)","material":"un mantello in miniatura","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura consenziente. Una volta prima che l’incantesimo termini, il bersaglio può tirare un d4 e aggiungere il numero ottenuto a un tiro salvezza a sua scelta. Può tirare il dado prima o dopo aver effettuato il tiro salvezza. L’incantesimo termina quindi.","language":"it","ui_language":"it"},{"id":"resurrection","name":"Resurrection","name_it":"Risurrezione","level":7,"level_it":"Livello 7","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (un diamante del valore di almeno 1.000 mo, che l’incantesimo consuma)","material":"un diamante del valore di almeno 1.000 mo, che l’incantesimo consuma","duration":"Istantanea","classes":["Bard","Cleric"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura morta da non più di un secolo, che non sia morta di vecchiaia e che non sia non-morta. Se la sua anima è libera e disposta a farlo, il bersaglio torna in vita con tutti i suoi punti ferita.\nQuesto incantesimo neutralizza qualsiasi veleno e cura le malattie normali che affliggevano la creatura al momento della morte. Non rimuove, tuttavia, malattie magiche, maledizioni e simili; se tali effetti non vengono rimossi prima di lanciare l’incantesimo, affliggono il bersaglio al suo ritorno in vita.\nQuesto incantesimo richiude tutte le ferite mortali e ripristina eventuali parti del corpo mancanti.\nTornare dalla morte è una prova ardua. Il bersaglio subisce una penalità di -4 a tutti i tiri per colpire, i tiri salvezza e le prove di Caratteristica. Ogni volta che il bersaglio completa un riposo lungo, la penalità si riduce di 1 finché non scompare.\nLanciare questo incantesimo per restituire la vita a una creatura morta da un anno o più ti affatica notevolmente. Finché non completi un riposo lungo, non puoi lanciare nuovamente incantesimi e hai svantaggio a tutti i tiri per colpire, le prove di Caratteristica e i tiri salvezza.","language":"it","ui_language":"it"},{"id":"reverse-gravity","name":"Reverse Gravity","name_it":"Invertire la Gravità","level":7,"level_it":"Livello 7","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"30 metri","components":"V, S, M (una magnetite e limatura di ferro)","material":"una magnetite e limatura di ferro","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo inverte la gravità in un cilindro di 15 metri di raggio e 30 metri di altezza, centrato su un punto entro gittata. Tutte le creature e gli oggetti che non sono in qualche modo ancorati al suolo nell’area cadono verso l’alto e raggiungono la sommità dell’area nel momento in cui lanci l’incantesimo. Una creatura può effettuare un tiro salvezza su Destrezza per aggrapparsi a un oggetto fisso che riesce a raggiungere, evitando così la caduta.\nSe durante questa caduta viene incontrato un oggetto solido (come un soffitto), gli oggetti e le creature che cadono lo colpiscono proprio come farebbero durante una normale caduta verso il basso. Se un oggetto o una creatura raggiunge la sommità dell’area senza colpire nulla, vi rimane, oscillando leggermente, per la durata.\nAl termine della durata, gli oggetti e le creature interessati ricadono verso il basso.","language":"it","ui_language":"it"},{"id":"revivify","name":"Revivify","name_it":"Rivivificare","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (diamanti del valore di 300 mo, che l’incantesimo consuma)","material":"diamanti del valore di 300 mo, che l’incantesimo consuma","duration":"Istantanea","classes":["Cleric","Paladin","Druid","Ranger"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura morta nell’ultimo minuto. Quella creatura torna in vita con 1 punto ferita. Questo incantesimo non può riportare in vita una creatura morta di vecchiaia, né può ripristinare eventuali parti del corpo mancanti.","language":"it","ui_language":"it"},{"id":"rime-s-binding-ice","name":"Rime's Binding Ice","name_it":"Ghiaccio Vincolante di Rime","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (cono di 9 metri)","components":"S, M (una fiala d’acqua di fusione)","material":"una fiala d’acqua di fusione","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"Le creature in un cono di 9 metri devono superare un tiro salvezza su Costituzione o subiscono 3d8 danni da freddo e la loro velocità si riduce a 0 (danno/livello).","language":"it","ui_language":"it"},{"id":"rope-trick","name":"Rope Trick","name_it":"Trucco della Corda","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (estratto di mais in polvere e un anello attorcigliato di pergamena)","material":"estratto di mais in polvere e un anello attorcigliato di pergamena","duration":"1 ora","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un tratto di corda lungo fino a 18 metri. Un’estremità della corda si solleva quindi in aria finché l’intera corda non pende perpendicolare al suolo. All’estremità superiore della corda si apre un ingresso invisibile verso uno spazio extradimensionale che dura finché l’incantesimo non termina.\nLo spazio extradimensionale può essere raggiunto arrampicandosi fino in cima alla corda. Lo spazio può contenere fino a otto creature di taglia Media o inferiore. La corda può essere tirata dentro lo spazio, facendola scomparire alla vista dall’esterno.\nAttacchi e incantesimi non possono attraversare l’ingresso, né entrando né uscendo dallo spazio extradimensionale, ma chi si trova all’interno può vedere fuori come attraverso una finestra di 0,9 per 1,5 metri centrata sulla corda.\nTutto ciò che si trova all’interno dello spazio extradimensionale cade fuori quando l’incantesimo termina.","language":"it","ui_language":"it"},{"id":"sacred-flame","name":"Sacred Flame","name_it":"Fiamma Sacra","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una fiammeggiante radianza scende su una creatura che riesci a vedere entro gittata. Il bersaglio deve superare un tiro salvezza su Destrezza o subisce 1d8 danni radiosi. Il bersaglio non ottiene alcun beneficio dalla copertura per questo tiro salvezza.\nI danni dell’incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l’11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"sanctuary","name":"Sanctuary","name_it":"Santuario","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione bonus","range":"9 metri","components":"V, S, M (un piccolo specchio d’argento)","material":"un piccolo specchio d’argento","duration":"1 minuto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Proteggi una creatura entro gittata dagli attacchi. Finché l’incantesimo non termina, qualsiasi creatura che prende di mira la creatura protetta con un attacco o un incantesimo dannoso deve prima effettuare un tiro salvezza su Saggezza. In caso di fallimento, la creatura deve scegliere un nuovo bersaglio o perdere l’attacco o l’incantesimo. Questo incantesimo non protegge la creatura protetta dagli effetti ad area, come l’esplosione di una palla di fuoco.\nSe la creatura protetta effettua un attacco, lancia un incantesimo che colpisce una creatura nemica, o infligge danni a un’altra creatura, questo incantesimo termina.","language":"it","ui_language":"it"},{"id":"scatter","name":"Scatter","name_it":"Disperdere","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"L’aria trema attorno a un massimo di cinque creature a tua scelta che riesci a vedere entro gittata. Una creatura non consenziente deve superare un tiro salvezza su Saggezza per resistere a questo incantesimo. Teletrasporti ciascun bersaglio interessato in uno spazio libero che riesci a vedere entro 36 metri da te. Quello spazio deve trovarsi sul terreno o su un pavimento.","language":"it","ui_language":"it"},{"id":"scorching-ray","name":"Scorching Ray","name_it":"Raggio Ustionante","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei tre raggi di fuoco e li scagli contro bersagli entro gittata. Puoi scagliarli contro un solo bersaglio o contro diversi.\nEffettua un attacco con incantesimo a distanza per ciascun raggio. Se colpisci, il bersaglio subisce 2d6 danni da fuoco.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 3° livello o superiore, crei un raggio aggiuntivo per ogni livello di slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"scrying","name":"Scrying","name_it":"Scrutare","level":5,"level_it":"Livello 5","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"10 minuti","range":"Personale","components":"V, S, M (un focalizzatore del valore di almeno 1.000 mo, come una sfera di cristallo, uno specchio d’argento o una fonte piena d’acqua santa)","material":"un focalizzatore del valore di almeno 1.000 mo, come una sfera di cristallo, uno specchio d’argento o una fonte piena d’acqua santa","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Cleric","Druid","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Riesci a vedere e sentire una particolare creatura che scegli e che si trova sullo stesso piano di esistenza in cui ti trovi tu. Il bersaglio deve effettuare un tiro salvezza su Saggezza, che viene modificato in base a quanto bene conosci il bersaglio e al tipo di legame fisico che hai con esso. Se un bersaglio sa che stai lanciando questo incantesimo, può fallire volontariamente il tiro salvezza se desidera essere osservato.\nConoscenza | Modificatore al Tiro Salvezza | Per sentito dire (hai sentito parlare del bersaglio) | +5 | Diretta (hai incontrato il bersaglio) | +0 | Approfondita (conosci bene il bersaglio) | −5\nLegame | Modificatore al Tiro Salvezza | Effigie o ritratto | −2 | Oggetto posseduto o indumento | −4 | Parte del corpo, ciocca di capelli, frammento di unghia o simili | −10\nIn caso di successo, il bersaglio non è interessato e non puoi utilizzare nuovamente questo incantesimo contro di esso per 24 ore. In caso di fallimento, l’incantesimo crea un sensore invisibile entro 3 metri dal bersaglio. Puoi vedere e sentire attraverso il sensore come se ti trovassi lì. Il sensore si muove insieme al bersaglio, rimanendo entro 3 metri da esso per la durata. Una creatura in grado di vedere oggetti invisibili percepisce il sensore come un orbe luminoso grande all’incirca quanto il tuo pugno. Invece di scegliere come bersaglio una creatura, puoi scegliere come bersaglio di questo incantesimo un luogo che hai già visto in precedenza. In tal caso, il sensore appare in quel luogo e non si muove.","language":"it","ui_language":"it"},{"id":"searing-smite","name":"Searing Smite","name_it":"Percossa Ardente","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin","Ranger"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci una creatura con un attacco con arma da mischia durante la durata dell’incantesimo, la tua arma divampa con un’intensità incandescente e l’attacco infligge al bersaglio 1d6 danni da fuoco aggiuntivi e lo fa avvolgere dalle fiamme. All’inizio di ciascuno dei suoi turni, finché l’incantesimo non termina, il bersaglio deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, subisce 1d6 danni da fuoco. In caso di successo, l’incantesimo termina. Se il bersaglio o una creatura entro 1,5 metri da esso utilizza un’azione per spegnere le fiamme, o se qualche altro effetto le estingue (ad esempio se il bersaglio viene immerso in acqua), l’incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, i danni aggiuntivi iniziali inflitti dall’attacco aumentano di 1d6 per ogni livello di slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"see-invisibility","name":"See Invisibility","name_it":"Vedere Invisibilità","level":2,"level_it":"Livello 2","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un pizzico di talco e una piccola spolverata di argento in polvere)","material":"un pizzico di talco e una piccola spolverata di argento in polvere","duration":"1 ora","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata, vedi le creature e gli oggetti invisibili come se fossero visibili, e riesci a vedere nel Piano Etereo. Le creature e gli oggetti eterei appaiono spettrali e traslucidi.","language":"it","ui_language":"it"},{"id":"seeming","name":"Seeming","name_it":"Sembianza","level":5,"level_it":"Livello 5","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S","material":"","duration":"8 ore","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo ti permette di cambiare l’aspetto di un numero qualsiasi di creature che riesci a vedere entro gittata. Dai a ciascun bersaglio che scegli un nuovo aspetto illusorio. Un bersaglio non consenziente può effettuare un tiro salvezza su Carisma e, in caso di successo, non è interessato da questo incantesimo.\nL’incantesimo maschera l’aspetto fisico, oltre a vestiti, armatura, armi ed equipaggiamento. Puoi far sembrare ciascuna creatura 30 centimetri più bassa o più alta e farla apparire magra, grassa o nella media. Non puoi cambiare il tipo di corporatura di un bersaglio, quindi devi adottare una forma che abbia la stessa disposizione di base degli arti. Per il resto, l’entità dell’illusione dipende da te. L’incantesimo dura per la sua durata, a meno che tu non usi la tua azione per congedarlo prima.\nI cambiamenti operati da questo incantesimo non reggono a un’ispezione fisica. Per esempio, se usi questo incantesimo per aggiungere un cappello all’abbigliamento di una creatura, gli oggetti passano attraverso il cappello, e chiunque lo tocchi non sentirebbe nulla o sentirebbe la testa e i capelli della creatura. Se usi questo incantesimo per far apparire un bersaglio più magro di quanto sia realmente, la mano di qualcuno che si protende per toccarlo urterebbe comunque contro di esso, mentre apparentemente si trova ancora a mezz’aria.\nUna creatura può usare la propria azione per ispezionare un bersaglio e deve superare una prova di Intelligenza (Indagare) contro la CD di salvezza del tuo incantesimo. In caso di successo, si accorge che il bersaglio è camuffato.","language":"it","ui_language":"it"},{"id":"sending","name":"Sending","name_it":"Messaggero","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Illimitata","components":"V, S, M (un breve pezzo di filo di rame sottile)","material":"un breve pezzo di filo di rame sottile","duration":"1 round","classes":["Bard","Cleric","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Invii un breve messaggio di venticinque parole o meno a una creatura con cui hai familiarità. La creatura sente il messaggio nella propria mente, ti riconosce come mittente se ti conosce, e può rispondere immediatamente allo stesso modo. L’incantesimo permette a creature con un punteggio di Intelligenza pari o superiore a 1 di comprendere il significato del tuo messaggio.\nPuoi inviare il messaggio a qualsiasi distanza e persino verso altri piani di esistenza, ma se il bersaglio si trova su un piano diverso dal tuo, c’è una probabilità del 5% che il messaggio non arrivi a destinazione.","language":"it","ui_language":"it"},{"id":"sequester","name":"Sequester","name_it":"Sequestro","level":7,"level_it":"Livello 7","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (una polvere composta da polvere di diamante, smeraldo, rubino e zaffiro del valore di almeno 5.000 mo, che l’incantesimo consuma)","material":"una polvere composta da polvere di diamante, smeraldo, rubino e zaffiro del valore di almeno 5.000 mo, che l’incantesimo consuma","duration":"Finché non viene dissolto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per mezzo di questo incantesimo, una creatura consenziente o un oggetto possono essere nascosti, al sicuro da qualsiasi rilevamento per la durata. Quando lanci l’incantesimo e tocchi il bersaglio, questo diventa invisibile e non può essere preso di mira da incantesimi di divinazione né percepito attraverso sensori di scrutazione creati da incantesimi di divinazione.\nSe il bersaglio è una creatura, cade in uno stato di animazione sospesa. Il tempo cessa di scorrere per essa, che non invecchia più.\nPuoi stabilire una condizione affinché l’incantesimo termini anticipatamente. La condizione può essere qualsiasi cosa tu scelga, ma deve verificarsi o essere visibile entro 1,5 chilometri dal bersaglio. Alcuni esempi sono «dopo 1.000 anni» o «quando il tarrasque si risveglia». Questo incantesimo termina anche se il bersaglio subisce danni.","language":"it","ui_language":"it"},{"id":"shadow-blade","name":"Shadow Blade","name_it":"Lama d'Ombra","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Intrecci fili d'ombra per creare una spada d'oscurità solidificata nella tua mano. Questa spada magica dura finché l'incantesimo non termina. Conta come un'arma da mischia semplice nel cui uso sei competente. Infligge 2d8 danni psichici in caso di colpo e possiede le proprietà accurata, leggera e da lancio (gittata 6/18 metri). Inoltre, quando usi la spada per attaccare un bersaglio che si trova in penombra o nell'oscurità, effettui il tiro per colpire con vantaggio. Se lasci cadere l'arma o la lanci, questa svanisce alla fine del turno. In seguito, finché l'incantesimo persiste, puoi usare un'azione bonus per far riapparire la spada nella tua mano.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 3° o 4° livello, il danno aumenta a 3d8. Quando lo lanci usando uno slot incantesimo di 5° o 6° livello, il danno aumenta a 4d8. Quando lo lanci usando uno slot incantesimo di 7° livello o superiore, il danno aumenta a 5d8.","language":"it","ui_language":"it"},{"id":"shadow-of-moil","name":"Shadow of Moil","name_it":"Manto di Moil","level":4,"level_it":"Livello 4","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un occhio di non morto racchiuso in una gemma del valore di almeno 150 mo)","material":"un occhio di non morto racchiuso in una gemma del valore di almeno 150 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Warlock"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Ombre simili a fiamme avvolgono il tuo corpo finché l'incantesimo non termina, facendoti diventare fortemente offuscato agli occhi degli altri. Le ombre trasformano la penombra entro 3 metri da te in oscurità, e la luce intensa nella stessa area in penombra.\nFinché l'incantesimo non termina, hai resistenza ai danni radianti. Inoltre, ogni volta che una creatura entro 3 metri da te ti colpisce con un attacco, le ombre si scagliano contro quella creatura, infliggendole 2d8 danni necrotici.","language":"it","ui_language":"it"},{"id":"shape-water","name":"Shape Water","name_it":"Modellare l'Acqua","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"S","material":"","duration":"Istantanea o 1 ora (vedi sotto)","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un'area d'acqua che puoi vedere entro gittata e che rientra in un cubo di 1,5 metri di lato. La manipoli in uno dei seguenti modi:\n• Sposti istantaneamente o modifichi in altro modo il flusso dell'acqua come desideri, fino a 1,5 metri in qualsiasi direzione. Questo movimento non ha forza sufficiente per causare danni.\n• Fai in modo che l'acqua assuma forme semplici e si animi secondo la tua volontà. Questo cambiamento dura 1 ora.\n• Cambi il colore o l'opacità dell'acqua. L'acqua deve essere modificata nello stesso modo in tutta la sua estensione. Questo cambiamento dura 1 ora.\n• Congeli l'acqua, a condizione che non vi siano creature al suo interno. L'acqua si scongela in 1 ora.\nSe lanci questo incantesimo più volte, puoi avere attivi contemporaneamente non più di due dei suoi effetti non istantanei, e puoi far cessare uno di questi effetti come azione.","language":"it","ui_language":"it"},{"id":"shapechange","name":"Shapechange","name_it":"Cambiaforma","level":9,"level_it":"Livello 9","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (un cerchietto di giada del valore di almeno 1.500 mo, che devi indossare sul capo prima di lanciare l'incantesimo)","material":"un cerchietto di giada del valore di almeno 1.500 mo, che devi indossare sul capo prima di lanciare l'incantesimo","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Assumi la forma di una creatura diversa per la durata dell'incantesimo. La nuova forma può essere quella di qualsiasi creatura con un Grado di Sfida pari o inferiore al tuo livello. La creatura non può essere un costrutto o un non morto, e devi aver visto almeno una volta quel tipo di creatura. Ti trasformi in un esemplare medio di quella creatura, privo di livelli di classe o del tratto Lancio degli Incantesimi.\nLe tue statistiche di gioco vengono sostituite da quelle della creatura scelta, sebbene tu conservi il tuo allineamento e i tuoi punteggi di Intelligenza, Saggezza e Carisma. Conservi inoltre tutte le tue competenze nelle abilità e nei tiri salvezza, oltre a ottenere quelle della creatura. Se la creatura possiede la stessa competenza che hai tu e il bonus indicato nelle sue statistiche è superiore al tuo, usa il bonus della creatura al posto del tuo. Non puoi usare alcuna azione leggendaria o azione di tana della nuova forma.\nAssumi i punti ferita e i Dadi Vita della nuova forma. Quando ritorni alla tua forma normale, recuperi il numero di punti ferita che avevi prima di trasformarti. Se ritorni alla forma normale a causa della riduzione a 0 punti ferita, ogni danno in eccesso si riversa sulla tua forma normale. Fintanto che il danno in eccesso non riduce la tua forma normale a 0 punti ferita, non cadi privo di sensi.\nConservi il beneficio di qualsiasi caratteristica della tua classe, razza o altra fonte e puoi utilizzarla, a condizione che la tua nuova forma sia fisicamente in grado di farlo. Non puoi usare alcun senso speciale in tuo possesso (ad esempio la scurovisione) a meno che anche la tua nuova forma non possieda quel senso. Puoi parlare solo se la creatura normalmente è in grado di farlo.\nQuando ti trasformi, scegli se il tuo equipaggiamento cade a terra, si fonde con la nuova forma oppure viene indossato da essa. L'equipaggiamento indossato funziona normalmente. Il DM stabilisce se sia pratico per la nuova forma indossare un pezzo di equipaggiamento, in base alla forma e alle dimensioni della creatura. Il tuo equipaggiamento non cambia forma o dimensione per adattarsi alla nuova forma, e qualsiasi equipaggiamento che la nuova forma non può indossare deve cadere a terra oppure fondersi con la tua nuova forma. L'equipaggiamento che si fonde non ha alcun effetto in quello stato.\nDurante la durata di questo incantesimo, puoi usare la tua azione per assumere una forma diversa seguendo le stesse restrizioni e regole della forma originale, con un'eccezione: se la tua nuova forma ha più punti ferita di quella attuale, i tuoi punti ferita rimangono al loro valore attuale.","language":"it","ui_language":"it"},{"id":"shatter","name":"Shatter","name_it":"Frantumare","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una scheggia di mica)","material":"una scheggia di mica","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un improvviso e fragoroso rintocco, dolorosamente intenso, erompe da un punto a tua scelta entro gittata. Ogni creatura in una sfera di raggio 3 metri centrata su quel punto deve effettuare un tiro salvezza su Costituzione. Una creatura subisce 3d8 danni da tuono se fallisce il tiro salvezza, o la metà di tali danni se lo supera. Una creatura fatta di materiale inorganico come pietra, cristallo o metallo ha svantaggio a questo tiro salvezza.\nAnche un oggetto non magico che non viene indossato né trasportato subisce i danni se si trova nell'area dell'incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d8 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"shield","name":"Shield","name_it":"Scudo","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 reazione, che si esegue quando si viene colpiti da un attacco o presi di mira dall'incantesimo dardo incantato","range":"Personale","components":"V, S","material":"","duration":"1 round","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una barriera invisibile di forza magica appare e ti protegge. Fino all'inizio del tuo prossimo turno, ottieni un bonus di +5 alla CA, incluso contro l'attacco scatenante, e non subisci danni da dardo incantato.","language":"it","ui_language":"it"},{"id":"shield-of-faith","name":"Shield of Faith","name_it":"Scudo della Fede","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V, S, M (una piccola pergamena su cui è scritto un breve testo sacro)","material":"una piccola pergamena su cui è scritto un breve testo sacro","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un campo scintillante appare e avvolge una creatura a tua scelta entro gittata, conferendole un bonus di +2 alla CA per la durata dell'incantesimo.","language":"it","ui_language":"it"},{"id":"shillelagh","name":"Shillelagh","name_it":"Randello Magico","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Contatto","components":"V, S, M (vischio, una foglia di trifoglio e un randello o un bastone)","material":"vischio, una foglia di trifoglio e un randello o un bastone","duration":"1 minuto","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Il legno di un randello o di un bastone che stai impugnando viene imbevuto del potere della natura. Per la durata dell'incantesimo, puoi usare la tua caratteristica da incantatore al posto della Forza per i tiri per colpire e per i danni degli attacchi in mischia effettuati con quell'arma, e il dado del danno dell'arma diventa un d8. L'arma diventa inoltre magica, se non lo è già. L'incantesimo termina se lo lanci di nuovo o se lasci andare l'arma.","language":"it","ui_language":"it"},{"id":"shocking-grasp","name":"Shocking Grasp","name_it":"Presa Elettrizzante","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un fulmine scaturisce dalla tua mano per infliggere una scossa a una creatura che tenti di toccare. Effettua un tiro per colpire in mischia con l'incantesimo contro il bersaglio. Hai vantaggio al tiro per colpire se il bersaglio indossa un'armatura di metallo. In caso di colpo, il bersaglio subisce 1d8 danni da fulmine e non può effettuare reazioni fino all'inizio del suo prossimo turno.\nIl danno dell'incantesimo aumenta di 1d8 quando raggiungi il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8).","language":"it","ui_language":"it"},{"id":"sickening-radiance","name":"Sickening Radiance","name_it":"Radianza Nauseante","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Una fioca luce verdastra si diffonde all'interno di una sfera di raggio 9 metri centrata su un punto a tua scelta entro gittata. La luce si propaga oltre gli angoli e dura finché l'incantesimo non termina.\nQuando una creatura entra per la prima volta nell'area dell'incantesimo durante il proprio turno, o inizia il proprio turno lì, quella creatura deve superare un tiro salvezza su Costituzione o subire 4d10 danni radianti, subire un livello di sfinimento ed emettere una fioca luce verdastra in un raggio di 1,5 metri. Questa luce rende impossibile per la creatura beneficiare dell'invisibilità. La luce e qualsiasi livello di sfinimento causato da questo incantesimo scompaiono quando l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"silence","name":"Silence","name_it":"Silenzio","level":2,"level_it":"Livello 2","school":"illusion","school_it":"Illusione","ritual":true,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Cleric","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per la durata dell'incantesimo, nessun suono può essere creato all'interno di una sfera di raggio 6 metri centrata su un punto a tua scelta entro gittata, né può attraversarla. Qualsiasi creatura o oggetto interamente all'interno della sfera è immune ai danni da tuono, e le creature sono assordate finché rimangono interamente al suo interno.\nLanciare un incantesimo che includa una componente verbale è impossibile in quell'area.","language":"it","ui_language":"it"},{"id":"silent-image","name":"Silent Image","name_it":"Immagine Silenziosa","level":1,"level_it":"Livello 1","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pizzico di lana)","material":"un pizzico di lana","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei l'immagine di un oggetto, di una creatura o di un altro fenomeno visibile non più grande di un cubo di 4,5 metri di lato. L'immagine appare in un punto entro gittata e dura per la durata dell'incantesimo. L'immagine è puramente visiva; non è accompagnata da suoni, odori o altri effetti sensoriali.\nPuoi usare la tua azione per far muovere l'immagine in qualsiasi punto entro gittata. Mentre l'immagine cambia posizione, puoi alterarne l'aspetto in modo che i suoi movimenti appaiano naturali. Per esempio, se crei l'immagine di una creatura e la muovi, puoi modificare l'immagine in modo che sembri camminare.\nL'interazione fisica con l'immagine rivela che si tratta di un'illusione, poiché gli oggetti possono attraversarla. Una creatura che usa la propria azione per esaminare l'immagine può stabilire che si tratta di un'illusione con una prova di Intelligenza (Indagare) riuscita contro la CD di salvezza del tuo incantesimo. Se una creatura scopre l'illusione per quello che è, può vedere attraverso l'immagine.","language":"it","ui_language":"it"},{"id":"simulacrum","name":"Simulacrum","name_it":"Simulacro","level":7,"level_it":"Livello 7","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"12 ore","range":"Contatto","components":"V, S, M (neve o ghiaccio in quantità sufficiente a creare una copia a grandezza naturale della creatura duplicata; capelli, ritagli di unghie o un'altra parte del corpo di quella creatura posta all'interno della neve o del ghiaccio; e rubino in polvere del valore di 1.500 mo, cosparso sul duplicato e consumato dall'incantesimo)","material":"neve o ghiaccio in quantità sufficiente a creare una copia a grandezza naturale della creatura duplicata; capelli, ritagli di unghie o un'altra parte del corpo di quella creatura posta all'interno della neve o del ghiaccio; e rubino in polvere del valore di 1.500 mo, cosparso sul duplicato e consumato dall'incantesimo","duration":"Finché non viene dissolto","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Plasmi un duplicato illusorio di una bestia o di un umanoide che si trova entro gittata per l'intero tempo di lancio dell'incantesimo. Il duplicato è una creatura, in parte reale e formata da ghiaccio o neve, e può compiere azioni ed essere altrimenti influenzata come una creatura normale. Appare identica all'originale, ma possiede la metà dei punti ferita massimi della creatura ed è formata senza alcun equipaggiamento. Per il resto, l'illusione utilizza tutte le statistiche della creatura che duplica, tranne per il fatto che è un costrutto.\nIl simulacro è amichevole nei tuoi confronti e verso le creature che designi. Obbedisce ai tuoi comandi verbali, muovendosi e agendo secondo i tuoi desideri, e agisce durante il tuo turno in combattimento. Il simulacro non ha la capacità di imparare o diventare più potente, quindi non aumenta mai di livello né migliora le proprie caratteristiche, né può recuperare gli slot incantesimo spesi.\nSe il simulacro subisce danni, puoi ripararlo in un laboratorio alchemico, utilizzando erbe rare e minerali del valore di 100 mo per ogni punto ferita recuperato. Il simulacro dura finché non scende a 0 punti ferita, momento in cui torna a essere neve e si scioglie istantaneamente.\nSe lanci di nuovo questo incantesimo, qualsiasi duplicato attualmente attivo creato con questo incantesimo viene istantaneamente distrutto.","language":"it","ui_language":"it"},{"id":"skill-empowerment","name":"Skill Empowerment","name_it":"Potenziamento dell'Abilità","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"La tua magia approfondisce la comprensione che una creatura ha del proprio talento. Tocchi una creatura consenziente e le conferisci competenza specializzata in un'abilità a tua scelta; finché l'incantesimo non termina, la creatura raddoppia il proprio bonus di competenza per le prove di Caratteristica che effettua utilizzando l'abilità scelta.\nDevi scegliere un'abilità in cui il bersaglio è competente e che non stia già beneficiando di un effetto, come la Competenza Specializzata, che ne raddoppi il bonus di competenza.","language":"it","ui_language":"it"},{"id":"skywrite","name":"Skywrite","name_it":"Scrivere nel Cielo","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":true,"casting_time":"1 azione","range":"Vista","components":"V, S","material":"","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Druid","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fai in modo che fino a dieci parole si formino in una porzione di cielo che puoi vedere. Le parole sembrano fatte di nuvole e rimangono al loro posto per la durata dell'incantesimo. Le parole si dissolvono quando l'incantesimo termina. Un vento forte può disperdere le nuvole e porre fine anticipatamente all'incantesimo.","language":"it","ui_language":"it"},{"id":"sleep","name":"Sleep","name_it":"Sonno","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un pizzico di sabbia fine, petali di rosa o un grillo)","material":"un pizzico di sabbia fine, petali di rosa o un grillo","duration":"1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo induce le creature in un sonno magico. Tira 5d8; il totale rappresenta quanti punti ferita di creature questo incantesimo può influenzare. Le creature entro 6 metri da un punto che scegli entro gittata sono influenzate in ordine crescente di punti ferita attuali (ignorando le creature private di sensi).\nIniziando dalla creatura con i punti ferita attuali più bassi, ogni creatura influenzata da questo incantesimo cade priva di sensi finché l'incantesimo non termina, il dormiente subisce danni, oppure qualcuno usa un'azione per scuotere o schiaffeggiare il dormiente per svegliarlo. Sottrai i punti ferita di ciascuna creatura dal totale prima di passare alla creatura con i punti ferita immediatamente superiori. I punti ferita di una creatura devono essere pari o inferiori al totale rimanente affinché quella creatura sia influenzata.\nI non morti e le creature immuni all'essere ammaliate non sono influenzati da questo incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, tira 2d8 aggiuntivi per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"sleet-storm","name":"Sleet Storm","name_it":"Tempesta di Nevischio","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (un pizzico di polvere e qualche goccia d'acqua)","material":"un pizzico di polvere e qualche goccia d'acqua","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Finché l'incantesimo non termina, pioggia gelata e nevischio cadono in un cilindro alto 6 metri con un raggio di 12 metri centrato su un punto a tua scelta entro gittata. L'area è fortemente offuscata e le fiamme esposte al suo interno vengono spente.\nIl terreno nell'area è ricoperto di ghiaccio scivoloso, rendendolo terreno difficile. Quando una creatura entra per la prima volta nell'area dell'incantesimo durante il proprio turno, o inizia lì il proprio turno, deve effettuare un tiro salvezza su Destrezza. Se fallisce il tiro salvezza, cade prona.\nSe una creatura inizia il proprio turno nell'area dell'incantesimo ed è concentrata su un incantesimo, deve superare un tiro salvezza su Costituzione contro la CD di salvezza del tuo incantesimo, altrimenti perde la concentrazione.","language":"it","ui_language":"it"},{"id":"slow","name":"Slow","name_it":"Rallentare","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (una goccia di melassa)","material":"una goccia di melassa","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard","Bard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Bard","name_it":"Bardo","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Alteri il tempo attorno a un massimo di sei creature a tua scelta in un cubo di 12 metri di lato entro gittata. Ogni bersaglio deve superare un tiro salvezza su Saggezza o essere influenzato da questo incantesimo per la sua durata.\nLa velocità di un bersaglio influenzato è dimezzata, subisce una penalità di -2 alla CA e ai tiri salvezza su Destrezza, e non può usare reazioni. Nel proprio turno, può usare o un'azione o un'azione bonus, non entrambe. Indipendentemente dalle capacità della creatura o dai suoi oggetti magici, non può effettuare più di un attacco in mischia o a distanza durante il proprio turno.\nSe la creatura tenta di lanciare un incantesimo con un tempo di lancio di 1 azione, tira un d20. Con un risultato di 11 o superiore, l'incantesimo non ha effetto fino al turno successivo della creatura, che deve usare la propria azione in quel turno per completare l'incantesimo. Se non può farlo, l'incantesimo viene sprecato.\nUna creatura influenzata da questo incantesimo effettua un altro tiro salvezza su Saggezza alla fine di ciascuno dei propri turni. Se ha successo, l'effetto termina per lei.","language":"it","ui_language":"it"},{"id":"snare","name":"Snare","name_it":"Laccio","level":1,"level_it":"Livello 1","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 minuto","range":"Contatto","components":"S, M (7,5 metri di corda, che l'incantesimo consuma)","material":"7,5 metri di corda, che l'incantesimo consuma","duration":"8 ore","classes":["Druid","Ranger","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Mentre lanci questo incantesimo, usi la corda per creare un cerchio con un raggio di 1,5 metri sul terreno o sul pavimento. Quando finisci di lanciarlo, la corda scompare e il cerchio diventa una trappola magica.\nQuesta trappola è quasi invisibile e richiede una prova di Intelligenza (Indagare) riuscita contro la CD di salvezza del tuo incantesimo per essere individuata.\nLa trappola scatta quando una creatura di taglia Piccola, Media o Grande si muove sul terreno o sul pavimento entro il raggio dell'incantesimo. Quella creatura deve superare un tiro salvezza su Destrezza o essere magicamente issata in aria, rimanendo sospesa a testa in giù a 90 centimetri dal terreno o dal pavimento. La creatura resta trattenuta lì finché l'incantesimo non termina.\nUna creatura trattenuta può effettuare un tiro salvezza su Destrezza alla fine di ciascuno dei propri turni, ponendo fine all'effetto su di sé in caso di successo. In alternativa, la creatura stessa o chiunque altro possa raggiungerla può usare un'azione per effettuare una prova di Intelligenza (Arcano) contro la CD di salvezza del tuo incantesimo. In caso di successo, l'effetto di trattenimento termina.\nDopo che la trappola è scattata, l'incantesimo termina quando nessuna creatura è trattenuta da essa.","language":"it","ui_language":"it"},{"id":"snilloc-s-snowball-swarm","name":"Snilloc's Snowball Swarm","name_it":"Sciame di Palle di Neve di Snilloc","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un pezzo di ghiaccio o una piccola scheggia di roccia bianca)","material":"un pezzo di ghiaccio o una piccola scheggia di roccia bianca","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Una raffica di palle di neve magiche erompe da un punto a tua scelta entro gittata. Ogni creatura in una sfera di raggio 1,5 metri centrata su quel punto deve effettuare un tiro salvezza su Destrezza. Una creatura subisce 3d6 danni da freddo se fallisce il tiro salvezza, o la metà di tali danni se lo supera.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d6 per ogni livello dello slot superiore al 2°.","language":"it","ui_language":"it"},{"id":"soul-cage","name":"Soul Cage","name_it":"Gabbia delle Anime","level":6,"level_it":"Livello 6","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 reazione, che si esegue quando un umanoide visibile entro 18 metri muore","range":"18 metri","components":"V, S, M (una piccola gabbia d'argento del valore di 100 mo)","material":"una piccola gabbia d'argento del valore di 100 mo","duration":"8 ore","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Questo incantesimo cattura l'anima di un umanoide nel momento della morte e la intrappola all'interno della piccola gabbia usata come componente materiale. Un'anima rubata rimane all'interno della gabbia finché l'incantesimo non termina o finché non distruggi la gabbia, il che pone fine all'incantesimo. Finché hai un'anima all'interno della gabbia, puoi sfruttarla in uno dei modi descritti di seguito. Puoi usare un'anima intrappolata fino a sei volte. Una volta che sfrutti un'anima per la sesta volta, questa viene rilasciata e l'incantesimo termina. Finché un'anima è intrappolata, l'umanoide morto da cui proviene non può essere resuscitato.\nRubare Vita. Puoi usare un'azione bonus per drenare vigore dall'anima e recuperare 2d8 punti ferita.\nInterrogare l'Anima. Poni una domanda all'anima (non è richiesta alcuna azione) e ricevi una breve risposta telepatica, che puoi comprendere indipendentemente dalla lingua usata. L'anima conosce solo ciò che sapeva in vita, ma deve risponderti sinceramente e al meglio delle sue capacità. La risposta non supera una o due frasi e potrebbe essere criptica.\nPrendere in Prestito l'Esperienza. Puoi usare un'azione bonus per rafforzarti con l'esperienza di vita dell'anima, effettuando il tuo prossimo tiro per colpire, prova di Caratteristica o tiro salvezza con vantaggio. Se non usi questo beneficio prima dell'inizio del tuo turno successivo, esso viene perso.\nOcchi dei Morti. Puoi usare un'azione per nominare un luogo che l'umanoide ha visto in vita, creando un sensore invisibile in quel luogo, se si trova sul piano di esistenza in cui ti trovi attualmente. Il sensore rimane finché mantieni la concentrazione, fino a un massimo di 10 minuti (come se stessi mantenendo la concentrazione su un incantesimo). Ricevi informazioni visive e uditive dal sensore come se ti trovassi nel suo spazio usando i tuoi sensi.\nUna creatura in grado di vedere il sensore (ad esempio una creatura che usa vedere l'invisibile o la vista pura) vede un'immagine translucida del tormentato umanoide la cui anima hai imprigionato.","language":"it","ui_language":"it"},{"id":"spare-the-dying","name":"Spare the Dying","name_it":"Risparmiare il Morente","level":0,"level_it":"Trucchetto","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura vivente che ha 0 punti ferita. La creatura si stabilizza. Questo incantesimo non ha alcun effetto su non morti o costrutti.","language":"it","ui_language":"it"},{"id":"speak-with-animals","name":"Speak with Animals","name_it":"Parlare con gli Animali","level":1,"level_it":"Livello 1","school":"divination","school_it":"Divinazione","ritual":true,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"10 minuti","classes":["Bard","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Per tutta la durata ottieni la capacità di comprendere e comunicare verbalmente con le bestie. La conoscenza e la consapevolezza di molte bestie sono limitate dalla loro intelligenza, ma come minimo le bestie possono fornirti informazioni su luoghi e mostri nelle vicinanze, incluso tutto ciò che possono percepire o hanno percepito nell'ultimo giorno. A discrezione del DM, potresti riuscire a convincere una bestia a svolgere per te un piccolo favore.","language":"it","ui_language":"it"},{"id":"speak-with-dead","name":"Speak with Dead","name_it":"Parlare con i Morti","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"3 metri","components":"V, S, M (incenso che brucia)","material":"incenso che brucia","duration":"10 minuti","classes":["Bard","Cleric","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Conferisci la parvenza di vita e intelligenza a un cadavere a tua scelta entro gittata, permettendogli di rispondere alle domande che gli poni. Il cadavere deve avere ancora una bocca e non può essere non morto. L'incantesimo fallisce se il cadavere è già stato bersaglio di questo incantesimo negli ultimi 10 giorni.\nFinché l'incantesimo non termina, puoi porre al cadavere fino a cinque domande. Il cadavere conosce solo ciò che sapeva in vita, incluse le lingue che conosceva. Le risposte sono di solito brevi, criptiche o ripetitive, e il cadavere non è in alcun modo obbligato a fornire una risposta sincera se sei ostile nei suoi confronti o se ti riconosce come un nemico. Questo incantesimo non riporta l'anima della creatura nel suo corpo, ma solo il suo spirito animatore. Pertanto, il cadavere non può apprendere nuove informazioni, non comprende nulla di ciò che è accaduto da quando è morto e non può speculare su eventi futuri.","language":"it","ui_language":"it"},{"id":"speak-with-plants","name":"Speak with Plants","name_it":"Parlare con le Piante","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 9 metri)","components":"V, S","material":"","duration":"10 minuti","classes":["Bard","Druid","Ranger"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Doni a piante entro 9 metri da te una senzienza e un'animazione limitate, conferendo loro la capacità di comunicare con te e di seguire i tuoi semplici comandi. Puoi interrogare le piante sugli eventi accaduti nell'area dell'incantesimo nell'ultimo giorno, ottenendo informazioni su creature che sono passate, condizioni meteorologiche e altre circostanze.\nPuoi anche trasformare il terreno difficile causato dalla crescita delle piante (come boscaglie e sottobosco) in terreno normale per tutta la durata. Oppure puoi trasformare in terreno difficile, per tutta la durata, un terreno normale in cui sono presenti piante, facendo sì che rampicanti e rami ostacolino, ad esempio, gli inseguitori.\nA discrezione del DM, le piante potrebbero essere in grado di svolgere altri compiti per tuo conto. L'incantesimo non permette alle piante di sradicarsi e muoversi, ma esse possono muovere liberamente rami, viticci e steli.\nSe nell'area è presente una creatura vegetale, puoi comunicare con essa come se condivideste una lingua comune, ma non ottieni alcuna capacità magica di influenzarla.\nQuesto incantesimo può far sì che le piante create dall'incantesimo groviglio d'erbe rilascino una creatura trattenuta.","language":"it","ui_language":"it"},{"id":"spider-climb","name":"Spider Climb","name_it":"Arrampicata del Ragno","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (una goccia di bitume e un ragno)","material":"una goccia di bitume e un ragno","duration":"Concentrazione, fino a 1 ora","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Finché l'incantesimo non termina, una creatura consenziente che tocchi ottiene la capacità di muoversi su, giù e attraverso superfici verticali, nonché capovolta lungo i soffitti, lasciando le mani libere. Il bersaglio ottiene inoltre una velocità di scalata pari alla sua velocità di camminata.","language":"it","ui_language":"it"},{"id":"spike-growth","name":"Spike Growth","name_it":"Spuntoni Vegetali","level":2,"level_it":"Livello 2","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (sette spine appuntite o sette piccoli rametti, ciascuno affilato a punta)","material":"sette spine appuntite o sette piccoli rametti, ciascuno affilato a punta","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Il terreno in un raggio di 6 metri centrato su un punto entro gittata si contorce e fa germogliare dure spine e spuntoni. L'area diventa terreno difficile per tutta la durata. Quando una creatura entra nell'area o vi si muove all'interno, subisce 2d4 danni perforanti ogni 1,5 metri percorsi.\nLa trasformazione del terreno è camuffata in modo da apparire naturale. Qualsiasi creatura che non può vedere l'area nel momento in cui l'incantesimo viene lanciato deve effettuare una prova di Saggezza (Percezione) contro la CD di salvezza del tuo incantesimo per riconoscere il terreno come pericoloso prima di entrarvi.","language":"it","ui_language":"it"},{"id":"spirit-guardians","name":"Spirit Guardians","name_it":"Spiriti Guardiani","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 4,5 metri)","components":"V, S, M (un simbolo sacro)","material":"un simbolo sacro","duration":"Concentrazione, fino a 10 minuti","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi spiriti per proteggerti. Per tutta la durata, essi svolazzano intorno a te fino a una distanza di 4,5 metri. Se sei buono o neutrale, la loro forma spettrale appare angelica o fatata (a tua scelta). Se sei malvagio, appaiono infernali.\nQuando lanci questo incantesimo, puoi designare un numero qualsiasi di creature che puoi vedere affinché non siano influenzate da esso. La velocità di una creatura interessata è dimezzata nell'area e, quando la creatura entra nell'area per la prima volta in un turno o inizia il proprio turno lì, deve effettuare un tiro salvezza su Saggezza. In caso di fallimento, la creatura subisce 3d8 danni radianti (se sei buono o neutrale) o 3d8 danni necrotici (se sei malvagio). In caso di successo, la creatura subisce la metà di tali danni.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, il danno aumenta di 1d8 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"spirit-shroud","name":"Spirit Shroud","name_it":"Sudario Spirituale","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Cleric","Paladin","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi spiriti dei morti, che svolazzano intorno a te per tutta la durata dell'incantesimo. Gli spiriti sono intangibili e invulnerabili. Finché l'incantesimo non termina, ogni attacco che effettui infligge 1d8 danni extra quando colpisci una creatura entro 3 metri da te. Questo danno è radiante, necrotico o da freddo (a tua scelta quando lanci l'incantesimo). Qualsiasi creatura che subisce questo danno non può recuperare punti ferita fino all'inizio del tuo turno successivo.\nInoltre, qualsiasi creatura a tua scelta che puoi vedere e che inizia il proprio turno entro 3 metri da te ha la propria velocità ridotta di 3 metri fino all'inizio del tuo turno successivo.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, il danno aumenta di 1d8 ogni due livelli dello slot superiori al 3°.","language":"it","ui_language":"it"},{"id":"spiritual-weapon","name":"Spiritual Weapon","name_it":"Arma Spirituale","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"18 metri","components":"V, S","material":"","duration":"1 minuto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un'arma spettrale fluttuante entro gittata, che dura per la durata dell'incantesimo o finché non lanci di nuovo questo incantesimo. Quando lanci l'incantesimo, puoi effettuare un attacco con incantesimo in mischia contro una creatura entro 1,5 metri dall'arma. Se colpisci, il bersaglio subisce danni da forza pari a 1d8 + il modificatore di caratteristica da incantatore.\nCome azione bonus nel tuo turno, puoi muovere l'arma fino a 6 metri e ripetere l'attacco contro una creatura entro 1,5 metri da essa.\nL'arma può assumere qualsiasi forma tu scelga. I chierici di divinità associate a un'arma particolare (come San Cuthbert è noto per la sua mazza e Thor per il suo martello) fanno sì che l'effetto di questo incantesimo assomigli a quell'arma.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, il danno aumenta di 1d8 ogni due livelli dello slot superiori al 2°.","language":"it","ui_language":"it"},{"id":"staggering-smite","name":"Staggering Smite","name_it":"Percossa Stordente","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci una creatura con un attacco con arma da mischia durante la durata di questo incantesimo, la tua arma trafigge sia il corpo sia la mente, e l'attacco infligge al bersaglio 4d6 danni psichici extra. Il bersaglio deve effettuare un tiro salvezza su Saggezza. In caso di fallimento, ha svantaggio ai tiri per colpire e alle prove di Caratteristica, e non può effettuare reazioni, fino alla fine del suo turno successivo.","language":"it","ui_language":"it"},{"id":"steel-wind-strike","name":"Steel Wind Strike","name_it":"Colpo del Vento d'Acciaio","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"S, M (un'arma da mischia del valore di almeno 1 ma)","material":"un'arma da mischia del valore di almeno 1 ma","duration":"Istantanea","classes":["Ranger","Wizard"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fai roteare l'arma usata per lanciare l'incantesimo e poi svanisci per colpire come il vento. Scegli fino a cinque creature che puoi vedere entro gittata. Effettua un attacco con incantesimo in mischia contro ciascun bersaglio. Se colpisci, il bersaglio subisce 6d10 danni da forza.\nPuoi quindi teletrasportarti in uno spazio libero che puoi vedere entro 1,5 metri da uno dei bersagli che hai colpito o mancato.","language":"it","ui_language":"it"},{"id":"stinking-cloud","name":"Stinking Cloud","name_it":"Nube Nauseante","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un uovo marcio o diverse foglie di cavolo puzzolente)","material":"un uovo marcio o diverse foglie di cavolo puzzolente","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una sfera di gas giallo e nauseante con un raggio di 6 metri, centrata su un punto entro gittata. La nube si diffonde oltre gli angoli e la sua area è fortemente oscurata. La nube permane nell'aria per tutta la durata.\nOgni creatura che si trova interamente all'interno della nube all'inizio del proprio turno deve effettuare un tiro salvezza su Costituzione contro il veleno. In caso di fallimento, la creatura spende la propria azione in quel turno tra conati e vacillamenti. Le creature che non hanno bisogno di respirare o che sono immuni al veleno superano automaticamente questo tiro salvezza.\nUn vento moderato (almeno 16 chilometri orari) disperde la nube dopo 4 round. Un vento forte (almeno 32 chilometri orari) la disperde dopo 1 round.","language":"it","ui_language":"it"},{"id":"stone-shape","name":"Stone Shape","name_it":"Modellare la Pietra","level":4,"level_it":"Livello 4","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (argilla morbida, che deve essere lavorata dandole grossolanamente la forma desiderata per l'oggetto di pietra)","material":"argilla morbida, che deve essere lavorata dandole grossolanamente la forma desiderata per l'oggetto di pietra","duration":"Istantanea","classes":["Cleric","Druid","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi un oggetto di pietra di taglia Media o inferiore, oppure una sezione di pietra non più grande di 1,5 metri in ciascuna dimensione, e la modelli in qualsiasi forma adatta al tuo scopo. Ad esempio, potresti trasformare una grande roccia in un'arma, un idolo o uno scrigno, oppure creare un piccolo passaggio attraverso un muro, purché lo spessore del muro sia inferiore a 1,5 metri. Potresti anche modellare una porta di pietra o il suo telaio per sigillare la porta. L'oggetto che crei può avere fino a due cardini e un chiavistello, ma non è possibile ottenere dettagli meccanici più fini.","language":"it","ui_language":"it"},{"id":"stoneskin","name":"Stoneskin","name_it":"Pelle di Pietra","level":4,"level_it":"Livello 4","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (polvere di diamante del valore di 100 mo, che l'incantesimo consuma)","material":"polvere di diamante del valore di 100 mo, che l'incantesimo consuma","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo trasforma la carne di una creatura consenziente che tocchi, rendendola dura come la pietra. Finché l'incantesimo non termina, il bersaglio ha resistenza ai danni contundenti, perforanti e taglienti non magici.","language":"it","ui_language":"it"},{"id":"storm-of-vengeance","name":"Storm of Vengeance","name_it":"Tempesta della Vendetta","level":9,"level_it":"Livello 9","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Vista","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Si forma una nube temporalesca vorticosa, centrata su un punto che puoi vedere e che si estende fino a un raggio di 108 metri. Lampi guizzano nell'area, tuoni rimbombano e forti venti ruggiscono. Ogni creatura sotto la nube (non oltre 1500 metri sotto la nube) nel momento in cui questa appare deve effettuare un tiro salvezza su Costituzione. In caso di fallimento, la creatura subisce 2d6 danni da tuono e diventa assordata per 5 minuti.\nOgni round in cui mantieni la concentrazione su questo incantesimo, la tempesta produce effetti diversi nel tuo turno.\nRound 2. Dalla nube cade pioggia acida. Ogni creatura e oggetto sotto la nube subisce 1d6 danni da acido.\nRound 3. Richiami sei fulmini dalla nube per colpire sei creature o oggetti a tua scelta sotto la nube. Una data creatura o oggetto non può essere colpito da più di un fulmine. Una creatura colpita deve effettuare un tiro salvezza su Destrezza. La creatura subisce 10d6 danni da fulmine se fallisce il tiro salvezza, o la metà di tali danni se lo supera.\nRound 4. Dalla nube cadono chicchi di grandine. Ogni creatura sotto la nube subisce 2d6 danni contundenti.\nRound 5-10. Raffiche e pioggia gelata investono l'area sotto la nube. L'area diventa terreno difficile ed è fortemente oscurata. Ogni creatura lì presente subisce 1d6 danni da freddo. Gli attacchi con armi a distanza nell'area sono impossibili. Il vento e la pioggia contano come una grave distrazione ai fini del mantenimento della concentrazione sugli incantesimi. Infine, raffiche di vento forte (comprese tra 32 e 80 chilometri orari) disperdono automaticamente nebbia, foschia e fenomeni simili nell'area, sia essa mondana o magica.","language":"it","ui_language":"it"},{"id":"storm-sphere","name":"Storm Sphere","name_it":"Sfera Tempestosa","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Una sfera di aria vorticosa con un raggio di 6 metri prende vita, centrata su un punto a tua scelta entro gittata. La sfera rimane per tutta la durata dell'incantesimo. Ogni creatura nella sfera nel momento in cui essa appare, o che termina il proprio turno al suo interno, deve superare un tiro salvezza su Forza oppure subire 2d6 danni contundenti. Lo spazio della sfera è terreno difficile.\nFinché l'incantesimo non termina, puoi usare un'azione bonus in ciascuno dei tuoi turni per far scoccare un fulmine dal centro della sfera verso una creatura a tua scelta entro 18 metri dal centro. Effettua un attacco con incantesimo a distanza. Hai vantaggio al tiro per colpire se il bersaglio si trova nella sfera. Se colpisci, il bersaglio subisce 4d6 danni da fulmine.\nLe creature entro 9 metri dalla sfera hanno svantaggio alle prove di Saggezza (Percezione) effettuate per ascoltare.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 5° livello o superiore, il danno aumenta, per ciascuno dei suoi effetti, di 1d6 per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"suggestion","name":"Suggestion","name_it":"Suggestione","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, M (una lingua di serpente e un pezzo di favo oppure una goccia di olio dolce)","material":"una lingua di serpente e un pezzo di favo oppure una goccia di olio dolce","duration":"Concentrazione, fino a 8 ore","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Suggerisci un corso d'azione (limitato a una o due frasi) e influenzi magicamente una creatura che puoi vedere entro gittata, in grado di sentirti e comprenderti. Le creature che non possono essere ammaliate sono immuni a questo effetto. Il suggerimento deve essere formulato in modo tale da far sembrare ragionevole il corso d'azione. Chiedere alla creatura di pugnalarsi, gettarsi su una lancia, darsi fuoco o compiere qualsiasi altro atto palesemente dannoso pone fine all'incantesimo.\nIl bersaglio deve effettuare un tiro salvezza su Saggezza. In caso di fallimento, persegue il corso d'azione che hai descritto al meglio delle sue capacità. Il corso d'azione suggerito può proseguire per l'intera durata. Se l'attività suggerita può essere completata in un tempo più breve, l'incantesimo termina quando il soggetto finisce ciò che gli è stato chiesto di fare.\nPuoi anche specificare condizioni che innescheranno un'attività speciale durante la durata. Ad esempio, potresti suggerire a un cavaliere di dare il proprio cavallo da guerra al primo mendicante che incontra. Se la condizione non viene soddisfatta prima che l'incantesimo scada, l'attività non viene eseguita.\nSe tu o uno dei tuoi compagni infliggete danni al bersaglio, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"summon-aberration","name":"Summon Aberration","name_it":"Evocare Aberrazione","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un tentacolo sott'aceto e un bulbo oculare in una fiala intarsiata di platino del valore di almeno 400 mo)","material":"un tentacolo sott'aceto e un bulbo oculare in una fiala intarsiata di platino del valore di almeno 400 mo","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito aberrante. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Aberrante. Quando lanci l'incantesimo, scegli tra Progenie degli Occhi Tiranni, Slaad o Progenie Stellare. La creatura assomiglia a un'aberrazione di quel tipo, il che determina alcuni tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 5° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-beast","name":"Summon Beast","name_it":"Evocare Bestia","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (una piuma, un ciuffo di pelo e una coda di pesce all'interno di una ghianda dorata del valore di almeno 200 mo)","material":"una piuma, un ciuffo di pelo e una coda di pesce all'interno di una ghianda dorata del valore di almeno 200 mo","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito bestiale. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Bestiale. Quando lanci l'incantesimo, scegli un ambiente: Aria, Terra o Acqua. La creatura assomiglia a un animale a tua scelta originario dell'ambiente selezionato, il che determina alcuni tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-celestial","name":"Summon Celestial","name_it":"Evocare Celestiale","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un reliquiario dorato del valore di almeno 500 mo)","material":"un reliquiario dorato del valore di almeno 500 mo","duration":"Concentrazione, fino a 1 ora","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito celestiale. Esso si manifesta in forma angelica in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Celestiale. Quando lanci l'incantesimo, scegli tra Vendicatore o Difensore. La tua scelta determina l'attacco della creatura nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 6° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-construct","name":"Summon Construct","name_it":"Evocare Costrutto","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (una cassaforte ornata di pietra e metallo del valore di almeno 400 mo)","material":"una cassaforte ornata di pietra e metallo del valore di almeno 400 mo","duration":"Concentrazione, fino a 1 ora","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi lo spirito di un costrutto. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Costrutto. Quando lanci l'incantesimo, scegli un materiale: Argilla, Metallo o Pietra. La creatura assomiglia a un golem o a un modron (a tua scelta) fatto del materiale scelto, il che determina alcuni tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-draconic-spirit","name":"Summon Draconic Spirit","name_it":"Evocare Spirito Draconico","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un oggetto con l'immagine di un drago inciso sopra, del valore di almeno 500 mo)","material":"un oggetto con l'immagine di un drago inciso sopra, del valore di almeno 500 mo","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Tesoro dei Draghi di Fizban","description":"Evoca 1 spirito draconico (cromatico, di gemma o metallico), amichevole (statistica/livello).","language":"it","ui_language":"it"},{"id":"summon-elemental","name":"Summon Elemental","name_it":"Evocare Elementale","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (aria, un ciottolo, cenere e acqua all'interno di una fiala intarsiata d'oro del valore di almeno 400 mo)","material":"aria, un ciottolo, cenere e acqua all'interno di una fiala intarsiata d'oro del valore di almeno 400 mo","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito elementale. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Elementale. Quando lanci l'incantesimo, scegli un elemento: Aria, Terra, Fuoco o Acqua. La creatura assomiglia a una forma bipede avvolta nell'elemento scelto, il che determina alcuni tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 5° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-fey","name":"Summon Fey","name_it":"Evocare Fatato","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un fiore dorato del valore di almeno 300 mo)","material":"un fiore dorato del valore di almeno 300 mo","duration":"Concentrazione, fino a 1 ora","classes":["Druid","Ranger","Warlock","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito fatato. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Fatato. Quando lanci l'incantesimo, scegli un umore: Furente, Gioioso o Beffardo. La creatura assomiglia a una creatura fatata a tua scelta, contraddistinta dall'umore selezionato, il che determina uno dei tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-fiend","name":"Summon Fiend","name_it":"Evocare Infernale","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (sangue umanoide all'interno di una fiala di rubino del valore di almeno 600 mo)","material":"sangue umanoide all'interno di una fiala di rubino del valore di almeno 600 mo","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito infernale. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito Infernale. Quando lanci l'incantesimo, scegli tra Demone, Diavolo o Yugoloth. La creatura assomiglia a un infernale del tipo scelto, il che determina alcuni tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 7° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-greater-demon","name":"Summon Greater Demon","name_it":"Evocare Demone Maggiore","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una fiala di sangue proveniente da un umanoide ucciso nelle ultime 24 ore)","material":"una fiala di sangue proveniente da un umanoide ucciso nelle ultime 24 ore","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Pronunci parole immonde, evocando un demone dal caos dell'Abisso. Scegli il tipo di demone, che deve avere grado di sfida 5 o inferiore, come un demone d'ombra o un barlgura. Il demone appare in uno spazio libero che puoi vedere entro gittata e scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nTira l'iniziativa per il demone, che agisce nei propri turni. Quando lo evochi e in ciascuno dei tuoi turni successivi, puoi impartirgli un comando verbale (che non richiede alcuna azione da parte tua), dicendogli cosa deve fare nel suo turno successivo. Se non impartisci alcun comando, esso trascorre il turno attaccando qualsiasi creatura a portata che lo abbia attaccato.\nAlla fine di ciascun turno del demone, questo effettua un tiro salvezza su Carisma. Il demone ha svantaggio a questo tiro salvezza se pronunci il suo vero nome. Se fallisce il tiro salvezza, il demone continua a obbedirti. Se lo supera, il tuo controllo sul demone termina per il resto della durata e il demone trascorre i propri turni inseguendo e attaccando i non-demoni più vicini al meglio delle proprie capacità. Se smetti di concentrarti sull'incantesimo prima che raggiunga la sua piena durata, un demone incontrollato non scompare per 1d6 round se possiede ancora punti ferita.\nCome parte del lancio dell'incantesimo, puoi tracciare un cerchio sul terreno con il sangue usato come componente materiale. Il cerchio è abbastanza grande da comprendere il tuo spazio. Per tutta la durata dell'incantesimo, il demone evocato non può attraversare il cerchio né danneggiarlo, e non può bersagliare nessuno al suo interno. Usare la componente materiale in questo modo la consuma quando l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 5° livello o superiore, il grado di sfida aumenta di 1 per ogni livello dello slot superiore al 4°.","language":"it","ui_language":"it"},{"id":"summon-lesser-demons","name":"Summon Lesser Demons","name_it":"Evocare Demoni Minori","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una fiala di sangue proveniente da un umanoide ucciso nelle ultime 24 ore)","material":"una fiala di sangue proveniente da un umanoide ucciso nelle ultime 24 ore","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Pronunci parole immonde, evocando demoni dal caos dell'Abisso. Tira sulla tabella seguente per determinare cosa appare.\nd6 | Demoni Evocati | 1-2 | Due demoni di grado di sfida 1 o inferiore | 3-4 | Quattro demoni di grado di sfida 1/2 o inferiore | 5-6 | Otto demoni di grado di sfida 1/4 o inferiore\nIl DM sceglie i demoni, come mani o dretch, e tu scegli gli spazi liberi che puoi vedere entro gittata dove appaiono. Un demone evocato scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nI demoni sono ostili verso tutte le creature, te compreso. Tira l'iniziativa per i demoni evocati come gruppo, che agisce nei propri turni. I demoni inseguono e attaccano i non-demoni più vicini al meglio delle proprie capacità.\nCome parte del lancio dell'incantesimo, puoi tracciare un cerchio sul terreno con il sangue usato come componente materiale. Il cerchio è abbastanza grande da comprendere il tuo spazio. Per tutta la durata dell'incantesimo, i demoni evocati non possono attraversare il cerchio né danneggiarlo, e non possono bersagliare nessuno al suo interno. Usare la componente materiale in questo modo la consuma quando l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 6° o 7° livello, evochi il doppio dei demoni. Se lo lanci usando uno slot incantesimo di 8° o 9° livello, evochi il triplo dei demoni.","language":"it","ui_language":"it"},{"id":"summon-shadowspawn","name":"Summon Shadowspawn","name_it":"Evocare Progenie d'Ombra","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (lacrime all'interno di una gemma del valore di almeno 300 mo)","material":"lacrime all'interno di una gemma del valore di almeno 300 mo","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito d'ombra. Esso si manifesta in uno spazio libero che puoi vedere entro gittata. Questa forma corporea utilizza il profilo statistico di Spirito d'Ombra. Quando lanci l'incantesimo, scegli un'emozione: Furia, Disperazione o Paura. La creatura assomiglia a un bipede deforme contraddistinto dall'emozione scelta, il che determina alcuni tratti nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi compagni. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, usa il livello più alto ovunque il livello dell'incantesimo compaia nel profilo statistico.","language":"it","ui_language":"it"},{"id":"summon-undead","name":"Summon Undead","name_it":"Evocare non Morto","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (un teschio dorato del valore di almeno 300 mo)","material":"un teschio dorato del valore di almeno 300 mo","duration":"Concentrazione, fino a 1 ora","classes":["Warlock","Wizard"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Evochi uno spirito non morto. Esso si manifesta in uno spazio libero che puoi vedere entro gittata e utilizza il profilo statistico di Spirito non Morto. Quando lanci l'incantesimo, scegli la forma della creatura: Spettrale, Putrida o Scheletrica. Lo spirito assomiglia a un non morto con la forma scelta, il che determina alcuni dettagli nel suo profilo statistico. La creatura scompare quando si riduce a 0 punti ferita o quando l'incantesimo termina.\nLa creatura è un'alleata per te e i tuoi alleati. In combattimento, la creatura condivide il tuo conteggio di iniziativa, ma agisce nel proprio turno subito dopo il tuo. Obbedisce ai tuoi comandi verbali (non è richiesta alcuna azione da parte tua). Se non ne impartisci alcuno, esegue l'azione Schivare e usa il proprio movimento per evitare i pericoli.\nAi Livelli Superiori. Usa il livello dello slot incantesimo come livello dell'incantesimo nel profilo statistico.","language":"it","ui_language":"it"},{"id":"sunbeam","name":"Sunbeam","name_it":"Raggio di Sole","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (linea di 18 metri)","components":"V, S, M (una lente d'ingrandimento)","material":"una lente d'ingrandimento","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard","Cleric"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Un raggio di luce brillante scaturisce dalla tua mano in una linea larga 1,5 metri e lunga 18 metri. Ogni creatura nella linea deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, una creatura subisce 6d8 danni radianti ed è accecata fino al tuo turno successivo. Se lo supera, subisce la metà dei danni e non viene accecata da questo incantesimo. I non morti e le melme hanno svantaggio a questo tiro salvezza.\nPuoi creare una nuova linea di radiosità come azione in qualsiasi turno finché l'incantesimo non termina.\nPer tutta la durata, una scintilla di radiosità brillante risplende nella tua mano. Essa emana luce intensa in un raggio di 9 metri e luce fioca per ulteriori 9 metri. Questa luce è luce solare.","language":"it","ui_language":"it"},{"id":"sunburst","name":"Sunburst","name_it":"Esplosione Solare","level":8,"level_it":"Livello 8","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (fuoco e un pezzo di pietra del sole)","material":"fuoco e un pezzo di pietra del sole","duration":"Istantanea","classes":["Druid","Sorcerer","Wizard","Cleric"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Una luce solare brillante lampeggia in un raggio di 18 metri centrato su un punto a tua scelta entro gittata. Ogni creatura in quella luce deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, una creatura subisce 12d6 danni radianti ed è accecata per 1 minuto. Se lo supera, subisce la metà dei danni e non viene accecata da questo incantesimo. I non morti e le melme hanno svantaggio a questo tiro salvezza.\nUna creatura accecata da questo incantesimo effettua un altro tiro salvezza su Costituzione alla fine di ciascuno dei suoi turni. Se lo supera, non è più accecata.\nQuesto incantesimo dissolve qualsiasi oscurità nella sua area che sia stata creata da un incantesimo.","language":"it","ui_language":"it"},{"id":"swift-quiver","name":"Swift Quiver","name_it":"Faretra Rapida","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Contatto","components":"V, S, M (una faretra contenente almeno un proiettile)","material":"una faretra contenente almeno un proiettile","duration":"Concentrazione, fino a 1 minuto","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Trasmuti la tua faretra affinché produca una scorta infinita di munizioni non magiche, che sembrano balzare nella tua mano quando le cerchi.\nIn ciascuno dei tuoi turni finché l'incantesimo non termina, puoi usare un'azione bonus per effettuare due attacchi con un'arma che utilizza munizioni prelevate dalla faretra. Ogni volta che effettui un attacco a distanza in questo modo, la tua faretra sostituisce magicamente il proiettile utilizzato con un proiettile simile non magico. Qualsiasi munizione creata da questo incantesimo si disintegra quando l'incantesimo termina. Se la faretra lascia il tuo possesso, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"sword-burst","name":"Sword Burst","name_it":"Raffica di Spade","level":0,"level_it":"Trucchetto","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale (raggio di 1,5 metri)","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Crei un momentaneo cerchio di lame spettrali che roteano intorno a te. Tutte le altre creature entro 1,5 metri da te devono superare un tiro salvezza su Destrezza o subire 1d6 danni da forza.\nIl danno di questo incantesimo aumenta di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"symbol","name":"Symbol","name_it":"Simbolo","level":7,"level_it":"Livello 7","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 minuto","range":"Contatto","components":"V, S, M (mercurio, fosforo e polvere di diamante e opale del valore totale di almeno 1.000 mo, che l'incantesimo consuma)","material":"mercurio, fosforo e polvere di diamante e opale del valore totale di almeno 1.000 mo, che l'incantesimo consuma","duration":"Finché non viene dissolto o innescato","classes":["Bard","Cleric","Wizard","Druid"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Quando lanci questo incantesimo, incidi un glifo dannoso su una superficie (come una sezione di pavimento, una parete o un tavolo) oppure all'interno di un oggetto che può essere chiuso per celare il glifo (come un libro, una pergamena o un forziere). Se scegli una superficie, il glifo può coprire un'area della superficie non più larga di 3 metri di diametro. Se scegli un oggetto, quell'oggetto deve rimanere al suo posto; se l'oggetto viene spostato per più di 3 metri dal punto in cui hai lanciato questo incantesimo, il glifo si spezza e l'incantesimo termina senza essere innescato.\nIl glifo è quasi invisibile e richiede una prova di Intelligenza (Indagare) contro la CD di salvezza del tuo incantesimo per essere individuato.\nDecidi cosa innesca il glifo quando lanci l'incantesimo. Per i glifi incisi su una superficie, gli inneschi più tipici includono toccare o calpestare il glifo, rimuovere un altro oggetto che lo copre, avvicinarsi entro una certa distanza da esso o manipolare l'oggetto che lo contiene. Per i glifi incisi all'interno di un oggetto, gli inneschi più comuni sono aprire l'oggetto, avvicinarsi entro una certa distanza da esso o vedere o leggere il glifo.\nPuoi ulteriormente perfezionare l'innesco in modo che l'incantesimo si attivi solo in determinate circostanze o in base alle caratteristiche fisiche di una creatura (come altezza o peso), o al suo tipo fisico (per esempio, la protezione potrebbe essere impostata per colpire streghe o metamorfi). Puoi anche specificare le creature che non innescano il glifo, come coloro che pronunciano una determinata parola d'ordine.\nQuando incidi il glifo, scegli una delle opzioni seguenti per il suo effetto. Una volta innescato, il glifo risplende, riempiendo una sfera di raggio 18 metri con luce fioca per 10 minuti, dopodiché l'incantesimo termina. Ogni creatura nella sfera quando il glifo si attiva è bersagliata dal suo effetto, così come una creatura che entra nella sfera per la prima volta in un turno o che termina lì il proprio turno.\nMorte. Ogni bersaglio deve effettuare un tiro salvezza su Costituzione, subendo 10d10 danni necrotici se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nDiscordia. Ogni bersaglio deve effettuare un tiro salvezza su Costituzione. Se fallisce il tiro salvezza, il bersaglio bisticcia e litiga con le altre creature per 1 minuto. Durante questo tempo, è incapace di comunicare in modo significativo e ha svantaggio ai tiri per colpire e alle prove di Caratteristica.\nPaura. Ogni bersaglio deve effettuare un tiro salvezza su Saggezza e diventa spaventato per 1 minuto se fallisce il tiro salvezza. Mentre è spaventato, il bersaglio lascia cadere ciò che sta tenendo in mano e deve spostarsi di almeno 9 metri lontano dal glifo in ciascuno dei suoi turni, se possibile.\nDisperazione. Ogni bersaglio deve effettuare un tiro salvezza su Carisma. Se fallisce il tiro salvezza, il bersaglio è sopraffatto dalla disperazione per 1 minuto. Durante questo tempo, non può attaccare o bersagliare alcuna creatura con abilità, incantesimi o altri effetti magici dannosi.\nFollia. Ogni bersaglio deve effettuare un tiro salvezza su Intelligenza. Se fallisce il tiro salvezza, il bersaglio viene reso folle per 1 minuto. Una creatura folle non può compiere azioni, non può capire ciò che dicono le altre creature, non può leggere e parla solo in modo incomprensibile. Il DM controlla il suo movimento, che è erratico.\nDolore. Ogni bersaglio deve effettuare un tiro salvezza su Costituzione e diventa incapacitato da un dolore lancinante per 1 minuto se fallisce il tiro salvezza.\nSonno. Ogni bersaglio deve effettuare un tiro salvezza su Saggezza e cade privo di sensi per 10 minuti se fallisce il tiro salvezza. Una creatura si sveglia se subisce danni o se qualcuno usa un'azione per scuoterla o schiaffeggiarla per svegliarla.\nStordimento. Ogni bersaglio deve effettuare un tiro salvezza su Saggezza e diventa stordito per 1 minuto se fallisce il tiro salvezza.","language":"it","ui_language":"it"},{"id":"synaptic-static","name":"Synaptic Static","name_it":"Scariche Sinaptiche","level":5,"level_it":"Livello 5","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un punto entro gittata e fai esplodere lì energia psichica. Ogni creatura in una sfera di raggio 6 metri centrata su quel punto deve effettuare un tiro salvezza su Intelligenza. Una creatura con un punteggio di Intelligenza pari o inferiore a 2 non può essere colpita da questo incantesimo. Un bersaglio subisce 8d6 danni psichici se fallisce il tiro salvezza, o la metà dei danni se lo supera.\nDopo un tiro salvezza fallito, un bersaglio ha pensieri confusi per 1 minuto. Durante questo tempo, tira un d6 e sottrae il numero ottenuto da tutti i suoi tiri per colpire e prove di Caratteristica, nonché dai tiri salvezza su Costituzione per mantenere la concentrazione. Il bersaglio può effettuare un tiro salvezza su Intelligenza alla fine di ciascuno dei suoi turni, ponendo fine all'effetto su di sé in caso di successo.","language":"it","ui_language":"it"},{"id":"tasha-s-caustic-brew","name":"Tasha's Caustic Brew","name_it":"Miscuglio Caustico di Tasha","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (linea di 9 metri)","components":"V, S, M (un pezzo di cibo marcio)","material":"un pezzo di cibo marcio","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Un fiotto di acido si irradia da te in una linea lunga 9 metri e larga 1,5 metri, nella direzione che scegli. Ogni creatura nella linea deve superare un tiro salvezza su Destrezza o essere ricoperta di acido per la durata dell'incantesimo o finché una creatura non usa la propria azione per raschiare o lavare via l'acido da sé stessa o da un'altra creatura. Una creatura ricoperta d'acido subisce 2d4 danni da acido all'inizio di ciascuno dei suoi turni.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il danno aumenta di 2d4 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"tasha-s-hideous-laughter","name":"Tasha's Hideous Laughter","name_it":"Orrenda Risata di Tasha","level":1,"level_it":"Livello 1","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (piccole crostatine e una piuma che viene agitata nell'aria)","material":"piccole crostatine e una piuma che viene agitata nell'aria","duration":"Concentrazione, fino a 1 minuto","classes":["Bard","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Una creatura a tua scelta che puoi vedere entro gittata percepisce ogni cosa come esilarante e scoppia in una crisi di risate se questo incantesimo la colpisce. Il bersaglio deve superare un tiro salvezza su Saggezza o cadere prono, diventando incapacitato e incapace di rialzarsi per tutta la durata. Una creatura con un punteggio di Intelligenza pari o inferiore a 4 non è colpita.\nAlla fine di ciascuno dei suoi turni, e ogni volta che subisce danni, il bersaglio può effettuare un altro tiro salvezza su Saggezza. Il bersaglio ha vantaggio al tiro salvezza se questo è innescato da un danno subito. In caso di successo, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"tasha-s-mind-whip","name":"Tasha's Mind Whip","name_it":"Frusta Mentale di Tasha","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V","material":"","duration":"1 round","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Colpisci psichicamente una creatura che puoi vedere entro gittata. Il bersaglio deve effettuare un tiro salvezza su Intelligenza. Se fallisce il tiro salvezza, il bersaglio subisce 3d6 danni psichici e non può utilizzare una reazione fino alla fine del suo turno successivo. Inoltre, nel suo turno successivo, deve scegliere se ottenere un movimento, un'azione o un'azione bonus; ottiene solo una di queste tre cose. Se supera il tiro salvezza, il bersaglio subisce la metà dei danni e non subisce nessuno degli altri effetti dell'incantesimo.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 3° livello o superiore, puoi bersagliare una creatura aggiuntiva per ogni livello dello slot superiore al 2°. Le creature devono trovarsi entro 9 metri l'una dall'altra quando le bersagli.","language":"it","ui_language":"it"},{"id":"tasha-s-otherworldly-guise","name":"Tasha's Otherworldly Guise","name_it":"Sembianze Ultraterrene di Tasha","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V, S, M (un oggetto inciso con un simbolo dei Piani Esterni, del valore di almeno 500 mo)","material":"un oggetto inciso con un simbolo dei Piani Esterni, del valore di almeno 500 mo","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Calderone Onnicomprensivo di Tasha","description":"Pronunciando un'incantazione, attingi alla magia dei Piani Inferiori o dei Piani Superiori (a tua scelta) per trasformarti. Ottieni i seguenti benefici finché l'incantesimo non termina:\n• Sei immune ai danni da fuoco e veleno (Piani Inferiori) o ai danni radianti e necrotici (Piani Superiori).\n• Sei immune alla condizione avvelenato (Piani Inferiori) o alla condizione affascinato (Piani Superiori).\n• Ali spettrali compaiono sulla tua schiena, conferendoti una velocità di volo di 12 metri.\n• Ottieni un bonus di +2 alla CA.\n• Tutti i tuoi attacchi con armi sono magici e, quando effettui un attacco con arma, puoi usare il tuo modificatore di caratteristica da incantatore al posto di Forza o Destrezza per i tiri per colpire e per i danni.\n• Puoi attaccare due volte, invece di una, quando esegui l'azione Attacco nel tuo turno. Ignori questo beneficio se possiedi già una caratteristica, come Attacco Extra, che ti permette di attaccare più di una volta quando esegui l'azione Attacco nel tuo turno.","language":"it","ui_language":"it"},{"id":"telekinesis","name":"Telekinesis","name_it":"Telecinesi","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Ottieni la capacità di muovere o manipolare creature o oggetti con il pensiero. Quando lanci l'incantesimo, e come tua azione in ogni round per la durata dell'incantesimo, puoi esercitare la tua volontà su una creatura o un oggetto che puoi vedere entro gittata, causando l'effetto appropriato indicato di seguito. Puoi influenzare lo stesso bersaglio round dopo round, oppure sceglierne uno nuovo in qualsiasi momento. Se cambi bersaglio, quello precedente non è più influenzato dall'incantesimo.\nCreatura. Puoi tentare di muovere una creatura di taglia Enorme o inferiore. Effettua una prova di Caratteristica con la tua caratteristica da incantatore, contrapposta alla prova di Forza della creatura. Se vinci la contesa, muovi la creatura fino a 9 metri in qualsiasi direzione, anche verso l'alto, ma non oltre la gittata di questo incantesimo. Fino alla fine del tuo turno successivo, la creatura è trattenuta nella tua presa telecinetica. Una creatura sollevata in alto rimane sospesa a mezz'aria. Nei round successivi, puoi usare la tua azione per tentare di mantenere la presa telecinetica sulla creatura ripetendo la contesa.\nOggetto. Puoi tentare di muovere un oggetto che pesa fino a 500 chilogrammi. Se l'oggetto non è indossato né trasportato, lo muovi automaticamente fino a 9 metri in qualsiasi direzione, ma non oltre la gittata di questo incantesimo. Se l'oggetto è indossato o trasportato da una creatura, devi effettuare una prova di Caratteristica con la tua caratteristica da incantatore, contrapposta alla prova di Forza di quella creatura. Se hai successo, strappi l'oggetto dalla creatura e puoi muoverlo fino a 9 metri in qualsiasi direzione, ma non oltre la gittata di questo incantesimo.\nPuoi esercitare un controllo fine sugli oggetti con la tua presa telecinetica, ad esempio manipolando un semplice attrezzo, aprendo una porta o un contenitore, riponendo o recuperando un oggetto da un contenitore aperto, oppure versando il contenuto di una fiala.","language":"it","ui_language":"it"},{"id":"telepathy","name":"Telepathy","name_it":"Telepatia","level":8,"level_it":"Livello 8","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Illimitata","components":"V, S, M (un paio di anelli d'argento collegati)","material":"un paio di anelli d'argento collegati","duration":"24 ore","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Crei un legame telepatico tra te e una creatura consenziente con cui hai familiarità. La creatura può trovarsi ovunque sullo stesso piano di esistenza in cui ti trovi tu. L'incantesimo termina se tu o il bersaglio non vi trovate più sullo stesso piano.\nFinché l'incantesimo non termina, tu e il bersaglio potete condividere istantaneamente parole, immagini, suoni e altri messaggi sensoriali attraverso il legame, e il bersaglio ti riconosce come la creatura con cui sta comunicando. L'incantesimo permette a una creatura con un punteggio di Intelligenza pari ad almeno 1 di comprendere il significato delle tue parole e percepire la portata di qualsiasi messaggio sensoriale che le invii.","language":"it","ui_language":"it"},{"id":"teleport","name":"Teleport","name_it":"Teletrasporto","level":7,"level_it":"Livello 7","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"3 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo trasporta istantaneamente te e fino a otto creature consenzienti a tua scelta che puoi vedere entro gittata, oppure un singolo oggetto che puoi vedere entro gittata, verso una destinazione che scegli. Se bersagli un oggetto, questo deve poter entrare interamente in un cubo di 3 metri e non può essere tenuto o trasportato da una creatura non consenziente.\nLa destinazione che scegli deve esserti nota e deve trovarsi sullo stesso piano di esistenza in cui ti trovi tu. La tua familiarità con la destinazione determina se vi arrivi con successo. Il DM tira un d100 e consulta la tabella.\nFamiliarità | Incidente | Zona Simile | Fuori Bersaglio | Nel Bersaglio | Circolo permanente | — | — | — | 01-100 | Oggetto associato | — | — | — | 01-100 | Molto familiare | 01-05 | 06-13 | 14-24 | 25-100 | Visto casualmente | 01-33 | 34-43 | 44-53 | 54-100 | Visto una volta | 01-43 | 44-53 | 54-73 | 74-100 | Descrizione | 01-43 | 44-53 | 54-73 | 74-100 | Destinazione falsa | 01-50 | 51-100 | — | —\nFamiliarità. \"Circolo permanente\" indica un circolo di teletrasporto permanente la cui sequenza di sigilli conosci.\n\"Oggetto associato\" significa che possiedi un oggetto proveniente dalla destinazione desiderata, preso negli ultimi sei mesi, come un libro dalla biblioteca di un mago, la biancheria da letto di una suite reale, o un frammento di marmo dalla tomba segreta di un lich.\n\"Molto familiare\" è un luogo in cui sei stato molto spesso, un luogo che hai studiato attentamente, o un luogo che puoi vedere quando lanci l'incantesimo.\n\"Visto casualmente\" è un luogo che hai visto più di una volta ma con cui non hai molta familiarità.\n\"Visto una volta\" è un luogo che hai visto una volta, possibilmente per mezzo della magia.\n\"Descrizione\" è un luogo la cui posizione e il cui aspetto conosci grazie alla descrizione di qualcun altro, magari tratta da una mappa.\n\"Destinazione falsa\" è un luogo che non esiste. Forse hai tentato di scrutare il santuario di un nemico ma hai invece visto un'illusione, oppure stai tentando di teletrasportarti verso un luogo familiare che non esiste più.\nNel Bersaglio. Tu e il tuo gruppo (o l'oggetto bersaglio) apparite dove volete.\nFuori Bersaglio. Tu e il tuo gruppo (o l'oggetto bersaglio) apparite a una distanza casuale dalla destinazione, in una direzione casuale. La distanza fuori bersaglio è pari a 1d10 x 1d10 percento della distanza che doveva essere percorsa. Per esempio, se hai tentato di viaggiare per 180 chilometri, sei atterrato fuori bersaglio, e hai tirato un 5 e un 3 sui due d10, allora saresti fuori bersaglio del 15 percento, ovvero 27 chilometri. Il DM determina casualmente la direzione fuori bersaglio tirando un d8 e assegnando 1 al nord, 2 al nordest, 3 all'est, e così via lungo i punti della bussola. Se stavi teletrasportandoti verso una città costiera e sei finito 27 chilometri al largo in mare, potresti avere qualche problema.\nZona Simile. Tu e il tuo gruppo (o l'oggetto bersaglio) finite in una zona diversa ma visivamente o tematicamente simile alla zona bersaglio. Se ti stavi dirigendo verso il tuo laboratorio, per esempio, potresti ritrovarti nel laboratorio di un altro mago o in un negozio di forniture alchemiche che possiede molti degli stessi strumenti e attrezzi del tuo laboratorio. Generalmente appari nel luogo simile più vicino, ma poiché l'incantesimo non ha limiti di gittata, potresti in teoria finire ovunque sul piano.\nIncidente. La magia imprevedibile dell'incantesimo provoca un viaggio difficoltoso. Ogni creatura che si teletrasporta (o l'oggetto bersaglio) subisce 3d10 danni da forza, e il DM tira nuovamente sulla tabella per determinare dove finisci (possono verificarsi più incidenti, infliggendo danni ogni volta).","language":"it","ui_language":"it"},{"id":"teleportation-circle","name":"Teleportation Circle","name_it":"Circolo di Teletrasporto","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"3 metri","components":"V, M (rari gessetti e inchiostri intrisi di pietre preziose del valore di 50 mo, che l'incantesimo consuma)","material":"rari gessetti e inchiostri intrisi di pietre preziose del valore di 50 mo, che l'incantesimo consuma","duration":"1 round","classes":["Bard","Sorcerer","Wizard","Warlock"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Mentre lanci l'incantesimo, disegni sul terreno un cerchio del diametro di 3 metri, inciso con sigilli che collegano la tua posizione a un circolo di teletrasporto permanente a tua scelta, la cui sequenza di sigilli conosci e che si trova sullo stesso piano di esistenza in cui ti trovi tu. Un portale scintillante si apre all'interno del cerchio che hai disegnato e rimane aperto fino alla fine del tuo turno successivo. Ogni creatura che entra nel portale appare istantaneamente entro 1,5 metri dal circolo di destinazione, o nello spazio libero più vicino se quello spazio è occupato.\nMolti templi importanti, gilde e altri luoghi significativi hanno circoli di teletrasporto permanenti incisi da qualche parte entro i loro confini. Ogni circolo di questo tipo include una sequenza di sigilli unica, una serie di rune magiche disposte secondo uno schema particolare. Quando ottieni per la prima volta la capacità di lanciare questo incantesimo, apprendi le sequenze di sigilli di due destinazioni sul Piano Materiale, determinate dal DM. Puoi apprendere sequenze di sigilli aggiuntive durante le tue avventure. Puoi memorizzare una nuova sequenza di sigilli dopo averla studiata per 1 minuto.\nPuoi creare un circolo di teletrasporto permanente lanciando questo incantesimo nello stesso luogo ogni giorno per un anno. Non è necessario usare il circolo per teletrasportarti quando lanci l'incantesimo in questo modo.","language":"it","ui_language":"it"},{"id":"temple-of-the-gods","name":"Temple of the Gods","name_it":"Tempio degli Dei","level":7,"level_it":"Livello 7","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 ora","range":"36 metri","components":"V, S, M (un simbolo sacro del valore di almeno 5 mo)","material":"un simbolo sacro del valore di almeno 5 mo","duration":"24 ore","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Fai apparire scintillando un tempio sul terreno che puoi vedere entro gittata. Il tempio deve entrare in un cubo di spazio libero, fino a 36 metri per lato. Il tempio rimane finché l'incantesimo non termina. È dedicato a qualsiasi divinità, pantheon o filosofia rappresentata dal simbolo sacro usato per il lancio.\nPrendi tu tutte le decisioni sull'aspetto del tempio. L'interno è racchiuso da un pavimento, delle pareti e un tetto, con una porta che garantisce l'accesso all'interno e tutte le finestre che desideri. Solo tu e le eventuali creature che designi quando lanci l'incantesimo potete aprire o chiudere la porta.\nL'interno del tempio è uno spazio aperto con un idolo o un altare a un'estremità. Decidi se il tempio è illuminato e se quell'illuminazione è luce intensa o luce fioca. L'odore di incenso bruciato riempie l'aria all'interno, e la temperatura è mite.\nIl tempio si oppone ai tipi di creature che scegli quando lanci questo incantesimo. Scegli uno o più dei seguenti: celestiali, elementali, fatati, immondi o non morti. Se una creatura del tipo scelto tenta di entrare nel tempio, quella creatura deve effettuare un tiro salvezza su Carisma. Con un tiro fallito, non può entrare nel tempio per 24 ore. Anche se la creatura riesce a entrare nel tempio, la magia presente al suo interno la ostacola; ogni volta che effettua un tiro per colpire, una prova di Caratteristica o un tiro salvezza all'interno del tempio, deve tirare un d4 e sottrarre il numero ottenuto dal tiro di d20.\nInoltre, i sensori creati dagli incantesimi di divinazione non possono comparire all'interno del tempio, e le creature al suo interno non possono essere bersagliate da incantesimi di divinazione.\nInfine, ogni volta che una creatura all'interno del tempio recupera punti ferita grazie a un incantesimo di 1° livello o superiore, quella creatura recupera punti ferita aggiuntivi pari al tuo modificatore di Saggezza (minimo 1 punto ferita).\nIl tempio è fatto di forza magica opaca che si estende nel Piano Etereo, bloccando così il passaggio etereo verso l'interno del tempio. Nulla può attraversare fisicamente l'esterno del tempio. Non può essere dissolto da Dissolvi Magie, e Campo Antimagia non ha alcun effetto su di esso. Un incantesimo Disintegrazione distrugge il tempio istantaneamente.\nLanciare questo incantesimo nello stesso punto ogni giorno per un anno rende questo effetto permanente.","language":"it","ui_language":"it"},{"id":"tenser-s-floating-disk","name":"Tenser's Floating Disk","name_it":"Disco Fluttuante di Tenser","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":true,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una goccia di mercurio)","material":"una goccia di mercurio","duration":"1 ora","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo crea un piano di forza circolare e orizzontale, del diametro di 90 centimetri e dello spessore di 2,5 centimetri, che fluttua a 90 centimetri da terra in uno spazio libero a tua scelta che puoi vedere entro gittata. Il disco rimane per la durata dell'incantesimo e può reggere fino a 250 chilogrammi. Se viene posto sopra di esso più peso, l'incantesimo termina e tutto ciò che si trova sul disco cade a terra.\nIl disco è immobile finché ti trovi entro 6 metri da esso. Se ti allontani più di 6 metri da esso, il disco ti segue in modo da rimanere entro 6 metri da te. Può muoversi su terreno accidentato, su per o giù per scale, pendii e simili, ma non può attraversare un dislivello di 3 metri o più. Per esempio, il disco non può attraversare un pozzo profondo 3 metri, né potrebbe uscirne se fosse stato creato sul fondo.\nSe ti allontani più di 30 metri dal disco (in genere perché non riesce ad aggirare un ostacolo per seguirti), l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"tenser-s-transformation","name":"Tenser's Transformation","name_it":"Trasformazione di Tenser","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S, M (alcuni peli di toro)","material":"alcuni peli di toro","duration":"Concentrazione, fino a 10 minuti","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Ti doni resistenza e abilità marziale alimentate dalla magia. Finché l'incantesimo non termina, non puoi lanciare incantesimi e ottieni i seguenti benefici:\n• Ottieni 50 punti ferita temporanei. Se te ne restano quando l'incantesimo termina, vengono perduti.\n• Hai vantaggio ai tiri per colpire che effettui con armi semplici e da guerra.\n• Quando colpisci un bersaglio con un attacco con arma, quel bersaglio subisce 2d12 danni da forza aggiuntivi.\n• Hai competenza con tutte le armature, gli scudi, le armi semplici e le armi da guerra.\n• Hai competenza nei tiri salvezza su Forza e Costituzione.\n• Puoi attaccare due volte, invece di una, quando esegui l'azione Attacco nel tuo turno. Ignori questo beneficio se possiedi già una caratteristica, come Attacco Extra, che ti garantisce attacchi aggiuntivi.\nImmediatamente dopo il termine dell'incantesimo, devi superare un tiro salvezza su Costituzione con CD 15 o subire un livello di sfinimento.","language":"it","ui_language":"it"},{"id":"thaumaturgy","name":"Thaumaturgy","name_it":"Taumaturgia","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V","material":"","duration":"Fino a 1 minuto","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Manifesti un piccolo prodigio, un segno di potere soprannaturale, entro gittata. Crei uno dei seguenti effetti magici entro gittata:\n• La tua voce rimbomba fino a tre volte più forte del normale per 1 minuto.\n• Fai tremolare, aumentare, diminuire o cambiare colore a delle fiamme per 1 minuto.\n• Provochi tremori innocui nel terreno per 1 minuto.\n• Crei un suono istantaneo che ha origine da un punto a tua scelta entro gittata, come un rombo di tuono, il grido di un corvo, o sussurri minacciosi.\n• Fai istantaneamente spalancare o sbattere una porta o una finestra sbloccata.\n• Alteri l'aspetto dei tuoi occhi per 1 minuto.\nSe lanci questo incantesimo più volte, puoi avere fino a tre dei suoi effetti della durata di 1 minuto attivi contemporaneamente, e puoi terminare uno di questi effetti come azione.","language":"it","ui_language":"it"},{"id":"thorn-whip","name":"Thorn Whip","name_it":"Frusta di Spine","level":0,"level_it":"Trucchetto","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (lo stelo di una pianta spinosa)","material":"lo stelo di una pianta spinosa","duration":"Istantanea","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Crei una lunga frusta simile a un tralcio, ricoperta di spine, che scatta al tuo comando verso una creatura entro gittata. Effettua un tiro per colpire in mischia con l'incantesimo contro il bersaglio. Se l'attacco colpisce, la creatura subisce 1d6 danni perforanti e, se la creatura è di taglia Grande o inferiore, la trascini fino a 3 metri più vicina a te.\nI danni di questo incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"thunder-step","name":"Thunder Step","name_it":"Passo del Tuono","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Ti teletrasporti in uno spazio libero che puoi vedere entro gittata. Immediatamente dopo la tua scomparsa, risuona un boato di tuono, e ogni creatura entro 3 metri dallo spazio che hai lasciato deve effettuare un tiro salvezza su Costituzione, subendo 3d10 danni da tuono con un tiro fallito, o la metà dei danni con uno riuscito. Il tuono può essere udito fino a 90 metri di distanza.\nPuoi portare con te degli oggetti, purché il loro peso non superi quello che puoi trasportare. Puoi anche teletrasportare una creatura consenziente della tua taglia o inferiore che sta trasportando equipaggiamento fino alla sua capacità di trasporto. La creatura deve trovarsi entro 1,5 metri da te quando lanci questo incantesimo, e deve esserci uno spazio libero entro 1,5 metri dal tuo spazio di destinazione in cui la creatura possa apparire; altrimenti, la creatura viene lasciata indietro.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d10 per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"thunderclap","name":"Thunderclap","name_it":"Schiocco Tonante","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"1,5 metri","components":"S","material":"","duration":"Istantanea","classes":["Bard","Druid","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Crei un'esplosione di suono tonante che può essere udita fino a 30 metri di distanza. Ogni creatura entro gittata, tranne te, deve superare un tiro salvezza su Costituzione o subire 1d6 danni da tuono.\nI danni dell'incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6).","language":"it","ui_language":"it"},{"id":"thunderous-smite","name":"Thunderous Smite","name_it":"Percossa Tonante","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prima volta che colpisci con un attacco con arma da mischia durante la durata di questo incantesimo, la tua arma risuona di tuono udibile entro 90 metri da te, e l'attacco infligge 2d6 danni da tuono aggiuntivi al bersaglio. Inoltre, se il bersaglio è una creatura, deve superare un tiro salvezza su Forza o essere spinta fino a 3 metri lontano da te e buttata a terra prona.","language":"it","ui_language":"it"},{"id":"thunderwave","name":"Thunderwave","name_it":"Onda Tonante","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale (cubo di 4,5 metri)","components":"V, S","material":"","duration":"Istantanea","classes":["Bard","Druid","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un'onda di forza tonante si propaga da te. Ogni creatura in un cubo di 4,5 metri che ha origine da te deve effettuare un tiro salvezza su Costituzione. Con un tiro fallito, la creatura subisce 2d8 danni da tuono ed è spinta fino a 3 metri lontano da te. Con un tiro riuscito, la creatura subisce la metà dei danni e non viene spinta.\nInoltre, gli oggetti non fissati che si trovano interamente entro l'area d'effetto vengono automaticamente spinti fino a 3 metri lontano da te dall'effetto dell'incantesimo, e l'incantesimo emette un boato tonante udibile fino a 90 metri di distanza.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d8 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"tidal-wave","name":"Tidal Wave","name_it":"Onda Anomala","level":3,"level_it":"Livello 3","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (una goccia d'acqua)","material":"una goccia d'acqua","duration":"Istantanea","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Evochi un'onda d'acqua che si abbatte su un'area entro gittata. L'area può essere lunga fino a 9 metri, larga fino a 3 metri e alta fino a 3 metri. Ogni creatura in quell'area deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, la creatura subisce 4d8 danni contundenti e viene buttata a terra prona. Con un tiro riuscito, la creatura subisce la metà dei danni e non viene buttata a terra prona. L'acqua si diffonde poi sul terreno in tutte le direzioni, estinguendo le fiamme esposte nella sua area ed entro 9 metri da essa, per poi svanire.","language":"it","ui_language":"it"},{"id":"time-stop","name":"Time Stop","name_it":"Fermare il Tempo","level":9,"level_it":"Livello 9","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Fermi brevemente lo scorrere del tempo per chiunque tranne che per te. Non passa alcun tempo per le altre creature, mentre tu affronti 1d4 + 1 turni consecutivi, durante i quali puoi usare azioni e muoverti normalmente.\nQuesto incantesimo termina se una delle azioni che usi durante questo periodo, o qualsiasi effetto che crei durante questo periodo, influenza una creatura diversa da te o un oggetto indossato o trasportato da qualcuno diverso da te. Inoltre, l'incantesimo termina se ti sposti in un luogo a più di 300 metri dal punto in cui lo hai lanciato.","language":"it","ui_language":"it"},{"id":"tiny-servant","name":"Tiny Servant","name_it":"Piccolo Servitore","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 minuto","range":"Contatto","components":"V, S","material":"","duration":"8 ore","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Tocchi un oggetto non magico di taglia Minuscola che non è collegato a un altro oggetto o a una superficie e non è trasportato da un'altra creatura. Il bersaglio si anima e fa spuntare piccole braccia e gambe, diventando una creatura sotto il tuo controllo finché l'incantesimo non termina o la creatura non scende a 0 punti ferita. Consulta il blocco statistiche per le sue statistiche.\nCome azione bonus, puoi comandare mentalmente la creatura se si trova entro 36 metri da te. (Se controlli più creature con questo incantesimo, puoi comandarne una qualsiasi o tutte contemporaneamente, impartendo lo stesso ordine a ciascuna.) Decidi quale azione la creatura compirà e dove si muoverà durante il suo turno successivo, oppure puoi impartire un ordine semplice e generico, come recuperare una chiave, fare la guardia o impilare dei libri. Se non impartisci ordini, il servitore non fa altro che difendersi dalle creature ostili. Una volta ricevuto un ordine, il servitore continua a seguirlo finché il compito non è completato.\nQuando la creatura scende a 0 punti ferita, torna alla sua forma originale, e ogni danno rimanente si trasferisce a quella forma.\nAi Livelli Superiori. Quando lanci questo incantesimo usando uno slot incantesimo di 4° livello o superiore, puoi animare due oggetti aggiuntivi per ogni livello dello slot superiore al 3°.","language":"it","ui_language":"it"},{"id":"toll-the-dead","name":"Toll the Dead","name_it":"Rintocco dei Morti","level":0,"level_it":"Trucchetto","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"Istantanea","classes":["Cleric","Warlock","Wizard"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Punti il dito verso una creatura che puoi vedere entro gittata, e il suono di una campana dolorosa riempie l'aria intorno a essa per un istante. Il bersaglio deve superare un tiro salvezza su Saggezza o subire 1d8 danni necrotici. Se al bersaglio mancano dei punti ferita, subisce invece 1d12 danni necrotici.\nI danni dell'incantesimo aumentano di un dado quando raggiungi il 5° livello (2d8 o 2d12), l'11° livello (3d8 o 3d12) e il 17° livello (4d8 o 4d12).","language":"it","ui_language":"it"},{"id":"tongues","name":"Tongues","name_it":"Lingue","level":3,"level_it":"Livello 3","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, M (un piccolo modello di argilla di uno ziggurat)","material":"un piccolo modello di argilla di uno ziggurat","duration":"1 ora","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo conferisce alla creatura che tocchi la capacità di comprendere qualsiasi linguaggio parlato che ascolta. Inoltre, quando il bersaglio parla, ogni creatura che conosce almeno un linguaggio e può udire il bersaglio comprende ciò che dice.","language":"it","ui_language":"it"},{"id":"transmute-rock","name":"Transmute Rock","name_it":"Trasmutare la Roccia","level":5,"level_it":"Livello 5","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (argilla e acqua)","material":"argilla e acqua","duration":"Finché non viene dissolto","classes":["Druid","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Scegli un'area di pietra o fango che puoi vedere, che entra in un cubo di 12 metri ed è entro gittata, e scegli uno dei seguenti effetti.\nTrasmutare la Roccia in Fango. La roccia non magica di qualsiasi tipo nell'area diventa un volume equivalente di fango denso e fluido che rimane per la durata dell'incantesimo.\nIl terreno nell'area dell'incantesimo diventa abbastanza fangoso da far affondare le creature. Ogni metro che una creatura percorre nel fango costa 4 metri di movimento, e ogni creatura sul terreno quando lanci l'incantesimo deve effettuare un tiro salvezza su Forza. Una creatura deve inoltre effettuare il tiro salvezza quando entra nell'area per la prima volta in un turno o termina lì il proprio turno. Con un tiro fallito, la creatura affonda nel fango ed è trattenuta, sebbene possa usare un'azione per liberarsi dal fango, ponendo così fine alla condizione trattenuto su di sé.\nSe lanci l'incantesimo su un soffitto, il fango cade. Ogni creatura sotto il fango quando cade deve effettuare un tiro salvezza su Destrezza. La creatura subisce 4d8 danni contundenti con un tiro fallito, o la metà dei danni con uno riuscito.\nTrasmutare il Fango in Roccia. Il fango o le sabbie mobili non magiche nell'area, profonde non più di 3 metri, si trasformano in pietra morbida per la durata dell'incantesimo. Ogni creatura nel fango quando avviene la trasformazione deve effettuare un tiro salvezza su Destrezza. Con un tiro riuscito, la creatura viene spinta in sicurezza verso la superficie in uno spazio libero. Con un tiro fallito, la creatura viene trattenuta dalla roccia. Una creatura trattenuta, oppure un'altra creatura a portata, può usare un'azione per tentare di spezzare la roccia superando una prova di Forza con CD 20 o infliggendole danni. La roccia ha CA 15 e 25 punti ferita, ed è immune ai danni da veleno e psichici.","language":"it","ui_language":"it"},{"id":"transport-via-plants","name":"Transport via Plants","name_it":"Trasporto tramite Piante","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"3 metri","components":"V, S","material":"","duration":"1 round","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo crea un collegamento magico tra una pianta inanimata di taglia Grande o superiore entro gittata e un'altra pianta, a qualsiasi distanza, sullo stesso piano di esistenza. Devi aver visto o toccato la pianta di destinazione almeno una volta in precedenza. Per la durata dell'incantesimo, qualsiasi creatura può entrare nella pianta bersaglio e uscire dalla pianta di destinazione usando 1,5 metri di movimento.","language":"it","ui_language":"it"},{"id":"tree-stride","name":"Tree Stride","name_it":"Camminare tra gli Alberi","level":5,"level_it":"Livello 5","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Ottieni la capacità di entrare in un albero e spostarti dal suo interno all'interno di un altro albero della stessa specie entro 150 metri. Entrambi gli alberi devono essere vivi e di dimensioni almeno pari alle tue. Devi usare 1,5 metri di movimento per entrare in un albero. Conosci istantaneamente la posizione di tutti gli altri alberi della stessa specie entro 150 metri e, come parte del movimento usato per entrare nell'albero, puoi passare in uno di quegli alberi oppure uscire dall'albero in cui ti trovi. Appari in un punto a tua scelta entro 1,5 metri dall'albero di destinazione, usando altri 1,5 metri di movimento. Se non ti resta movimento, appari entro 1,5 metri dall'albero in cui sei entrato.\nPuoi usare questa capacità di trasporto una volta per round per la durata dell'incantesimo. Devi terminare ogni turno fuori da un albero.","language":"it","ui_language":"it"},{"id":"true-polymorph","name":"True Polymorph","name_it":"Vera Metamorfosi","level":9,"level_it":"Livello 9","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una goccia di mercurio, una noce di gomma arabica e un pizzico di fumo)","material":"una goccia di mercurio, una noce di gomma arabica e un pizzico di fumo","duration":"Concentrazione, fino a 1 ora","classes":["Bard","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scegli una creatura o un oggetto non magico che puoi vedere entro gittata. Trasformi la creatura in una creatura diversa, la creatura in un oggetto non magico, oppure l'oggetto in una creatura (l'oggetto non deve essere indossato né trasportato da un'altra creatura). La trasformazione dura per la durata dell'incantesimo, oppure finché il bersaglio non scende a 0 punti ferita o muore. Se mantieni la concentrazione su questo incantesimo per l'intera durata, la trasformazione dura finché non viene dissolta.\nQuesto incantesimo non ha effetto su un mutaforma o su una creatura con 0 punti ferita. Una creatura non consenziente può effettuare un tiro salvezza su Saggezza e, se ha successo, non è interessata dall'incantesimo.\nCreatura in Creatura. Se trasformi una creatura in un altro tipo di creatura, la nuova forma può essere di qualsiasi tipo tu scelga, purché il suo grado di sfida sia uguale o inferiore a quello del bersaglio (o il suo livello, se il bersaglio non ha un grado di sfida). Le statistiche di gioco del bersaglio, incluse le caratteristiche mentali, sono sostituite da quelle della nuova forma. Mantiene il proprio allineamento e la propria personalità.\nIl bersaglio assume i punti ferita della nuova forma e, quando ritorna alla sua forma normale, la creatura recupera il numero di punti ferita che aveva prima della trasformazione. Se ritorna alla forma normale a causa del calo a 0 punti ferita, l'eventuale danno in eccesso si riversa sulla sua forma normale. Fintanto che il danno in eccesso non riduce a 0 i punti ferita della forma normale della creatura, questa non viene resa priva di sensi.\nLa creatura è limitata nelle azioni che può compiere dalla natura della sua nuova forma e non può parlare, lanciare incantesimi o compiere qualsiasi altra azione che richieda mani o parola, a meno che la sua nuova forma non ne sia capace.\nL'equipaggiamento del bersaglio si fonde con la nuova forma. La creatura non può attivare, usare, impugnare o altrimenti beneficiare di alcuno dei propri oggetti.\nOggetto in Creatura. Puoi trasformare un oggetto in qualsiasi tipo di creatura, purché le dimensioni della creatura non siano superiori a quelle dell'oggetto e il grado di sfida della creatura sia 9 o inferiore. La creatura è amichevole nei tuoi confronti e verso i tuoi compagni. Agisce a ogni tuo turno. Decidi tu quale azione compie e come si muove. Il DM possiede le statistiche della creatura e risolve tutte le sue azioni e i suoi movimenti.\nSe l'incantesimo diventa permanente, non controlli più la creatura. Potrebbe rimanere amichevole nei tuoi confronti, a seconda di come l'hai trattata.\nCreatura in Oggetto. Se trasformi una creatura in un oggetto, questa si trasforma insieme a tutto ciò che indossa e trasporta in quella forma, purché le dimensioni dell'oggetto non siano superiori a quelle della creatura. Le statistiche della creatura diventano quelle dell'oggetto e la creatura non ha memoria del tempo trascorso in questa forma, dopo che l'incantesimo termina e ritorna alla sua forma normale.","language":"it","ui_language":"it"},{"id":"true-resurrection","name":"True Resurrection","name_it":"Vera Resurrezione","level":9,"level_it":"Livello 9","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 ora","range":"Contatto","components":"V, S, M (una spruzzata di acqua santa e diamanti del valore di almeno 25.000 mo, che l'incantesimo consuma)","material":"una spruzzata di acqua santa e diamanti del valore di almeno 25.000 mo, che l'incantesimo consuma","duration":"Istantanea","classes":["Cleric","Druid"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tocchi una creatura morta da non più di 200 anni e deceduta per qualsiasi motivo eccetto la vecchiaia. Se l'anima della creatura è libera e consenziente, la creatura viene riportata in vita con tutti i suoi punti ferita.\nQuesto incantesimo chiude tutte le ferite, neutralizza ogni veleno, cura tutte le malattie e rimuove qualsiasi maledizione che affliggeva la creatura al momento della morte. L'incantesimo sostituisce organi e arti danneggiati o mancanti. Se la creatura era non morta, riacquista la sua forma originaria di essere vivente.\nL'incantesimo può persino fornire un nuovo corpo se quello originale non esiste più; in tal caso devi pronunciare il nome della creatura. La creatura appare quindi in uno spazio libero a tua scelta entro 3 metri da te.","language":"it","ui_language":"it"},{"id":"true-seeing","name":"True Seeing","name_it":"Vista Pura","level":6,"level_it":"Livello 6","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un unguento per gli occhi del valore di 25 mo, fatto di polvere di fungo, zafferano e grasso, che viene consumato dall'incantesimo)","material":"un unguento per gli occhi del valore di 25 mo, fatto di polvere di fungo, zafferano e grasso, che viene consumato dall'incantesimo","duration":"1 ora","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo conferisce alla creatura consenziente che tocchi la capacità di vedere le cose come realmente sono. Per la durata dell'incantesimo, la creatura possiede vista pura, nota le porte segrete nascoste dalla magia e può vedere nel Piano Etereo, il tutto fino a una portata di 36 metri.","language":"it","ui_language":"it"},{"id":"true-strike","name":"True Strike","name_it":"Colpo Sicuro","level":0,"level_it":"Trucchetto","school":"divination","school_it":"Divinazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"S","material":"","duration":"Concentrazione, fino a 1 round","classes":["Bard","Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Estendi la mano e punti un dito verso un bersaglio entro gittata. La tua magia ti concede una breve intuizione sulle difese del bersaglio. Al tuo turno successivo, ottieni vantaggio sul tuo primo tiro per colpire contro il bersaglio, a patto che questo incantesimo non sia terminato.","language":"it","ui_language":"it"},{"id":"tsunami","name":"Tsunami","name_it":"Tsunami","level":8,"level_it":"Livello 8","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 minuto","range":"Vista","components":"V, S","material":"","duration":"Concentrazione, fino a 6 round","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"Un muro d'acqua si materializza in un punto a tua scelta entro gittata. Puoi creare il muro lungo fino a 90 metri, alto fino a 90 metri e spesso fino a 15 metri. Il muro dura per la durata dell'incantesimo.\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Forza. Con un tiro fallito, una creatura subisce 6d10 danni contundenti, o la metà dei danni con uno riuscito.\nAll'inizio di ciascuno dei tuoi turni successivi alla comparsa del muro, il muro, insieme a qualsiasi creatura al suo interno, si sposta di 15 metri lontano da te. Ogni creatura di taglia Enorme o inferiore all'interno del muro, o il cui spazio viene raggiunto dal muro quando si sposta, deve superare un tiro salvezza su Forza o subire 5d10 danni contundenti. Una creatura può subire questo danno solo una volta per round. Alla fine del turno, l'altezza del muro si riduce di 15 metri, e il danno subito dalle creature a causa dell'incantesimo nei round successivi si riduce di 1d10. Quando il muro raggiunge un'altezza di 0 metri, l'incantesimo termina.\nUna creatura intrappolata nel muro può muoversi nuotando. A causa della forza dell'onda, tuttavia, la creatura deve superare una prova di Forza (Atletica) contro la CD di salvezza del tuo incantesimo per potersi muovere. Se fallisce la prova, non può muoversi. Una creatura che esce dall'area cade a terra.","language":"it","ui_language":"it"},{"id":"unseen-servant","name":"Unseen Servant","name_it":"Servitore Invisibile","level":1,"level_it":"Livello 1","school":"conjuration","school_it":"Evocazione","ritual":true,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pezzo di spago e un pezzetto di legno)","material":"un pezzo di spago e un pezzetto di legno","duration":"1 ora","classes":["Bard","Warlock","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo crea una forza invisibile, priva di mente, informe, di taglia Media, che esegue compiti semplici ai tuoi comandi finché l'incantesimo non termina. Il servitore si materializza in uno spazio libero sul terreno entro gittata. Ha CA 10, 1 punto ferita e una Forza di 2, e non può attaccare. Se scende a 0 punti ferita, l'incantesimo termina.\nUna volta per ciascuno dei tuoi turni, come azione bonus, puoi comandare mentalmente al servitore di spostarsi fino a 4,5 metri e interagire con un oggetto. Il servitore può eseguire compiti semplici che un servitore umano potrebbe svolgere, come recuperare oggetti, pulire, rammendare, piegare vestiti, accendere fuochi, servire cibo e versare vino. Una volta impartito il comando, il servitore esegue il compito al meglio delle sue capacità finché non lo completa, poi attende il tuo comando successivo.\nSe comandi al servitore di eseguire un compito che lo porterebbe a più di 18 metri di distanza da te, l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"vampiric-touch","name":"Vampiric Touch","name_it":"Tocco Vampirico","level":3,"level_it":"Livello 3","school":"necromancy","school_it":"Necromanzia","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Warlock","Wizard","Sorcerer"],"class_details":[{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Il tocco della tua mano avvolta d'ombra può risucchiare forza vitale dagli altri per curare le tue ferite. Effettua un attacco con incantesimo in mischia contro una creatura entro la tua portata. Se colpisci, il bersaglio subisce 3d6 danni necrotici e tu recuperi punti ferita pari alla metà dei danni necrotici inflitti. Finché l'incantesimo non termina, puoi ripetere l'attacco a ogni tuo turno come azione.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno spazio incantesimo di 4° livello o superiore, il danno aumenta di 1d6 per ogni livello dello spazio superiore al 3°.","language":"it","ui_language":"it"},{"id":"vicious-mockery","name":"Vicious Mockery","name_it":"Scherno Crudele","level":0,"level_it":"Trucchetto","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V","material":"","duration":"Istantanea","classes":["Bard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Scagli una serie di insulti intrisi di sottili incantamenti contro una creatura che puoi vedere entro gittata. Se il bersaglio può sentirti (anche se non ha bisogno di capirti), deve superare un tiro salvezza su Saggezza o subire 1d4 danni psichici e avere svantaggio al prossimo tiro per colpire che effettua prima della fine del suo prossimo turno.\nIl danno di questo incantesimo aumenta di 1d4 quando raggiungi il 5° livello (2d4), l'11° livello (3d4) e il 17° livello (4d4).","language":"it","ui_language":"it"},{"id":"vitriolic-sphere","name":"Vitriolic Sphere","name_it":"Sfera Vetriolica","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"45 metri","components":"V, S, M (una goccia di bile di lumaca gigante)","material":"una goccia di bile di lumaca gigante","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Indichi un punto entro gittata, e una sfera luminosa di acido color smeraldo con un diametro di 30 centimetri sfreccia verso di esso ed esplode in una sfera di raggio 6 metri. Ogni creatura in quell'area deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, una creatura subisce 10d4 danni da acido e altri 5d4 danni da acido alla fine del suo turno successivo. Con un tiro riuscito, una creatura subisce la metà del danno iniziale e nessun danno alla fine del suo turno successivo.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno spazio incantesimo di 5° livello o superiore, il danno iniziale aumenta di 2d4 per ogni livello dello spazio superiore al 4°.","language":"it","ui_language":"it"},{"id":"wall-of-fire","name":"Wall of Fire","name_it":"Muro di Fuoco","level":4,"level_it":"Livello 4","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un piccolo pezzo di fosforo)","material":"un piccolo pezzo di fosforo","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un muro di fuoco su una superficie solida entro gittata. Puoi creare il muro lungo fino a 18 metri, alto fino a 6 metri e spesso 30 centimetri, oppure un muro ad anello con un diametro fino a 6 metri, alto 6 metri e spesso 30 centimetri. Il muro è opaco e dura per la durata dell'incantesimo.\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, una creatura subisce 5d8 danni da fuoco, o la metà dei danni con uno riuscito.\nUn lato del muro, scelto da te quando lanci l'incantesimo, infligge 5d8 danni da fuoco a ogni creatura che termina il proprio turno entro 3 metri da quel lato o all'interno del muro. Una creatura subisce lo stesso danno quando entra nel muro per la prima volta in un turno o vi termina il proprio turno.\nL'altro lato del muro non infligge alcun danno.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno spazio incantesimo di 5° livello o superiore, il danno aumenta di 1d8 per ogni livello dello spazio superiore al 4°.","language":"it","ui_language":"it"},{"id":"wall-of-force","name":"Wall of Force","name_it":"Muro di Forza","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un pizzico di polvere ottenuta frantumando una gemma trasparente)","material":"un pizzico di polvere ottenuta frantumando una gemma trasparente","duration":"Concentrazione, fino a 10 minuti","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un muro di forza invisibile si materializza in un punto a tua scelta entro gittata. Il muro appare nell'orientamento che scegli, come barriera orizzontale, verticale o inclinata. Può restare sospeso in aria o poggiare su una superficie solida. Puoi modellarlo a forma di cupola emisferica o di sfera con un raggio fino a 3 metri, oppure puoi dargli la forma di una superficie piatta composta da dieci pannelli di 3 metri per 3 metri. Ogni pannello deve essere contiguo a un altro pannello. In qualsiasi forma, il muro è spesso 0,6 centimetri. Dura per la durata dell'incantesimo. Se il muro attraversa lo spazio di una creatura quando appare, la creatura viene spinta su un lato del muro (a tua scelta).\nNulla può attraversare fisicamente il muro. È immune a tutti i danni e non può essere dissolto da dissolvi magie. Un incantesimo disintegrazione distrugge invece il muro istantaneamente. Il muro si estende inoltre nel Piano Etereo, bloccando il passaggio etereo attraverso di esso.","language":"it","ui_language":"it"},{"id":"wall-of-ice","name":"Wall of Ice","name_it":"Muro di Ghiaccio","level":6,"level_it":"Livello 6","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un piccolo pezzo di quarzo)","material":"un piccolo pezzo di quarzo","duration":"Concentrazione, fino a 10 minuti","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un muro di ghiaccio su una superficie solida entro gittata. Puoi modellarlo a forma di cupola emisferica o di sfera con un raggio fino a 3 metri, oppure puoi dargli la forma di una superficie piatta composta da dieci pannelli quadrati di 3 metri di lato. Ogni pannello deve essere contiguo a un altro pannello. In qualsiasi forma, il muro è spesso 30 centimetri e dura per la durata dell'incantesimo.\nSe il muro attraversa lo spazio di una creatura quando appare, la creatura all'interno della sua area viene spinta su un lato del muro e deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, la creatura subisce 10d6 danni da freddo, o la metà dei danni con uno riuscito.\nIl muro è un oggetto che può essere danneggiato e quindi sfondato. Ha CA 12 e 30 punti ferita per ogni sezione di 3 metri, ed è vulnerabile ai danni da fuoco. Ridurre a 0 punti ferita una sezione di 3 metri di muro la distrugge e lascia dietro di sé una lastra d'aria gelida nello spazio occupato dal muro. Una creatura che si muove attraverso la lastra d'aria gelida per la prima volta in un turno deve effettuare un tiro salvezza su Costituzione. Quella creatura subisce 5d6 danni da freddo con un tiro fallito, o la metà dei danni con uno riuscito.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno spazio incantesimo di 7° livello o superiore, il danno inflitto dal muro quando appare aumenta di 2d6, e il danno subito attraversando la lastra d'aria gelida aumenta di 1d6, per ogni livello dello spazio superiore al 6°.","language":"it","ui_language":"it"},{"id":"wall-of-light","name":"Wall of Light","name_it":"Muro di Luce","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (uno specchietto da mano)","material":"uno specchietto da mano","duration":"Concentrazione, fino a 10 minuti","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Un muro scintillante di luce brillante appare in un punto a tua scelta entro gittata. Il muro appare nell'orientamento che scegli: orizzontale, verticale o diagonale. Può restare sospeso in aria oppure poggiare su una superficie solida. Il muro può essere lungo fino a 18 metri, alto fino a 3 metri e spesso 1,5 metri. Il muro blocca la linea di vista, ma creature e oggetti possono attraversarlo. Emette luce brillante fino a 36 metri e luce fioca per altri 36 metri.\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Costituzione. Con un tiro fallito, una creatura subisce 4d8 danni radiosi ed è accecata per 1 minuto. Con un tiro riuscito, subisce la metà dei danni e non viene accecata. Una creatura accecata può effettuare un tiro salvezza su Costituzione alla fine di ciascuno dei suoi turni, ponendo fine all'effetto su se stessa con un successo.\nUna creatura che termina il proprio turno nell'area del muro subisce 4d8 danni radiosi.\nFinché l'incantesimo non termina, puoi usare un'azione per lanciare un raggio di luce dal muro contro una creatura che puoi vedere entro 18 metri da esso. Effettua un attacco con incantesimo a distanza. Se colpisci, il bersaglio subisce 4d8 danni radiosi. Che tu colpisca o manchi, riduci la lunghezza del muro di 3 metri. Se la lunghezza del muro scende a 0 metri, l'incantesimo termina.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno spazio incantesimo di 6° livello o superiore, il danno aumenta di 1d8 per ogni livello dello spazio superiore al 5°.","language":"it","ui_language":"it"},{"id":"wall-of-sand","name":"Wall of Sand","name_it":"Muro di Sabbia","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (una manciata di sabbia)","material":"una manciata di sabbia","duration":"Concentrazione, fino a 10 minuti","classes":["Wizard"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Crei un muro di sabbia turbinante sul terreno in un punto che puoi vedere entro gittata. Puoi creare il muro lungo fino a 9 metri, alto fino a 3 metri e spesso fino a 3 metri, e svanisce quando l'incantesimo termina. Blocca la linea di vista ma non il movimento. Una creatura è accecata mentre si trova nello spazio del muro e deve spendere 0,9 metri di movimento per ogni 30 centimetri percorsi al suo interno.","language":"it","ui_language":"it"},{"id":"wall-of-stone","name":"Wall of Stone","name_it":"Muro di Pietra","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un piccolo blocco di granito)","material":"un piccolo blocco di granito","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un muro non magico di pietra solida si materializza in un punto a tua scelta entro gittata. Il muro è spesso 15 centimetri ed è composto da dieci pannelli di 3 metri per 3 metri. Ogni pannello deve essere contiguo ad almeno un altro pannello. In alternativa, puoi creare pannelli di 3 metri per 6 metri spessi solo 7,5 centimetri.\nSe il muro attraversa lo spazio di una creatura quando appare, la creatura viene spinta su un lato del muro (a tua scelta). Se una creatura si trovasse circondata su tutti i lati dal muro (o dal muro e da un'altra superficie solida), quella creatura può effettuare un tiro salvezza su Destrezza. Con un successo, può usare la propria reazione per muoversi fino alla propria velocità in modo da non rimanere più racchiusa dal muro.\nIl muro può avere qualsiasi forma tu desideri, sebbene non possa occupare lo stesso spazio di una creatura o di un oggetto. Il muro non deve necessariamente essere verticale o poggiare su una base solida. Deve tuttavia fondersi con la pietra esistente ed esserne solidamente sostenuto. Puoi quindi usare questo incantesimo per creare un ponte su un crepaccio o costruire una rampa.\nSe crei una campata di lunghezza superiore a 6 metri, devi dimezzare le dimensioni di ciascun pannello per creare dei sostegni. Puoi modellare grossolanamente il muro per creare merlature, bastioni e simili.\nIl muro è un oggetto fatto di pietra che può essere danneggiato e quindi sfondato. Ogni pannello ha CA 15 e 30 punti ferita per ogni 2,5 centimetri di spessore. Ridurre un pannello a 0 punti ferita lo distrugge e potrebbe causare il crollo dei pannelli collegati, a discrezione del DM.\nSe mantieni la concentrazione su questo incantesimo per l'intera durata, il muro diventa permanente e non può essere dissolto. Altrimenti, il muro scompare quando l'incantesimo termina.","language":"it","ui_language":"it"},{"id":"wall-of-thorns","name":"Wall of Thorns","name_it":"Muro di Spine","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (una manciata di spine)","material":"una manciata di spine","duration":"Concentrazione, fino a 10 minuti","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei un muro di sterpaglia robusta, flessibile e aggrovigliata, irta di spine aguzze come aghi. Il muro appare entro gittata su una superficie solida e dura per la durata dell'incantesimo. Puoi scegliere di creare il muro lungo fino a 18 metri, alto fino a 3 metri e spesso 1,5 metri, oppure un cerchio con un diametro di 6 metri, alto fino a 6 metri e spesso 1,5 metri. Il muro blocca la linea di vista.\nQuando il muro appare, ogni creatura nella sua area deve effettuare un tiro salvezza su Destrezza. Con un tiro fallito, una creatura subisce 7d8 danni perforanti, o la metà dei danni con uno riuscito.\nUna creatura può muoversi attraverso il muro, sebbene lentamente e dolorosamente. Per ogni 30 centimetri che una creatura percorre attraverso il muro, deve spendere 1,2 metri di movimento. Inoltre, la prima volta che una creatura entra nel muro in un turno o vi termina il proprio turno, deve effettuare un tiro salvezza su Destrezza. Subisce 7d8 danni taglienti con un tiro fallito, o la metà dei danni con uno riuscito.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno spazio incantesimo di 7° livello o superiore, entrambi i tipi di danno aumentano di 1d8 per ogni livello dello spazio superiore al 6°.","language":"it","ui_language":"it"},{"id":"wall-of-water","name":"Wall of Water","name_it":"Muro d'Acqua","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (una goccia d'acqua)","material":"una goccia d'acqua","duration":"Concentrazione, fino a 10 minuti","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Crei un muro d'acqua sul terreno in un punto che puoi vedere entro gittata. Puoi creare il muro lungo fino a 9 metri, alto fino a 3 metri e spesso 30 centimetri, oppure puoi creare un muro ad anello con un diametro fino a 6 metri, alto 6 metri e spesso 30 centimetri. Il muro svanisce quando l'incantesimo termina. Lo spazio del muro è terreno difficile.\nQualsiasi attacco con arma a distanza che entra nello spazio del muro ha svantaggio al tiro per colpire, e i danni da fuoco sono dimezzati se l'effetto di fuoco attraversa il muro per raggiungere il proprio bersaglio. Gli incantesimi che infliggono danni da freddo che attraversano il muro fanno gelare solidamente l'area del muro da essi attraversata (viene ghiacciata almeno una sezione di 1,5 metri per lato). Ogni sezione ghiacciata di 1,5 metri per lato ha CA 5 e 15 punti ferita. Ridurre una sezione ghiacciata a 0 punti ferita la distrugge. Quando una sezione viene distrutta, l'acqua del muro non la riempie più.","language":"it","ui_language":"it"},{"id":"warding-bond","name":"Warding Bond","name_it":"Legame Protettivo","level":2,"level_it":"Livello 2","school":"abjuration","school_it":"Abiurazione","ritual":false,"casting_time":"1 azione","range":"Contatto","components":"V, S, M (un paio di anelli di platino del valore di almeno 50 mo ciascuno, che tu e il bersaglio dovete indossare per la durata dell'incantesimo)","material":"un paio di anelli di platino del valore di almeno 50 mo ciascuno, che tu e il bersaglio dovete indossare per la durata dell'incantesimo","duration":"1 ora","classes":["Cleric","Paladin"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo protegge una creatura consenziente che tocchi e crea una connessione mistica tra te e il bersaglio finché l'incantesimo non termina. Finché il bersaglio si trova entro 18 metri da te, ottiene un bonus di +1 alla CA e ai tiri salvezza, e ha resistenza a tutti i danni. Inoltre, ogni volta che subisce danni, tu subisci la stessa quantità di danni.\nL'incantesimo termina se scendi a 0 punti ferita o se tu e il bersaglio venite separati da più di 18 metri. Termina anche se l'incantesimo viene lanciato di nuovo su una delle due creature collegate. Puoi anche congedare l'incantesimo come azione.","language":"it","ui_language":"it"},{"id":"warding-wind","name":"Warding Wind","name_it":"Vento di Protezione","level":2,"level_it":"Livello 2","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 10 minuti","classes":["Bard","Druid","Sorcerer","Wizard"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Un forte vento (32 chilometri orari) soffia intorno a te in un raggio di 3 metri e si sposta con te, rimanendo centrato su di te. Il vento dura per la durata dell'incantesimo.\nIl vento ha i seguenti effetti:\n• Assorda te e le altre creature nella sua area.\n• Estingue le fiamme non protette nella sua area, delle dimensioni di una torcia o inferiori.\n• Respinge vapori, gas e nebbia che possono essere dispersi da un vento forte.\n• L'area è terreno difficile per le creature diverse da te.\n• I tiri per colpire degli attacchi con armi a distanza hanno svantaggio se attraversano il vento, in entrata o in uscita.","language":"it","ui_language":"it"},{"id":"water-breathing","name":"Water Breathing","name_it":"Respirare Sott'Acqua","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":true,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (una piccola canna o un filo di paglia)","material":"una piccola canna o un filo di paglia","duration":"24 ore","classes":["Druid","Ranger","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo concede fino a dieci creature consenzienti che riesci a vedere entro gittata la capacità di respirare sott'acqua finché l'incantesimo non termina. Le creature interessate mantengono inoltre la loro normale modalità di respirazione.","language":"it","ui_language":"it"},{"id":"water-walk","name":"Water Walk","name_it":"Camminare sull'Acqua","level":3,"level_it":"Livello 3","school":"transmutation","school_it":"Trasmutazione","ritual":true,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un pezzo di sughero)","material":"un pezzo di sughero","duration":"1 ora","classes":["Cleric","Druid","Ranger","Sorcerer"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Questo incantesimo concede la capacità di muoversi su qualsiasi superficie liquida — come acqua, acido, fango, neve, sabbie mobili o lava — come se fosse innocuo terreno solido (le creature che attraversano lava fusa possono comunque subire danni dal calore). Fino a dieci creature consenzienti che riesci a vedere entro gittata ottengono questa capacità per la durata dell'incantesimo.\nSe scegli come bersaglio una creatura sommersa in un liquido, l'incantesimo porta il bersaglio alla superficie del liquido a una velocità di 18 metri al round.","language":"it","ui_language":"it"},{"id":"watery-sphere","name":"Watery Sphere","name_it":"Sfera d'Acqua","level":4,"level_it":"Livello 4","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"27 metri","components":"V, S, M (una goccia d'acqua)","material":"una goccia d'acqua","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Evochi una sfera d'acqua con un raggio di 1,5 metri in un punto che riesci a vedere entro gittata. La sfera può fluttuare, ma non più di 3 metri da terra. La sfera rimane per la durata dell'incantesimo.\nOgni creatura nello spazio della sfera deve effettuare un tiro salvezza su Forza. Se ha successo, la creatura viene espulsa da quello spazio nello spazio libero più vicino a sua scelta fuori dalla sfera. Una creatura enorme o più grande supera automaticamente il tiro salvezza, mentre una creatura grande o più piccola può scegliere di fallirlo. Se fallisce, la creatura viene bloccata dalla sfera e viene avvolta dall'acqua. Alla fine di ciascuno dei suoi turni, un bersaglio bloccato può ripetere il tiro salvezza, ponendo fine all'effetto su di sé in caso di successo.\nLa sfera può bloccare fino a quattro creature di taglia media o inferiore, oppure una creatura grande. Se la sfera blocca una creatura che le fa superare questa capacità, una creatura scelta casualmente tra quelle già bloccate dalla sfera ne fuoriesce e atterra prona in uno spazio entro 1,5 metri da essa.\nCome azione, puoi spostare la sfera fino a 9 metri in linea retta. Se si sposta sopra una fossa, un dirupo o un altro dislivello, essa scende in sicurezza finché non fluttua a 3 metri da terra. Ogni creatura bloccata dalla sfera si sposta insieme ad essa. Puoi scagliare la sfera contro le creature, costringendole a effettuare il tiro salvezza.\nQuando l'incantesimo termina, la sfera cade a terra ed estingue tutte le fiamme normali entro 9 metri da essa. Ogni creatura bloccata dalla sfera viene atterrata prona nello spazio in cui cade. L'acqua quindi svanisce.","language":"it","ui_language":"it"},{"id":"web","name":"Web","name_it":"Ragnatela","level":2,"level_it":"Livello 2","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S, M (un pezzo di ragnatela)","material":"un pezzo di ragnatela","duration":"Concentrazione, fino a 1 ora","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Evochi una massa di ragnatela spessa e appiccicosa in un punto a tua scelta entro gittata. Le ragnatele riempiono un cubo di 6 metri di lato a partire da quel punto per la durata dell'incantesimo. Le ragnatele sono terreno difficile e offuscano leggermente la loro area.\nSe le ragnatele non sono ancorate tra due masse solide (come muri o alberi) o stese su un pavimento, un muro o un soffitto, la ragnatela evocata collassa su se stessa e l'incantesimo termina all'inizio del tuo turno successivo. Le ragnatele stese su una superficie piana hanno una profondità di 1,5 metri.\nOgni creatura che inizia il proprio turno nelle ragnatele o che vi entra durante il proprio turno deve effettuare un tiro salvezza su Destrezza. Se fallisce, la creatura viene bloccata finché rimane nelle ragnatele o finché non si libera.\nUna creatura bloccata dalle ragnatele può usare la propria azione per effettuare una prova di Forza contro la CD di salvezza del tuo incantesimo. Se ha successo, non è più bloccata.\nLe ragnatele sono infiammabili. Qualsiasi cubo di 1,5 metri di ragnatele esposto al fuoco brucia completamente in 1 round, infliggendo 2d4 danni da fuoco a ogni creatura che inizia il proprio turno nel fuoco.","language":"it","ui_language":"it"},{"id":"weird","name":"Weird","name_it":"Terrore Illusorio","level":9,"level_it":"Livello 9","school":"illusion","school_it":"Illusione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Wizard","Warlock"],"class_details":[{"name":"Wizard","name_it":"Mago","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":true,"source":"TCoE"}],"source":"Manuale del Giocatore (SRD)","description":"Attingendo alle paure più profonde di un gruppo di creature, crei creature illusorie nelle loro menti, visibili solo a loro. Ogni creatura in una sfera con un raggio di 9 metri centrata su un punto a tua scelta entro gittata deve effettuare un tiro salvezza su Saggezza. Se fallisce, la creatura diventa spaventata per la durata dell'incantesimo. L'illusione attinge alle paure più profonde della creatura, manifestando i suoi incubi peggiori come una minaccia implacabile. Alla fine di ciascuno dei turni della creatura spaventata, questa deve superare un tiro salvezza su Saggezza o subire 4d10 danni psichici. Se ha successo, l'incantesimo termina per quella creatura.","language":"it","ui_language":"it"},{"id":"whirlwind","name":"Whirlwind","name_it":"Turbine","level":7,"level_it":"Livello 7","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"90 metri","components":"V, M (un filo di paglia)","material":"un filo di paglia","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Sorcerer","Wizard"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Un turbine ulula fino a un punto che riesci a vedere sul terreno entro gittata. Il turbine è un cilindro con un raggio di 3 metri e un'altezza di 9 metri, centrato su quel punto. Finché l'incantesimo non termina, puoi usare la tua azione per spostare il turbine fino a 9 metri in qualsiasi direzione lungo il terreno. Il turbine risucchia qualsiasi oggetto di taglia media o inferiore che non sia fissato a qualcosa e che non sia indossato o trasportato da nessuno.\nUna creatura deve effettuare un tiro salvezza su Destrezza la prima volta in un turno in cui entra nel turbine o in cui il turbine entra nel suo spazio, incluso quando il turbine appare per la prima volta. Una creatura subisce 10d6 danni contundenti se fallisce il tiro salvezza, o la metà dei danni se ha successo. Inoltre, una creatura di taglia grande o inferiore che fallisce il tiro salvezza deve superare un tiro salvezza su Forza o essere bloccata all'interno del turbine finché l'incantesimo non termina. Quando una creatura inizia il proprio turno bloccata dal turbine, viene trascinata 1,5 metri più in alto al suo interno, a meno che non si trovi già in cima. Una creatura bloccata si sposta insieme al turbine e cade quando l'incantesimo termina, a meno che non abbia un modo per rimanere in volo.\nUna creatura bloccata può usare un'azione per effettuare una prova di Forza o Destrezza contro la CD di salvezza del tuo incantesimo. Se ha successo, non è più bloccata dal turbine e viene scagliata a 3d6 × 3 metri di distanza da esso in una direzione casuale.","language":"it","ui_language":"it"},{"id":"wind-walk","name":"Wind Walk","name_it":"Camminare nel Vento","level":6,"level_it":"Livello 6","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 minuto","range":"9 metri","components":"V, S, M (fuoco e acqua santa)","material":"fuoco e acqua santa","duration":"8 ore","classes":["Druid"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tu e fino a dieci creature consenzienti che riesci a vedere entro gittata assumete una forma gassosa per la durata dell'incantesimo, apparendo come volute di nuvola. Mentre si trova in questa forma di nuvola, una creatura ha una velocità di volo di 90 metri e ha resistenza ai danni delle armi non magiche. Le uniche azioni che una creatura può intraprendere in questa forma sono l'azione Scattare o il ritorno alla propria forma normale. Il ritorno richiede 1 minuto, durante il quale la creatura è incapacitata e non può muoversi. Finché l'incantesimo non termina, una creatura può tornare alla forma di nuvola, il che richiede anch'esso la trasformazione di 1 minuto.\nSe una creatura si trova in forma di nuvola e in volo quando l'effetto termina, essa scende di 18 metri per round per 1 minuto finché non atterra, cosa che fa in sicurezza. Se non riesce ad atterrare dopo 1 minuto, la creatura cade per la distanza rimanente.","language":"it","ui_language":"it"},{"id":"wind-wall","name":"Wind Wall","name_it":"Muro di Vento","level":3,"level_it":"Livello 3","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S, M (un piccolo ventaglio e una piuma di origine esotica)","material":"un piccolo ventaglio e una piuma di origine esotica","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Un muro di vento forte si alza dal terreno in un punto che scegli entro gittata. Puoi rendere il muro lungo fino a 15 metri, alto 4,5 metri e spesso 30 centimetri. Puoi dare al muro la forma che preferisci, purché costituisca un unico percorso continuo lungo il terreno. Il muro dura per la durata dell'incantesimo.\nQuando il muro appare, ogni creatura all'interno della sua area deve effettuare un tiro salvezza su Forza. Una creatura subisce 3d8 danni contundenti se fallisce il tiro salvezza, o la metà dei danni se ha successo.\nIl vento forte tiene a bada nebbia, fumo e altri gas. Le creature o gli oggetti volanti di taglia piccola o inferiore non possono attraversare il muro. I materiali sciolti e leggeri portati nel muro volano verso l'alto. Frecce, dardi e altri proiettili ordinari lanciati contro bersagli dietro il muro vengono deviati verso l'alto e mancano automaticamente. (Massi scagliati da giganti o macchine d'assedio, e proiettili simili, non ne sono influenzati.) Le creature in forma gassosa non possono attraversarlo.","language":"it","ui_language":"it"},{"id":"wish","name":"Wish","name_it":"Desiderio","level":9,"level_it":"Livello 9","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"Personale","components":"V","material":"","duration":"Istantanea","classes":["Sorcerer","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Desiderio è il più potente incantesimo che una creatura mortale possa lanciare. Semplicemente parlando ad alta voce, puoi alterare le fondamenta stesse della realtà in accordo con i tuoi desideri.\nL'uso base di questo incantesimo consiste nel duplicare qualsiasi altro incantesimo di 8° livello o inferiore. Non devi soddisfare alcun requisito di quell'incantesimo, incluse le componenti costose. L'incantesimo ha semplicemente effetto.\nIn alternativa, puoi creare uno dei seguenti effetti a tua scelta:\n• Crei un oggetto del valore massimo di 25.000 mo che non sia un oggetto magico. L'oggetto non può superare i 90 metri in nessuna dimensione e appare in uno spazio libero che riesci a vedere sul terreno.\n• Permetti a un massimo di venti creature che riesci a vedere di recuperare tutti i punti ferita, e poni fine a tutti gli effetti su di esse descritti dall'incantesimo ripristino superiore.\n• Concedi a un massimo di dieci creature che riesci a vedere resistenza a un tipo di danno a tua scelta.\n• Concedi a un massimo di dieci creature che riesci a vedere immunità a un singolo incantesimo o altro effetto magico per 8 ore. Ad esempio, potresti rendere te stesso e tutti i tuoi compagni immuni all'attacco di assorbimento vitale di un lich.\n• Annulli un singolo evento recente forzando un nuovo tiro per qualsiasi tiro effettuato entro l'ultimo round (incluso il tuo ultimo turno). La realtà si rimodella per accogliere il nuovo risultato. Ad esempio, un incantesimo di desiderio potrebbe annullare il tiro salvezza riuscito di un avversario, il colpo critico di un nemico o il tiro salvezza fallito di un amico. Puoi forzare il nuovo tiro con vantaggio o svantaggio, e puoi scegliere se usare il nuovo tiro o quello originale.\nPotresti essere in grado di ottenere qualcosa che va oltre la portata degli esempi sopra citati. Esponi il tuo desiderio al DM nel modo più preciso possibile. Il DM ha ampia libertà nel decidere cosa accade in un caso simile; più grande è il desiderio, maggiore è la probabilità che qualcosa vada storto. Questo incantesimo potrebbe semplicemente fallire, l'effetto desiderato potrebbe essere ottenuto solo parzialmente, oppure potresti subire qualche conseguenza imprevista a causa del modo in cui hai formulato il desiderio. Ad esempio, desiderare che un cattivo sia morto potrebbe proiettarti avanti nel tempo fino a un periodo in cui quel cattivo non è più in vita, rimuovendoti di fatto dal gioco. Allo stesso modo, desiderare un oggetto magico o un artefatto leggendario potrebbe teletrasportarti istantaneamente alla presenza dell'attuale proprietario dell'oggetto.\nLo stress di lanciare questo incantesimo per produrre un effetto diverso dalla duplicazione di un altro incantesimo ti indebolisce. Dopo aver sopportato questo stress, ogni volta che lanci un incantesimo finché non completi un riposo lungo, subisci 1d10 danni necrotici per livello di quell'incantesimo. Questo danno non può essere ridotto o prevenuto in alcun modo. Inoltre, la tua Forza scende a 3, se non è già pari o inferiore a 3, per 2d4 giorni. Per ciascuno di quei giorni che trascorri riposando e non facendo nulla di più di un'attività leggera, il tempo di recupero rimanente diminuisce di 2 giorni. Infine, c'è una probabilità del 33 percento che tu non sia più in grado di lanciare desiderio se subisci questo stress.","language":"it","ui_language":"it"},{"id":"witch-bolt","name":"Witch Bolt","name_it":"Dardo della Strega","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"9 metri","components":"V, S, M (un rametto di un albero colpito da un fulmine)","material":"un rametto di un albero colpito da un fulmine","duration":"Concentrazione, fino a 1 minuto","classes":["Sorcerer","Warlock","Wizard"],"class_details":[{"name":"Sorcerer","name_it":"Stregone","optional":false,"source":null},{"name":"Warlock","name_it":"Warlock","optional":false,"source":null},{"name":"Wizard","name_it":"Mago","optional":false,"source":null}],"source":"Manuale del Giocatore (BR+)","description":"Un raggio di energia blu crepitante scatta verso una creatura entro gittata, formando un arco continuo di fulmine tra te e il bersaglio. Effettua un attacco con incantesimo a distanza contro quella creatura. Se colpisci, il bersaglio subisce 1d12 danni da fulmine, e a ogni tuo turno per la durata dell'incantesimo puoi usare la tua azione per infliggere automaticamente 1d12 danni da fulmine al bersaglio. L'incantesimo termina se usi la tua azione per fare qualsiasi altra cosa. L'incantesimo termina anche se il bersaglio si trova al di fuori della gittata dell'incantesimo o se ha copertura totale da te.\nAi Livelli Superiori. Quando lanci questo incantesimo utilizzando uno slot incantesimo di 2° livello o superiore, il danno iniziale aumenta di 1d12 per ogni livello dello slot superiore al 1°.","language":"it","ui_language":"it"},{"id":"word-of-radiance","name":"Word of Radiance","name_it":"Parola di Radianza","level":0,"level_it":"Trucchetto","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"1,5 metri","components":"V, M (un simbolo sacro)","material":"un simbolo sacro","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Pronunci una parola divina, e una radianza ardente erompe da te. Ogni creatura a tua scelta che riesci a vedere entro gittata deve superare un tiro salvezza su Costituzione o subire 1d6 danni radianti.\nIl danno dell'incantesimo aumenta di 1d6 quando raggiungi il livello 5 (2d6), il livello 11 (3d6) e il livello 17 (4d6).","language":"it","ui_language":"it"},{"id":"word-of-recall","name":"Word of Recall","name_it":"Parola di Richiamo","level":6,"level_it":"Livello 6","school":"conjuration","school_it":"Evocazione","ritual":false,"casting_time":"1 azione","range":"1,5 metri","components":"V","material":"","duration":"Istantanea","classes":["Cleric"],"class_details":[{"name":"Cleric","name_it":"Chierico","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Tu e fino a cinque creature consenzienti entro 1,5 metri da te vi teletrasportate istantaneamente verso un santuario precedentemente designato. Tu e ogni creatura che si teletrasporta con te apparite nello spazio libero più vicino al punto che hai designato quando hai preparato il tuo santuario (vedi sotto). Se lanci questo incantesimo senza aver prima preparato un santuario, l'incantesimo non ha effetto.\nDevi designare un santuario lanciando questo incantesimo all'interno di un luogo, come un tempio, dedicato o fortemente legato alla tua divinità. Se tenti di lanciare l'incantesimo in questo modo in un'area non dedicata alla tua divinità, l'incantesimo non ha effetto.","language":"it","ui_language":"it"},{"id":"wrath-of-nature","name":"Wrath of Nature","name_it":"Ira della Natura","level":5,"level_it":"Livello 5","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione","range":"36 metri","components":"V, S","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Druid","Ranger"],"class_details":[{"name":"Druid","name_it":"Druido","optional":false,"source":null},{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Chiami a raccolta gli spiriti della natura per aizzarli contro i tuoi nemici. Scegli un punto che riesci a vedere entro gittata. Gli spiriti fanno sì che alberi, rocce ed erba in un cubo di 18 metri di lato centrato su quel punto si animino finché l'incantesimo non termina.\nErba e Sottobosco. Qualsiasi area di terreno nel cubo coperta da erba o sottobosco è terreno difficile per i tuoi nemici.\nAlberi. All'inizio di ciascuno dei tuoi turni, ogni tuo nemico entro 3 metri da un albero nel cubo deve superare un tiro salvezza su Destrezza o subire 4d6 danni taglienti da rami sferzanti.\nRadici e Liane. Alla fine di ciascuno dei tuoi turni, una creatura a tua scelta che si trova a terra nel cubo deve superare un tiro salvezza su Forza o essere bloccata finché l'incantesimo non termina. Una creatura bloccata può usare un'azione per effettuare una prova di Forza (Atletica) contro la CD di salvezza del tuo incantesimo, ponendo fine all'effetto su di sé in caso di successo.\nRocce. Come azione bonus nel tuo turno, puoi far sì che una roccia libera nel cubo si scagli contro una creatura che riesci a vedere nel cubo. Effettua un attacco con incantesimo a distanza contro il bersaglio. Se lo colpisci, il bersaglio subisce 3d8 danni contundenti non magici e deve superare un tiro salvezza su Forza o cadere prono.","language":"it","ui_language":"it"},{"id":"wrathful-smite","name":"Wrathful Smite","name_it":"Percossa Iraconda","level":1,"level_it":"Livello 1","school":"evocation","school_it":"Invocazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Paladin"],"class_details":[{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore","description":"La prossima volta che colpisci con un attacco con arma da mischia durante la durata di questo incantesimo, il tuo attacco infligge 1d6 danni psichici aggiuntivi. Inoltre, se il bersaglio è una creatura, deve effettuare un tiro salvezza su Saggezza o essere spaventata da te finché l'incantesimo non termina. Come azione, la creatura può effettuare una prova di Saggezza contro la CD di salvezza del tuo incantesimo per rafforzare la propria determinazione e porre fine a questo incantesimo.","language":"it","ui_language":"it"},{"id":"zephyr-strike","name":"Zephyr Strike","name_it":"Colpo di Zefiro","level":1,"level_it":"Livello 1","school":"transmutation","school_it":"Trasmutazione","ritual":false,"casting_time":"1 azione bonus","range":"Personale","components":"V","material":"","duration":"Concentrazione, fino a 1 minuto","classes":["Ranger"],"class_details":[{"name":"Ranger","name_it":"Ranger","optional":false,"source":null}],"source":"Guida Omnicomprensiva di Xanathar","description":"Ti muovi come il vento. Per la durata dell'incantesimo, i tuoi spostamenti non provocano attacchi di opportunità.\nUna volta prima che l'incantesimo termini, puoi concederti vantaggio su un tiro per colpire con arma nel tuo turno. Quell'attacco infligge 1d8 danni da forza aggiuntivi se colpisce. Che tu colpisca o manchi, la tua velocità di movimento aumenta di 9 metri fino alla fine di quel turno.","language":"it","ui_language":"it"},{"id":"zone-of-truth","name":"Zone of Truth","name_it":"Zona di Verità","level":2,"level_it":"Livello 2","school":"enchantment","school_it":"Ammaliamento","ritual":false,"casting_time":"1 azione","range":"18 metri","components":"V, S","material":"","duration":"10 minuti","classes":["Bard","Cleric","Paladin"],"class_details":[{"name":"Bard","name_it":"Bardo","optional":false,"source":null},{"name":"Cleric","name_it":"Chierico","optional":false,"source":null},{"name":"Paladin","name_it":"Paladino","optional":false,"source":null}],"source":"Manuale del Giocatore (SRD)","description":"Crei una zona magica che protegge dall'inganno in una sfera con un raggio di 4,5 metri centrata su un punto a tua scelta entro gittata. Finché l'incantesimo non termina, una creatura che entra nell'area dell'incantesimo per la prima volta in un turno o che inizia lì il proprio turno deve effettuare un tiro salvezza su Carisma. Se fallisce, la creatura non può pronunciare una bugia deliberata mentre si trova nel raggio. Sai se ciascuna creatura supera o fallisce il proprio tiro salvezza.\nUna creatura interessata è consapevole dell'incantesimo e può quindi evitare di rispondere a domande alle quali normalmente risponderebbe con una bugia. Tale creatura può essere evasiva nelle sue risposte, purché rimanga entro i confini della verità.","language":"it","ui_language":"it"}];
window.DND_SPELLS = window.DND_SPELLS_IT;
